
function genId() { return 'PT' + Date.now().toString().slice(-6) + Math.floor(Math.random() * 100); }
function genApptId() { return 'AP' + Date.now().toString().slice(-6) + Math.floor(Math.random() * 100); }
function todayISO() { return new Date().toISOString().slice(0, 10); }
function monthISO() { return new Date().toISOString().slice(0, 7); }
function fmtDate(d) {
  try {
    return new Date(d + 'T00:00:00').toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
  } catch (e) {
    return d || '';
  }
}
function esc(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function fmtMoney(n) {
  return 'Rs.' + Number(n || 0).toLocaleString('en-IN');
}
function avatarColor(name) {
  return 'hsl(' + (((name || 'A').charCodeAt(0) * 7) % 360) + ',55%,52%)';
}
function cleanWA(s) {
  return String(s || '').replace(/[^\x20-\x7E\u0900-\u097F\n\r]/g, '').trim();
}

