function getAuthHeader() {
  const token = localStorage.getItem('hos_session_token');
  return token ? { 'Authorization': `Bearer ${token}` } : {};
}

function dbGet(store, key) {
  try {
    return localStorage.getItem(`hos_meta_${key}`);
  } catch(e) {
    return null;
  }
}

function dbSet(store, key, value) {
  try {
    localStorage.setItem(`hos_meta_${key}`, value);
  } catch(e) {}
}

