  var loader = document.createElement('div');
  loader.id = 'cloud-loading';
  loader.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-family:\'DM Sans\',sans-serif;font-size:14px;font-weight:700;z-index:100000;gap:12px';
