function migrateData(d) {
  const base = getDefaultData();
  if (!d || typeof d !== 'object') return base;
  const merged = {
    ...base,
    ...d,
    version: APP_VERSION,
    patients: (d.patients||[]).map(p => ({
      ...p,
      type: p.type||'regular',
      treatmentStatus: p.treatmentStatus||'ongoing',
      orthoDetails: p.orthoDetails||null,
      images: p.images||[],
      prescriptions: p.prescriptions||[],
      billing: p.billing||[],
      records: p.records||[],
      dob: p.dob||'',
      treatmentPlan: p.treatmentPlan||[],
      xrayReports: p.xrayReports||[],
      signedConsents: p.signedConsents||[],
      surveys: p.surveys||[],
      emiPlans: p.emiPlans||[],
      timeLogs: p.timeLogs||[],
      rctLog: p.rctLog||[],
      creditWallet: p.creditWallet||{balance:0, transactions:[]}
    })),
    appointments: d.appointments||[],
    alignerCases: d.alignerCases||[],
    rxTemplates:  d.rxTemplates||[],
    labJobs:      d.labJobs||[],
    inventory:    d.inventory||[],
    queue:        d.queue||[],
    consentTemplates: d.consentTemplates||[],
    staffLog: d.staffLog||[],
    sterilLog: d.sterilLog||[],
    labJobs: d.labJobs||[],
    emiDashboard: d.emiDashboard||null,
    packages: d.packages||[],
    leads: d.leads||[],
    settings: d.settings || base.settings
  };
  return merged;
}

