var FINANCE_PAGES = ['expenses','finance','report'];
var APPT_PAGES    = ['appointments'];

function goPage(id) {
  curPage = id;
  document.querySelectorAll('.page').forEach(function(p){ p.classList.remove('active'); p.style.display='none'; });
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active','finance-active','appt-active'));
  const pg = document.getElementById('page-'+id);
  if(pg){ pg.classList.add('active'); pg.style.display='block'; }
  const nav = document.getElementById('nav-'+id);
  if (nav) nav.classList.add(FINANCE_PAGES.includes(id)?'finance-active':APPT_PAGES.includes(id)?'appt-active':'active');
  closeSidebar();
  const renders = {
    dashboard:renderDashboard, patients:function(){renderPatientList();setTimeout(searchHist_render,50);},
    records:renderRecordsGlobal, images:renderImagesGlobal,
    billing:renderBillingGlobal, dues:renderDuesDashboard,
    'fee-schedule':function(){feeSchedule_renderPage();},
    'wa-templates':function(){waMsgs_renderPage();}, ortho:renderOrthoList,
    analytics:analytics_render, staff:renderStaffPage, steril:renderSterilPage, expenses:renderExpenses, report:renderReport, leads:renderLeads, 'pending-tx':renderPendingTx, packages:pkg_renderPage, perio:perio_render, 'photo-protocol':function(){photoProtocol_renderSession('new');}, waitingroom:wr_renderPending, education:renderEduGrid,
    appointments:renderAppointments, fmr:renderFMRPage, backup:function(){ renderBackupPage(); setTimeout(storage_renderMonitor,100); },
    aligner:renderAlignerPage, 'rx-templates':rxTpl_render,
    lab:lab_render, inventory:inv_render, queue:queue_render, consent:consent_render,
    search:gsearch_render, recall:recall_render,
    finance: ()=>{renderFinance();chart_inject();setTimeout(()=>{fin_initYearSelects();fin_renderHistory();},50);},
    bulkwa: bulkwa_render,
    'add-patient': function(){ var el=document.getElementById('reg-date-display'); if(el) el.textContent=new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}); },
  };
  if (renders[id]) renders[id]();
}

var activePt   = null;
var activeTab  = 'records';
var curPage    = 'dashboard';
var imgGlobalFilter = 'All';
var imgTabFilter    = 'All';

function openSidebar(){document.getElementById('sidebar').classList.add('open');document.getElementById('overlay').classList.add('open')}
