  h+='<button class="btn btn-sm" style="background:#7c3aed;color:#fff;border:none;font-weight:700" onclick="beforeAfter_open()">📸 Before/After</button>';
  h+='</div></div>';

  // Live Camera panel (Hidden by default, opened via cam_open)
  h+='<div id="cam-panel" style="display:none;background:#0f172a;border-radius:16px;padding:16px;margin-bottom:18px;border:1.5px solid #0284c7;box-shadow:0 8px 24px rgba(0,0,0,0.4)">';
