  h+='<div style="color:#fff;font-weight:700;font-size:14px">🎥 Live Camera / Intraoral Capture</div>';
  h+='<div style="display:flex;gap:6px">';
  h+='<button class="btn btn-sm" style="background:#1e293b;color:#38bdf8;border:1px solid #334155" onclick="cam_flipCamera()">🔄 Flip Cam</button>';
  h+='<button class="btn btn-sm" style="background:#334155;color:#94a3b8;border:none" onclick="cam_close()">✕ Close</button>';
  h+='</div></div>';
