function setImgFilter(f){imgTabFilter=f;renderImagesTab();}

/* ══ IMAGE UPLOAD & LIGHTBOX ══ */
function uploadImages(e){
  var files=Array.from(e.target.files||[]); if(!files.length)return;
  var totalMB=files.reduce(function(s,f){return s+f.size;},0)/1024/1024;
  if(totalMB>15){if(!confirm('Total size is '+totalMB.toFixed(1)+'MB. Large images may slow the app. Continue?'))return;}
  
  showLoading('Uploading ' + files.length + ' image(s) to cloud...');
  
  var done=0;
  var idx2=DATA.patients.findIndex(function(p){return p.id===activePt.id;});
  if(idx2<0) { hideLoading(); return; }

  files.forEach(function(file){
    var reader=new FileReader();
    reader.onload=async function(ev){
      try {
        const secureUrl = await uploadToCloudinary(ev.target.result);
        if(!DATA.patients[idx2].images) DATA.patients[idx2].images=[];
        DATA.patients[idx2].images.push({
          id:'img'+Date.now()+Math.random().toString(36).slice(2),
          src:secureUrl,
          name:file.name,
          category: imgTabFilter && imgTabFilter!=='All' ? imgTabFilter : 'Clinical Photo',
          date:todayISO()
        });
        activePt=DATA.patients[idx2];
      } catch (err) {
        console.error('Cloudinary upload error:', err);
        alert('Failed to upload image ' + file.name + ': ' + err.message);
      } finally {
        done++;
        if(done===files.length){
          await saveData();
          hideLoading();
          renderImagesTab();
        }
      }
    };
    reader.readAsDataURL(file);
  });
}

function openLightboxById(imgId){
  var img=null;
  // Search activePt first (fastest), then all patients
  if(activePt) img=(activePt.images||[]).find(function(x){return x.id===imgId;})||null;
  if(!img){
    for(var i=0;i<(DATA.patients||[]).length;i++){
      var found=(DATA.patients[i].images||[]).find(function(x){return x.id===imgId;});
      if(found){img=found;break;}
    }
  }
  if(!img)return;
  var lb=document.getElementById('lightbox');
  var lbImg=document.getElementById('lb-img');
  if(lb&&lbImg){
    lbImg.src=img.src;
    lb.classList.add('open');
    // Keyboard close
    lb._keyHandler=function(e){if(e.key==='Escape')closeLightbox();};
    document.addEventListener('keydown',lb._keyHandler,{once:true});
  }
}

/* ══ X-RAY REPORT IMPORT ══ */
function importXrayReport(e){
  var file=e.target.files[0]; if(!file)return;
  if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){
    alert('Please select a PDF file from your Eighteeth/AI X-ray software.');
    e.target.value=''; return;
  }
  var sizeMB=file.size/1024/1024;
  if(sizeMB>20){
    if(!confirm('This PDF is '+sizeMB.toFixed(1)+'MB. Large files may slow down the app. Continue?')){
      e.target.value=''; return;
    }
  }

  showLoading('Uploading X-ray PDF report to cloud...');

  var reader=new FileReader();
  reader.onload=async function(ev){
    try {
      const idx=DATA.patients.findIndex(function(p){return p.id===activePt.id;});
      if(idx<0) { hideLoading(); return; }
      
      const secureUrl = await uploadToCloudinary(ev.target.result, 'raw'); // raw for PDF
      
      if(!DATA.patients[idx].xrayReports) DATA.patients[idx].xrayReports=[];
      var rpt={
        id:'xr'+Date.now(),
        name:file.name.replace(/\.pdf$/i,''),
        date:todayISO(),
        data:secureUrl, // Hosted on Cloudinary
        size:sizeMB.toFixed(1)+'MB',
        findings:''
      };
      DATA.patients[idx].xrayReports.push(rpt);
      activePt=DATA.patients[idx];
      await saveData();
      renderImagesTab();
      alert('✅ AI X-ray Report uploaded and imported successfully!');
    } catch (err) {
      console.error('Cloudinary PDF upload error:', err);
      alert('Failed to upload PDF report: ' + err.message);
    } finally {
      hideLoading();
    }
  };
  reader.readAsDataURL(file);
  e.target.value='';
}

function viewXrayReport(rptId){
  var rpt=(activePt.xrayReports||[]).find(function(r){return r.id===rptId;});
  if(!rpt){alert('Report not found.');return;}
  // Open PDF in new tab
  var pw=window.open('','_blank');
  if(pw){
    pw.document.write(
      '<html><head><title>'+esc(rpt.name)+'</title></head><body style="margin:0">'+
      '<embed src="'+rpt.data+'" type="application/pdf" width="100%" height="100%" style="min-height:100vh"/>'+
      '</body></html>'
    );
    pw.document.close();
  }
}

function downloadXrayReport(rptId){
  var rpt=(activePt.xrayReports||[]).find(function(r){return r.id===rptId;});
  if(!rpt)return;
  var a=document.createElement('a');
  a.href=rpt.data;
  a.download=rpt.name+'.pdf';
  a.click();
}

function deleteXrayReport(rptId){
  if(!confirm('Delete this X-ray report?'))return;
  var idx=DATA.patients.findIndex(function(p){return p.id===activePt.id;});
  DATA.patients[idx].xrayReports=(DATA.patients[idx].xrayReports||[]).filter(function(r){return r.id!==rptId;});
  activePt=DATA.patients[idx];
  saveData();
  renderImagesTab();
}

/* ══════════════════════════════════════════
   LIVE CAMERA & INTRAORAL CAPTURE
   Supports: USB Intraoral cameras (Unicorn etc),
   Laptops/Webcams, Mobile Front/Back cameras,
   Foot pedals, Gamepads & Hardware buttons.
══════════════════════════════════════════ */
var cam_stream = null;
var cam_devices = [];
var cam_currentDeviceIndex = 0;

async function cam_open(){
  if(!activePt){ alert('Please select a patient first.'); return; }
  var panel = document.getElementById('cam-panel');
  if(!panel) return;
  panel.style.display = 'block';
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  await cam_initDevicesAndStream();
}

function cam_close(){
  cam_stop();
  var panel = document.getElementById('cam-panel');
  if(panel) panel.style.display = 'none';
  cam_stopGamepadWatch();
}

function cam_stop(){
  if(cam_stream){
    cam_stream.getTracks().forEach(function(t){ t.stop(); });
    cam_stream = null;
  }
  var vid = document.getElementById('cam-video');
  if(vid) vid.srcObject = null;
}

async function cam_initDevicesAndStream(){
  cam_showError(''); // clear errors
  try {
    if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia){
      throw new Error('Camera API requires HTTPS or localhost.');
    }

    // First request permission to unlock device labels
    var initialStream = await navigator.mediaDevices.getUserMedia({
      video: { width: { ideal: 1920 }, height: { ideal: 1080 } },
      audio: false
    });
    
    // Stop temporary stream immediately
    initialStream.getTracks().forEach(function(t){ t.stop(); });

    // Enumerate devices
    var devices = await navigator.mediaDevices.enumerateDevices();
    cam_devices = devices.filter(function(d){ return d.kind === 'videoinput'; });

    var select = document.getElementById('cam-device-select');
    if(select){
      select.innerHTML = '';
      if(cam_devices.length === 0){
        select.innerHTML = '<option>Default Camera</option>';
      } else {
        cam_devices.forEach(function(d, idx){
          var opt = document.createElement('option');
          opt.value = d.deviceId;
          opt.textContent = d.label || ('Camera ' + (idx + 1));
          select.appendChild(opt);
        });
      }
    }

    // Start with the first video device
    var targetId = cam_devices.length > 0 ? cam_devices[0].deviceId : null;
    await cam_startStream(targetId);
    cam_startGamepadWatch();
  } catch(err) {
    console.error('Camera init error:', err);
    cam_showError('⚠️ Camera error: ' + err.message + '. Please ensure camera permissions are allowed.');
  }
}

async function cam_startStream(deviceId){
  cam_stop();
  var constraints = {
    audio: false,
    video: {
      width: { ideal: 1920 },
      height: { ideal: 1080 }
    }
  };
  if(deviceId){
    constraints.video.deviceId = { exact: deviceId };
  } else {
    constraints.video.facingMode = 'environment';
  }

  try {
    cam_stream = await navigator.mediaDevices.getUserMedia(constraints);
    var vid = document.getElementById('cam-video');
    if(vid){
      vid.srcObject = cam_stream;
      await vid.play();
    }
  } catch(err) {
    console.warn('Exact constraint failed, trying fallback stream...', err);
    try {
      cam_stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      var vid = document.getElementById('cam-video');
      if(vid){
        vid.srcObject = cam_stream;
        await vid.play();
      }
    } catch(err2) {
      cam_showError('Could not start video stream: ' + err2.message);
    }
  }
}

function cam_switchDevice(deviceId){
  cam_startStream(deviceId);
}

function cam_flipCamera(){
  if(cam_devices.length <= 1) return;
  cam_currentDeviceIndex = (cam_currentDeviceIndex + 1) % cam_devices.length;
  var nextDev = cam_devices[cam_currentDeviceIndex];
  var select = document.getElementById('cam-device-select');
  if(select && nextDev){
    select.value = nextDev.deviceId;
    cam_switchDevice(nextDev.deviceId);
  }
}

function cam_showError(msg){
  var existing = document.getElementById('cam-error-msg');
  if(existing) existing.remove();
  if(!msg) return;
  var errDiv = document.createElement('div');
  errDiv.id = 'cam-error-msg';
  errDiv.style.cssText = 'color:#f87171;font-size:12px;text-align:center;padding:12px 14px;background:#1e293b;border-radius:8px;margin-bottom:12px;line-height:1.5;border:1px solid #7f1d1d';
  errDiv.textContent = msg;
  var video = document.getElementById('cam-video');
  if(video && video.parentNode) video.parentNode.insertBefore(errDiv, video);
}

function cam_capture(){
  cam_doCapture();
}

async function cam_doCapture(){
  var vid = document.getElementById('cam-video');
  var canvas = document.getElementById('cam-canvas');
  if(!vid || !canvas || !cam_stream) {
    alert('No active camera feed. Please open the camera first.');
    return;
  }

  // Draw current frame to canvas
  var w = vid.videoWidth || 1280;
  var h = vid.videoHeight || 720;
  canvas.width = w;
  canvas.height = h;
  var ctx = canvas.getContext('2d');
  ctx.drawImage(vid, 0, 0, w, h);

  var rawDataURL = canvas.toDataURL('image/jpeg', 0.88);
  var cat = (document.getElementById('cam-cat-select') || {}).value || 'Intraoral';
  var timestamp = new Date().toTimeString().slice(0,8).replace(/:/g,'');

  var idx = DATA.patients.findIndex(function(p){ return p.id === activePt.id; });
  if(idx < 0){ alert('No active patient selected.'); return; }
  if(!DATA.patients[idx].images) DATA.patients[idx].images = [];

  var imgSrc = rawDataURL;
  try {
    showLoading('Uploading photo to Cloudinary...');
    imgSrc = await uploadToCloudinary(rawDataURL, 'image');
    hideLoading();
  } catch(cErr) {
    hideLoading();
    console.warn('Cloudinary upload failed, falling back to local base64:', cErr);
    try { imgSrc = await compressBase64Image(rawDataURL); } catch(e) {}
  }

  var newImage = {
    id: 'cam' + Date.now(),
    src: imgSrc,
    name: 'Photo_' + todayISO() + '_' + timestamp + '.jpg',
    category: cat,
    date: todayISO()
  };

  DATA.patients[idx].images.unshift(newImage);
  activePt = DATA.patients[idx];
  saveData();

  // Visual flash feedback
  var btn = document.getElementById('cam-capture-btn');
  if(btn){
    var orig = btn.innerHTML;
    btn.innerHTML = '✅ Saved!';
    btn.style.background = '#059669';
    setTimeout(function(){
      btn.innerHTML = orig;
      btn.style.background = '#0284c7';
    }, 1000);
  }

  // Refresh image grid below while preserving live camera
  var camPanel = document.getElementById('cam-panel');
  var isCamOpen = camPanel && camPanel.style.display !== 'none';
  renderImagesTab();
  if(isCamOpen){
    var newPanel = document.getElementById('cam-panel');
    if(newPanel) newPanel.style.display = 'block';
    var newVid = document.getElementById('cam-video');
    if(newVid && cam_stream) newVid.srcObject = cam_stream;
  }
}

async function cam_mobileCapture(input){
  var file = input.files && input.files[0];
  if(!file) return;
  showLoading('Saving mobile photo...');
  var reader = new FileReader();
  reader.onload = async function(ev){
    try {
      var compressed = await compressBase64Image(ev.target.result);
      var idx = DATA.patients.findIndex(function(p){ return p.id === activePt.id; });
      if(idx >= 0){
        if(!DATA.patients[idx].images) DATA.patients[idx].images = [];
        DATA.patients[idx].images.unshift({
          id: 'mob' + Date.now(),
          src: compressed,
          name: file.name || ('Mobile_' + todayISO() + '.jpg'),
          category: 'Intraoral',
          date: todayISO()
        });
        activePt = DATA.patients[idx];
        await saveData();
        renderImagesTab();
      }
    } catch(e){
      alert('Failed to save mobile photo: ' + e.message);
    } finally {
      hideLoading();
      input.value = '';
    }
  };
  reader.readAsDataURL(file);
}




/* ══════════════════════════════════════════
   NANOPIX X-RAY WATCHER
   Polls local Python server for new X-ray
   images saved by Nanopix software.
   Works via: python server.py
══════════════════════════════════════════ */
var xwatch_active   = false;
var xwatch_interval = null;
var xwatch_pending  = null;  // current unassigned image

function xwatch_toggle(){
  if(xwatch_active) { xwatch_stop(); return; }
  xwatch_start();
}

function xwatch_start(){
  // Check if server is running
  fetch('http://localhost:8080/api/xray-status')
    .then(function(r){return r.json();})
    .then(function(data){
      xwatch_active = true;
      var btn = document.getElementById('xray-watch-btn');
      if(btn){ btn.textContent='📡 Watching...'; btn.style.background='#16a34a'; }
      var panel = document.getElementById('xwatch-panel');
      if(panel) panel.style.display='block';
      var statusEl = document.getElementById('xwatch-status');
      if(statusEl){
        if(data.watching){
          statusEl.innerHTML = '✅ Connected · Watching: <span style="color:#fff;font-weight:600">'+data.directory+'</span>';
        } else {
          statusEl.innerHTML = '⚠️ Server running but Nanopix folder not found. <br>'+
            '<span style="color:#fbbf24">Edit server.py line 22 with your Nanopix output path.</span>';
        }
      }
      // Start polling every 1.5 seconds
      xwatch_interval = setInterval(xwatch_poll, 1500);
    })
    .catch(function(){
      var statusEl = document.getElementById('xwatch-status');
      if(statusEl) statusEl.innerHTML = '❌ Server not running. Start <b>StartServer.bat</b> first, then try again.';
      var panel = document.getElementById('xwatch-panel');
      if(panel) panel.style.display='block';
    });
}

function xwatch_stop(){
  xwatch_active = false;
  if(xwatch_interval){ clearInterval(xwatch_interval); xwatch_interval=null; }
  var btn = document.getElementById('xray-watch-btn');
  if(btn){ btn.textContent='📡 Watch X-ray'; btn.style.background='#dc2626'; }
  var panel = document.getElementById('xwatch-panel');
  if(panel) panel.style.display='none';
  xwatch_pending = null;
}

function xwatch_poll(){
  // Don't poll if we already have an unassigned image waiting
  if(xwatch_pending) return;
  fetch('http://localhost:8080/api/xray-next')
    .then(function(r){return r.json();})
    .then(function(data){
      if(!data.found) return;
      xwatch_pending = data;
      xwatch_showPreview(data);
    })
    .catch(function(){ /* server stopped */ });
}

function xwatch_showPreview(data){
  var preview = document.getElementById('xwatch-preview');
  var img     = document.getElementById('xwatch-img');
  var fname   = document.getElementById('xwatch-filename');
  if(!preview||!img) return;
  img.src = data.dataURL;
  if(fname) fname.textContent = '📁 '+data.filename+' · Detected just now';
  preview.style.display = 'block';
  // Vibrate/beep to alert doctor
  if(navigator.vibrate) navigator.vibrate([200,100,200]);
  // Flash the panel
  var panel = document.getElementById('xwatch-panel');
  if(panel){
    panel.style.border='2px solid #22c55e';
    setTimeout(function(){if(panel)panel.style.border='1.5px solid #4338ca';},1000);
  }
}

function xwatch_save(){
  if(!xwatch_pending){return;}
  var cat = (document.getElementById('xwatch-cat')||{}).value || 'IOPA X-Ray';
  var idx2 = DATA.patients.findIndex(function(p){return p.id===activePt.id;});
  if(idx2<0){alert('No patient selected.');return;}
  if(!DATA.patients[idx2].images) DATA.patients[idx2].images=[];
  DATA.patients[idx2].images.push({
    id: 'xray'+Date.now(),
    src: xwatch_pending.dataURL,
    name: xwatch_pending.filename,
    category: cat,
    date: todayISO()
  });
  activePt = DATA.patients[idx2];
  saveData();
  xwatch_pending = null;
  // Hide preview, keep watching
  var preview = document.getElementById('xwatch-preview');
  if(preview) preview.style.display='none';
  var statusEl = document.getElementById('xwatch-status');
  if(statusEl) statusEl.innerHTML = '✅ Saved! Watching for next X-ray...';
  // Re-render images grid (keep camera/watch panels open)
  var camDisplay   = (document.getElementById('cam-panel')||{}).style&&document.getElementById('cam-panel').style.display;
  var watchDisplay = (document.getElementById('xwatch-panel')||{}).style&&document.getElementById('xwatch-panel').style.display;
  renderImagesTab();
  var cp = document.getElementById('cam-panel');    if(cp && camDisplay)   cp.style.display = camDisplay;
  var wp = document.getElementById('xwatch-panel'); if(wp && watchDisplay) wp.style.display = watchDisplay;
}

function xwatch_skip(){
  xwatch_pending = null;
  var preview = document.getElementById('xwatch-preview');
  if(preview) preview.style.display='none';
  var statusEl = document.getElementById('xwatch-status');
  if(statusEl) statusEl.innerHTML = '⏭ Skipped · Watching for next X-ray...';
}
/* ══════════════════════════════════════════
   UNICORN CAMERA HARDWARE BUTTON SUPPORT
   Intraoral cameras send keypress signals.
   We listen for ALL common trigger keys
   simultaneously — no setup needed.
   Also handles mouse-click cameras and
   gamepad-mode cameras (USB HID).
══════════════════════════════════════════ */

// ── Camera hardware button system ──
// Unicorn DenMart sends a key signal when photo button is pressed.
// We detect which key by logging ALL keypresses when camera is open.
// Then map that key permanently.

var cam_lastCaptureTime = 0;
var cam_mappedKey = localStorage.getItem('cam_key') || null;
var cam_logMode = false; // key detection mode

function cam_isCameraOpen(){
  var panel = document.getElementById('cam-panel');
  return panel && panel.style.display !== 'none' && cam_stream;
}

// Listen for ANY key when camera is open
document.addEventListener('keydown', function(e){
  if(!cam_isCameraOpen()) return;

  // Key detection mode - log what key the camera sends
  if(cam_logMode){
    cam_logMode = false;
    cam_mappedKey = e.key;
    localStorage.setItem('cam_key', e.key);
    e.preventDefault();
    e.stopPropagation();
    var lbl = document.getElementById('cam-key-status');
    if(lbl){
      lbl.textContent = '✅ Mapped to: ' + (e.key===' '?'Space':e.key) + ' — Now press the button to capture!';
      lbl.style.color = '#34d399';
    }
    return;
  }

  // Normal capture mode
  // If key is mapped, only fire on that key
  // If no key mapped yet, fire on ANY key (broad detection)
  var now = Date.now();
  if(now - cam_lastCaptureTime < 800) return;

  var shouldCapture = false;
  if(cam_mappedKey){
    shouldCapture = (e.key === cam_mappedKey);
  } else {
    // No key mapped - capture on any non-modifier key
    var skip = ['Shift','Control','Alt','Meta','Tab','Escape','CapsLock'];
    shouldCapture = skip.indexOf(e.key) < 0;
  }

  if(shouldCapture){
    e.preventDefault();
    e.stopPropagation();
    cam_lastCaptureTime = now;
    cam_doCapture();
  }
}, true);

// Tap video to capture
function cam_videoClick(){
  if(!cam_stream) return;
  var now = Date.now();
  if(now - cam_lastCaptureTime < 800) return;
  cam_lastCaptureTime = now;
  cam_doCapture();
}

// Gamepad (USB HID cameras)
var cam_gamepadInterval = null;
function cam_startGamepadWatch(){
  if(cam_gamepadInterval) return;
  cam_gamepadInterval = setInterval(function(){
    if(!cam_isCameraOpen()){ cam_stopGamepadWatch(); return; }
    var pads = navigator.getGamepads ? navigator.getGamepads() : [];
    for(var i=0;i<pads.length;i++){
      var pad = pads[i]; if(!pad) continue;
      for(var b=0;b<pad.buttons.length;b++){
        if(pad.buttons[b].pressed){
          var now = Date.now();
          if(now - cam_lastCaptureTime < 800) return;
          cam_lastCaptureTime = now;
          cam_doCapture();
          return;
        }
      }
    }
  }, 100);
}
function cam_stopGamepadWatch(){
  if(cam_gamepadInterval){ clearInterval(cam_gamepadInterval); cam_gamepadInterval=null; }
}
window.addEventListener('gamepadconnected', function(){
  if(cam_isCameraOpen()) cam_startGamepadWatch();
});

function cam_startDetect(){
  cam_logMode = true;
  cam_mappedKey = null;
  var lbl = document.getElementById('cam-key-status');
  if(lbl){
    lbl.textContent = '👆 Now press the 📷 button on the camera...';
    lbl.style.color = '#fbbf24';
  }
  // Focus the page so key events are received
  window.focus();
  document.body.focus();
}

function cam_resetKey(){
  cam_mappedKey = null;
  localStorage.removeItem('cam_key');
  var lbl = document.getElementById('cam-key-status');
  if(lbl){ lbl.textContent = 'No key mapped — any key will capture'; lbl.style.color='#94a3b8'; }
}

/* ══════════════════════════════════════════
   NANOPIX X-RAY INTEGRATION
   Uses File System Access API (Chrome 86+)
   to watch Nanopix output folder and
   auto-import new X-ray images.
   Requires: localhost server (StartServer.bat)
══════════════════════════════════════════ */
var npx_dirHandle   = null;   // FileSystemDirectoryHandle
var npx_knownFiles  = new Set(); // already-seen filenames
var npx_autoTimer   = null;   // polling interval
var npx_autoActive  = false;
var npx_pendingFiles = [];    // files waiting to import

// Restore saved state
(function npx_init(){
  try {
    var saved = localStorage.getItem('npx_known');
    if(saved) npx_knownFiles = new Set(JSON.parse(saved));
  } catch(e){}
  // Restore directory handle from IndexedDB on page load
  setTimeout(npx_restoreHandle, 500);
})();

async function npx_restoreHandle(){
  try {
    var handle = await dbGet('npx_store', 'npx_dir_handle');
    if(!handle) return;
    // Ask for permission silently
    var perm = await handle.queryPermission({mode:'read'});
    if(perm === 'granted'){
      npx_dirHandle = handle;
      npx_setStatus('📁 '+handle.name+' — ready','#34d399');
    } else if(perm === 'prompt'){
      // Store handle, show button to re-grant
      npx_dirHandle = handle;
      npx_pendingPermission = true;
    }
  } catch(e){ /* handle may be stale */ }
}

var npx_pendingPermission = false;

async function npx_requestPermission(){
  if(!npx_dirHandle) return;
  try {
    var perm = await npx_dirHandle.requestPermission({mode:'read'});
    if(perm === 'granted'){
      npx_pendingPermission = false;
      npx_setStatus('📁 '+npx_dirHandle.name+' — ready','#34d399');
      var lbl = document.getElementById('npx-folder-label');
      if(lbl){ lbl.style.color='#7dd3fc'; lbl.textContent='📁 '+npx_dirHandle.name; }
    }
  } catch(e){ npx_setStatus('Permission error: '+e.message,'#f87171'); }
}

function npx_openPanel(){
  var panel = document.getElementById('npx-panel');
  if(!panel) return;
  if(!window.showDirectoryPicker){
    alert('Nanopix integration requires Chrome on desktop. Run via: http://localhost:8080');
    return;
  }
  panel.style.display = 'block';
  npx_restoreUI();
}

function npx_closePanel(){
  var panel = document.getElementById('npx-panel');
  if(panel) panel.style.display = 'none';
}

function npx_restoreUI(){
  var lbl = document.getElementById('npx-folder-label');
  if(lbl && npx_dirHandle){
    lbl.style.color = '#7dd3fc';
    lbl.textContent = '📁 ' + npx_dirHandle.name;
  }
  npx_setAutoSlider(npx_autoActive);
  // If permission needs to be re-granted, show a button
  if(npx_pendingPermission){
    var setup = document.getElementById('npx-setup');
    if(setup){
      var btn = document.createElement('button');
      btn.className = 'btn btn-sm';
      btn.style.cssText = 'background:#d97706;color:#fff;border:none;margin-top:8px;width:100%';
      btn.textContent = '🔓 Re-allow Folder Access (one click)';
      btn.onclick = npx_requestPermission;
      setup.appendChild(btn);
    }
  }
}

function npx_setAutoSlider(on){
  var slider = document.getElementById('npx-auto-slider');
  var knob   = document.getElementById('npx-auto-knob');
  var toggle = document.getElementById('npx-auto-toggle');
  if(slider) slider.style.background = on ? '#0369a1' : '#334155';
  if(knob)   knob.style.transform    = on ? 'translateX(20px)' : 'translateX(0)';
  if(toggle) toggle.checked = on;
}

async function npx_pickFolder(){
  if(!window.showDirectoryPicker){
    alert('File System Access API not available. Use Chrome on desktop via localhost:8080');
    return;
  }
  try {
    npx_dirHandle = await window.showDirectoryPicker({mode:'read'});
    // Seed known files recursively (don't import existing ones, only NEW ones from now)
    npx_knownFiles.clear();
    var existingFiles = await npx_collectFiles(npx_dirHandle, 4);
    existingFiles.forEach(function(f){ npx_knownFiles.add(f._key); });
    localStorage.setItem('npx_known', JSON.stringify([...npx_knownFiles]));
    // Persist handle in IndexedDB so it survives page refresh
    try { await dbSet('npx_store', 'npx_dir_handle', npx_dirHandle); } catch(e){}

    var lbl = document.getElementById('npx-folder-label');
    if(lbl){ lbl.style.color='#7dd3fc'; lbl.textContent='📁 '+npx_dirHandle.name+' ('+npx_knownFiles.size+' existing files indexed)'; }
    npx_setStatus('✅ Folder saved! Will auto-reconnect on restart.','#34d399');
  } catch(e){
    if(e.name !== 'AbortError') npx_setStatus('Error: '+e.message,'#f87171');
  }
}

async function npx_scanFolder(){
  if(!npx_dirHandle){ alert('Select the Nanopix folder first.'); return; }
  npx_setStatus('🔍 Scanning subfolders...','#7dd3fc');
  try {
    var newFiles = await npx_collectFiles(npx_dirHandle, 4); // scan 4 levels deep
    var fresh = newFiles.filter(function(f){ return !npx_knownFiles.has(f._key); });
    if(fresh.length === 0){
      npx_setStatus('No new X-rays found. Take an X-ray in Nanopix then scan again.','#94a3b8');
      return;
    }
    npx_setStatus('Found '+fresh.length+' new X-ray'+(fresh.length>1?'s':'')+'!','#34d399');
    npx_showQueue(fresh);
  } catch(e){
    npx_setStatus('Scan error: '+e.message+' — Re-select the folder.','#f87171');
    npx_dirHandle = null;
  }
}

// Recursively collect image files from a directory handle up to maxDepth levels
async function npx_collectFiles(dirHandle, maxDepth){
  var results = [];
  if(maxDepth <= 0) return results;
  try {
    for await (var entry of dirHandle.values()){
      if(entry.kind === 'file' && npx_isXray(entry.name)){
        entry._key  = dirHandle.name + '/' + entry.name; // unique key incl. folder
        entry._dir  = dirHandle.name;
        results.push(entry);
      } else if(entry.kind === 'directory'){
        var sub = await npx_collectFiles(entry, maxDepth - 1);
        results = results.concat(sub);
      }
    }
  } catch(e){ /* skip inaccessible dirs */ }
  return results;
}

function npx_isXray(name){
  return /\.(jpg|jpeg|bmp|png|tif|tiff|dcm)$/i.test(name);
}

function npx_showQueue(entries){
  npx_pendingFiles = entries;
  var qEl = document.getElementById('npx-queue');
  var listEl = document.getElementById('npx-queue-list');
  if(!qEl||!listEl) return;
  qEl.style.display = 'block';
  var h = '';
  entries.forEach(function(entry, i){
    h += '<div style="display:flex;align-items:center;justify-content:space-between;background:#1e3a5f;border-radius:8px;padding:8px 12px">';
    h += '<div style="font-size:12px;font-weight:600;color:#e2e8f0">'+entry.name+'</div>';
    h += '<div style="display:flex;gap:6px">';
    h += '<button class="btn btn-sm" style="background:#0369a1;color:#fff;border:none;font-size:11px" data-idx="'+i+'" onclick="npx_importOne(this.dataset.idx)">Import as IOPA</button>';
    h += '<button class="btn btn-sm" style="background:#7c3aed;color:#fff;border:none;font-size:11px" data-idx="'+i+'" onclick="npx_importOne(this.dataset.idx,true)">Import as OPG</button>';
    h += '</div></div>';
  });
  if(entries.length > 1){
    h += '<button class="btn btn-primary btn-sm" style="width:100%;margin-top:6px" onclick="npx_importAll()">⬇️ Import All as IOPA X-Ray</button>';
  }
  listEl.innerHTML = h;
}

async function npx_importOne(idxStr, asOPG){
  var i = Number(idxStr);
  var entry = npx_pendingFiles[i];
  if(!entry) return;
  var cat = asOPG ? 'OPG' : 'IOPA X-Ray';
  await npx_doImport(entry, cat);
  // Remove from pending
  npx_pendingFiles.splice(i, 1);
  npx_markKnown(entry._key || entry.name);
  if(npx_pendingFiles.length === 0){
    var qEl = document.getElementById('npx-queue');
    if(qEl) qEl.style.display = 'none';
    npx_setStatus('✅ All imported!','#34d399');
  } else {
    npx_showQueue(npx_pendingFiles);
  }
}

async function npx_importAll(){
  var entries = npx_pendingFiles.slice();
  for(var i=0;i<entries.length;i++){
    await npx_doImport(entries[i],'IOPA X-Ray');
    npx_markKnown(entries[i]._key || entries[i].name);
  }
  npx_pendingFiles = [];
  var qEl = document.getElementById('npx-queue');
  if(qEl) qEl.style.display = 'none';
  npx_setStatus('✅ '+entries.length+' X-ray'+(entries.length>1?'s':'')+' imported!','#34d399');
}

async function npx_doImport(entry, category){
  var ptIdx = DATA.patients.findIndex(function(p){return p.id===activePt.id;});
  if(ptIdx<0) return;
  try {
    var file   = await entry.getFile();
    var reader = new FileReader();
    var dataURL = await new Promise(function(resolve,reject){
      reader.onload=function(e){resolve(e.target.result);};
      reader.onerror=reject;
      reader.readAsDataURL(file);
    });
    if(!DATA.patients[ptIdx].images) DATA.patients[ptIdx].images=[];
    DATA.patients[ptIdx].images.push({
      id:'npx'+Date.now()+Math.random().toString(36).slice(2),
      src:dataURL,
      name:entry.name,
      category:category,
      date:todayISO(),
      source:'nanopix'
    });
    activePt = DATA.patients[ptIdx];
    saveData();
    // Re-render grid keeping panel open
    var panel = document.getElementById('npx-panel');
    renderImagesTab();
    var newPanel = document.getElementById('npx-panel');
    if(newPanel) newPanel.style.display='block';
    npx_restoreUI();
  } catch(e){
    npx_setStatus('Import error: '+e.message,'#f87171');
  }
}

function npx_markKnown(keyOrName){
  npx_knownFiles.add(keyOrName);
  try { localStorage.setItem('npx_known', JSON.stringify([...npx_knownFiles])); } catch(e){}
}

function npx_toggleAuto(on){
  npx_autoActive = on;
  npx_setAutoSlider(on);
  if(on){
    if(!npx_dirHandle){ alert('Select Nanopix folder first.'); npx_setAutoSlider(false); npx_autoActive=false; return; }
    npx_setStatus('⚡ Auto-import active — watching every 3 seconds...','#34d399');
    npx_autoTimer = setInterval(npx_autoScan, 3000);
  } else {
    clearInterval(npx_autoTimer);
    npx_autoTimer = null;
    npx_setStatus('Auto-import stopped.','#94a3b8');
  }
}

async function npx_autoScan(){
  if(!npx_dirHandle||!npx_autoActive) return;
  try {
    var allFiles = await npx_collectFiles(npx_dirHandle, 4);
    var newFiles = allFiles.filter(function(f){ return !npx_knownFiles.has(f._key); });
    if(newFiles.length>0){
      npx_setStatus('⚡ '+newFiles.length+' new X-ray detected — importing...','#fbbf24');
      for(var i=0;i<newFiles.length;i++){
        await npx_doImport(newFiles[i],'IOPA X-Ray');
        npx_markKnown(newFiles[i]._key || newFiles[i].name);
      }
      npx_setStatus('✅ Auto-imported '+newFiles.length+' X-ray'+(newFiles.length>1?'s':'')+'!','#34d399');
    }
  } catch(e){
    // Folder permission may have expired — stop auto
    clearInterval(npx_autoTimer);
    npx_autoActive=false;
    npx_setAutoSlider(false);
    npx_setStatus('⚠️ Auto-import stopped: re-select folder.','#f87171');
  }
}

function npx_setStatus(msg, color){
  var el = document.getElementById('npx-status');
  if(el){ el.textContent=msg; el.style.color=color||'#94a3b8'; }
}





function updateImgCat(imgId,cat){
  const idx=DATA.patients.findIndex(p=>p.id===activePt.id);
  DATA.patients[idx].images=DATA.patients[idx].images.map(i=>i.id===imgId?{...i,category:cat}:i);
  activePt=DATA.patients[idx]; saveData();
}
function deleteImg(imgId){
  if(!confirm('Delete image?'))return;
  const idx=DATA.patients.findIndex(p=>p.id===activePt.id);
  DATA.patients[idx].images=DATA.patients[idx].images.filter(i=>i.id!==imgId);
  activePt=DATA.patients[idx]; saveData(); renderImagesTab();
}

/* ── PRESCRIPTIONS TAB ── */
var activeRxId=null;
function renderPrescriptionsTab(){
  const p=activePt; const rxs=p.prescriptions||[];
  const rx=rxs.find(r=>r.id===activeRxId)||rxs[0]||null;
  if(rx&&!activeRxId) activeRxId=rx.id;
  document.getElementById('tab-content-prescriptions').innerHTML=`
    <div style="display:grid;grid-template-columns:${rx?'250px 1fr':'1fr'};gap:20px">
      <div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
          <div class="sec-title" style="margin:0">Prescriptions</div>
          <button class="btn btn-primary btn-sm" onclick="newRx()">+ New Rx</button>
          <button class="btn btn-sm" onclick="rxCalib_showTool()" style="background:#f1f5f9;color:#475569;border:1px solid #e2e8f0;margin-left:4px" title="Calibrate print margins for your pad">⚙️ Margins</button>${activePt&&activePt.type==='pediatric'?'<button class="btn btn-sm" style="background:#f59e0b;color:#fff;border:none;margin-left:6px" onclick="pedo_showDoseCalc()">🦷 Pedo Doses</button>':''}
        </div>
        ${rxs.length===0?`<div class="empty" style="border:1px solid #e2e8f0;border-radius:14px"><span class="empty-icon">💊</span><div class="empty-title">No prescriptions yet</div></div>`
        :rxs.map(r=>`<div onclick="selectRx('${r.id}')" style="background:${activeRxId===r.id?'#eff6ff':'#fff'};border-radius:12px;padding:12px 14px;margin-bottom:8px;border:1.5px solid ${activeRxId===r.id?'#bfdbfe':'#e2e8f0'};cursor:pointer">
          <div style="display:flex;justify-content:space-between">
            <div>
              <div style="font-size:13px;font-weight:700;color:#1e293b">${fmtDate(r.date)}</div>
              <div style="font-size:11px;color:#64748b;margin-top:2px">${esc((r.diagnosis||'No diagnosis').slice(0,30))}</div>
              <div style="font-size:10px;color:#94a3b8;margin-top:1px">${(r.medicines||[]).filter(m=>m.name).length} medicines</div>
            </div>
            <div style="display:flex;gap:4px;align-items:flex-start">
              <button class="btn btn-sm" style="background:#dcfce7;color:#16a34a;padding:4px 7px" onclick="event.stopPropagation();shareRxWA('${r.id}')">WA</button>
              <button class="btn btn-red btn-sm" style="padding:4px 7px" onclick="event.stopPropagation();deleteRx('${r.id}')">x</button>
            </div>
          </div>
        </div>`).join('')}
      </div>
      ${rx?rxEditorHTML(rx):''}
    </div>`;
}
function rxEditorHTML(rx){return`
  <div>
    <div style="background:#1e3a5f;border-radius:14px 14px 0 0;padding:13px 18px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">
      <div><div style="color:white;font-weight:700;font-size:14px;font-family:'Playfair Display',serif">Rx - ${fmtDate(rx.date)}</div><div style="color:#93c5fd;font-size:11px">${esc(activePt.name)}, ${activePt.age}y</div></div>
      <div style="display:flex;gap:7px;flex-wrap:wrap;align-items:center">
        <select style="font-size:11px;padding:5px 10px;background:#1e3a5f;color:#93c5fd;border:1.5px solid #3b82f6;border-radius:8px;cursor:pointer;outline:none;font-family:'DM Sans',sans-serif" onchange="applyRxPreset('${rx.id}',this.value);this.value=''">
          <option value="">Load Template...</option>
          <optgroup label="Built-in">
          ${RX_PRESETS.map((p,i)=>`<option value="p_${i}">${p.label}</option>`).join('')}
          </optgroup>
          ${(DATA.rxTemplates&&DATA.rxTemplates.length)?`<optgroup label="⭐ My Templates">${DATA.rxTemplates.map(t=>`<option value="c_${t.id}">${t.label}</option>`).join('')}</optgroup>`:''}
        </select>
        <button class="btn btn-sm" style="background:#25D366;color:white" onclick="shareRxWA('${rx.id}')">WA Send</button>
        <button class="btn btn-sm" style="background:white;color:#1e3a5f" onclick="printRx('${rx.id}')">Print</button>
      </div>
    </div>
    <div class="card" style="border-radius:0 0 14px 14px;border-top:none;padding:20px">
      <div class="form-group"><label class="form-label">Diagnosis</label><input class="form-input" value="${esc(rx.diagnosis||'')}" placeholder="e.g. Dental caries on #16, #26" oninput="updateRxField('${rx.id}','diagnosis',this.value)"/></div>
      <div style="margin-bottom:16px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px">
          <label class="form-label" style="margin:0">Medicines</label>
          <button class="btn btn-sm" style="background:#eff6ff;color:#1d4ed8" onclick="addMed('${rx.id}')">+ Add Medicine</button>
        </div>
        <div style="font-size:10px;font-weight:700;color:#94a3b8;text-transform:uppercase;padding:4px 0 8px;border-bottom:1px solid #f1f5f9;margin-bottom:10px">Medicines &mdash; Name &bull; Type &bull; Dose &bull; Freq &bull; Timing &bull; Duration</div>
        <div id="meds-list-${rx.id}">${(rx.medicines||[]).map(m=>medRowHTML(rx.id,m)).join('')}</div>
      </div>
      <div class="form-group"><label class="form-label">Advice / Instructions</label><textarea class="form-input" rows="4" placeholder="Soft diet for 3 days, Avoid hot/cold, Return if pain persists" oninput="updateRxField('${rx.id}','advice',this.value)">${esc(rx.advice||'')}</textarea></div>
    </div>
  </div>`;}
function medRowHTML(rxId,m){
  var catBg={'Antibiotic':'#fef2f2','Painkiller':'#fff7ed','Anti-inflammatory':'#fffbeb','Antacid':'#f0fdf4','Antifungal':'#faf5ff','Vitamin':'#eff6ff','Mouthwash':'#f0fdfa'}[m.category||'']||'#f8fafc';
  return `<div style="background:${catBg};border:1.5px solid #e2e8f0;border-radius:10px;padding:10px 12px;margin-bottom:8px" id="med-row-${m.id}">
<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px">
  <input class="form-input" style="font-size:12px;padding:7px 9px;font-weight:600;flex:1" value="${esc(m.name)}" placeholder="Tab. Amoxicillin 500mg" oninput="updateMed('${rxId}','${m.id}','name',this.value)"/>
  <select class="form-input" style="font-size:11px;padding:6px 8px;width:145px" onchange="updateMed('${rxId}','${m.id}','category',this.value)">
    <option value="">Drug type…</option>
    ${['Antibiotic','Painkiller','Anti-inflammatory','Antacid','Antifungal','Antiseptic','Vitamin','Mouthwash','Gel/Ointment','Other'].map(function(cat){return '<option '+(((m.category||'')===cat)?'selected':'')+'>'+cat+'</option>';}).join('')}
  </select>
  <button class="btn btn-red btn-sm" style="padding:7px 10px;flex-shrink:0" onclick="deleteMed('${rxId}','${m.id}')">&#10005;</button>
</div>
<div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:7px">
  <div>
    <div style="font-size:9px;font-weight:700;color:#94a3b8;margin-bottom:3px">DOSE</div>
    <input class="form-input" style="font-size:12px;padding:6px 8px" value="${esc(m.dose||'')}" placeholder="500mg" oninput="updateMed('${rxId}','${m.id}','dose',this.value)"/>
  </div>
  <div>
    <div style="font-size:9px;font-weight:700;color:#94a3b8;margin-bottom:3px">FREQUENCY</div>
    <select class="form-input" style="font-size:12px;padding:6px 8px" onchange="updateMed('${rxId}','${m.id}','freq',this.value)">
      <option value="">—</option>
      ${['OD','BD','TDS','QID','SOS','HS','ON','PRN'].map(function(f){return '<option '+(((m.freq||'')===f)?'selected':'')+'>'+f+'</option>';}).join('')}
    </select>
  </div>
  <div>
    <div style="font-size:9px;font-weight:700;color:#94a3b8;margin-bottom:3px">TIMING</div>
    <select class="form-input" style="font-size:12px;padding:6px 8px" onchange="updateMed('${rxId}','${m.id}','timing',this.value)">
      <option value="">—</option>
      ${['After meals','Before meals','With meals','Empty stomach','At bedtime','With water','As directed'].map(function(t){return '<option '+(((m.timing||'')===t)?'selected':'')+'>'+t+'</option>';}).join('')}
    </select>
  </div>
  <div>
    <div style="font-size:9px;font-weight:700;color:#94a3b8;margin-bottom:3px">DURATION</div>
    <input class="form-input" style="font-size:12px;padding:6px 8px" value="${esc(m.duration||'')}" placeholder="5 Days" oninput="updateMed('${rxId}','${m.id}','duration',this.value)"/>
  </div>
</div>
</div>`;
}
function newRx(){
  const rx={id:Date.now().toString(),date:todayISO(),diagnosis:'',advice:'',medicines:[{id:'m'+Date.now(),name:'',dose:'',freq:'',duration:''}]};
  const idx=DATA.patients.findIndex(p=>p.id===activePt.id);
  DATA.patients[idx].prescriptions=[rx,...(DATA.patients[idx].prescriptions||[])];
  activePt=DATA.patients[idx]; activeRxId=rx.id; saveData(); renderPrescriptionsTab();
}
function applyRxPreset(rxId,val){
  if(!val)return;
  let preset=null;
  if(val.startsWith('p_')){
    preset=RX_PRESETS[parseInt(val.slice(2))];
  } else if(val.startsWith('c_')){
    preset=(DATA.rxTemplates||[]).find(t=>t.id===val.slice(2));
  }
  if(!preset)return;
  if(!confirm('Load template "'+preset.label+'"? This will replace current diagnosis, medicines, and advice.'))return;
  const idx=DATA.patients.findIndex(p=>p.id===activePt.id);
  DATA.patients[idx].prescriptions=DATA.patients[idx].prescriptions.map(r=>{
    if(r.id!==rxId)return r;
    return {...r,diagnosis:preset.diagnosis,advice:preset.advice,medicines:preset.medicines.map((m,i)=>({id:'m'+Date.now()+i,name:m.name,dose:m.dose,freq:m.freq,duration:m.duration}))};
  });
  activePt=DATA.patients[idx]; saveData(); renderPrescriptionsTab();
}
function selectRx(id){activeRxId=id;renderPrescriptionsTab()}
function deleteRx(id){if(!confirm('Delete this prescription?'))return;const idx=DATA.patients.findIndex(p=>p.id===activePt.id);DATA.patients[idx].prescriptions=DATA.patients[idx].prescriptions.filter(r=>r.id!==id);activePt=DATA.patients[idx];if(activeRxId===id)activeRxId=null;saveData();renderPrescriptionsTab();}
function updateRxField(rxId,field,val){const idx=DATA.patients.findIndex(p=>p.id===activePt.id);DATA.patients[idx].prescriptions=DATA.patients[idx].prescriptions.map(r=>r.id===rxId?{...r,[field]:val}:r);activePt=DATA.patients[idx];saveData();}
function addMed(rxId){const newM={id:'m'+Date.now(),name:'',dose:'',freq:'',duration:''};const idx=DATA.patients.findIndex(p=>p.id===activePt.id);DATA.patients[idx].prescriptions=DATA.patients[idx].prescriptions.map(r=>r.id===rxId?{...r,medicines:[...(r.medicines||[]),newM]}:r);activePt=DATA.patients[idx];saveData();const c=document.getElementById('meds-list-'+rxId);if(c)c.insertAdjacentHTML('beforeend',medRowHTML(rxId,newM));}
function updateMed(rxId,medId,field,val){const idx=DATA.patients.findIndex(p=>p.id===activePt.id);DATA.patients[idx].prescriptions=DATA.patients[idx].prescriptions.map(r=>r.id===rxId?{...r,medicines:(r.medicines||[]).map(m=>m.id===medId?{...m,[field]:val}:m)}:r);activePt=DATA.patients[idx];saveData();}
function deleteMed(rxId,medId){const idx=DATA.patients.findIndex(p=>p.id===activePt.id);DATA.patients[idx].prescriptions=DATA.patients[idx].prescriptions.map(r=>r.id===rxId?{...r,medicines:(r.medicines||[]).filter(m=>m.id!==medId)}:r);activePt=DATA.patients[idx];saveData();const el=document.getElementById('med-row-'+medId);if(el)el.remove();}

/* ── SHARE RX WA (FIXED) ── */
function shareRxWA(rxId){
  const rx=(activePt.prescriptions||[]).find(r=>r.id===rxId); if(!rx)return;
  const meds=(rx.medicines||[]).filter(m=>m.name).map((m,i)=>`${i+1}. ${m.name}${m.dose?' '+m.dose:''}${m.category?' ['+m.category+']':''} - ${[m.freq,m.timing].filter(Boolean).join(', ')||'as directed'}${m.duration?' x '+m.duration:''}`).join(String.fromCharCode(10));
  const lines = [
    CLINIC,
    DOCTOR + ' | ' + PHONE,
    '---',
    'Date: ' + fmtDate(rx.date),
    'Patient: ' + activePt.name + ' (' + activePt.age + 'y)',
    '',
    'Diagnosis: ' + (rx.diagnosis||'N/A'),
    '',
    'Medicines:',
    meds || 'None',
    '',
    rx.advice ? 'Advice:\n' + rx.advice : '',
    '',
    TIMING
  ].filter(l=>l!==undefined);
  const msg = lines.join(String.fromCharCode(10));
  window.open('https://wa.me/91'+activePt.phone+'?text='+encodeURIComponent(msg),'_blank');
}

/* ══════════════════════════════════════════════════════
   RX PRINT UPGRADE — Feature #14
   Letterhead-quality prescription: branding, seal, QR
   Read-only — no DATA writes
══════════════════════════════════════════════════════ */
function printRx(rxId){
  const rx=(activePt.prescriptions||[]).find(r=>r.id===rxId); if(!rx)return;
  const meds=(rx.medicines||[]).filter(m=>m.name);
  const p = activePt;

  /* ── Medicine rows ── */
  const medRowsHTML = meds.map(function(m,i){
    const freqTiming = [m.freq, m.timing].filter(Boolean).join(', ') || '—';
    const cat = m.category ? '<div style="font-size:7.5pt;color:#94a3b8;font-weight:400;margin-top:1px">'+esc(m.category)+'</div>' : '';
    return '<tr style="border-bottom:1px solid #edf0f5">'+
      '<td style="padding:8px 6px;font-size:11pt;font-weight:700;color:#1e3a5f;vertical-align:top;width:24px">'+(i+1)+'.</td>'+
      '<td style="padding:8px 8px;font-size:11pt;font-weight:700;vertical-align:top">'+esc(m.name)+cat+'</td>'+
      '<td style="padding:8px 8px;font-size:10.5pt;color:#374151;text-align:center;vertical-align:top">'+(m.dose||'—')+'</td>'+
      '<td style="padding:8px 10px;font-size:10.5pt;color:#374151;text-align:center;vertical-align:top">'+freqTiming+'</td>'+
      '<td style="padding:8px 6px;font-size:10.5pt;color:#374151;text-align:center;vertical-align:top;white-space:nowrap">'+(m.duration||'—')+'</td>'+
      '</tr>';
  }).join('');

  /* ── Diagnosis ── */
  const diagHTML = rx.diagnosis
    ? '<div style="font-size:10.5pt;margin-bottom:14px;padding:8px 12px;background:#f0f4fa;border-left:3px solid #1e3a5f;border-radius:0 6px 6px 0">'+
      '<span style="font-weight:800;color:#1e3a5f;font-size:9pt;text-transform:uppercase;letter-spacing:.4px">Diagnosis &nbsp;</span>'+
      '<span style="color:#1a1a1a">'+esc(rx.diagnosis)+'</span></div>'
    : '';

  /* ── Medicine table ── */
  const tableHTML = meds.length > 0
    ? '<table style="width:100%;border-collapse:collapse;margin-bottom:14px">'+
      '<thead><tr style="background:#1e3a5f;color:#fff">'+
      '<th style="padding:7px 6px;font-size:9pt;text-align:left;border-radius:4px 0 0 0">#</th>'+
      '<th style="padding:7px 8px;font-size:9pt;text-align:left">Medicine</th>'+
      '<th style="padding:7px 8px;font-size:9pt;text-align:center">Dose</th>'+
      '<th style="padding:7px 10px;font-size:9pt;text-align:center">Frequency</th>'+
      '<th style="padding:7px 6px;font-size:9pt;text-align:center;border-radius:0 4px 0 0">Duration</th>'+
      '</tr></thead><tbody>'+medRowsHTML+'</tbody></table>'
    : '<p style="color:#94a3b8;font-style:italic;font-size:10pt;margin:20px 0">No medicines prescribed.</p>';

  /* ── Advice ── */
  const adviceHTML = rx.advice
    ? '<div style="margin-top:12px;padding:10px 14px;border-left:3px solid #1e3a5f;background:#f8fafc;border-radius:0 6px 6px 0">'+
      '<p style="font-size:8.5pt;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:#1e3a5f;margin:0 0 5px">Advice / Instructions</p>'+
      '<div style="font-size:10.5pt;color:#374151;line-height:1.7;white-space:pre-wrap">'+esc(rx.advice)+'</div></div>'
    : '';

  /* ── Age/Sex line ── */
  const ageSex = [p.age ? p.age+' yrs' : '', p.gender || ''].filter(Boolean).join(' / ');
  const patientPhone = p.phone ? '&nbsp;&nbsp;&#128222;&nbsp;'+esc(p.phone) : '';
  const patientAddr  = p.address ? '<div style="font-size:9pt;color:#64748b;margin-top:2px">'+esc(p.address)+'</div>' : '';

  /* ── Date: right-aligned, positioned to sit at end of "Date ........." line ── */
  // The pad pre-prints "Date" on the right of the header area.
  // We print the date value right-aligned at the very top of the content area.
  const dateStr = fmtDate(rx.date);

  const html =
    '<!DOCTYPE html><html><head><meta charset="UTF-8">'+
    '<style>'+
    '@page{size:A4 portrait;margin:'+rxCalib_load().top+'mm '+rxCalib_load().right+'mm '+rxCalib_load().bottom+'mm '+rxCalib_load().left+'mm}'+
    'body{font-family:"Arial",sans-serif;color:#1a1a1a;font-size:11pt;margin:0;padding:0;line-height:1.4}'+
    '.rx-sym{font-size:28pt;font-weight:900;color:#1e3a5f;font-style:italic;line-height:1;margin-right:4px}'+
    '</style></head><body>'+

    /* Date — right-aligned as first content line, aligns with pad Date field */
    '<div style="display:flex;justify-content:flex-end;margin-bottom:6px">'+'<span style="font-size:11pt;font-weight:700;color:#1a1a1a">'+dateStr+'</span>'+'</div>'+

    /* Patient info block */
    '<div style="border:1.5px solid #1e3a5f;border-radius:8px;padding:10px 14px;margin-bottom:14px;background:#fafcff">'+
    '<div style="display:flex;align-items:baseline;gap:6px;margin-bottom:4px">'+
    '<span style="font-size:9pt;font-weight:700;color:#64748b;min-width:52px">Patient</span>'+
    '<span style="font-size:9pt;color:#64748b;margin-right:6px">:</span>'+
    '<span style="font-size:12pt;font-weight:800;color:#1e3a5f">'+esc(p.name)+'</span>'+
    (ageSex ? '<span style="font-size:9.5pt;color:#64748b;margin-left:auto">'+ageSex+'</span>' : '')+
    '</div>'+
    '<div style="display:flex;align-items:center;gap:6px">'+
    '<span style="font-size:9pt;font-weight:700;color:#64748b;min-width:52px">Contact</span>'+
    '<span style="font-size:9pt;color:#64748b;margin-right:6px">:</span>'+
    '<span style="font-size:10pt;color:#374151">'+(p.phone ? esc(p.phone) : '—')+patientPhone.replace('&#128222;&nbsp;'+esc(p.phone||''),'')+
    (p.address ? '&nbsp;&nbsp;|&nbsp;&nbsp;'+esc(p.address) : '')+'</span>'+
    '</div>'+
    '</div>'+

    /* Rx symbol + diagnosis + table + advice */
    '<div style="display:flex;align-items:flex-start;gap:4px;margin-bottom:10px">'+
    '<span class="rx-sym">℞</span>'+
    '<div style="flex:1">'+diagHTML+tableHTML+adviceHTML+'</div>'+
    '</div>'+

    /* Signature */
    '<div style="margin-top:28px;display:flex;justify-content:flex-end">'+
    '<div style="text-align:center;min-width:200px">'+
    '<div style="border-top:1.5px solid #1e3a5f;padding-top:8px">'+
    '<p style="font-weight:800;font-size:11.5pt;color:#1e3a5f;margin:0">'+DOCTOR+'</p>'+
    '<p style="font-size:9pt;color:#64748b;margin:3px 0">'+QUAL+'</p>'+
    '<p style="font-size:9pt;color:#64748b;margin:0">Reg. No. '+REG+'</p>'+
    '</div></div></div>'+

    /* Google Review QR */
    '<div style="margin-top:16px;display:flex;align-items:center;gap:14px;background:#f8fafc;border-radius:10px;padding:10px 14px;border:1px solid #e2e8f0">'+
    '<img src="data:image/jpeg;base64,'+GOOGLE_QR_B64+'" style="width:100px;height:100px;flex-shrink:0;border-radius:8px"/>'+
    '<div>'+
    '<p style="font-size:9.5pt;color:#1e3a5f;font-weight:800;margin:0 0 4px">&#11088; Rate us on Google!</p>'+
    '<p style="font-size:8.5pt;color:#374151;margin:0 0 3px">Scan with your phone camera &amp; share your experience.</p>'+
    '<p style="font-size:8pt;color:#64748b;margin:0 0 2px">Thank you for visiting <strong>The Home of Smiles</strong>.</p>'+
    '<p style="font-size:8pt;color:#64748b;margin:0">Next check-up in <strong>6 months</strong> &nbsp;&#9679;&nbsp; &#128222; '+PHONE+'</p>'+
    '</div></div>'+

    '<script>window.onload=function(){window.print();window.onafterprint=function(){window.close();};};<\/script>'+
    '</body></html>';

  const pw = window.open('','_blank','width=800,height=900');
  if(pw){ pw.document.write(html); pw.document.close(); }
}


/* ── BILLING TAB ── */
function renderBillingTab(){
  const p=activePt; const bills=p.billing||[];
  const total = bills.reduce(function(s,b){ return s+Number(b.totalAmount||b.amount||0); }, 0);
  const paid  = bills.reduce(function(s,b){ return s+Number(b.paidAmount||(b.paid?(b.totalAmount||b.amount||0):0)); }, 0);
  const due   = Math.max(0, total - paid);
  document.getElementById('tab-content-billing').innerHTML= billing_renderLabSection() + credit_renderWallet() + `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
      <div class="sec-title" style="margin:0">Billing</div>
      <div style="display:flex;gap:8px">
        <button class="btn btn-sm btn-wa" onclick="shareInvoiceWA()">WA Invoice</button>
        <button class="btn btn-primary btn-sm" onclick="showAddBill()">+ Add</button>
      <button class="btn btn-sm" style="background:#1e3a5f;color:#fff;border:none" onclick="invoice_generate(activePt.id)">🧾 Invoice</button>
      </div>
    </div>
    <div id="bill-form" style="display:none" class="alert-box alert-blue">
      <input type="hidden" id="bil-editid" value=""/>
      <div style="font-size:13px;font-weight:700;color:#1d4ed8;margin-bottom:10px" id="bil-form-title">➕ Add Billing Item</div>
      <div class="form-grid-3">
        <div class="form-group"><label class="form-label">Treatment / Item</label><input class="form-input" id="bil-item" placeholder="e.g. Root Canal" list="tx-list"/><datalist id="tx-list">${COMMON_TX.map(t=>`<option value="${t}"/>`).join('')}</datalist></div>
        <div class="form-group"><label class="form-label">Total Treatment Price (Rs.) *</label><input class="form-input" id="bil-amt" type="number" placeholder="e.g. 5000" oninput="bil_updateBalance()"/></div>
        <div class="form-group"><label class="form-label">Amount Paid Now (Rs.)</label><input class="form-input" id="bil-paid-now" type="number" placeholder="e.g. 2500 (leave 0 if nothing paid yet)" oninput="bil_updateBalance()"/></div>
        <div id="bil-balance-preview" style="display:none;background:#eff6ff;border-radius:8px;padding:8px 12px;font-size:12px;font-weight:700;color:#1d4ed8;margin-bottom:4px"></div>
        <div class="form-group"><label class="form-label">Lab Cost (Rs.) — optional</label><input class="form-input" id="bil-lab-cost" type="number" placeholder="0 — for margin tracking"/></div>
        <div class="form-group"><label class="form-label">Date</label><input class="form-input" id="bil-date" type="date" value="${todayISO()}"/></div>
      </div>
      <label style="display:flex;align-items:center;gap:7px;font-size:13px;font-weight:500;cursor:pointer;margin-bottom:12px"><input type="checkbox" id="bil-paid" style="width:14px;height:14px"/> Mark as Paid</label>
      <div style="display:flex;gap:8px">
        <button class="btn btn-primary btn-sm" id="bil-save-btn" onclick="saveBill()">Add</button>
        <button class="btn btn-ghost btn-sm" onclick="document.getElementById('bil-editid').value='';document.getElementById('bill-form').style.display='none'">Cancel</button>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px">
      <div style="background:#eff6ff;border-radius:11px;padding:13px 16px;text-align:center"><div style="font-size:20px;font-weight:800;color:#1d4ed8">${fmtMoney(total)}</div><div style="font-size:10px;font-weight:700;color:#1d4ed8;margin-top:1px">TOTAL BILLED</div></div>
      <div style="background:#ecfdf5;border-radius:11px;padding:13px 16px;text-align:center"><div style="font-size:20px;font-weight:800;color:#059669">${fmtMoney(paid)}</div><div style="font-size:10px;font-weight:700;color:#059669;margin-top:1px">PAID</div></div>
      <div style="background:${due>0?'#fffbeb':'#ecfdf5'};border-radius:11px;padding:13px 16px;text-align:center"><div style="font-size:20px;font-weight:800;color:${due>0?'#d97706':'#059669'}">${fmtMoney(due)}</div><div style="font-size:10px;font-weight:700;color:${due>0?'#d97706':'#059669'};margin-top:1px">DUE</div></div>
    </div>
    <div class="table-wrap">
      <div class="table-head" style="grid-template-columns:1fr 95px 105px 95px 40px 32px"><span>Treatment</span><span>Date</span><span>Amount</span><span>Status</span><span></span></div>
      ${bills.length===0?`<div class="empty"><span class="empty-icon">🧾</span><div class="empty-title">No billing items yet</div></div>`
      :bills.map(function(b) {
      var total   = Number(b.totalAmount||b.amount||0);
      var paid    = Number(b.paidAmount||(b.paid?total:0));
      var balance = Math.max(0, total - paid);
      var pct     = total>0 ? Math.round((paid/total)*100) : 0;
      var isPartial = paid > 0 && paid < total;
      var statusBg  = (b.paid||paid>=total) ? '#ecfdf5' : isPartial ? '#fffbeb' : '#fef2f2';
      var statusCol = (b.paid||paid>=total) ? '#059669' : isPartial ? '#d97706' : '#dc2626';
      var statusTxt = (b.paid||paid>=total) ? '\u2705 Paid'  : isPartial ? '\u23f3 Partial' : '\ud83d\udd34 Due';
      var pmts = b.payments||[];
      var html = '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:12px;padding:12px 14px;margin-bottom:8px">';
      html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;flex-wrap:wrap">';
      html += '<div style="flex:1;min-width:140px"><div style="font-size:13.5px;font-weight:700;color:#1e293b;margin-bottom:2px">'+esc(b.item)+'</div><div style="font-size:11px;color:#64748b">'+fmtDate(b.date)+'&nbsp;'+payMode_badge(b.paymentMode||'cash')+'</div></div>';
      html += '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><div style="text-align:right"><div style="font-size:16px;font-weight:800;color:#1e293b">'+fmtMoney(total)+'</div>';
      if (isPartial || (!b.paid && paid < total && total > 0)) {
        html += '<div style="font-size:11px;color:#059669">\u2713 '+fmtMoney(paid)+' paid</div>';
        html += '<div style="font-size:11px;color:#dc2626;font-weight:700">'+fmtMoney(balance)+' due</div>';
      }
      html += '</div><span style="background:'+statusBg+';color:'+statusCol+';padding:4px 10px;border-radius:8px;font-size:11px;font-weight:700;white-space:nowrap">'+statusTxt+'</span></div></div>';
      if (total > 0 && paid > 0 && paid < total) {
        html += '<div style="background:#f1f5f9;border-radius:4px;height:5px;overflow:hidden;margin:8px 0 6px"><div style="background:#059669;height:100%;width:'+pct+'%;border-radius:4px"></div></div>';
      }
      html += '<div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap">';
      if (paid < total) html += '<button class="btn btn-sm" style="background:#059669;color:#fff;border:none;font-size:11px" data-bid="'+b.id+'" onclick="bil_addPayment(this.dataset.bid)">+ Add Payment</button>';
      html += '<button class="btn btn-sm" style="background:#eff6ff;color:#1d4ed8;padding:3px 8px;font-size:11px" onclick="showEditBill(\''+b.id+'\')">&#x270F;&#xFE0F; Edit</button>';
      if (due > 0) html += '<button class="btn btn-sm" style="background:#059669;color:#fff;border:none;padding:3px 8px;font-size:11px" data-bid="'+b.id+'" onclick="bil_markFullyPaid(this.dataset.bid)">✅ Fully Paid</button>';
      html += '<button class="btn btn-sm" style="background:#fef2f2;color:#dc2626;padding:3px 8px;font-size:11px" onclick="deleteBill(\''+b.id+'\')">&#x1F5D1;</button>';
      if (pmts.length > 1) html += '<button class="btn btn-sm" style="background:#f8fafc;color:#64748b;font-size:11px" onclick="bil_toggleHistory(\''+b.id+'\')">&#x1F4CB; History ('+pmts.length+')</button>';
      html += '</div>';
      html += '<div id="bil-hist-'+b.id+'" style="display:none;margin-top:8px;border-top:1px solid #f1f5f9;padding-top:8px">';
      pmts.forEach(function(p,i) {
        html += '<div style="display:flex;justify-content:space-between;font-size:11px;padding:3px 0;color:#374151"><span>'+fmtDate(p.date)+' \u2014 '+esc(p.note||'Payment '+(i+1))+'</span><span style="font-weight:700;color:#059669">+'+fmtMoney(p.amount)+'</span></div>';
      });
      html += '</div></div>';
      return html;
    }).join('')}
    </div>`;
  // EMI section appended after billing content
  var billingEl = document.getElementById('billing-tab-content');
  if(billingEl && activePt){
    billingEl.innerHTML += emi_renderSection(activePt);
    billingEl.innerHTML += lab_recon_renderSummary();
  }
}
function showAddBill(){
  document.getElementById('bil-editid').value='';
  document.getElementById('bil-form-title').textContent='➕ Add Billing Item';
  document.getElementById('bil-save-btn').textContent='Add';
  document.getElementById('bil-item').value='';
  document.getElementById('bil-amt').value='';
  document.getElementById('bil-date').value=todayISO();
  document.getElementById('bil-paid').checked=false;
  var modeEl=document.getElementById('bil-mode'); if(modeEl) modeEl.value='cash';
  document.getElementById('bill-form').style.display='block';
  document.getElementById('bil-item').focus();
}
function showEditBill(id){
  var b=(activePt.billing||[]).find(function(x){ return x.id===id; });
  if(!b) return;
  document.getElementById('bil-editid').value = id;
  document.getElementById('bil-form-title').textContent = '✏️ Edit Billing Item';
  document.getElementById('bil-save-btn').textContent   = 'Save Changes';
  document.getElementById('bil-item').value  = b.item||'';
  /* FIX: use totalAmount first, fall back to amount */
  document.getElementById('bil-amt').value   = b.totalAmount||b.amount||0;
  document.getElementById('bil-date').value  = b.date||todayISO();
  /* Show current paid amount in paid-now field so user sees it */
  var paidNowEl = document.getElementById('bil-paid-now');
  if (paidNowEl) paidNowEl.value = b.paidAmount||0;
  var bilModeEl = document.getElementById('bil-mode');
  if (bilModeEl) bilModeEl.value = b.paymentMode||'Cash';
  document.getElementById('bill-form').style.display='block';
  document.getElementById('bil-item').focus();
  bil_updateBalance();
}
function saveBill(){
  var item     = document.getElementById('bil-item').value.trim();
  var totalAmt = parseFloat(document.getElementById('bil-amt').value||0);
  if(!item||!totalAmt){alert('Item and amount required.');return;}

  var editId   = document.getElementById('bil-editid').value;
  var paidNow  = parseFloat((document.getElementById('bil-paid-now')||{}).value||0);
  var labCost  = parseFloat((document.getElementById('bil-lab-cost')||{}).value||0);
  var dateVal  = document.getElementById('bil-date').value||todayISO();
  var payMode  = (document.getElementById('bil-mode')||{}).value||'Cash';
  var ptIdx    = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  if (ptIdx<0) return;

  if(editId){
    /* Edit — update item/amount/date, preserve existing payments */
    var billing = DATA.patients[ptIdx].billing||[];
    for (var i=0; i<billing.length; i++) {
      if (billing[i].id !== editId) continue;
      var existPaid = Number(billing[i].paidAmount||0);
      /* If user changed the paid-now field (different from existing), treat as new total paid */
      var newPaid = (document.getElementById('bil-paid-now') && document.getElementById('bil-paid-now').value !== '')
        ? paidNow
        : existPaid;
      billing[i].item        = item;
      billing[i].totalAmount = totalAmt;
      billing[i].amount      = totalAmt;
      billing[i].paidAmount  = newPaid;
      billing[i].paid        = Math.round(newPaid*100) >= Math.round(totalAmt*100);
      billing[i].labCost     = labCost;
      billing[i].date        = dateVal;
      billing[i].paymentMode = payMode;
      break;
    }
    DATA.patients[ptIdx].billing = billing;
  } else {
    /* New entry */
    var payments = [];
    if(paidNow > 0){
      payments.push({id:'pmt'+Date.now(), amount:paidNow, date:dateVal,
                     mode:payMode, note:'Initial payment'});
    }
    var invNum = parseInt(localStorage.getItem('hos_invoice_num')||'1000') + 1;
    localStorage.setItem('hos_invoice_num', String(invNum));
    var invId = 'INV-'+new Date().getFullYear()+'-'+String(invNum).padStart(4,'0');
    var newBill = {
      id:          Date.now().toString(),
      invoiceNo:   invId,
      item:        item,
      date:        dateVal,
      paymentMode: payMode,
      totalAmount: totalAmt,
      paidAmount:  paidNow,
      amount:      totalAmt,
      paid:        Math.round(paidNow*100) >= Math.round(totalAmt*100),
      labCost:     labCost,
      payments:    payments
    };
    if (!DATA.patients[ptIdx].billing) DATA.patients[ptIdx].billing = [];
    DATA.patients[ptIdx].billing.push(newBill);
  }

  document.getElementById('bil-editid').value  = '';
  document.getElementById('bill-form').style.display = 'none';
  activePt = DATA.patients[ptIdx];
  saveData();
  renderBillingTab();
  renderPatientHeader();
  setTimeout(function(){ billing_waPrompt(totalAmt, item); }, 400);
}
function toggleBillPaid(id){
  var idx=DATA.patients.findIndex(function(p){return p.id===activePt.id;});
  DATA.patients[idx].billing=(DATA.patients[idx].billing||[]).map(function(b){
    if(b.id!==id) return b;
    if(!b.paid){
      var total=b.totalAmount||b.amount||0;
      var diff=Math.max(0,total-(b.paidAmount||0));
      var pmts=diff>0?[...(b.payments||[]),{id:'pmt'+Date.now(),amount:diff,date:todayISO(),note:'Marked paid'}]:(b.payments||[]);
      return Object.assign({},b,{paid:true,paidAmount:total,payments:pmts});
    }
    return Object.assign({},b,{paid:false});
  });
  activePt=DATA.patients[idx]; saveData(); renderBillingTab(); renderPatientHeader();
}
function deleteBill(id){if(!confirm('Remove this item?'))return;const idx=DATA.patients.findIndex(p=>p.id===activePt.id);DATA.patients[idx].billing=DATA.patients[idx].billing.filter(b=>b.id!==id);activePt=DATA.patients[idx];saveData();renderBillingTab();renderPatientHeader();}

/* ── SHARE INVOICE WA (FIXED) ── */
function shareInvoiceWA(){
  const p=activePt; const bills=p.billing||[];
  const items=bills.map(b=>`${b.paid?'[PAID]':'[DUE]'} ${b.item}: ${fmtMoney(b.amount)}`).join(String.fromCharCode(10));
  const total=bills.reduce((s,b)=>s+Number(b.amount),0);
  const paid=bills.filter(b=>b.paid).reduce((s,b)=>s+Number(b.amount),0);
  const lines = [
    CLINIC,
    DOCTOR + ' | ' + PHONE,
    '',
    'Invoice for ' + p.name + ' (' + p.id + ')',
    'Date: ' + fmtDate(todayISO()),
    '',
    items,
    '',
    'Total: ' + fmtMoney(total),
    'Paid: ' + fmtMoney(paid),
    'Due: ' + fmtMoney(total-paid),
    '',
    'Thank you for choosing us!',
    CLINIC
  ];
  window.open('https://wa.me/91'+p.phone+'?text='+encodeURIComponent(lines.join(String.fromCharCode(10))),'_blank');
}

/* ── SHARE ALL DATA WA (FIXED) ── */
function shareAllData(){
  const p=activePt; if(!p)return;
  const recs=(p.records||[]).slice(0,5).map((r,i)=>`${i+1}. ${fmtDate(r.date)}: ${r.diagnosis}${r.treatment?' | '+r.treatment:''}`).join(String.fromCharCode(10));
  const bills=(p.billing||[]).map(b=>`${b.paid?'[PAID]':'[DUE]'} ${b.item}: ${fmtMoney(b.amount)}`).join(String.fromCharCode(10));
  const total=(p.billing||[]).reduce((s,b)=>s+Number(b.amount),0);
  const paid=(p.billing||[]).filter(b=>b.paid).reduce((s,b)=>s+Number(b.amount),0);
  const latestRx=(p.prescriptions||[])[0];
  const rxLines = latestRx ? [
    '',
    'Latest Prescription (' + fmtDate(latestRx.date) + '):',
    ...(latestRx.medicines||[]).filter(m=>m.name).map((m,i)=>`${i+1}. ${m.name}${m.dose?' '+m.dose:''} - ${m.freq||''}${m.duration?' x '+m.duration:''}`),
    latestRx.advice ? 'Advice: ' + latestRx.advice : ''
  ] : [];
  const lines = [
    CLINIC,
    DOCTOR + ' | ' + PHONE,
    '---',
    'Patient Summary',
    'Name: ' + p.name,
    'ID: ' + p.id + ' | Age: ' + p.age + 'y | ' + p.gender,
    'Phone: ' + p.phone,
    p.address ? 'Address: ' + p.address : '',
    '',
    'Chief Complaint: ' + (p.complaint||'-'),
    'Medical History: ' + (p.medHistory||'-'),
    p.type==='ortho' ? 'Ortho Patient - ' + (p.orthoDetails?.bracket||'Braces') : '',
    '',
    'Clinical Records:',
    recs||'No records yet',
    ...rxLines,
    '',
    'Billing Summary:',
    bills||'No billing',
    'Total: ' + fmtMoney(total) + ' | Paid: ' + fmtMoney(paid) + ' | Due: ' + fmtMoney(total-paid),
    '',
    'Images on record: ' + (p.images||[]).length + ' file(s)',
    '---',
    CLINIC + ' | ' + CITY,
    TIMING
  ].filter(l=>l!==undefined&&l!=='');
  window.open('https://wa.me/91'+p.phone+'?text='+encodeURIComponent(lines.join(String.fromCharCode(10))),'_blank');
}

/* ── ORTHO DETAIL TAB ── */
function renderOrthoDetailTab(){
  const p=activePt;
  if(p.type!=='ortho'){
    // Non-ortho: still show aligner option if they have/could have an aligner case
    var orthoEl2=document.getElementById('tab-content-ortho-detail');
    if(orthoEl2) orthoEl2.innerHTML='<div style="padding:16px">'+aligner_renderPatientSummary(p.id)+'</div>';
    return;
  }
  const od=p.orthoDetails||{};
  const totalCost=Number(od.totalCost||0); const paidAmt=Number(od.paidAmount||0); const dueAmt=totalCost-paidAmt;
  const prog=totalCost>0?Math.min(100,(paidAmt/totalCost)*100):0;
  document.getElementById('tab-content-ortho-detail').innerHTML=`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
      <div class="sec-title" style="margin:0">Orthodontic Details</div>
      <button class="btn btn-wa btn-sm" onclick="sendApptWA()">WA Appointment</button>
    </div>
    <div class="card card-body" style="margin-bottom:16px">
      <div class="form-grid-2">
        <div class="form-group"><label class="form-label">Start Date</label><input class="form-input" type="date" value="${od.startDate||todayISO()}" onchange="updateOrtho('startDate',this.value)"/></div>
        <div class="form-group"><label class="form-label">Bracket Type</label>
          <select class="form-input" onchange="updateOrtho('bracket',this.value)">${BRACKETS.map(b=>`<option ${od.bracket===b?'selected':''}>${b}</option>`).join('')}</select>
        </div>
        <div class="form-group"><label class="form-label">Total Treatment Cost (Rs.)</label><input class="form-input" type="number" value="${od.totalCost||''}" placeholder="e.g. 35000" onchange="updateOrtho('totalCost',this.value)"/></div>
        <div class="form-group"><label class="form-label">Amount Paid (Rs.)</label><input class="form-input" type="number" value="${od.paidAmount||''}" placeholder="0" onchange="updateOrtho('paidAmount',this.value)"/></div>
      </div>
      ${totalCost>0?`<div style="margin-bottom:14px">
        <div style="display:flex;justify-content:space-between;margin-bottom:6px;font-size:12px;font-weight:600;color:#64748b">
          <span>Payment Progress</span><span>${fmtMoney(paidAmt)} / ${fmtMoney(totalCost)}</span>
        </div>
        <div class="prog-track"><div class="prog-fill" style="width:${prog}%;background:linear-gradient(90deg,#1d4ed8,#0ea5e9)"></div></div>
        <div style="display:flex;justify-content:space-between;margin-top:4px;font-size:11px;color:#94a3b8">
          <span>${prog.toFixed(0)}% paid</span><span>Due: ${fmtMoney(dueAmt)}</span>
        </div>
      </div>`:''}
      <div class="form-group"><label class="form-label">Treatment Notes</label><textarea class="form-input" rows="3" onchange="updateOrtho('treatmentNotes',this.value)" placeholder="Extractions planned, wire sequence, etc.">${esc(od.treatmentNotes||'')}</textarea></div>
    </div>
    <div class="card card-body">
      <div class="sec-title">Next Appointment</div>
      <div class="form-grid-2">
        <div class="form-group"><label class="form-label">Appointment Date</label><input class="form-input" type="date" id="appt-date" value="${od.nextAppt||''}" onchange="updateOrtho('nextAppt',this.value)"/></div>
        <div class="form-group"><label class="form-label">Appointment Time</label><input class="form-input" type="time" id="appt-time" value="${od.nextApptTime||'10:00'}" onchange="updateOrtho('nextApptTime',this.value)"/></div>
      </div>
      ${od.nextAppt?`<div class="alert-box alert-green" style="margin-top:4px;font-size:13px">
        Next appointment: <strong>${fmtDate(od.nextAppt)}</strong> at <strong>${od.nextApptTime||'-'}</strong>
        <br/><button class="btn btn-wa btn-sm" style="margin-top:10px" onclick="sendApptWA()">Send WhatsApp Reminder</button>
      </div>`:''}
    </div>
    ${ortho_renderProgressPhotos(p)}`;
  // Inject enhanced tracking panel
  setTimeout(function(){
    var orthoEl=document.getElementById('tab-content-ortho-detail');
    if(orthoEl&&activePt){
      var od=(activePt.orthoDetails||{});
      // Inject aligner summary at top of ortho tab
      var alignerDiv=document.createElement('div');
      alignerDiv.innerHTML=aligner_renderPatientSummary(p.id);
      orthoEl.insertBefore(alignerDiv,orthoEl.firstChild);

      var ep=document.createElement('div');
      ep.innerHTML=ortho_renderEnhancedPanel(od);
      orthoEl.appendChild(ep);
    }
  },100);
}
function updateOrtho(field,val){
  const idx=DATA.patients.findIndex(p=>p.id===activePt.id);
  DATA.patients[idx].orthoDetails={...(DATA.patients[idx].orthoDetails||{}),[field]:val};
  activePt=DATA.patients[idx]; saveData();
}
/* ── SEND APPT WA (FIXED) ── */
function sendApptWA(){
  const p=activePt; const od=p.orthoDetails||{};
  if(!od.nextAppt){alert('Please set appointment date first.');return}
  const tmpl=DATA.waTemplate||DEFAULT_WA_TEMPLATE;
  const fmt12hr=t=>{if(!t)return'';const[hh,mm]=t.split(':').map(Number);const ampm=hh>=12?'PM':'AM';return((hh%12)||12)+':'+String(mm).padStart(2,'0')+' '+ampm;};
  const msg=tmpl.replace(/{name}/g,p.name).replace(/{date}/g,fmtDate(od.nextAppt)).replace(/{time}/g,fmt12hr(od.nextApptTime||'10:00')).replace(/{doctor}/g,DOCTOR).replace(/{clinic}/g,CLINIC).replace(/{phone}/g,PHONE);
  window.open('https://wa.me/91'+p.phone+'?text='+encodeURIComponent(msg),'_blank');
}

/* ══════════════════════════════════════════════════════
   ORTHO PATIENTS PAGE
══════════════════════════════════════════════════════ */
function renderOrthoList(){
  const orthos=(DATA.patients||[]).filter(p=>p.type==='ortho');
  document.getElementById('ortho-list').innerHTML=orthos.length===0?`<div class="empty" style="border:1px solid #e2e8f0;border-radius:14px"><span class="empty-icon">🦷</span><div class="empty-title">No ortho patients yet</div></div>`
  :orthos.map(p=>{
    const od=p.orthoDetails||{};
    const total=Number(od.totalCost||0),paid=Number(od.paidAmount||0),due=total-paid;
    const prog=total>0?Math.min(100,(paid/total)*100):0;
    const hasAppt=od.nextAppt;
    const fmt12hr=t=>{if(!t)return'-';const[hh,mm]=t.split(':').map(Number);const ampm=hh>=12?'PM':'AM';return((hh%12)||12)+':'+String(mm).padStart(2,'0')+' '+ampm;};
    return`<div class="appt-card">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px;margin-bottom:12px">
        <div style="display:flex;gap:10px;align-items:center">
          <div class="avatar" style="width:42px;height:42px;background:linear-gradient(135deg,#7c3aed,#0ea5e9);font-size:16px">${p.name[0]}</div>
          <div>
            <div style="font-weight:700;font-size:15px;color:#1e293b">${esc(p.name)}</div>
            <div style="font-size:12px;color:#64748b">${p.age}y | ${p.phone}</div>
            <div style="font-size:11px;color:#7c3aed;font-weight:600;margin-top:2px">${od.bracket||'-'}</div>
          </div>
        </div>
        <div style="display:flex;gap:7px">
          <button class="btn btn-wa btn-sm" onclick="sendOrthoPageSmartWA('${p.id}')">📋 WA</button>
          <button class="btn btn-primary btn-sm" onclick="openPatient('${p.id}')">Open</button>
        </div>
      </div>
      ${total>0?`<div style="margin-bottom:10px">
        <div style="display:flex;justify-content:space-between;font-size:11px;color:#64748b;margin-bottom:4px">
          <span>Payment: ${fmtMoney(paid)} / ${fmtMoney(total)}</span>
          <span style="color:${due>0?'#d97706':'#059669'}">${due>0?'Due: '+fmtMoney(due):'Paid in full'}</span>
        </div>
        <div class="prog-track"><div class="prog-fill" style="width:${prog}%;background:linear-gradient(90deg,#7c3aed,#0ea5e9)"></div></div>
      </div>`:''}
      ${hasAppt?`<div style="background:#f0fdf4;border-radius:8px;padding:8px 12px;font-size:12px;color:#16a34a;font-weight:600">
        Next Appt: ${fmtDate(od.nextAppt)} at ${fmt12hr(od.nextApptTime||'10:00')}
      </div>`:'<div style="font-size:12px;color:#94a3b8">No appointment scheduled</div>'}
    </div>`;
  }).join('');
}

