/* ══════════════════════════════════════════════════════
   EXPENSE TRACKER
══════════════════════════════════════════════════════ */
/* ══════════════════════════════════════════
   OUTSTANDING DUES DASHBOARD
   Shows all patients with unpaid balances,
   sorted by amount owed (highest first)
══════════════════════════════════════════ */
var dues_filter = 'all';

function dues_setFilter(f){
  dues_filter = f;
  ['all','high','medium','low'].forEach(function(x){
    var btn = document.getElementById('dues-chip-'+x);
    if(!btn) return;
    var active = x === f;
    btn.style.cssText = active
      ? 'background:#eff6ff;color:#1d4ed8;border:1.5px solid #bfdbfe'
      : 'background:#f8fafc;color:#64748b;border:1.5px solid #e2e8f0';
  });
  dues_renderList();
}

function dues_getPatients(){
  // Build list of patients with outstanding dues
  return (DATA.patients||[]).map(function(p){
    var bills = p.billing||[];
    var total = bills.reduce(function(s,b){return s+Number(b.amount||0);},0);
    var paid  = bills.filter(function(b){return b.paid;}).reduce(function(s,b){return s+Number(b.amount||0);},0);
    var due   = total - paid;
    return {id:p.id, name:p.name, phone:p.phone||'', due:due, total:total, paid:paid,
            lastVisit: (p.records||[]).length ? (p.records||[])[0].date : null,
            bills: bills.filter(function(b){return !b.paid;})};
  }).filter(function(x){return x.due > 0;})
    .sort(function(a,b){return b.due - a.due;});
}

function renderDuesDashboard(){
  var all = dues_getPatients();
  var totalDue   = all.reduce(function(s,x){return s+x.due;},0);
  var countHigh  = all.filter(function(x){return x.due>=5000;}).length;
  var countMed   = all.filter(function(x){return x.due>=1000&&x.due<5000;}).length;
  var countLow   = all.filter(function(x){return x.due<1000;}).length;

  // Stats cards
  var statsEl = document.getElementById('dues-stats');
  if(statsEl){
    statsEl.innerHTML = [
      {l:'Total Outstanding',  v:'₹'+totalDue.toLocaleString('en-IN'), i:'⚠️', c:'#dc2626', bg:'#fef2f2'},
      {l:'Patients with Dues', v:all.length,                            i:'👥', c:'#d97706', bg:'#fffbeb'},
      {l:'High Priority (₹5k+)',v:countHigh,                            i:'🔴', c:'#dc2626', bg:'#fef2f2'},
      {l:'Medium (₹1k–5k)',    v:countMed,                              i:'🟡', c:'#d97706', bg:'#fffbeb'},
    ].map(function(s){
      return '<div class="stat-card"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:4px">'+s.l+'</div>'+
             '<div style="font-size:24px;font-weight:800;color:'+s.c+'">'+s.v+'</div></div>'+
             '<div class="stat-icon" style="background:'+s.bg+'">'+s.i+'</div></div>';
    }).join('');
  }

  dues_renderList();
}

function dues_renderList(){
  var all = dues_getPatients();

  // Apply filter
  var filtered = all.filter(function(x){
    if(dues_filter === 'high')   return x.due >= 5000;
    if(dues_filter === 'medium') return x.due >= 1000 && x.due < 5000;
    if(dues_filter === 'low')    return x.due < 1000;
    return true;
  });

  var el = document.getElementById('dues-list');
  if(!el) return;

  if(filtered.length === 0){
    el.innerHTML = '<div class="empty"><span class="empty-icon">🎉</span>'+
      '<div class="empty-title">No outstanding dues'+(dues_filter!=='all'?' in this range':'')+'</div>'+
      '<div class="empty-sub">All patients are settled up</div></div>';
    return;
  }

  var h = '<div style="display:flex;flex-direction:column;gap:10px">';
  filtered.forEach(function(pt, i){
    var urgColor = pt.due>=5000 ? '#dc2626' : pt.due>=1000 ? '#d97706' : '#64748b';
    var urgBg    = pt.due>=5000 ? '#fef2f2' : pt.due>=1000 ? '#fffbeb' : '#f8fafc';
    var urgBdr   = pt.due>=5000 ? '#fecaca' : pt.due>=1000 ? '#fde68a' : '#e2e8f0';
    var oldestUnpaid=(pt.billing||[]).filter(function(b){return !b.paid&&b.date;}).sort(function(a,b){return a.date.localeCompare(b.date);})[0];
    var overdueDays=oldestUnpaid?Math.floor((new Date(todayISO())-new Date(oldestUnpaid.date))/86400000):0;
    if(overdueDays>7){urgBdr='#f87171';urgBg='#fff5f5';}
    h += '<div style="background:#fff;border:1.5px solid '+urgBdr+';border-radius:14px;padding:14px 16px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px">';
    // Left: rank + patient info
    h += '<div style="display:flex;align-items:center;gap:12px">';
    h += '<div style="width:36px;height:36px;background:'+urgBg+';border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:800;color:'+urgColor+';flex-shrink:0">'+(i+1)+'</div>';
    h += '<div>';
    h += '<div style="font-size:14px;font-weight:700;color:#1e293b">'+esc(pt.name)+'</div>';
    h += '<div style="font-size:11px;color:#64748b;margin-top:2px">';
    if(pt.phone) h += '📞 '+esc(pt.phone);
    if(pt.lastVisit) h += (pt.phone?' · ':'')+'Last visit: '+fmtDate(pt.lastVisit);
    h += '</div>';
    // Unpaid items
    if(pt.bills.length > 0){
      h += '<div style="margin-top:6px;display:flex;flex-wrap:wrap;gap:4px">';
      pt.bills.slice(0,3).forEach(function(b){
        h += '<span style="font-size:10px;background:#f1f5f9;color:#475569;border-radius:6px;padding:2px 8px;font-weight:600">'+
             esc(b.item||'Treatment')+' · ₹'+Number(b.amount||0).toLocaleString('en-IN')+'</span>';
      });
      if(pt.bills.length > 3) h += '<span style="font-size:10px;color:#94a3b8">+' + (pt.bills.length-3) + ' more</span>';
      h += '</div>';
    }
    h += '</div></div>';
    // Right: amount + actions
    h += '<div style="display:flex;align-items:center;gap:10px;flex-shrink:0">';
    h += '<div style="text-align:right">';
    h += '<div style="font-size:20px;font-weight:800;color:'+urgColor+'">₹'+pt.due.toLocaleString('en-IN')+'</div>';
    h += '<div style="font-size:10px;color:#94a3b8;margin-top:1px">of ₹'+pt.total.toLocaleString('en-IN')+' total</div>';
    h += '</div>';
    h += '<button class="btn btn-sm" style="background:#25d366;color:#fff;border:none;flex-shrink:0" data-ptid="'+pt.id+'" onclick="dues_sendReminder(this.dataset.ptid)">📲 Remind</button>';
    h += '<button class="btn btn-primary btn-sm" style="flex-shrink:0" data-ptid="'+pt.id+'" onclick="openPatient(this.dataset.ptid)">Open</button>';
    h += '</div>';
    h += '</div>';
  });
  h += '</div>';
  h += '<div style="margin-top:12px;font-size:11px;color:#94a3b8;text-align:right">'+filtered.length+' patient'+(filtered.length!==1?'s':'')+' · ₹'+filtered.reduce(function(s,x){return s+x.due;},0).toLocaleString('en-IN')+' total outstanding</div>';
  el.innerHTML = h;
}

function dues_sendReminder(ptId){
  var pt = (DATA.patients||[]).find(function(p){return p.id===ptId;});
  if(!pt||!pt.phone){alert('No phone number for this patient.');return;}
  var bills = (pt.billing||[]).filter(function(b){return !b.paid;});
  var due   = bills.reduce(function(s,b){return s+Number(b.amount||0);},0);
  var itemList = bills.slice(0,5).map(function(b){
    return '  • '+( b.item||'Treatment')+': ₹'+Number(b.amount||0).toLocaleString('en-IN');
  }).join(String.fromCharCode(10));
  // Find oldest unpaid bill date
  var oldestDate = bills.reduce(function(oldest,b){ return (!oldest||(b.date||'')>oldest)?b.date:oldest; }, null);
  var daysPending = oldestDate ? Math.floor((new Date()-new Date(oldestDate+'T00:00:00'))/86400000) : 0;
  var urgency = daysPending > 60 ? 'high' : daysPending > 30 ? 'medium' : 'gentle';
  var greeting = urgency==='high'
    ? 'We regret to inform you that your payment of ₹'+due.toLocaleString('en-IN')+' has been pending for over '+daysPending+' days. We kindly request immediate settlement.'
    : urgency==='medium'
    ? 'Your outstanding balance of ₹'+due.toLocaleString('en-IN')+' has been pending for '+daysPending+' days. Please arrange payment at your earliest.'
    : 'This is a gentle reminder regarding your outstanding balance of ₹'+due.toLocaleString('en-IN')+'. Kindly clear at your convenience.';
  var msg = [
    CLINIC,
    DOCTOR+' | '+PHONE,
    '─────────────────',
    'Dear '+pt.name+',',
    '',
    greeting,
    '',
    'Pending items:',
    itemList,
    '',
    '💰 Total Due: ₹'+due.toLocaleString('en-IN'),
    '',
    'For any queries, please call us at '+PHONE,
    '',
    TIMING
  ].join(String.fromCharCode(10));
  window.open('https://wa.me/91'+pt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

function dues_remindAll(){
  var pts = dues_getPatients().filter(function(x){
    if(dues_filter==='high')   return x.due>=5000;
    if(dues_filter==='medium') return x.due>=1000&&x.due<5000;
    if(dues_filter==='low')    return x.due<1000;
    return true;
  }).filter(function(x){return x.phone;});
  if(pts.length===0){alert('No patients with phone numbers to remind.');return;}
  if(!confirm('Send WhatsApp reminders to '+pts.length+' patient(s)?'))return;
  var i=0;
  function next(){
    if(i>=pts.length)return;
    dues_sendReminder(pts[i].id);
    i++;
    if(i<pts.length) setTimeout(next,1500);
  }
  next();
}


function renderExpenses(){
  var exps = DATA.expenses||[];
  var now = new Date();
  var moISO = now.toISOString().slice(0,7);

  // ── Read filter state (persisted on globals)
  var q       = (window.expSearch||'').toLowerCase();
  var filterMo= window.expMonth !== undefined ? window.expMonth : moISO;
  var filterCat = window.expCat || 'all';
  var sortBy  = window.expSort || 'date-desc';

  // ── Filter
  var filtered = exps.filter(function(e){
    if(filterMo !== 'all' && !e.date.startsWith(filterMo)) return false;
    if(filterCat !== 'all' && e.category !== filterCat) return false;
    if(q){
      var hay = (e.description||'')+(e.subcategory||'')+(e.category||'')+(e.amount||'');
      if(hay.toLowerCase().indexOf(q)<0) return false;
    }
    return true;
  });

  // ── Sort
  filtered.sort(function(a,b){
    if(sortBy==='date-desc') return b.date.localeCompare(a.date);
    if(sortBy==='date-asc')  return a.date.localeCompare(b.date);
    if(sortBy==='amt-desc')  return Number(b.amount)-Number(a.amount);
    if(sortBy==='amt-asc')   return Number(a.amount)-Number(b.amount);
    return 0;
  });

  // ── Stats (on filtered set)
  var total   = filtered.reduce(function(s,e){return s+Number(e.amount||0);},0);
  var clinic  = filtered.filter(function(e){return e.category==='clinic';}).reduce(function(s,e){return s+Number(e.amount||0);},0);
  var personal= filtered.filter(function(e){return e.category==='personal';}).reduce(function(s,e){return s+Number(e.amount||0);},0);
  var avgPerDay = filtered.length>0 ? (total / Math.max(1, new Set(filtered.map(function(e){return e.date;})).size)) : 0;

  // ── Build UI
  var h = '';

  // Stats row
  h += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-bottom:20px">';
  h += '<div class="stat-card"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:4px">'+(filterMo==='all'?'All Time':filterMo)+' Total</div><div style="font-size:22px;font-weight:800;color:#dc2626">'+fmtMoney(total)+'</div></div><div class="stat-icon" style="background:#fef2f2">💸</div></div>';
  h += '<div class="stat-card"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:4px">Clinic</div><div style="font-size:22px;font-weight:800;color:#7c3aed">'+fmtMoney(clinic)+'</div></div><div class="stat-icon" style="background:#f5f3ff">🏥</div></div>';
  h += '<div class="stat-card"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:4px">Personal</div><div style="font-size:22px;font-weight:800;color:#0369a1">'+fmtMoney(personal)+'</div></div><div class="stat-icon" style="background:#eff6ff">🏠</div></div>';
  h += '<div class="stat-card"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:4px">Avg/Day</div><div style="font-size:22px;font-weight:800;color:#d97706">'+fmtMoney(Math.round(avgPerDay))+'</div></div><div class="stat-icon" style="background:#fffbeb">📊</div></div>';
  h += '</div>';

  // Add Expense Form
  h += '<div class="card" style="margin-bottom:18px">';
  h += '<div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:14px">➕ Add Expense</div>';
  h += '<div class="form-grid-2">';
  h += '<div class="form-group"><label class="form-label">Date</label><input class="form-input" id="exp-date" type="date" value="'+todayISO()+'"/></div>';
  h += '<div class="form-group"><label class="form-label">Amount (₹) *</label><input class="form-input" id="exp-amt" type="number" placeholder="0" min="0"/></div>';
  h += '<div class="form-group"><label class="form-label">Category</label>';
  h += '<select class="form-input" id="exp-cat"><option value="clinic">🏥 Clinic</option><option value="personal">🏠 Personal</option></select></div>';
  h += '<div class="form-group"><label class="form-label">Sub-category</label>';
  h += '<select class="form-input" id="exp-subcat">';
  ['Rent','Electricity','Staff Salary','Materials','Equipment','Lab Charges','Medicine Stock','Maintenance','Marketing','Food','Transport','Other'].forEach(function(s){
    h += '<option>'+s+'</option>';
  });
  h += '</select></div>';
  h += '<div class="form-group"><label class="form-label">Payment Mode</label>';
  h += '<select class="form-input" id="exp-mode"><option value="cash">💵 Cash</option><option value="upi">📱 UPI</option><option value="card">💳 Card</option><option value="bank">🏦 Bank Transfer</option></select></div>';
  h += '<div class="form-group"><label class="form-label">Description</label><input class="form-input" id="exp-desc" placeholder="e.g. Bought gloves from supplier"/></div>';
  h += '</div>';
  h += '<button class="btn btn-primary" onclick="addExpense()" style="margin-top:4px">💾 Save Expense</button>';
  h += '</div>';

  // Search + Filter Bar
  h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:14px 16px;margin-bottom:14px">';
  h += '<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:10px">';
  // Search
  h += '<div style="flex:1;min-width:180px;position:relative">';
  h += '<input class="form-input" id="exp-search-input" placeholder="🔍 Search expenses..." value="'+((window.expSearch||'')).replace(/"/g,'&quot;')+'" oninput="window.expSearch=this.value;renderExpenses()" style="padding-left:14px"/>';
  if(window.expSearch) h += '<button data-action="clear-search" onclick="window.expSearch=\'\';renderExpenses()" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);background:none;border:none;color:#94a3b8;cursor:pointer;font-size:16px">×</button>';
  h += '</div>';
  // Month picker
  h += '<input type="month" class="form-input" value="'+(filterMo==='all'?'':filterMo)+'" style="width:160px" onchange="window.expMonth=this.value||&quot;all&quot;;renderExpenses()" title="Filter by month"/>';
  h += '<button class="btn btn-sm" data-action="all-time" onclick="window.expMonth=&quot;all&quot;;renderExpenses()" style="'+(filterMo==='all'?'background:#eff6ff;color:#1d4ed8;border:1.5px solid #bfdbfe':'background:#f8fafc;color:#64748b;border:1.5px solid #e2e8f0')+'">All Time</button>';
  h += '</div>';
  // Category + Sort
  h += '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">';
  ['all','clinic','personal'].forEach(function(cat){
    var lbl = cat==='all'?'All':cat==='clinic'?'🏥 Clinic':'🏠 Personal';
    var active = filterCat===cat;
    h += '<button class="btn btn-sm" data-cat="'+cat+'" onclick="window.expCat=this.dataset.cat;renderExpenses()" style="'+(active?'background:#eff6ff;color:#1d4ed8;border:1.5px solid #bfdbfe':'background:#f8fafc;color:#64748b;border:1.5px solid #e2e8f0')+'">' + lbl + '</button>';
  });
  h += '<div style="margin-left:auto;display:flex;align-items:center;gap:6px">';
  h += '<span style="font-size:11px;color:#94a3b8">Sort:</span>';
  h += '<select class="form-input" style="padding:4px 8px;font-size:11px;height:auto" onchange="window.expSort=this.value;renderExpenses()">';
  [['date-desc','Newest First'],['date-asc','Oldest First'],['amt-desc','Highest First'],['amt-asc','Lowest First']].forEach(function(opt){
    h += '<option value="'+opt[0]+'"'+(sortBy===opt[0]?' selected':'')+'>'+opt[1]+'</option>';
  });
  h += '</select></div></div></div>';

  // Results count
  h += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">';
  h += '<span style="font-size:12px;color:#64748b;font-weight:600">'+filtered.length+' expense'+(filtered.length!==1?'s':'')+' · '+fmtMoney(total)+'</span>';
  h += '<button class="btn btn-sm btn-red" onclick="exp_deleteAll()" style="font-size:11px">🗑 Clear Filtered</button>';
  h += '</div>';

  // Expense list
  if(filtered.length===0){
    h += '<div class="empty"><span class="empty-icon">💸</span><div class="empty-title">No expenses found</div><div class="empty-sub">Try a different filter or add a new expense</div></div>';
  } else {
    // Group by date
    var byDate = {};
    filtered.forEach(function(e){
      if(!byDate[e.date]) byDate[e.date]=[];
      byDate[e.date].push(e);
    });
    var dates = Object.keys(byDate).sort(function(a,b){
      return sortBy.startsWith('date-asc') ? a.localeCompare(b) : b.localeCompare(a);
    });

    dates.forEach(function(date){
      var dayExps = byDate[date];
      var dayTotal = dayExps.reduce(function(s,e){return s+Number(e.amount||0);},0);
      h += '<div style="margin-bottom:14px">';
      h += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;padding:0 2px">';
      h += '<span style="font-size:11px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px">'+fmtDate(date)+'</span>';
      h += '<span style="font-size:11px;font-weight:700;color:#dc2626">'+fmtMoney(dayTotal)+'</span>';
      h += '</div>';
      dayExps.forEach(function(e){
        var modeBadge = {cash:'💵 Cash',upi:'📱 UPI',card:'💳 Card',bank:'🏦 Bank'}[e.mode]||e.mode||'Cash';
        var catColor  = e.category==='clinic' ? '#7c3aed' : '#0369a1';
        var catBg     = e.category==='clinic' ? '#f5f3ff' : '#eff6ff';
        h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:12px 14px;margin-bottom:6px;display:flex;align-items:center;justify-content:space-between;gap:10px">';
        h += '<div style="display:flex;align-items:center;gap:12px;flex:1;min-width:0">';
        h += '<div style="width:40px;height:40px;background:'+catBg+';border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0">';
        h += (e.category==='clinic'?'🏥':'🏠')+'</div>';
        h += '<div style="min-width:0">';
        h += '<div style="font-size:13px;font-weight:700;color:#1e293b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+(e.subcategory||'Expense')+(e.description?' — <span style="font-weight:400;color:#64748b">'+esc(e.description)+'</span>':'')+'</div>';
        h += '<div style="display:flex;gap:6px;margin-top:4px;flex-wrap:wrap">';
        h += '<span style="font-size:10px;background:'+catBg+';color:'+catColor+';border-radius:5px;padding:2px 7px;font-weight:700">'+e.category+'</span>';
        h += '<span style="font-size:10px;background:#f1f5f9;color:#475569;border-radius:5px;padding:2px 7px">'+modeBadge+'</span>';
        h += '</div></div></div>';
        h += '<div style="display:flex;align-items:center;gap:10px;flex-shrink:0">';
        h += '<div style="font-size:17px;font-weight:800;color:#dc2626">'+fmtMoney(e.amount)+'</div>';
        h += '<button class="btn btn-red btn-sm" style="padding:5px 10px" data-id="'+e.id+'" onclick="deleteExpense(this.dataset.id)">🗑</button>';
        h += '</div></div>';
      });
      h += '</div>';
    });
  }

  document.getElementById('expenses-content').innerHTML = h;
}

function exp_deleteAll(){
  var q = (window.expSearch||'').toLowerCase();
  var filterMo = window.expMonth !== undefined ? window.expMonth : new Date().toISOString().slice(0,7);
  var filterCat = window.expCat||'all';
  var filtered = (DATA.expenses||[]).filter(function(e){
    if(filterMo!=='all'&&!e.date.startsWith(filterMo))return false;
    if(filterCat!=='all'&&e.category!==filterCat)return false;
    if(q){var hay=(e.description||'')+(e.subcategory||'')+(e.amount||'');if(hay.toLowerCase().indexOf(q)<0)return false;}
    return true;
  });
  if(!filtered.length){alert('No expenses to clear.');return;}
  if(!confirm('Delete '+filtered.length+' expense(s)?')) return;
  var ids = new Set(filtered.map(function(e){return e.id;}));
  DATA.expenses=(DATA.expenses||[]).filter(function(e){return !ids.has(e.id);});
  saveData(); renderExpenses();
}

function deleteExpense(id){
  if(!confirm('Delete this expense?')) return;
  DATA.expenses=(DATA.expenses||[]).filter(function(e){return e.id!==id;});
  saveData(); renderExpenses();
}


function addExpense(){
  const amt=document.getElementById('exp-amt').value;
  if(!amt){alert('Amount required.');return}
  const e={id:Date.now().toString(),date:document.getElementById('exp-date').value,category:document.getElementById('exp-cat').value,subcategory:document.getElementById('exp-subcat').value,amount:Number(amt),description:document.getElementById('exp-desc').value,mode:document.getElementById('exp-mode').value};
  DATA.expenses=[...(DATA.expenses||[]),e]; saveData(); renderExpenses();
}


/* ══════════════════════════════════════════════════════
   FINANCE OVERVIEW
══════════════════════════════════════════════════════ */
function renderFinance(){
  const mo=monthISO();
  const moLabel=new Date().toLocaleString('en-IN',{month:'long',year:'numeric'});
  document.getElementById('fin-month-label').textContent=moLabel;
  const pts=DATA.patients||[];
  const moRev=pts.flatMap(p=>p.billing||[]).filter(b=>b.paid&&b.date.startsWith(mo)).reduce((s,b)=>s+Number(b.amount),0);
  const moExpC=(DATA.expenses||[]).filter(e=>e.date.startsWith(mo)&&e.category==='clinic').reduce((s,e)=>s+Number(e.amount),0);
  const moExpP=(DATA.expenses||[]).filter(e=>e.date.startsWith(mo)&&e.category==='personal').reduce((s,e)=>s+Number(e.amount),0);
  const totalClinicCost=moExpC+FIXED_STAFF;
  const profit=moRev-totalClinicCost;
  const surplus=profit-moExpP;
  const cashT=pts.flatMap(p=>p.billing||[]).filter(b=>b.paid&&b.date.startsWith(mo)&&b.mode==='cash').reduce((s,b)=>s+Number(b.amount),0);
  const upiT=pts.flatMap(p=>p.billing||[]).filter(b=>b.paid&&b.date.startsWith(mo)&&b.mode==='upi').reduce((s,b)=>s+Number(b.amount),0);
  const cardT=pts.flatMap(p=>p.billing||[]).filter(b=>b.paid&&b.date.startsWith(mo)&&b.mode==='card').reduce((s,b)=>s+Number(b.amount),0);
  const otherT=moRev-cashT-upiT-cardT;
  const targetPct=TARGET>0?(moRev/TARGET*100):0;
  const bar=(v,max,c)=>`<div class="prog-track"><div class="prog-fill" style="width:${max>0?Math.min(100,v/max*100):0}%;background:${c}"></div></div>`;
  document.getElementById('finance-content').innerHTML=`
    <div class="card card-body" style="margin-bottom:18px">
      <div style="font-size:14px;font-weight:700;margin-bottom:10px">Monthly Target: ${fmtMoney(TARGET)}</div>
      <div class="prog-track"><div class="prog-fill" style="width:${Math.min(100,targetPct)}%;background:linear-gradient(90deg,#1d4ed8,#10b981)"></div></div>
      <div style="display:flex;justify-content:space-between;margin-top:5px;font-size:11px;color:#94a3b8">
        <span>${targetPct.toFixed(1)}% achieved</span>
        <span style="color:${moRev>=TARGET?'#059669':'#d97706'}">${moRev>=TARGET?'Target Hit!':'Rs.'+(TARGET-moRev).toLocaleString('en-IN')+' to go'}</span>
      </div>
    </div>
    <div class="card card-body" style="margin-bottom:18px">
      <div style="font-size:14px;font-weight:700;margin-bottom:14px">Profit & Loss - ${moLabel}</div>
      ${[{l:'Collections (Paid)',v:moRev,c:'#059669',pre:'+'},{l:'Fixed Staff Cost',v:FIXED_STAFF,c:'#d97706',pre:'-'},{l:'Variable Clinic Exp',v:moExpC,c:'#d97706',pre:'-'},{l:'Total Clinic Cost',v:totalClinicCost,c:'#d97706',bold:true,sep:true},{l:'Net Clinic Profit',v:profit,c:profit>=0?'#059669':'#dc2626',bold:true,sep:true},{l:'Personal Expenses',v:moExpP,c:'#7c3aed',pre:'-'},{l:'Monthly Surplus',v:surplus,c:surplus>=0?'#1d4ed8':'#dc2626',bold:true,sep:true}].map(r=>`<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid ${r.sep?'#e2e8f0':'#f8fafc'}"><span style="font-size:13px;color:${r.bold?'#1e293b':'#64748b'};font-weight:${r.bold?700:400}">${r.l}</span><span style="font-size:14px;font-weight:700;color:${r.c}">${(r.pre||'')}${fmtMoney(r.v)}</span></div>`).join('')}
      <div style="font-size:11px;color:#94a3b8;text-align:center;margin-top:8px">Savings Rate: ${moRev>0?((surplus/moRev)*100).toFixed(1):0}%</div>
    </div>
    <div class="card card-body" style="margin-bottom:18px">
      <div style="font-size:14px;font-weight:700;margin-bottom:14px">Collection Mode</div>
      ${[{l:'Cash',v:cashT,c:'#059669'},{l:'UPI',v:upiT,c:'#1d4ed8'},{l:'Card',v:cardT,c:'#7c3aed'},{l:'Other/Untagged',v:otherT,c:'#64748b'}].map(m=>`<div style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:3px"><span style="color:#64748b">${m.l}</span><span style="font-weight:700;color:${m.c}">${fmtMoney(m.v)}</span></div>${bar(m.v,moRev||1,m.c)}</div>`).join('')}
    </div>
    <div id="fin-history-wrap" class="card card-body">
      <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:14px">
        <div style="font-size:14px;font-weight:700">📅 All-Time Monthly History</div>
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
          <select id="fin-view-mode" class="form-input" style="padding:5px 10px;font-size:12px;width:auto" onchange="fin_renderHistory()">
            <option value="year">By Year</option>
            <option value="compare">Compare 2 Years</option>
          </select>
          <select id="fin-year-a" class="form-input" style="padding:5px 10px;font-size:12px;width:auto" onchange="fin_renderHistory()"></select>
          <span id="fin-vs-label" style="font-size:12px;color:#94a3b8;display:none">vs</span>
          <select id="fin-year-b" class="form-input" style="padding:5px 10px;font-size:12px;width:auto;display:none" onchange="fin_renderHistory()"></select>
        </div>
      </div>
      <div id="fin-history-body"></div>
      <div style="margin-top:10px;font-size:10px;color:#94a3b8;text-align:center">
        🔒 All historical data is permanently stored — nothing is ever auto-deleted.
        Back up regularly to keep your data safe.
      </div>
    </div>`;
}

/* ══════════════════════════════════════════════════════
   MULTI-YEAR FINANCE COMPARE — Feature #17
   fin_  prefix | Read-only — no DATA writes
   All historical data preserved permanently.
══════════════════════════════════════════════════════ */

function fin_allYears() {
  // Collect every calendar year present in billing + expenses
  const pts = DATA.patients || [];
  const exps = DATA.expenses || [];
  const years = new Set();
  pts.forEach(p => (p.billing||[]).forEach(b => { if(b.date) years.add(b.date.slice(0,4)); }));
  exps.forEach(e => { if(e.date) years.add(e.date.slice(0,4)); });
  // Always include current year even if empty
  years.add(new Date().getFullYear().toString());
  return [...years].sort((a,b)=>b-a); // newest first
}

function fin_monthData(yearStr) {
  // Returns 12-month breakdown for a given year string e.g. "2025"
  const pts = DATA.patients || [];
  const exps = DATA.expenses || [];
  return Array.from({length:12},(_,i)=>{
    const d = new Date(Number(yearStr), i, 1);
    const m = d.toISOString().slice(0,7);
    const label = d.toLocaleString('en-IN',{month:'short'});
    const income = pts.flatMap(p=>(p.billing||[]).filter(b=>b.paid&&(b.date||'').startsWith(m)))
                      .reduce((s,b)=>s+Number(b.amount||0),0);
    const expenses = exps.filter(e=>(e.date||'').startsWith(m))
                         .reduce((s,e)=>s+Number(e.amount||0),0);
    const profit = income - expenses;
    return { label, m, income, expenses, profit, hasData: income>0||expenses>0 };
  });
}

function fin_initYearSelects() {
  const years = fin_allYears();
  const selA = document.getElementById('fin-year-a');
  const selB = document.getElementById('fin-year-b');
  if (!selA) return;
  [selA, selB].forEach((sel, si) => {
    sel.innerHTML = years.map((y,i)=>`<option value="${y}" ${i===si?'selected':''}>${y}</option>`).join('');
  });
}

function fin_renderHistory() {
  const mode = (document.getElementById('fin-view-mode')||{}).value || 'year';
  const yearA = (document.getElementById('fin-year-a')||{}).value;
  const yearB = (document.getElementById('fin-year-b')||{}).value;
  const vsLabel = document.getElementById('fin-vs-label');
  const selB = document.getElementById('fin-year-b');
  const body = document.getElementById('fin-history-body');
  if (!body) return;

  if (mode === 'compare') {
    if (vsLabel) vsLabel.style.display = 'inline';
    if (selB) selB.style.display = 'inline';
    body.innerHTML = fin_buildCompare(yearA, yearB);
  } else {
    if (vsLabel) vsLabel.style.display = 'none';
    if (selB) selB.style.display = 'none';
    body.innerHTML = fin_buildSingleYear(yearA);
  }
}

function fin_buildSingleYear(yearStr) {
  const months = fin_monthData(yearStr);
  const totIncome = months.reduce((s,m)=>s+m.income,0);
  const totExp = months.reduce((s,m)=>s+m.expenses,0);
  const totProfit = totIncome - totExp;
  const maxVal = Math.max(...months.map(m=>Math.max(m.income,m.expenses)),1);

  return `
    <div style="display:grid;grid-template-columns:44px 1fr 80px 80px 80px;font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;padding:5px 0;border-bottom:1.5px solid #e2e8f0;margin-bottom:4px">
      <span>Month</span><span>Revenue bar</span><span style="text-align:right">Income</span><span style="text-align:right">Expenses</span><span style="text-align:right">Profit</span>
    </div>
    ${months.map(m=>{
      const incW = Math.round(m.income/maxVal*100);
      const expW = Math.round(m.expenses/maxVal*100);
      return `<div style="display:grid;grid-template-columns:44px 1fr 80px 80px 80px;align-items:center;padding:6px 0;border-bottom:1px solid #f8fafc;opacity:${m.hasData?1:0.35}">
        <span style="font-size:11px;color:#64748b;font-weight:600">${m.label}</span>
        <div style="padding-right:8px">
          <div style="height:5px;background:#dbeafe;border-radius:3px;margin-bottom:2px;position:relative">
            <div style="position:absolute;left:0;top:0;height:100%;width:${incW}%;background:#3b82f6;border-radius:3px"></div>
          </div>
          <div style="height:5px;background:#fee2e2;border-radius:3px;position:relative">
            <div style="position:absolute;left:0;top:0;height:100%;width:${expW}%;background:#ef4444;border-radius:3px"></div>
          </div>
        </div>
        <span style="font-size:11px;font-weight:700;color:#059669;text-align:right">${m.income?fmtMoney(m.income):'-'}</span>
        <span style="font-size:11px;font-weight:700;color:#d97706;text-align:right">${m.expenses?fmtMoney(m.expenses):'-'}</span>
        <span style="font-size:11px;font-weight:700;color:${m.profit>=0?'#1d4ed8':'#dc2626'};text-align:right">${m.hasData?(m.profit>=0?'+':'')+fmtMoney(m.profit):'-'}</span>
      </div>`;
    }).join('')}
    <div style="display:grid;grid-template-columns:44px 1fr 80px 80px 80px;padding:8px 0;margin-top:4px;border-top:2px solid #e2e8f0;font-weight:800">
      <span style="font-size:11px;color:#1e3a5f">Total</span>
      <span></span>
      <span style="font-size:12px;color:#059669;text-align:right">${fmtMoney(totIncome)}</span>
      <span style="font-size:12px;color:#d97706;text-align:right">${fmtMoney(totExp)}</span>
      <span style="font-size:12px;color:${totProfit>=0?'#1d4ed8':'#dc2626'};text-align:right">${(totProfit>=0?'+':'')+fmtMoney(totProfit)}</span>
    </div>`;
}

function fin_buildCompare(yearA, yearB) {
  const mA = fin_monthData(yearA);
  const mB = fin_monthData(yearB);
  const totA = { income:mA.reduce((s,m)=>s+m.income,0), expenses:mA.reduce((s,m)=>s+m.expenses,0) };
  const totB = { income:mB.reduce((s,m)=>s+m.income,0), expenses:mB.reduce((s,m)=>s+m.expenses,0) };
  totA.profit = totA.income - totA.expenses;
  totB.profit = totB.income - totB.expenses;

  const col = (v, color) => `<span style="font-size:11px;font-weight:700;color:${color};text-align:right;display:block">${v?fmtMoney(v):'-'}</span>`;

  return `
    <!-- Summary comparison banner -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">
      ${[{yr:yearA,t:totA},{yr:yearB,t:totB}].map(({yr,t})=>`
      <div style="background:#f8fafc;border-radius:10px;padding:12px 14px;border-left:4px solid #3b82f6">
        <div style="font-size:13px;font-weight:800;color:#1e3a5f;margin-bottom:8px">📅 ${yr}</div>
        <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:4px">
          <span style="color:#64748b">Income</span><span style="font-weight:700;color:#059669">${fmtMoney(t.income)}</span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:4px">
          <span style="color:#64748b">Expenses</span><span style="font-weight:700;color:#d97706">${fmtMoney(t.expenses)}</span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:12px;border-top:1px solid #e2e8f0;padding-top:6px;margin-top:6px">
          <span style="color:#64748b;font-weight:700">Net Profit</span><span style="font-weight:800;color:${t.profit>=0?'#1d4ed8':'#dc2626'}">${(t.profit>=0?'+':'')+fmtMoney(t.profit)}</span>
        </div>
      </div>`).join('')}
    </div>
    <!-- Month-by-month comparison -->
    <div style="display:grid;grid-template-columns:44px 1fr 1fr;font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;padding:5px 0;border-bottom:1.5px solid #e2e8f0;margin-bottom:4px">
      <span>Month</span><span style="padding-left:6px">${yearA}</span><span style="padding-left:6px">${yearB}</span>
    </div>
    ${mA.map((ma,i)=>{
      const mb = mB[i];
      const diff = ma.income - mb.income;
      return `<div style="display:grid;grid-template-columns:44px 1fr 1fr;align-items:start;padding:6px 0;border-bottom:1px solid #f8fafc;opacity:${ma.hasData||mb.hasData?1:0.3}">
        <span style="font-size:11px;color:#64748b;font-weight:600;padding-top:2px">${ma.label}</span>
        <div style="padding:0 6px">
          ${col(ma.income,'#059669')}
          <span style="font-size:9px;color:#d97706">${ma.expenses?'exp '+fmtMoney(ma.expenses):''}</span>
          <span style="font-size:9px;color:${ma.profit>=0?'#1d4ed8':'#dc2626'}">${ma.hasData?'profit '+(ma.profit>=0?'+':'')+fmtMoney(ma.profit):''}</span>
        </div>
        <div style="padding:0 6px">
          ${col(mb.income,'#059669')}
          <span style="font-size:9px;color:#d97706">${mb.expenses?'exp '+fmtMoney(mb.expenses):''}</span>
          <span style="font-size:9px;color:${mb.profit>=0?'#1d4ed8':'#dc2626'}">${mb.hasData?'profit '+(mb.profit>=0?'+':'')+fmtMoney(mb.profit):''}</span>
          ${ma.hasData&&mb.hasData&&diff!==0?`<div style="font-size:9px;font-weight:700;color:${diff>0?'#059669':'#ef4444'}">${diff>0?'▲':'▼'} ${fmtMoney(Math.abs(diff))}</div>`:''}
        </div>
      </div>`;
    }).join('')}`;
}

/* ══════════════════════════════════════════════════════
   MONTHLY REPORT
══════════════════════════════════════════════════════ */
function renderReport(){
  const mo=monthISO();
  const moLabel=new Date().toLocaleString('en-IN',{month:'long',year:'numeric'});
  const pts=DATA.patients||[];
  const moRev=pts.flatMap(p=>p.billing||[]).filter(b=>b.paid&&b.date.startsWith(mo)).reduce((s,b)=>s+Number(b.amount),0);
  const moExpC=(DATA.expenses||[]).filter(e=>e.date.startsWith(mo)&&e.category==='clinic').reduce((s,e)=>s+Number(e.amount),0);
  const moExpP=(DATA.expenses||[]).filter(e=>e.date.startsWith(mo)&&e.category==='personal').reduce((s,e)=>s+Number(e.amount),0);
  const totalCost=moExpC+FIXED_STAFF; const profit=moRev-totalCost; const surplus=profit-moExpP;
  const moPts=pts.filter(p=>p.createdAt.startsWith(mo)||(p.records||[]).some(r=>r.date.startsWith(mo)));
  const procMap={}; pts.flatMap(p=>p.billing||[]).filter(b=>b.date.startsWith(mo)&&b.paid).forEach(b=>{procMap[b.item]=(procMap[b.item]||0)+Number(b.amount);});
  const topProcs=Object.entries(procMap).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const report=`====================================
  THE HOME OF SMILES DENTAL CLINIC
  Dr. Tanmay Jain | ${PHONE}
  ${REG} | ${CITY}
  Monthly Report - ${moLabel}
====================================

INCOME
  Patient Billing (Paid)  : ${fmtMoney(moRev)}
  Patients This Month     : ${moPts.length}
  Target Achievement      : ${TARGET>0?((moRev/TARGET)*100).toFixed(1):0}%

CLINIC EXPENSES
  Fixed (Staff Salaries)  : ${fmtMoney(FIXED_STAFF)}
  Variable Expenses       : ${fmtMoney(moExpC)}
  Total Clinic Cost       : ${fmtMoney(totalCost)}

NET CLINIC PROFIT         : ${fmtMoney(profit)}
PERSONAL EXPENSES         : ${fmtMoney(moExpP)}
MONTHLY SURPLUS           : ${fmtMoney(surplus)}
SAVINGS RATE              : ${moRev>0?((surplus/moRev)*100).toFixed(1):0}%

TOP PROCEDURES / SERVICES
${topProcs.map(([p,a])=>`  ${p.substring(0,24).padEnd(24)} : ${fmtMoney(a)}`).join(String.fromCharCode(10))||'  No data yet'}

====================================
Generated: ${new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'long',year:'numeric'})}
====================================`;
  document.getElementById('report-content').innerHTML=`
    <div class="card card-body" style="margin-bottom:16px">
      <pre style="font-size:12px;color:#374151;font-family:'Courier New',monospace;line-height:1.9;white-space:pre-wrap;background:#f8fafc;padding:16px;border-radius:10px;border:1px solid #e2e8f0">${report}</pre>
    </div>
    <div style="display:flex;gap:10px;margin-bottom:20px;flex-wrap:wrap">
      <button class="btn btn-primary" onclick="downloadReport()">Download .txt</button>
      <button class="btn btn-ghost" onclick="printReport()">Print / PDF</button>
      <button class="btn btn-wa" onclick="shareReportWA()">Share on WhatsApp</button>
    </div>`;
  window.__reportText = report;
  // Inject procedure breakdown
  setTimeout(function(){
    if(!document.getElementById('proc-breakdown-wrap')){
      var target=document.getElementById('report-content')||document.querySelector('#page-report');
      if(target){
        var wrap=document.createElement('div');
        wrap.id='proc-breakdown-wrap';
        wrap.className='card';
        wrap.style.marginTop='16px';
        wrap.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><div class="sec-title" style="margin:0">&#127942; Top Procedures by Revenue</div><button class="btn btn-sm" style="background:#1d4ed8;color:#fff;border:none" onclick="generateDailyReport()">&#128202; Daily Report</button></div><div id="proc-breakdown"></div>';
        target.appendChild(wrap);
      }
    }
    renderProcedureBreakdown();
  },150);
}

function printReport(){
  const el = document.getElementById('page-report');
  if(!el) return;
  const pre = el.querySelector('pre');
  const text = pre ? pre.textContent : (window.__reportText||'No report');
  const pw = window.open('','_blank','width=800,height=900');
  if(pw){
    pw.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8">'+
      '<title>Monthly Report</title>'+
      '<style>@page{size:A4;margin:15mm}body{font-family:monospace;font-size:9pt;white-space:pre-wrap;color:#1a1a1a}'+
      'h2{font-family:Arial;font-size:14pt;margin-bottom:8px}</style></head>'+
      '<body><h2>The Home Of Smiles — Monthly Report</h2>'+text.replace(/</g,'&lt;').replace(/>/g,'&gt;')+
      '<script>window.onload=function(){window.print();window.onafterprint=function(){window.close();};};<\/script>'+
      '</body></html>');
    pw.document.close();
  }
}
function downloadReport(){
  const b=new Blob([window.__reportText||''],{type:'text/plain'});
  const a=document.createElement('a');a.href=URL.createObjectURL(b);
  a.download='HOS_Report_'+monthISO()+'.txt';a.click();
}
function shareReportWA(){
  const mo=monthISO();
  const pts=DATA.patients||[];
  const rev=pts.flatMap(p=>p.billing||[]).filter(b=>b.paid&&b.date.startsWith(mo)).reduce((s,b)=>s+Number(b.amount),0);
  const exp=(DATA.expenses||[]).filter(e=>e.date.startsWith(mo)).reduce((s,e)=>s+Number(e.amount),0)+FIXED_STAFF;
  const moLabel=new Date().toLocaleString('en-IN',{month:'long',year:'numeric'});
  const lines=[
    CLINIC,
    'Monthly Summary - ' + moLabel,
    '',
    'Revenue: ' + fmtMoney(rev),
    'Expenses: ' + fmtMoney(exp),
    'Net Profit: ' + fmtMoney(rev-exp),
    'Patients: ' + pts.filter(p=>p.createdAt.startsWith(mo)).length,
    '',
    DOCTOR + ' | ' + CITY
  ];
  window.open('https://wa.me/?text='+encodeURIComponent(lines.join(String.fromCharCode(10))),'_blank');
}
function resetAllData(){
  if(!confirm('Reset ALL data? This will permanently delete everything and cannot be undone.\n\nMake sure you have a backup first!'))return;
  DATA=getDefaultData(); saveData(); goPage('dashboard');
}

