/* ══ CHAIRSIDE MODE UPGRADE ══ */
var cs_activeTab='records',cs_timerInterval=null,cs_timerSeconds=0,cs_timerRunning=false;

function toggleChairsideMode(){
  const ov=document.getElementById('chairside-overlay');
  const on=ov.style.display==='none'||ov.style.display==='';
  if(on){
    if(!activePt){alert('Open a patient first, then enable Chairside Mode.');return;}
    ov.style.display='flex';ov.style.flexDirection='column';
    document.body.classList.add('chairside-mode');
    document.body.classList.add('chairside-active');
    cs_loadPatient();cs_tab('records');
    setTimeout(cs_applyChairsideStyle, 300);
  } else {cs_exit();}
  const b=document.getElementById('chairside-toggle');
  if(b){b.textContent=on?'ON':'OFF';b.style.background=on?'#16a34a':'#e2e8f0';b.style.color=on?'#fff':'#64748b';}
  localStorage.setItem('hos_chairside',on?'1':'0');
}
function cs_exit(){
  document.getElementById('chairside-overlay').style.display='none';
  document.body.classList.remove('chairside-mode');document.body.classList.remove('chairside-active');
  const b=document.getElementById('chairside-toggle');
  if(b){b.textContent='OFF';b.style.background='#e2e8f0';b.style.color='#64748b';}
  cs_stopTimer();localStorage.setItem('hos_chairside','0');
}
function cs_loadPatient(){
  if(!activePt)return;const p=activePt;
  const av=document.getElementById('cs-avatar');
  if(av){av.textContent=(p.name||'?')[0].toUpperCase();av.style.background=avatarColor(p.name);}
  const nm=document.getElementById('cs-name');if(nm)nm.textContent=p.name||'—';
  const mt=document.getElementById('cs-meta');
  if(mt)mt.textContent=(p.age||'?')+'y · '+(p.gender||'—')+' · '+(p.phone||'—')+(p.medHistory?' · ⚠️ '+p.medHistory.slice(0,40):'');
  const cp=document.getElementById('cs-complaint');
  if(cp&&p.complaint){cp.textContent='Chief Complaint: '+p.complaint;cp.style.display='block';}
  else if(cp)cp.style.display='none';
}
function cs_tab(name){
  cs_activeTab=name;
  document.querySelectorAll('.cs-tab').forEach(b=>b.classList.remove('active'));
  const btn=document.getElementById('cs-tab-'+name);if(btn)btn.classList.add('active');
  cs_renderContent();cs_renderActions();
}
function cs_recFormHTML(){
  var d=cs_timerSeconds;
  var fmtDur=function(s){return s>=3600?Math.floor(s/3600)+'h '+Math.floor((s%3600)/60)+'m':s>=60?Math.floor(s/60)+'m '+(s%60)+'s':s+'s';};
  var timerBadge=d>0?'<div style="font-size:11px;color:#60a5fa;background:#1e3a5f;padding:3px 8px;border-radius:6px">&#9201; '+fmtDur(d)+' will be saved</div>':'<div style="font-size:11px;color:#475569">Start timer to track time</div>';
  var html='<div id="cs-rec-form" style="display:none;background:#1e293b;border-radius:14px;padding:18px;margin-bottom:18px;border:1px solid #334155">';
  html+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><div style="font-size:14px;font-weight:700;color:#e2e8f0">&#10133; New Record</div>'+timerBadge+'</div>';
  html+=recTpl_renderDropdown();
  html+='<input id="cs-diag" class="form-input" placeholder="Diagnosis *" style="margin-bottom:10px;width:100%;box-sizing:border-box"/>';
  html+='<input id="cs-treat" class="form-input" placeholder="Treatment done" style="margin-bottom:10px;width:100%;box-sizing:border-box"/>';
  html+='<textarea id="cs-notes" class="form-input" rows="2" placeholder="Notes" style="width:100%;box-sizing:border-box;margin-bottom:10px"></textarea>';
  html+='<details style="margin-bottom:10px"><summary style="cursor:pointer;font-size:11px;font-weight:700;color:#64748b;padding:6px 10px;background:#f8fafc;border-radius:6px;list-style:none;display:flex;justify-content:space-between;align-items:center">&#128280; Advanced (Shade / Vitals / Timer) <span style="font-size:10px">tap to expand</span></summary>';
  html+='<div style="margin-top:8px">';
  html+='<div id="shade-picker-wrap">'+shade_renderPicker()+'</div>';
  html+=vitals_renderForm();
  html+='<div id="proc-timer-display"></div>';
  html+='</div></details>';
  html+='<div style="display:flex;gap:10px">';
  html+='<button onclick="cs_saveRecord()" style="background:#3b82f6;border:none;border-radius:10px;padding:10px 20px;color:#fff;font-weight:700;cursor:pointer;font-size:14px">&#128190; Save</button>';
  html+='<button onclick="cs_hideRecForm()" style="background:#334155;border:none;border-radius:10px;padding:10px 16px;color:#94a3b8;font-weight:700;cursor:pointer">Cancel</button>';
  html+='</div></div>';
  return html;
}
function cs_hideRecForm(){var f=document.getElementById('cs-rec-form');if(f)f.style.display='none';}

function cs_renderContent(){
  var el=document.getElementById('cs-content');
  if(!el||!activePt)return;
  var p=activePt;
  var fmtDur=function(s){if(!s||s===0)return null;return s>=3600?Math.floor(s/3600)+'h '+Math.floor((s%3600)/60)+'m':s>=60?Math.floor(s/60)+'m '+(s%60)+'s':s+'s';};

  if(cs_activeTab==='records'){
    var recs=(p.records||[]).slice().reverse();
    var tl=p.timeLogs||[];
    var tot=(p.records||[]).reduce(function(s,r){return s+(r.duration||0);},0)+tl.reduce(function(s,t){return s+(t.duration||0);},0);
    var html='';
    if(tot>0){
      html+='<div style="background:#1e3a5f;border-radius:12px;padding:12px 16px;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center">';
      html+='<div><div style="font-size:10px;color:#93c5fd;font-weight:700;text-transform:uppercase">Total Time Spent</div>';
      html+='<div style="font-size:22px;font-weight:800;color:#60a5fa">'+fmtDur(tot)+'</div></div></div>';
    }
    html+=cs_recFormHTML();
    if(recs.length===0){
      html+='<div style="color:#475569;text-align:center;padding:40px">No records yet &#8212; tap Add Record below</div>';
    } else {
      recs.forEach(function(r){
        html+='<div style="background:#1e293b;border-radius:14px;padding:16px;margin-bottom:12px;border-left:4px solid #3b82f6">';
        html+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">';
        html+='<span style="font-size:11px;color:#64748b">'+fmtDate(r.date)+'</span>';
        if(r.duration>0) html+='<span style="font-size:11px;font-weight:700;color:#a78bfa;background:#1e1040;padding:3px 9px;border-radius:8px">&#9201; '+fmtDur(r.duration)+'</span>';
        html+='</div>';
        html+='<div style="font-size:15px;font-weight:700;color:#e2e8f0;margin-bottom:4px">'+esc(r.diagnosis||'&#8212;')+'</div>';
        if(r.treatment) html+='<div style="font-size:13px;color:#94a3b8">'+esc(r.treatment)+'</div>';
        if(r.notes) html+='<div style="font-size:12px;color:#64748b;margin-top:4px;font-style:italic">'+esc(r.notes)+'</div>';
        html+='</div>';
      });
    }
    if(tl.length>0){
      html+='<div style="margin-top:8px;border-top:1px solid #334155;padding-top:12px">';
      html+='<div style="font-size:11px;color:#64748b;font-weight:700;text-transform:uppercase;margin-bottom:8px">&#9201; Time-Only Sessions</div>';
      tl.slice().reverse().forEach(function(t){
        html+='<div style="background:#1e293b;border-radius:10px;padding:10px 14px;margin-bottom:8px;border-left:4px solid #7c3aed;display:flex;justify-content:space-between;align-items:center">';
        html+='<div><div style="font-size:13px;color:#e2e8f0;font-weight:600">'+esc(t.label||'Session')+'</div>';
        html+='<div style="font-size:11px;color:#64748b">'+fmtDate(t.date)+'</div></div>';
        html+='<span style="font-size:14px;font-weight:800;color:#a78bfa">&#9201; '+fmtDur(t.duration)+'</span></div>';
      });
      html+='</div>';
    }
    el.innerHTML=html;

  } else if(cs_activeTab==='rx'){
    var rxs=(p.prescriptions||[]).slice().reverse();
    if(rxs.length===0){el.innerHTML='<div style="color:#475569;text-align:center;padding:40px">No prescriptions yet</div>';return;}
    var html='';
    rxs.forEach(function(rx){
      html+='<div style="background:#1e293b;border-radius:14px;padding:16px;margin-bottom:12px;border-left:4px solid #10b981">';
      html+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">';
      html+='<span style="font-size:13px;color:#94a3b8">'+fmtDate(rx.date)+'</span>';
      html+='<button onclick="printRx(&quot;'+rx.id+'&quot;)" style="background:#334155;border:none;border-radius:8px;padding:5px 12px;color:#60a5fa;font-size:12px;cursor:pointer;font-weight:700">&#128424; Print</button></div>';
      if(rx.diagnosis) html+='<div style="font-size:13px;color:#60a5fa;margin-bottom:8px">Dx: '+esc(rx.diagnosis)+'</div>';
      (rx.medicines||[]).filter(function(m){return m.name;}).forEach(function(m,i){
        html+='<div style="font-size:14px;color:#e2e8f0;margin-bottom:4px">'+(i+1)+'. <strong>'+esc(m.name)+'</strong>'+(m.dose?' &#183; '+m.dose:'')+(m.freq?' &#183; '+m.freq:'')+(m.duration?' &#215; '+m.duration:'')+'</div>';
      });
      if(rx.advice) html+='<div style="font-size:12px;color:#94a3b8;margin-top:6px;font-style:italic">Advice: '+esc(rx.advice)+'</div>';
      html+='</div>';
    });
    el.innerHTML=html;

  } else if(cs_activeTab==='billing'){
    var bills=(p.billing||[]).slice().reverse();
    var total=bills.reduce(function(s,b){return s+Number(b.amount||0);},0);
    var paid=bills.filter(function(b){return b.paid;}).reduce(function(s,b){return s+Number(b.amount||0);},0);
    var html='<div style="display:flex;gap:12px;margin-bottom:16px">';
    html+='<div style="flex:1;background:#14291a;border-radius:12px;padding:14px;border:1px solid #166534"><div style="font-size:11px;color:#4ade80;font-weight:700;margin-bottom:4px">COLLECTED</div><div style="font-size:22px;font-weight:800;color:#4ade80">&#8377;'+paid.toLocaleString('en-IN')+'</div></div>';
    html+='<div style="flex:1;background:#2d1f00;border-radius:12px;padding:14px;border:1px solid #92400e"><div style="font-size:11px;color:#fbbf24;font-weight:700;margin-bottom:4px">PENDING</div><div style="font-size:22px;font-weight:800;color:#fbbf24">&#8377;'+(total-paid).toLocaleString('en-IN')+'</div></div></div>';
    if(bills.length===0){html+='<div style="color:#475569;text-align:center;padding:40px">No billing entries</div>';}
    else{bills.forEach(function(b){
      html+='<div style="background:#1e293b;border-radius:12px;padding:14px;margin-bottom:10px;display:flex;align-items:center;justify-content:space-between;gap:10px">';
      html+='<div><div style="font-size:14px;font-weight:700;color:#e2e8f0">'+esc(b.item||'&#8212;')+'</div><div style="font-size:11px;color:#64748b">'+fmtDate(b.date)+'</div></div>';
      html+='<div style="display:flex;align-items:center;gap:10px"><div style="font-size:16px;font-weight:800;color:'+(b.paid?'#4ade80':'#fbbf24')+'">&#8377;'+Number(b.amount||0).toLocaleString('en-IN')+'</div>';
      html+='<span style="font-size:10px;font-weight:700;padding:3px 9px;border-radius:8px;background:'+(b.paid?'#14291a':'#2d1f00')+';color:'+(b.paid?'#4ade80':'#fbbf24')+'">'+(b.paid?'PAID':'DUE')+'</span></div></div>';
    });}
    el.innerHTML=html;

  } else if(cs_activeTab==='tooth'){
    el.innerHTML=renderToothChart(p.id);
  } else if(cs_activeTab==='txplan'){
    var plans=(p.treatmentPlan||[]).filter(function(i){return i.status!=='cancelled';});
    if(plans.length===0){el.innerHTML='<div style="color:#475569;text-align:center;padding:40px">No treatment plan entries</div>';return;}
    var html='';
    plans.forEach(function(item){
      html+='<div style="background:#1e293b;border-radius:12px;padding:14px;margin-bottom:10px;border-left:4px solid #8b5cf6">';
      html+='<div style="display:flex;justify-content:space-between;align-items:start">';
      html+='<div><div style="font-size:15px;font-weight:700;color:#e2e8f0">'+esc(item.procedure||'&#8212;')+'</div>';
      if(item.toothNo) html+='<div style="font-size:12px;color:#94a3b8">Tooth #'+item.toothNo+'</div>';
      html+='</div><div style="text-align:right"><div style="font-size:14px;font-weight:700;color:#a78bfa">&#8377;'+Number(item.estimatedCost||0).toLocaleString('en-IN')+'</div>';
      html+='<div style="font-size:11px;color:#64748b">'+(item.status||'planned')+'</div></div></div></div>';
    });
    el.innerHTML=html;
  }
}
function cs_renderActions(){
  var el=document.getElementById('cs-action-bar');if(!el)return;
  el.innerHTML='';
  function mkBtn(label,bg,fn){
    var b=document.createElement('button');
    b.className='cs-quick-btn';b.style.cssText='background:'+bg+';color:#fff';
    b.textContent=label;b.onclick=fn;el.appendChild(b);
  }
  if(cs_activeTab==='records'){
    mkBtn('+ Add Record','#3b82f6',function(){
      var f=document.getElementById('cs-rec-form');if(f)f.style.display='block';
      var d=document.getElementById('cs-diag');if(d)d.focus();
    });
    mkBtn('⏱ Log Time','#7c3aed',cs_logTimeOnly);
    mkBtn('Full View','#334155',function(){goPage('patients');cs_exit();});
  } else if(cs_activeTab==='rx'){
    mkBtn('+ New Rx','#10b981',function(){cs_exit();switchTab('prescriptions');newRx();});
  } else if(cs_activeTab==='billing'){
    mkBtn('+ Add Billing','#f59e0b',function(){cs_exit();switchTab('billing');showAddBill();});
  } else if(cs_activeTab==='tooth'){
    mkBtn('Edit Chart','#8b5cf6',function(){cs_exit();switchTab('tooth-chart');});
  } else if(cs_activeTab==='txplan'){
    mkBtn('Edit Plan','#8b5cf6',function(){cs_exit();switchTab('tx-plan');});
  }
}
function cs_saveRecord(){
  const diag=(document.getElementById('cs-diag')||{}).value?.trim();
  if(!diag){alert('Diagnosis required');return;}
  const treat=(document.getElementById('cs-treat')||{}).value?.trim();
  const notes=(document.getElementById('cs-notes')||{}).value?.trim();
  const duration=cs_timerSeconds;
  const shade = (document.getElementById('shade-value')||{}).value||'';
  const vitals = vitals_getFromForm();
  _selectedShade = ''; // reset
  const rec={id:'r'+Date.now(),date:todayISO(),diagnosis:diag,treatment:treat,notes,duration,shade,vitals};
  const idx=DATA.patients.findIndex(p=>p.id===activePt.id);
  DATA.patients[idx].records=[...(DATA.patients[idx].records||[]),rec];
  if(duration>0){
    if(!DATA.patients[idx].timeLogs)DATA.patients[idx].timeLogs=[];
    DATA.patients[idx].timeLogs.push({id:'tl'+Date.now(),date:todayISO(),duration,label:diag.slice(0,40)});
  }
  activePt=DATA.patients[idx];saveData();cs_resetTimer();
  document.getElementById('cs-rec-form').style.display='none';
  ['cs-diag','cs-treat','cs-notes'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  cs_renderContent();
}
function cs_logTimeOnly(){
  if(cs_timerSeconds===0){alert('Start the timer first.');return;}
  const label=prompt('Label this session:','Clinical Session')||'Clinical Session';
  const idx=DATA.patients.findIndex(p=>p.id===activePt.id);
  if(!DATA.patients[idx].timeLogs)DATA.patients[idx].timeLogs=[];
  DATA.patients[idx].timeLogs.push({id:'tl'+Date.now(),date:todayISO(),duration:cs_timerSeconds,label:label.slice(0,50)});
  activePt=DATA.patients[idx];saveData();cs_resetTimer();cs_renderContent();
}
function cs_quickWA(){
  if(!activePt)return;
  const msg='The Home Of Smiles Dental Clinic\nDr. Tanmay Jain | '+PHONE+'\n\nDear '+activePt.name+',\n\nThank you for visiting us today.\n\n'+TIMING;
  window.open('https://wa.me/91'+activePt.phone+'?text='+encodeURIComponent(msg),'_blank');
}
function cs_toggleTimer(){
  if(cs_timerRunning){cs_stopTimer();}
  else{
    cs_timerRunning=true;
    const btn=document.getElementById('cs-timer-btn');
    if(btn){btn.textContent='PAUSE';btn.style.background='#d97706';}
    cs_timerInterval=setInterval(()=>{
      cs_timerSeconds++;
      const m=String(Math.floor(cs_timerSeconds/60)).padStart(2,'0');
      const s=String(cs_timerSeconds%60).padStart(2,'0');
      const el=document.getElementById('cs-timer');if(el)el.textContent=m+':'+s;
    },1000);
  }
}
function cs_stopTimer(){
  cs_timerRunning=false;clearInterval(cs_timerInterval);
  const btn=document.getElementById('cs-timer-btn');
  if(btn){btn.textContent='START';btn.style.background='#3b82f6';}
}
function cs_resetTimer(){
  cs_stopTimer();cs_timerSeconds=0;
  const el=document.getElementById('cs-timer');if(el)el.textContent='00:00';
}

/* ── V6 Modal ── */
function openV6Modal(title, contentHTML){
  document.getElementById('v6-modal-content').innerHTML=`<h2 style="font-family:'Playfair Display',serif;font-size:19px;margin-bottom:18px;color:#1e3a5f">${title}</h2>${contentHTML}`;
  document.getElementById('v6-modal').classList.add('open');
}
function closeV6Modal(){
  document.getElementById('v6-modal').classList.remove('open');
}

/* ── Restore display prefs ── */
async function restoreDisplayPrefs(){
  if(localStorage.getItem('hos_dark')==='1') toggleDarkMode();
  if(localStorage.getItem('hos_chairside')==='1') toggleChairsideMode();
  // Backup reminder: check if last backup > 7 days
  (async()=>{
    try{
      const lb=await dbGet(STORE_META,'last_backup');
      if(!lb){
        setTimeout(()=>{document.getElementById('backup-reminder').style.display='flex';},3000);
      } else {
        const diff=(Date.now()-new Date(lb).getTime())/(1000*60*60*24);
        if(diff>7) setTimeout(()=>{document.getElementById('backup-reminder').style.display='flex';},3000);
      }
    }catch(e){}
  })();
}

/* ── Smart WhatsApp Pre-Send Questionnaire ── */
var waAnswers = {};
function showWAQuestionnaire(patientId){
  const p=(DATA.patients||[]).find(x=>x.id===patientId);
  if(!p){alert('Patient not found');return;}
  waAnswers={};
  const html=`
    <div class="wa-question">
      <div class="q-label">Pain or discomfort?</div>
      <div class="wa-options">
        <button class="wa-opt" onclick="setWAAnswer('pain','Yes',this)">Yes</button>
        <button class="wa-opt" onclick="setWAAnswer('pain','No',this)">No</button>
      </div>
    </div>
    <div class="wa-question">
      <div class="q-label">Wire poking?</div>
      <div class="wa-options">
        <button class="wa-opt" onclick="setWAAnswer('wire','Yes',this)">Yes</button>
        <button class="wa-opt" onclick="setWAAnswer('wire','No',this)">No</button>
      </div>
    </div>
    <div class="wa-question">
      <div class="q-label">Elastics being worn?</div>
      <div class="wa-options">
        <button class="wa-opt" onclick="setWAAnswer('elastic','Yes',this)">Yes</button>
        <button class="wa-opt" onclick="setWAAnswer('elastic','No',this)">No</button>
      </div>
    </div>
    <div class="wa-question">
      <div class="q-label">Appointment preference?</div>
      <div class="wa-options">
        <button class="wa-opt" onclick="setWAAnswer('slot','Morning',this)">Morning</button>
        <button class="wa-opt" onclick="setWAAnswer('slot','Evening',this)">Evening</button>
      </div>
    </div>
    <div class="wa-question">
      <div class="q-label">Emergency?</div>
      <div class="wa-options">
        <button class="wa-opt" onclick="setWAAnswer('emergency','Yes',this)">Yes</button>
        <button class="wa-opt" onclick="setWAAnswer('emergency','No',this)">No</button>
      </div>
    </div>
    <button class="btn btn-wa" style="width:100%;padding:13px;margin-top:8px" onclick="sendSmartWA('${patientId}')">
      📱 Generate & Send WhatsApp Message
    </button>`;
  openV6Modal('📋 Pre-Appointment Check — '+esc(p.name), html);
}

function setWAAnswer(key,val,btn){
  waAnswers[key]=val;
  btn.closest('.wa-options').querySelectorAll('.wa-opt').forEach(b=>b.classList.remove('selected'));
  btn.classList.add('selected');
}

function sendSmartWA(patientId){
  const p=(DATA.patients||[]).find(x=>x.id===patientId); if(!p) return;
  const od=p.orthoDetails||{};
  const fmt12hr=t=>{if(!t)return'';const[hh,mm]=t.split(':').map(Number);const ampm=hh>=12?'PM':'AM';return((hh%12)||12)+':'+String(mm).padStart(2,'0')+' '+ampm;};
  const lines=[
    waAnswers.emergency==='Yes' ? '🚨 URGENT APPOINTMENT NEEDED' : '',
    CLINIC, DOCTOR+' | '+PHONE, '---',
    'Dear '+p.name+',',
    '',
    od.nextAppt ? 'Your next appointment: '+fmtDate(od.nextAppt)+' at '+fmt12hr(od.nextApptTime||'10:00') : '',
    '',
  ];
  if(waAnswers.pain==='Yes') lines.push('⚠️ We understand you are experiencing discomfort. Please arrive as scheduled or call us immediately if severe.');
  if(waAnswers.wire==='Yes') lines.push('🦷 For wire discomfort, use orthodontic wax on the sharp end until your appointment. Call if severe.');
  if(waAnswers.elastic==='No') lines.push('📌 Reminder: Please wear your elastics as instructed — consistent wear is key to timely treatment completion!');
  if(waAnswers.slot) lines.push('⏰ Your preferred slot: '+waAnswers.slot+'. We will try to accommodate this.');
  lines.push('', 'Kindly arrive 10 minutes early. Bring previous records if any.', '', TIMING, CITY);
  const msg=lines.filter(l=>l!==undefined&&l!=='').join(String.fromCharCode(10));
  closeV6Modal();
  window.open('https://wa.me/91'+p.phone+'?text='+encodeURIComponent(msg),'_blank');
}

/* ── Payment Reminder WhatsApp ── */
function sendPaymentReminderWA(patientId){
  const p=(DATA.patients||[]).find(x=>x.id===patientId); if(!p) return;
  const due=(p.billing||[]).filter(b=>!b.paid).reduce((s,b)=>s+Math.max(0,Number(b.totalAmount||b.amount)-(b.paidAmount||0)),0);
  if(due<=0){alert('No pending amount for this patient.');return;}
  const msg=[
    CLINIC, DOCTOR+' | '+PHONE, '---',
    'Dear '+p.name+',',
    '',
    'This is a gentle reminder that your outstanding balance is:',
    '',
    '💰 Pending Amount: Rs.'+due.toLocaleString('en-IN'),
    '',
    'Please clear your dues at your earliest convenience. Thank you for choosing us!',
    '',
    TIMING, CITY
  ].join(String.fromCharCode(10));
  window.open('https://wa.me/91'+p.phone+'?text='+encodeURIComponent(msg),'_blank');
}

/* ── Case Tagging ── */
function setPatientTag(patientId, tag){
  const idx=DATA.patients.findIndex(p=>p.id===patientId); if(idx<0)return;
  const current=(DATA.patients[idx].tags||[]);
  if(current.includes(tag)){
    DATA.patients[idx].tags=current.filter(t=>t!==tag);
  } else {
    DATA.patients[idx].tags=[...current,tag];
  }
  if(activePt&&activePt.id===patientId) activePt=DATA.patients[idx];
  saveData();
  renderPatientHeader();
}

function renderTagBtns(p){
  const tags=p.tags||[];
  return `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">
    ${['High Value','Pending Payment','Complex Case'].map(t=>{
      const cls=t==='High Value'?'tag-highvalue':t==='Pending Payment'?'tag-pending':'tag-complex';
      const on=tags.includes(t);
      return `<span class="${on?cls:'badge badge-blue'}" style="cursor:pointer;${on?'':'opacity:.5'}" onclick="setPatientTag('${p.id}','${t}')">${on?'✓ ':'+'}${t}</span>`;
    }).join('')}
  </div>`;
}

/* ── Auto Follow-Up Suggestions ── */
var FOLLOWUP_RULES = {
  'Root Canal':3,'RCT':3,'Scaling':30,'Extraction':7,'Implant':14,
  'Braces':28,'Ortho':28,'Clear Aligners':28,'Consultation':90,'Filling':180,
  'Crown':7,'Whitening':180
};

function getFollowUpDays(diagnosis){
  const dl=(diagnosis||'').toLowerCase();
  for(const[k,v] of Object.entries(FOLLOWUP_RULES)){
    if(dl.includes(k.toLowerCase())) return v;
  }
  return null;
}

function renderFollowUpBanner(p){
  const recs=(p.records||[]);
  if(!recs.length) return '';
  const last=recs[0];
  const days=getFollowUpDays(last.diagnosis);
  if(!days) return '';
  const followupDate=new Date(last.date+'T00:00:00');
  followupDate.setDate(followupDate.getDate()+days);
  const fdStr=followupDate.toISOString().slice(0,10);
  const today=todayISO();
  if(fdStr<today) return '';
  return `<div class="followup-banner">
    <div>
      <div style="font-size:13px;font-weight:700;color:#065f46">💡 Suggested Follow-Up</div>
      <div style="font-size:12px;color:#047857;margin-top:2px">${last.diagnosis.slice(0,40)} → Follow up on <strong>${fmtDate(fdStr)}</strong> (${days} days)</div>
    </div>
    <button class="btn btn-teal btn-sm" onclick="scheduleFollowUp('${p.id}','${fdStr}')">📅 Schedule</button>
  </div>`;
}

function scheduleFollowUp(patientId, dateStr){
  const p=(DATA.patients||[]).find(x=>x.id===patientId); if(!p) return;
  const appt={id:genId(),patientId,date:dateStr,time:'10:00',notes:'Follow-up visit',createdAt:todayISO()};
  DATA.appointments=[...(DATA.appointments||[]),appt];
  saveData();
  alert('Follow-up appointment scheduled for '+fmtDate(dateStr)+'!');
}

/* ── Tooth Chart (FDI) ── */
// FDI Adult — quadrant arrays (screen L→R = patient R→L)
var FDI_UPPER_Q1=[18,17,16,15,14,13,12,11]; // patient's right
var FDI_UPPER_Q2=[21,22,23,24,25,26,27,28]; // patient's left
var FDI_LOWER_Q4=[48,47,46,45,44,43,42,41]; // patient's right
var FDI_LOWER_Q3=[31,32,33,34,35,36,37,38]; // patient's left
// FDI Pedo (Deciduous) — quadrant arrays
var PEDO_UPPER_Q5=[55,54,53,52,51];
var PEDO_UPPER_Q6=[61,62,63,64,65];
var PEDO_LOWER_Q8=[85,84,83,82,81];
var PEDO_LOWER_Q7=[71,72,73,74,75];
// Legacy compat
var FDI_UPPER=[FDI_UPPER_Q1,FDI_UPPER_Q2];
var FDI_LOWER=[FDI_LOWER_Q4,FDI_LOWER_Q3];

function getToothData(patientId, toothNum){
  const p=(DATA.patients||[]).find(x=>x.id===patientId); if(!p) return null;
  return (p.toothChart||{})[toothNum]||null;
}

var TOOTH_STATUSES = [
  { value:'',          label:'Healthy / No issue',  cls:'',            code:'' },
  { value:'pending',   label:'🔴 Needs Treatment',  cls:'tx-pending',  code:'Tx' },
  { value:'planned',   label:'🟡 Planned',           cls:'tx-planned',  code:'Pln' },
  { value:'done',      label:'🟢 Treatment Done',    cls:'tx-done',     code:'✓' },
  { value:'rct',       label:'🦷 RCT Done',          cls:'tx-rct',      code:'RCT' },
  { value:'crown',     label:'👑 Crown / Cap',       cls:'tx-crown',    code:'Cr' },
  { value:'extracted', label:'⬛ Extracted',          cls:'tx-extracted',code:'Ext' },
  { value:'implant',   label:'🔩 Implant',           cls:'tx-implant',  code:'Imp' },
  { value:'bridge',    label:'🌉 Bridge',            cls:'tx-bridge',   code:'Br' },
  { value:'missing',   label:'⬜ Missing / Gap',     cls:'tx-missing',  code:'—' },
  { value:'sealant',   label:'💜 Sealant / Fluoride',cls:'tx-sealant',  code:'Fl' },
];

function toothStatusClass(status){
  const s = TOOTH_STATUSES.find(x=>x.value===status);
  return s ? s.cls : '';
}
function toothStatusCode(status){
  const s = TOOTH_STATUSES.find(x=>x.value===status);
  return s ? s.code : '';
}

function renderToothChart(patientId){
  const p=(DATA.patients||[]).find(x=>x.id===patientId); if(!p) return '';
  const tc=p.toothChart||{};
  const isPedo=p.isPedoChart===true;

  function btn(n){
    const d=tc[n];
    const cls=d?toothStatusClass(d.status):'';
    const code=d?toothStatusCode(d.status):'';
    return `<button class="tooth-btn ${cls}" onclick="openToothModal('${patientId}',${n})" title="Tooth ${n}${d&&d.diagnosis?' — '+d.diagnosis:''}">
      <span class="tooth-num">${n}</span>
      ${code?`<span class="tooth-code">${code}</span>`:''}
    </button>`;
  }
  function arch(leftArr,rightArr){
    return `<div style="display:flex;align-items:center;justify-content:center;flex-wrap:nowrap;gap:0">
      <div style="display:flex;gap:3px;flex-wrap:nowrap">${leftArr.map(btn).join('')}</div>
      <div style="width:2px;min-height:44px;background:linear-gradient(180deg,#dc2626,#16a34a);border-radius:2px;flex-shrink:0;margin:0 5px"></div>
      <div style="display:flex;gap:3px;flex-wrap:nowrap">${rightArr.map(btn).join('')}</div>
    </div>`;
  }

  const toggle=`<div style="display:flex;justify-content:center;gap:8px;margin-bottom:14px">
    <button class="btn btn-sm ${!isPedo?'btn-primary':'btn-ghost'}" onclick="setChartType('${patientId}',false)">🦷 Adult</button>
    <button class="btn btn-sm ${isPedo?'btn-primary':'btn-ghost'}" onclick="setChartType('${patientId}',true)">🍼 Pedo / Milk Teeth</button>
  </div>`;

  let uArch,lArch,uLbl,lLbl;
  if(isPedo){
    uArch=arch(PEDO_UPPER_Q5,PEDO_UPPER_Q6);
    lArch=arch(PEDO_LOWER_Q8,PEDO_LOWER_Q7);
    uLbl=`<div style="display:flex;justify-content:space-between;padding:0 18px;font-size:9px;font-weight:800;color:#7c3aed;margin-bottom:3px"><span>Q5 (55–51)</span><span>Q6 (61–65)</span></div>`;
    lLbl=`<div style="display:flex;justify-content:space-between;padding:0 18px;font-size:9px;font-weight:800;color:#7c3aed;margin-top:3px"><span>Q8 (85–81)</span><span>Q7 (71–75)</span></div>`;
  } else {
    uArch=arch(FDI_UPPER_Q1,FDI_UPPER_Q2);
    lArch=arch(FDI_LOWER_Q4,FDI_LOWER_Q3);
    uLbl=`<div style="display:flex;justify-content:space-between;padding:0 18px;font-size:9px;font-weight:800;color:#1d4ed8;margin-bottom:3px"><span>Q1 (18–11)</span><span>Q2 (21–28)</span></div>`;
    lLbl=`<div style="display:flex;justify-content:space-between;padding:0 18px;font-size:9px;font-weight:800;color:#1d4ed8;margin-top:3px"><span>Q4 (48–41)</span><span>Q3 (31–38)</span></div>`;
  }

  // Summary of annotated teeth
  const annotated = Object.entries(tc).filter(([,d])=>d&&d.status);
  const summaryHTML = annotated.length > 0 ? `
    <div style="margin-top:16px">
      <div style="font-size:12px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">📋 Tooth Summary (${annotated.length} annotated)</div>
      <div class="table-wrap">
        <div class="table-head" style="grid-template-columns:60px 100px 1fr 1fr">
          <span>Tooth</span><span>Status</span><span>Diagnosis</span><span>Treatment</span>
        </div>
        ${annotated.sort((a,b)=>Number(a[0])-Number(b[0])).map(([num,d])=>{
          const sm=TOOTH_STATUSES.find(x=>x.value===d.status)||{label:d.status,cls:''};
          return `<div class="table-row" style="grid-template-columns:60px 100px 1fr 1fr;cursor:pointer" onclick="openToothModal('${patientId}',${num})">
            <div style="font-weight:800;font-size:14px;color:#1e293b">#${num}</div>
            <div><span class="badge ${sm.cls}" style="font-size:10px">${sm.label.replace(/^[^\s]+\s/,'')}</span></div>
            <div style="font-size:12px;color:#374151">${esc(d.diagnosis||'—')}</div>
            <div style="font-size:12px;color:#374151">${esc(d.treatment||'—')}</div>
          </div>`;
        }).join('')}
      </div>
    </div>` : '';

  const legend=`<div class="tooth-legend" style="margin-top:10px">
    ${TOOTH_STATUSES.filter(s=>s.value).map(s=>`
      <span>
        <span class="tooth-btn ${s.cls}" style="width:14px;height:14px;border-radius:3px;display:inline-block;flex-shrink:0;font-size:0"></span>
        ${s.label.replace(/^[^\s]+\s/,'')}
      </span>`).join('')}
  </div>`;

  return `<div class="tooth-chart-wrap">
    ${toggle}
    <div style="background:#f8fafc;border:1.5px solid #e2e8f0;border-radius:14px;padding:14px 10px 12px;overflow-x:auto">
      <div style="min-width:320px">
        <div style="display:flex;justify-content:space-between;padding:0 12px;font-size:9px;font-weight:800;color:#94a3b8;letter-spacing:.8px;margin-bottom:3px">
          <span>← R (Patient's Right)</span><span>(Patient's Left) L →</span>
        </div>
        <div style="text-align:center;font-size:10px;font-weight:800;color:#475569;letter-spacing:.8px;margin-bottom:6px">UPPER JAW ↑</div>
        ${uLbl}${uArch}
        <div style="border-top:2.5px dashed #cbd5e1;margin:10px 6px"></div>
        ${lArch}${lLbl}
        <div style="text-align:center;font-size:10px;font-weight:800;color:#475569;letter-spacing:.8px;margin-top:6px">↓ LOWER JAW</div>
      </div>
    </div>
    ${legend}
    ${summaryHTML}
  </div>`;
}

function setChartType(patientId,isPedo){
  const idx=DATA.patients.findIndex(p=>p.id===patientId); if(idx<0) return;
  DATA.patients[idx].isPedoChart=isPedo;
  activePt=DATA.patients[idx]; saveData(); switchTab('tooth-chart');
}

function openToothModal(patientId, toothNum){ tc_openSurfaceModal(patientId, toothNum); }
function openToothModal_orig(patientId, toothNum){
  const p=(DATA.patients||[]).find(x=>x.id===patientId); if(!p) return;
  const tc=p.toothChart||{};
  const d=tc[toothNum]||{};
  const statusOpts = TOOTH_STATUSES.map(s=>
    `<option value="${s.value}" ${d.status===s.value?'selected':''}>${s.label}</option>`
  ).join('');
  const html=`
    <div class="form-group"><label class="form-label">Status</label>
      <select class="form-input" id="tooth-status">${statusOpts}</select>
    </div>
    <div class="form-group"><label class="form-label">Diagnosis / Finding</label>
      <input class="form-input" id="tooth-diag" value="${esc(d.diagnosis||'')}" placeholder="e.g. Deep caries, Fracture, Periapical abscess"/>
    </div>
    <div class="form-group"><label class="form-label">Treatment Done / Planned</label>
      <input class="form-input" id="tooth-tx" value="${esc(d.treatment||'')}" placeholder="e.g. Zirconia Crown, RCT+Crown, Extraction done"/>
    </div>
    <div class="form-group"><label class="form-label">Notes</label>
      <input class="form-input" id="tooth-notes" value="${esc(d.notes||'')}" placeholder="Shade, post details, follow-up…"/>
    </div>
    <div style="display:flex;gap:10px;margin-top:4px">
      <button class="btn btn-primary" style="flex:1" onclick="saveToothData('${patientId}',${toothNum})">💾 Save</button>
      <button class="btn btn-red" onclick="clearToothData('${patientId}',${toothNum})">🗑️ Clear</button>
      <button class="btn btn-ghost" onclick="closeV6Modal()">Cancel</button>
    </div>`;
  openV6Modal('🦷 Tooth #'+toothNum+' — '+esc(p.name), html);
}

function saveToothData(patientId, toothNum){
  const idx=DATA.patients.findIndex(p=>p.id===patientId); if(idx<0) return;
  const status=document.getElementById('tooth-status').value;
  const diag=document.getElementById('tooth-diag').value;
  const tx=document.getElementById('tooth-tx').value;
  const notes=document.getElementById('tooth-notes')?.value||'';
  if(!DATA.patients[idx].toothChart) DATA.patients[idx].toothChart={};
  if(!status&&!diag&&!tx&&!notes){
    delete DATA.patients[idx].toothChart[toothNum];
  } else {
    DATA.patients[idx].toothChart[toothNum]={status,diagnosis:diag,treatment:tx,notes};
  }
  activePt=DATA.patients[idx];
  saveData();
  closeV6Modal();
  switchTab('tooth-chart');
}

function clearToothData(patientId, toothNum){
  if(!confirm('Clear all data for Tooth #'+toothNum+'?')) return;
  const idx=DATA.patients.findIndex(p=>p.id===patientId); if(idx<0) return;
  if(DATA.patients[idx].toothChart) delete DATA.patients[idx].toothChart[toothNum];
  activePt=DATA.patients[idx];
  saveData();
  closeV6Modal();
  switchTab('tooth-chart');
}

/* ── Ortho Visit Tracker (Advanced) ── */
var ORTHO_WIRES = [
  '0.012 NiTi','0.014 NiTi','0.016 NiTi','0.016x22 NiTi','0.017x25 NiTi',
  '0.017x25 SS','0.019x25 NiTi','0.019x25 SS','0.021x25 SS','TMA 0.017x25',
  'Reverse Curve NiTi','Utility Arch','Ideal Arch SS'
];
var ORTHO_ELASTICS=['None','Class I (Same Side)','Class II','Class III','Vertical','Triangle','Box','Cross-bite'];
var ORTHO_ECHAIN=['None','Short E-chain','Medium E-chain','Long E-chain','Continuous E-chain'];
var ORTHO_APPT_TYPE=['Activation','Review','Wire Change','E-chain Placement','Bracket Bonding','Debond','Retainer Fit','Emergency','Consultation'];
var ORTHO_RETAINERS=['None','Hawley Retainer','Essix/Vacuum-formed','Fixed Lingual (3-3)','Fixed Lingual (6-6)','Begg Retainer'];
var ORTHO_QUICK_NOTES=[
  'Good progress, continue','Patient compliant','Poor oral hygiene - advised','Need more engagement',
  'Space closure in progress','Levelling and aligning','Detailing phase','Ready for debond soon',
  'IPR done','Bracket rebonded','Power chain replaced','Auxillary spring placed'
];

function renderOrthoVisitsTab(patientId){
  const p=(DATA.patients||[]).find(x=>x.id===patientId)||activePt;
  if(!p||p.type!=='ortho') return '<div class="empty"><span class="empty-icon">🦷</span><div class="empty-title">Not an ortho patient</div></div>';
  const visits=(p.orthoVisits||[]);
  const lastVisit=visits[0]||null;
  
  return `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
      <div class="sec-title" style="margin:0">🦷 Ortho Visit Log (${visits.length})</div>
      <div style="display:flex;gap:8px">
        ${lastVisit?`<button class="btn btn-ghost btn-sm" onclick="repeatLastOrthoVisit('${p.id}')">🔄 Repeat Last</button>`:''}
        <button class="btn btn-primary btn-sm" onclick="showAddOrthoVisit('${p.id}')">+ New Visit</button>
      </div>
    </div>
    <div id="ortho-visit-form-wrap"></div>
    <div id="ortho-visits-list">
      ${visits.length===0?`<div class="empty" style="border:1px solid #e2e8f0;border-radius:14px"><span class="empty-icon">🦷</span><div class="empty-title">No ortho visits yet</div></div>`
      :visits.map((v,i)=>orthoVisitCardHTML(v,i)).join('')}
    </div>`;
}

function orthoVisitCardHTML(v, idx){
  return `<div class="ortho-visit-card">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
      <div>
        <span class="badge badge-purple" style="margin-right:6px">${esc(v.type||'Visit')}</span>
        <span style="font-size:12px;color:#64748b">${fmtDate(v.date)}</span>
      </div>
      <button class="btn btn-red btn-sm btn-icon" onclick="deleteOrthoVisit('${v.id}')">×</button>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:12px;margin-bottom:8px">
      ${v.wire?`<div><span style="color:#94a3b8;font-weight:700;text-transform:uppercase;font-size:10px">Wire</span><div style="font-weight:600;color:#7c3aed">${esc(v.wire)}</div></div>`:''}
      ${v.elastics&&v.elastics!=='None'?`<div><span style="color:#94a3b8;font-weight:700;text-transform:uppercase;font-size:10px">Elastics</span><div style="font-weight:600;color:#1d4ed8">${esc(v.elastics)}</div></div>`:''}
      ${v.echain&&v.echain!=='None'?`<div><span style="color:#94a3b8;font-weight:700;text-transform:uppercase;font-size:10px">E-Chain</span><div style="font-weight:600;color:#059669">${esc(v.echain)}</div></div>`:''}
      ${v.retainer&&v.retainer!=='None'?`<div><span style="color:#94a3b8;font-weight:700;text-transform:uppercase;font-size:10px">Retainer</span><div style="font-weight:600;color:#d97706">${esc(v.retainer)}</div></div>`:''}
    </div>
    ${v.notes?`<div style="background:#f8fafc;border-left:3px solid #7c3aed;border-radius:0 8px 8px 0;padding:7px 12px;font-size:12px;color:#475569">${esc(v.notes)}</div>`:''}
  ${v.nextAppt?`<div style="font-size:11px;color:#3b82f6;margin-top:6px;font-weight:700">&#128197; Next appt: ${fmtDate(v.nextAppt)}</div>`:''}
  </div>`;
}

