/* ── Export single patient ── */
function exportSinglePatient(patientId){
  const p=(DATA.patients||[]).find(x=>x.id===patientId);
  if(!p){alert('Patient not found');return;}
  const payload={patient:p,exportedAt:new Date().toISOString(),clinic:CLINIC};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='Patient_'+p.name.replace(/\s+/g,'_')+'_'+p.id+'.json';
  a.click(); URL.revokeObjectURL(a.href);
  alert('Patient data exported: '+p.name);
}

/* ══════════════════════════════════════════════════════
   EDIT PATIENT
══════════════════════════════════════════════════════ */
function showEditPatient() {
  const p = activePt;
  if (!p) return;
  // Pre-fill all fields with current values
  document.getElementById('ep-name').value      = p.name      || '';
  document.getElementById('ep-phone').value     = p.phone     || '';
  document.getElementById('ep-age').value       = p.age       || '';
  document.getElementById('ep-dob').value       = fmtDob(p.dob||'');
  document.getElementById('ep-gender').value    = p.gender    || 'Female';
  document.getElementById('ep-type').value      = p.type      || 'regular';
  document.getElementById('ep-address').value   = p.address   || '';
  document.getElementById('ep-complaint').value = p.complaint || '';
  document.getElementById('ep-medhist').value   = p.medHistory|| '';
  document.getElementById('edit-patient-modal').style.display = 'flex';
}

function closeEditPatient() {
  document.getElementById('edit-patient-modal').style.display = 'none';
}

function saveEditPatient() {
  const name  = document.getElementById('ep-name').value.trim();
  const phone = document.getElementById('ep-phone').value.trim();
  if (!name)  { alert('Name is required.'); return; }
  if (!phone) { alert('Phone is required.'); return; }

  const idx = DATA.patients.findIndex(p => p.id === activePt.id);
  if (idx < 0) return;

  const prevType = DATA.patients[idx].type;
  const newType  = document.getElementById('ep-type').value;

  DATA.patients[idx] = {
    ...DATA.patients[idx],
    name,
    phone,
    age:        document.getElementById('ep-age').value,
    dob:        dobToISO(document.getElementById('ep-dob').value),
    gender:     document.getElementById('ep-gender').value,
    type:       newType,
    address:    document.getElementById('ep-address').value,
    complaint:  document.getElementById('ep-complaint').value,
    medHistory: document.getElementById('ep-medhist').value,
    // Auto-init orthoDetails if switched to ortho and none exist yet
    orthoDetails: newType === 'ortho' && !DATA.patients[idx].orthoDetails
      ? { startDate: todayISO(), bracket: 'Metal Braces', totalCost: '', paidAmount: 0, nextAppt: '', nextApptTime: '10:00', treatmentNotes: '' }
      : DATA.patients[idx].orthoDetails,
  };

  activePt = DATA.patients[idx];
  saveData();
  closeEditPatient();

  // Refresh header and show/hide Ortho tabs if type changed
  renderPatientHeader();
  const isOrtho = activePt.type === 'ortho';
  var hasAlignerCase = !!(DATA.alignerCases||[]).find(function(ac){return ac.patientId===p.id;});
  document.getElementById('tab-ortho-detail').style.display  = (isOrtho||hasAlignerCase) ? '' : 'none';
  document.getElementById('tab-ortho-visits').style.display  = isOrtho ? '' : 'none';
}


var _origInitApp = initApp;
async function initApp() {
  // Clear any corrupted nav order from previous drag-reorder feature
  localStorage.removeItem('hos_nav_order');
  await loadDataFromDB();
  initDoctorAuth();
  restoreDisplayPrefs();
  goPage('dashboard');
  // Warn if running on file:// - camera/xray won't work
  if(location.protocol==='file:'){
    setTimeout(function(){
      var warn=document.createElement('div');
      warn.id='file-warn';
      warn.style.cssText='position:fixed;top:0;left:0;right:0;background:#7f1d1d;color:#fef2f2;font-size:12px;font-weight:600;text-align:center;padding:9px 16px;z-index:99999;display:flex;align-items:center;justify-content:space-between;gap:10px';
      warn.innerHTML='<span>⚠️ Camera & X-ray need the local server. Double-click <strong>StartServer.bat</strong> → open <strong>http://localhost:8080/HomeOfSmiles_v51_FINAL.html</strong> in Chrome</span>'+
        '<button onclick="document.getElementById(&quot;file-warn&quot;).remove()" style="background:rgba(255,255,255,.2);border:none;color:#fff;padding:4px 10px;border-radius:6px;cursor:pointer;font-size:12px;flex-shrink:0">✕ dismiss</button>';
      document.body.appendChild(warn);
    },1500);
  }
  // Auto checks after data loads
  setTimeout(birthday_autoCheck, 2000);
  setTimeout(appt_autoReminderCheck, 2500);
  setTimeout(sidebar_renderFooter, 600);
}

/* ══════════════════════════════════════════════════════
   ALIGNER CASES MODULE
══════════════════════════════════════════════════════ */

/* ── Helpers ── */
function getAlignerCases() {
  return DATA.alignerCases || (DATA.alignerCases = []);
}

function saveAlignerCase(c) {
  const cases = getAlignerCases();
  const idx = cases.findIndex(x => x.id === c.id);
  if (idx >= 0) cases[idx] = c; else cases.unshift(c);
  DATA.alignerCases = cases;
  saveData();
}

function addDaysToDate(dateStr, days) {
  const d = new Date(dateStr + 'T00:00:00');
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}

function alignerStatus(c) {
  if (c.treatmentStatus === 'completed') return 'completed';
  if (c.treatmentStatus === 'paused') return 'paused';
  if (c.nextChangeDate < todayISO()) return 'overdue';
  const diff = (new Date(c.nextChangeDate) - new Date()) / (1000 * 60 * 60 * 24);
  if (diff <= 3) return 'upcoming';
  return 'active';
}

/* ── Render: Page (list + stats) ── */
function renderAlignerPage() {
  renderAlignerStats();
  checkAlignerReminders();
  renderAlignerList();
  document.getElementById('aligner-form-wrap').style.display = 'none';
  document.getElementById('aligner-detail-wrap').style.display = 'none';
  document.getElementById('aligner-list').style.display = 'block';
}

function renderAlignerStats() {
  const cases = getAlignerCases();
  const active    = cases.filter(c => c.treatmentStatus === 'ongoing').length;
  const completed = cases.filter(c => c.treatmentStatus === 'completed').length;
  const overdue   = cases.filter(c => alignerStatus(c) === 'overdue').length;
  const pending   = cases.reduce((s, c) => s + (Number(c.pendingAmount) || 0), 0);
  const el = document.getElementById('aligner-stats');
  if (!el) return;
  el.innerHTML = [
    {l:'Total Cases',     v: cases.length, icon:'💎', c:'#1d4ed8', bg:'#eff6ff'},
    {l:'Active',          v: active,        icon:'🔄', c:'#059669', bg:'#ecfdf5'},
    {l:'Completed',       v: completed,     icon:'✅', c:'#7c3aed', bg:'#f5f3ff'},
    {l:'Overdue Changes', v: overdue,       icon:'⚠️', c:'#dc2626', bg:'#fef2f2'},
    {l:'Pending Revenue', v:'₹'+pending.toLocaleString('en-IN'), icon:'💰', c:'#d97706', bg:'#fffbeb'},
  ].map(s => `<div class="stat-card">
    <div>
      <div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:5px">${s.l}</div>
      <div style="font-size:26px;font-weight:800;color:#1e293b">${s.v}</div>
    </div>
    <div class="stat-icon" style="background:${s.bg}">${s.icon}</div>
  </div>`).join('');
}

function checkAlignerReminders() {
  const cases = getAlignerCases();
  const today = todayISO();
  const el = document.getElementById('aligner-reminders');
  if (!el) return;
  const overdue  = cases.filter(c => c.treatmentStatus === 'ongoing' && c.nextChangeDate < today);
  const upcoming = cases.filter(c => {
    if (c.treatmentStatus !== 'ongoing') return false;
    const diff = (new Date(c.nextChangeDate) - new Date()) / (1000 * 60 * 60 * 24);
    return diff >= 0 && diff <= 3;
  });
  let html = '';
  if (overdue.length) {
    html += overdue.map(c => `
      <div class="alert-box alert-red" style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:8px">
        <div>
          <div style="font-weight:700;color:#dc2626">⚠️ Overdue: ${esc(c.patientName)} — Set #${c.currentSet}/${c.totalSets}</div>
          <div style="font-size:12px;color:#7f1d1d">Change was due: ${fmtDate(c.nextChangeDate)}</div>
        </div>
        <div style="display:flex;gap:8px">
          <button class="btn btn-wa btn-sm" onclick="sendAlignerWA('${c.id}')">📲 Remind</button>
          <button class="btn btn-primary btn-sm" onclick="openAlignerDetail('${c.id}')">Open</button>
        </div>
      </div>`).join('');
  }
  if (upcoming.length) {
    html += upcoming.map(c => `
      <div class="alert-box alert-amber" style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:8px">
        <div>
          <div style="font-weight:700;color:#d97706">⏰ Due Soon: ${esc(c.patientName)} — Set #${c.currentSet}/${c.totalSets}</div>
          <div style="font-size:12px;color:#92400e">Change due: ${fmtDate(c.nextChangeDate)}</div>
        </div>
        <div style="display:flex;gap:8px">
          <button class="btn btn-wa btn-sm" onclick="sendAlignerWA('${c.id}')">📲 Remind</button>
          <button class="btn btn-primary btn-sm" onclick="openAlignerDetail('${c.id}')">Open</button>
        </div>
      </div>`).join('');
  }
  el.innerHTML = html;
}

function renderAlignerList() {
  const cases = getAlignerCases();
  const el = document.getElementById('aligner-list');
  if (!el) return;
  if (!cases.length) {
    el.innerHTML = `<div class="empty"><span class="empty-icon">💎</span>
      <div class="empty-title">No aligner cases yet</div>
      <div class="empty-sub">Click "New Aligner Case" to get started</div></div>`;
    return;
  }
  const cols = '2fr 1.2fr 1.4fr 1fr 1fr auto';
  let html = `<div class="table-wrap">
    <div class="table-head" style="grid-template-columns:${cols}">
      <div>Patient</div><div>Progress</div><div>Next Change</div><div>Payment</div><div>Status</div><div></div>
    </div>`;
  cases.forEach(c => {
    const pct = Math.round((c.currentSet / c.totalSets) * 100);
    const st  = alignerStatus(c);
    const stBadge = {
      active:    '<span class="badge badge-blue">🔄 Active</span>',
      upcoming:  '<span class="badge badge-amber">⏰ Soon</span>',
      overdue:   '<span class="badge badge-red">⚠️ Overdue</span>',
      completed: '<span class="badge badge-green">✅ Done</span>',
      paused:    '<span class="badge badge-purple">⏸ Paused</span>',
    }[st] || '';
    const pending = Number(c.pendingAmount) || 0;
    html += `<div class="table-row row-clickable" style="grid-template-columns:${cols}" onclick="openAlignerDetail('${c.id}')">
      <div>
        <div style="font-weight:700;font-size:14px">${esc(c.patientName)}</div>
        <div style="font-size:11px;color:#64748b">${c.phone || ''}</div>
      </div>
      <div>
        <div style="font-size:12px;font-weight:700;margin-bottom:4px">Set ${c.currentSet} / ${c.totalSets}</div>
        <div class="prog-track"><div class="prog-fill" style="width:${pct}%;background:${pct>=100?'#16a34a':'#1d4ed8'}"></div></div>
        <div style="font-size:10px;color:#94a3b8;margin-top:2px">${pct}%</div>
      </div>
      <div style="font-size:13px;color:${st==='overdue'?'#dc2626':st==='upcoming'?'#d97706':'#1e293b'};font-weight:600">
        ${fmtDate(c.nextChangeDate)}
      </div>
      <div>${pending > 0
        ? `<span class="badge badge-amber">₹${pending.toLocaleString('en-IN')} due</span>`
        : `<span class="badge badge-green">Paid</span>`}
      </div>
      <div>${stBadge}</div>
      <div style="display:flex;gap:5px" onclick="event.stopPropagation()">
        <button class="btn btn-wa btn-sm btn-icon" onclick="sendAlignerWA('${c.id}')" title="WhatsApp Reminder">📲</button>
      </div>
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
}

/* ── Render: New / Edit form ── */
