  const cases = getAlignerCases();
  const c = editId ? cases.find(x => x.id === editId) : null;
  const allPts = (DATA.patients || []);

  document.getElementById('aligner-list').style.display = 'none';
  document.getElementById('aligner-detail-wrap').style.display = 'none';
  const wrap = document.getElementById('aligner-form-wrap');
