function closeAlignerDetail() {
  document.getElementById('aligner-detail-wrap').style.display = 'none';
  document.getElementById('aligner-list').style.display = 'block';
}

/* ── Actions ── */
function nextAlignerSet(id) {
  const cases = getAlignerCases();
  const idx = cases.findIndex(x => x.id === id);
  if (idx < 0) return;
  const c = cases[idx];
  if (c.currentSet >= c.totalSets) {
    if (confirm('Patient is on the last set. Mark treatment as completed?')) {
      markAlignerCompleted(id);
    }
    return;
  }
  const newSet = c.currentSet + 1;
  if (!confirm(`Advance to Set #${newSet}? This records today as the last change date.`)) return;
  cases[idx] = {
    ...c,
    currentSet: newSet,
    lastChangeDate: todayISO(),
    nextChangeDate: addDaysToDate(todayISO(), 15),
    timeline: [...(c.timeline || []), { date: todayISO(), event: `Advanced to Set #${newSet}`, set: newSet }],
  };
  DATA.alignerCases = cases;
  saveData();
  openAlignerDetail(id);
  renderAlignerStats();
  checkAlignerReminders();
}

function addAlignerPayment(id) {
  const amtStr = prompt('Enter payment amount (₹):');
  if (!amtStr) return;
  const amt = Number(amtStr);
  if (!amt || amt <= 0) { alert('Enter a valid amount.'); return; }
  const note = prompt('Payment note (optional):') || '';

  const cases = getAlignerCases();
  const idx = cases.findIndex(x => x.id === id);
  if (idx < 0) return;
  const c = cases[idx];
  const newPaid = (c.paidAmount || 0) + amt;
  cases[idx] = {
    ...c,
    paidAmount:    newPaid,
    pendingAmount: Math.max(0, (c.totalAmount || 0) - newPaid),
    paymentHistory: [...(c.paymentHistory || []), { date: todayISO(), amount: amt, note }],
    timeline: [...(c.timeline || []), {
      date: todayISO(),
      event: `Payment received: ₹${amt.toLocaleString('en-IN')}`,
      note,
    }],
  };
  DATA.alignerCases = cases;
  // ── SYNC to patient billing ──
  aligner_syncPaymentToBilling(id, amt, note);
  saveData();
  openAlignerDetail(id);
  renderAlignerStats();
}

function markAlignerCompleted(id) {
  if (!confirm('Mark this aligner case as completed?')) return;
  const cases = getAlignerCases();
  const idx = cases.findIndex(x => x.id === id);
  if (idx < 0) return;
  cases[idx] = {
    ...cases[idx],
    treatmentStatus: 'completed',
    timeline: [...(cases[idx].timeline || []), { date: todayISO(), event: '🎉 Treatment Completed!' }],
  };
  DATA.alignerCases = cases;
  saveData();
  openAlignerDetail(id);
  renderAlignerStats();
  checkAlignerReminders();
}

function deleteAlignerCase(id) {
  if (!confirm('Delete this aligner case? This cannot be undone.')) return;
  DATA.alignerCases = getAlignerCases().filter(x => x.id !== id);
  saveData();
  closeAlignerDetail();
  renderAlignerPage();
}

function sendAlignerWA(id) {
  const c = getAlignerCases().find(x => x.id === id);
  if (!c || !c.phone) { alert('No phone number for this patient.'); return; }
  const msg = `Hi ${c.patientName}! 😊\n\nThis is a reminder from *The Home Of Smiles* regarding your Clear Aligner treatment.\n\n` +
    `📋 *Set #${c.currentSet} of ${c.totalSets}*\n` +
    `📅 *Next Change Due:* ${fmtDate(c.nextChangeDate)}\n\n` +
    `Please switch to your next set of aligners as scheduled. Wear each set for 20-22 hours/day for best results.\n\n` +
    `For any queries, contact us:\n📞 ${PHONE}\n⏰ ${TIMING}`;
  window.open('https://wa.me/91' + c.phone.replace(/\D/g, '').slice(-10) + '?text=' + encodeURIComponent(msg), '_blank');
}



/* ══════════════════════════════════════════════════════
   RX TEMPLATES — Feature #1
   Prefix: rxTpl_  |  DATA key: DATA.rxTemplates
══════════════════════════════════════════════════════ */
var rxTpl_medCount = 0;

function rxTpl_render() {
  rxTpl_renderCustom();
  rxTpl_renderBuiltin();
}

function rxTpl_renderCustom() {
  const list = document.getElementById('rxTpl-custom-list');
  if (!list) return;
  const templates = DATA.rxTemplates || [];
  if (templates.length === 0) {
    list.innerHTML = `<div class="empty" style="border:1px solid #e2e8f0;border-radius:14px;padding:30px 20px">
      <span class="empty-icon">📝</span>
      <div class="empty-title">No custom templates yet</div>
      <div class="empty-sub">Click "New Template" to create your first one</div>
    </div>`;
    return;
  }
  list.innerHTML = templates.map(t => `
    <div class="card" style="margin-bottom:12px;border:1px solid #e2e8f0">
      <div class="card-header">
        <div>
          <div style="font-weight:700;font-size:14px;color:#1e293b">${esc(t.label)}</div>
          <div style="font-size:12px;color:#64748b;margin-top:2px">${esc(t.diagnosis||'—')} · ${(t.medicines||[]).filter(m=>m.name).length} medicines</div>
        </div>
        <div style="display:flex;gap:7px">
          <button class="btn btn-ghost btn-sm" onclick="rxTpl_editForm('${t.id}')">✏️ Edit</button>
          <button class="btn btn-red btn-sm" onclick="rxTpl_delete('${t.id}')">🗑️ Delete</button>
        </div>
      </div>
      <div class="card-body" style="padding:14px 20px">
        ${(t.medicines||[]).filter(m=>m.name).length > 0
          ? `<div style="display:flex;flex-direction:column;gap:4px">
              ${(t.medicines||[]).filter(m=>m.name).map(m=>`
                <div style="display:flex;gap:10px;font-size:12px;align-items:center">
                  <span style="font-weight:600;min-width:160px;color:#1e293b">${esc(m.name)}</span>
                  <span class="badge badge-blue">${esc(m.dose||'—')}</span>
                  <span class="badge badge-teal">${esc(m.freq||'—')}</span>
                  <span style="color:#64748b">${esc(m.duration||'—')}</span>
                </div>`).join('')}
            </div>`
          : `<span style="font-size:12px;color:#94a3b8">No medicines added</span>`}
        ${t.advice ? `<div style="margin-top:10px;font-size:12px;color:#64748b;background:#f8fafc;border-radius:8px;padding:8px 12px">💬 ${esc(t.advice)}</div>` : ''}
      </div>
    </div>`).join('');
}

function rxTpl_renderBuiltin() {
  const list = document.getElementById('rxTpl-builtin-list');
  if (!list) return;
  list.innerHTML = RX_PRESETS.map(t => `
    <div class="card" style="margin-bottom:12px;border:1px solid #f1f5f9;opacity:.85">
      <div class="card-header">
        <div>
          <div style="font-weight:700;font-size:14px;color:#1e293b">${esc(t.label)}</div>
          <div style="font-size:12px;color:#64748b;margin-top:2px">${esc(t.diagnosis||'—')} · ${(t.medicines||[]).length} medicines</div>
        </div>
        <span class="badge badge-purple">Built-in</span>
      </div>
      <div class="card-body" style="padding:14px 20px">
        <div style="display:flex;flex-direction:column;gap:4px">
          ${t.medicines.map(m=>`
            <div style="display:flex;gap:10px;font-size:12px;align-items:center">
              <span style="font-weight:600;min-width:160px;color:#1e293b">${esc(m.name)}</span>
              <span class="badge badge-blue">${esc(m.dose||'—')}</span>
              <span class="badge badge-teal">${esc(m.freq||'—')}</span>
              <span style="color:#64748b">${esc(m.duration||'—')}</span>
            </div>`).join('')}
        </div>
        ${t.advice ? `<div style="margin-top:10px;font-size:12px;color:#64748b;background:#f8fafc;border-radius:8px;padding:8px 12px">💬 ${esc(t.advice)}</div>` : ''}
      </div>
    </div>`).join('');
}

function rxTpl_showForm() {
  document.getElementById('rxTpl-edit-id').value = '';
  document.getElementById('rxTpl-label').value = '';
  document.getElementById('rxTpl-diagnosis').value = '';
  document.getElementById('rxTpl-advice').value = '';
  document.getElementById('rxTpl-form-title').textContent = 'New Template';
  rxTpl_medCount = 0;
  document.getElementById('rxTpl-meds-list').innerHTML = '';
  rxTpl_addMedRow();
  document.getElementById('rxTpl-form-wrap').style.display = 'block';
  document.getElementById('rxTpl-label').focus();
  document.getElementById('rxTpl-form-wrap').scrollIntoView({behavior:'smooth',block:'start'});
}

function rxTpl_hideForm() {
  document.getElementById('rxTpl-form-wrap').style.display = 'none';
}

function rxTpl_addMedRow() {
  const idx = rxTpl_medCount++;
  const row = document.createElement('div');
  row.id = 'rxTpl-med-row-' + idx;
  row.style.cssText = 'display:grid;grid-template-columns:2fr 1fr 1fr 1fr 28px;gap:7px;margin-bottom:7px;align-items:center';
  row.innerHTML = `
    <input class="form-input" style="font-size:12px;padding:7px 9px" placeholder="Tab. Amoxclav-625" data-field="name"/>
    <input class="form-input" style="font-size:12px;padding:7px 9px" placeholder="500mg" data-field="dose"/>
    <select class="form-input" style="font-size:12px;padding:7px 9px" data-field="freq">
      <option value="">-</option>${FREQS.map(f=>`<option>${f}</option>`).join('')}
    </select>
    <input class="form-input" style="font-size:12px;padding:7px 9px" placeholder="5 days" data-field="duration"/>
    <button class="btn btn-red btn-icon btn-sm" onclick="document.getElementById('rxTpl-med-row-${idx}').remove()">x</button>`;
  document.getElementById('rxTpl-meds-list').appendChild(row);
}

function rxTpl_collectMeds() {
  const rows = document.querySelectorAll('#rxTpl-meds-list > div');
  return Array.from(rows).map(row => ({
    name:     (row.querySelector('[data-field="name"]')?.value||'').trim(),
    dose:     (row.querySelector('[data-field="dose"]')?.value||'').trim(),
    freq:     (row.querySelector('[data-field="freq"]')?.value||'').trim(),
    duration: (row.querySelector('[data-field="duration"]')?.value||'').trim()
  })).filter(m => m.name);
}

function rxTpl_save() {
  const label = document.getElementById('rxTpl-label').value.trim();
  if (!label) { alert('Please enter a template name.'); return; }
  const editId = document.getElementById('rxTpl-edit-id').value;
  const tpl = {
    id:        editId || ('tpl' + Date.now()),
    label,
    diagnosis: document.getElementById('rxTpl-diagnosis').value.trim(),
    advice:    document.getElementById('rxTpl-advice').value.trim(),
    medicines: rxTpl_collectMeds()
  };
  if (editId) {
    DATA.rxTemplates = (DATA.rxTemplates||[]).map(t => t.id === editId ? tpl : t);
  } else {
    DATA.rxTemplates = [...(DATA.rxTemplates||[]), tpl];
  }
  saveData();
  rxTpl_hideForm();
  rxTpl_render();
}

function rxTpl_delete(id) {
  if (!confirm('Delete this template? This cannot be undone.')) return;
  DATA.rxTemplates = (DATA.rxTemplates||[]).filter(t => t.id !== id);
  saveData();
  rxTpl_render();
}

function rxTpl_editForm(id) {
  const t = (DATA.rxTemplates||[]).find(x => x.id === id);
  if (!t) return;
  document.getElementById('rxTpl-edit-id').value   = t.id;
  document.getElementById('rxTpl-label').value      = t.label;
  document.getElementById('rxTpl-diagnosis').value  = t.diagnosis || '';
  document.getElementById('rxTpl-advice').value     = t.advice || '';
  document.getElementById('rxTpl-form-title').textContent = 'Edit Template';
  rxTpl_medCount = 0;
  const medsList = document.getElementById('rxTpl-meds-list');
  medsList.innerHTML = '';
  (t.medicines||[]).forEach(m => {
    const idx = rxTpl_medCount++;
    const row = document.createElement('div');
    row.id = 'rxTpl-med-row-' + idx;
    row.style.cssText = 'display:grid;grid-template-columns:2fr 1fr 1fr 1fr 28px;gap:7px;margin-bottom:7px;align-items:center';
    row.innerHTML = `
      <input class="form-input" style="font-size:12px;padding:7px 9px" value="${esc(m.name)}" data-field="name"/>
      <input class="form-input" style="font-size:12px;padding:7px 9px" value="${esc(m.dose)}" data-field="dose"/>
      <select class="form-input" style="font-size:12px;padding:7px 9px" data-field="freq">
        <option value="">-</option>${FREQS.map(f=>`<option ${m.freq===f?'selected':''}>${f}</option>`).join('')}
      </select>
      <input class="form-input" style="font-size:12px;padding:7px 9px" value="${esc(m.duration)}" data-field="duration"/>
      <button class="btn btn-red btn-icon btn-sm" onclick="document.getElementById('rxTpl-med-row-${idx}').remove()">x</button>`;
    medsList.appendChild(row);
  });
  document.getElementById('rxTpl-form-wrap').style.display = 'block';
  document.getElementById('rxTpl-form-wrap').scrollIntoView({behavior:'smooth',block:'start'});
}

/* ══════════════════════════════════════════════════════
   LAB WORK TRACKER — Feature #2
   Prefix: lab_  |  DATA key: DATA.labJobs
══════════════════════════════════════════════════════ */
var LAB_WORK_TYPES = [
  'Metal Crown','PFM Crown','Zirconia Crown','E-Max Crown',
  'Complete Denture','Partial Denture (RPD)',
  'Fixed Bridge','Maryland Bridge',
  'Retainer (Hawley)','Retainer (Vacuum-formed)',
  'Night Guard','Surgical Stent','Post & Core','Inlay / Onlay','Other'
];

var lab_activeFilter = 'all';

function lab_getJobs() { return DATA.labJobs || []; }

function lab_isOverdue(job) {
  if (job.status !== 'pending') return false;
  if (!job.dueDate) return false;
  return job.dueDate < todayISO();
}

function lab_effectiveStatus(job) {
  return lab_isOverdue(job) ? 'overdue' : job.status;
}



function lab_renderStats() {
  const el = document.getElementById('lab-stats');
  if (!el) return;
  const jobs = lab_getJobs();
  const today = todayISO();
  const thisMonth = today.slice(0,7);
  const total     = jobs.length;
  const pending   = jobs.filter(j => j.status === 'pending' && !lab_isOverdue(j)).length;
  const overdue   = jobs.filter(j => lab_isOverdue(j)).length;
  const receivedThisMonth = jobs.filter(j => j.status !== 'pending' && (j.receivedDate||'').startsWith(thisMonth)).length;
  const totalCost = jobs.reduce((s,j) => s + Number(j.cost||0), 0);
  const unpaidCost = jobs.filter(j => !j.paid).reduce((s,j) => s + Number(j.cost||0), 0);

  el.innerHTML = [
    {icon:'🏭', label:'Total Jobs',        value:total,                          bg:'#eff6ff', ic:'#dbeafe'},
    {icon:'⏳', label:'Pending',           value:pending,                        bg:'#fffbeb', ic:'#fef3c7'},
    {icon:'🔴', label:'Overdue',           value:overdue,                        bg:'#fef2f2', ic:'#fee2e2'},
    {icon:'✅', label:'Received This Month',value:receivedThisMonth,             bg:'#ecfdf5', ic:'#d1fae5'},
    {icon:'💰', label:'Total Lab Cost',    value:'₹'+totalCost.toLocaleString('en-IN'), bg:'#f5f3ff', ic:'#ede9fe'},
    {icon:'💸', label:'Unpaid to Lab',     value:'₹'+unpaidCost.toLocaleString('en-IN'), bg:'#fff7ed', ic:'#fed7aa'},
  ].map(s=>`
    <div class="stat-card">
      <div><div style="font-size:11px;color:#64748b;font-weight:600;text-transform:uppercase;letter-spacing:.4px;margin-bottom:4px">${s.label}</div>
        <div style="font-size:22px;font-weight:800;color:#1e293b">${s.value}</div></div>
      <div class="stat-icon" style="background:${s.ic};font-size:22px">${s.icon}</div>
    </div>`).join('');
}

function lab_setFilter(f) {
  lab_activeFilter = f;
  document.querySelectorAll('[id^="lab-chip-"]').forEach(b => {
    b.style.background = '#f1f5f9'; b.style.color = '#64748b';
  });
  const active = document.getElementById('lab-chip-'+f);
  if (active) { active.style.background = '#eff6ff'; active.style.color = '#1d4ed8'; }
  lab_renderList();
}

function lab_renderList() {
  const el = document.getElementById('lab-list');
  if (!el) return;
  let jobs = lab_getJobs().slice().sort((a,b) => (a.dueDate||'').localeCompare(b.dueDate||''));

  if (lab_activeFilter !== 'all') {
    jobs = jobs.filter(j => lab_effectiveStatus(j) === lab_activeFilter);
  }

  if (jobs.length === 0) {
    el.innerHTML = `<div class="empty" style="border:1px solid #e2e8f0;border-radius:14px;padding:44px 20px">
      <span class="empty-icon">🏭</span>
      <div class="empty-title">No lab jobs${lab_activeFilter!=='all'?' in this category':''}</div>
      <div class="empty-sub">Click "New Lab Job" to log your first one</div>
    </div>`;
    return;
  }

  el.innerHTML = `
    <div class="table-wrap">
      <div class="table-head" style="grid-template-columns:1.5fr 1.2fr 1fr 90px 90px 100px 80px 70px">
        <span>Patient / Work</span><span>Lab</span><span>Tooth / Shade</span>
        <span>Sent</span><span>Due</span><span>Status</span><span>Cost</span><span>Actions</span>
      </div>
      ${jobs.map(j => {
        const status = lab_effectiveStatus(j);
        const statusMeta = {
          pending:   {label:'Pending',   cls:'badge-amber'},
          overdue:   {label:'⚠️ Overdue', cls:'badge-red'},
          received:  {label:'Received',  cls:'badge-blue'},
          delivered: {label:'Delivered', cls:'badge-green'},
          redo:      {label:'Redo',      cls:'badge-purple'},
        }[status] || {label:status, cls:'badge-blue'};
        return `
        <div class="table-row" style="grid-template-columns:1.5fr 1.2fr 1fr 90px 90px 100px 80px 70px">
          <div>
            <div style="font-weight:700;font-size:13px;color:#1e293b">${esc(j.patientName||'—')}</div>
            <div style="font-size:11px;color:#64748b">${esc(j.workType)}</div>
          </div>
          <div style="font-size:13px;color:#374151">${esc(j.labName||'—')}</div>
          <div>
            <div style="font-size:12px;color:#374151">${esc(j.toothNo||'—')}</div>
            <div style="font-size:11px;color:#94a3b8">${j.shade?'Shade: '+esc(j.shade):''}</div>
          </div>
          <div style="font-size:12px;color:#64748b">${j.sentDate?fmtDate(j.sentDate):'—'}</div>
          <div style="font-size:12px;color:${status==='overdue'?'#dc2626':'#64748b'};font-weight:${status==='overdue'?'700':'400'}">${j.dueDate?fmtDate(j.dueDate):'—'}</div>
          <div><span class="badge ${statusMeta.cls}">${statusMeta.label}</span>
            ${!j.paid?'<span class="badge badge-red" style="margin-top:3px;display:block;width:fit-content">Unpaid</span>':''}</div>
          <div style="font-size:13px;font-weight:700;color:#1e293b">₹${Number(j.cost||0).toLocaleString('en-IN')}</div>
          <div style="display:flex;gap:4px;flex-wrap:wrap">
            ${j.status==='pending'?`<button class="btn btn-sm" style="background:#ecfdf5;color:#059669;padding:4px 7px;font-size:10px" onclick="lab_markReceived('${j.id}')">✅ Rcvd</button>`:''}
            ${j.status==='received'?`<button class="btn btn-sm" style="background:#eff6ff;color:#1d4ed8;padding:4px 7px;font-size:10px" onclick="lab_markDelivered('${j.id}')">📦 Del.</button>`:''}
            <button class="btn btn-sm" style="background:#f1f5f9;color:#475569;padding:4px 7px;font-size:10px" onclick="lab_showEditForm('${j.id}')">✏️</button>
            <button class="btn btn-red btn-sm" style="padding:4px 7px;font-size:10px" onclick="lab_delete('${j.id}')">🗑️</button>
          </div>
        </div>`;
      }).join('')}
    </div>`;
}

function lab_showForm() {
  const patients = (DATA.patients||[]).map(p=>`<option value="${esc(p.name)}">${esc(p.name)}</option>`).join('');
  document.getElementById('lab-form-wrap').innerHTML = `
    <div class="card card-body" style="max-width:800px;border:2px solid #bfdbfe">
      <div style="font-size:15px;font-weight:700;color:#1e3a5f;margin-bottom:16px" id="lab-form-title">➕ New Lab Job</div>
      <input type="hidden" id="lab-edit-id" value=""/>
      <div class="form-grid-2">
        <div class="form-group">
          <label class="form-label">Patient Name</label>
          <input class="form-input" id="lab-patient" list="lab-patient-list" placeholder="Type or select patient"/>
          <datalist id="lab-patient-list">${patients}</datalist>
        </div>
        <div class="form-group">
          <label class="form-label">Work Type *</label>
          <select class="form-input" id="lab-worktype">
            <option value="">Select…</option>
            ${LAB_WORK_TYPES.map(w=>`<option>${w}</option>`).join('')}
          </select>
        </div>
        <div class="form-group">
          <label class="form-label">Lab Name</label>
          <input class="form-input" id="lab-labname" placeholder="e.g. Smile Lab, Kota Dental Lab"/>
        </div>
        <div class="form-group">
          <label class="form-label">Tooth No(s)</label>
          <input class="form-input" id="lab-toothno" placeholder="e.g. #16, #26 or Upper 6"/>
        </div>
        <div class="form-group">
          <label class="form-label">Shade</label>
          <input class="form-input" id="lab-shade" placeholder="e.g. A2, B1, BL2"/>
        </div>
        <div class="form-group">
          <label class="form-label">Lab Cost (₹)</label>
          <input class="form-input" id="lab-cost" type="number" placeholder="0"/>
        </div>
        <div class="form-group">
          <label class="form-label">Date Sent to Lab</label>
          <input class="form-input" id="lab-sentdate" type="date"/>
        </div>
        <div class="form-group">
          <label class="form-label">Expected Return Date</label>
          <input class="form-input" id="lab-duedate" type="date"/>
        </div>
        <div class="form-group">
          <label class="form-label">Status</label>
          <select class="form-input" id="lab-status">
            <option value="pending">⏳ Pending</option>
            <option value="received">✅ Received</option>
            <option value="delivered">📦 Delivered to Patient</option>
            <option value="redo">🔁 Redo</option>
          </select>
        </div>
        <div class="form-group" style="display:flex;align-items:center;gap:10px;padding-top:28px">
          <input type="checkbox" id="lab-paid" style="width:18px;height:18px;cursor:pointer"/>
          <label for="lab-paid" style="font-size:13px;font-weight:600;color:#374151;cursor:pointer">Lab fee paid ✓</label>
        </div>
      </div>
      <div class="form-group">
        <label class="form-label">Notes</label>
        <textarea class="form-input" id="lab-notes" rows="2" placeholder="Any special instructions, material specs, or follow-up notes"></textarea>
      </div>
      <div style="display:flex;gap:10px;margin-top:4px">
        <button class="btn btn-primary" onclick="lab_save()">💾 Save Job</button>
        <button class="btn btn-ghost" onclick="lab_hideForm()">Cancel</button>
      </div>
    </div>`;
  document.getElementById('lab-sentdate').value = todayISO();
  document.getElementById('lab-form-wrap').style.display = 'block';
  document.getElementById('lab-form-wrap').scrollIntoView({behavior:'smooth',block:'start'});
}

function lab_showEditForm(id) {
  lab_showForm();
  const j = lab_getJobs().find(x => x.id === id);
  if (!j) return;
  document.getElementById('lab-form-title').textContent = '✏️ Edit Lab Job';
  document.getElementById('lab-edit-id').value   = j.id;
  document.getElementById('lab-patient').value   = j.patientName||'';
  document.getElementById('lab-worktype').value  = j.workType||'';
  document.getElementById('lab-labname').value   = j.labName||'';
  document.getElementById('lab-toothno').value   = j.toothNo||'';
  document.getElementById('lab-shade').value     = j.shade||'';
  document.getElementById('lab-cost').value      = j.cost||0;
  document.getElementById('lab-sentdate').value  = j.sentDate||'';
  document.getElementById('lab-duedate').value   = j.dueDate||'';
  document.getElementById('lab-status').value    = j.status||'pending';
  document.getElementById('lab-paid').checked    = !!j.paid;
  document.getElementById('lab-notes').value     = j.notes||'';
}

function lab_hideForm() {
  document.getElementById('lab-form-wrap').style.display = 'none';
  document.getElementById('lab-form-wrap').innerHTML = '';
}

function lab_save() {
  const workType = document.getElementById('lab-worktype').value;
  if (!workType) { alert('Please select a work type.'); return; }
  const editId = document.getElementById('lab-edit-id').value;
  const labPtName = document.getElementById('lab-patient').value.trim();
  const labPtMatch = (DATA.patients||[]).find(function(p){ return p.name.toLowerCase()===labPtName.toLowerCase(); });
  const job = {
    id:          editId || ('labj' + Date.now()),
    patientId:   labPtMatch ? labPtMatch.id : '',
    patientName: labPtName,
    workType,
    labName:     document.getElementById('lab-labname').value.trim(),
    toothNo:     document.getElementById('lab-toothno').value.trim(),
    shade:       document.getElementById('lab-shade').value.trim(),
    cost:        Number(document.getElementById('lab-cost').value) || 0,
    sentDate:    document.getElementById('lab-sentdate').value,
    receivedDate: (document.getElementById('lab-received')||{}).value||'',
    dueDate:     document.getElementById('lab-duedate').value,
    receivedDate: editId ? (lab_getJobs().find(j=>j.id===editId)?.receivedDate||'') : '',
    status:      document.getElementById('lab-status').value,
    paid:        document.getElementById('lab-paid').checked,
    notes:       document.getElementById('lab-notes').value.trim(),
    createdAt:   editId ? (lab_getJobs().find(j=>j.id===editId)?.createdAt||todayISO()) : todayISO()
  };
  if (editId) {
    DATA.labJobs = (DATA.labJobs||[]).map(j => j.id === editId ? job : j);
  } else {
    DATA.labJobs = [...(DATA.labJobs||[]), job];
  }
  saveData();
  lab_hideForm();
  lab_render();
}

function lab_markReceived(id) {
  if (!confirm('Mark this job as Received from lab?')) return;
  DATA.labJobs = (DATA.labJobs||[]).map(j =>
    j.id === id ? {...j, status:'received', receivedDate:todayISO()} : j
  );
  saveData();
  lab_render();
}

function lab_markDelivered(id) {
  if (!confirm('Mark as Delivered to patient?')) return;
  DATA.labJobs = (DATA.labJobs||[]).map(j =>
    j.id === id ? {...j, status:'delivered'} : j
  );
  saveData();
  lab_render();
}

function lab_delete(id) {
  if (!confirm('Delete this lab job? Cannot be undone.')) return;
  DATA.labJobs = (DATA.labJobs||[]).filter(j => j.id !== id);
  saveData();
  lab_render();
}

/* ══════════════════════════════════════════════════════
   INVENTORY / STOCK TRACKER — Feature #3
   Prefix: inv_  |  DATA key: DATA.inventory
══════════════════════════════════════════════════════ */
var INV_CATEGORIES = [
  'Anaesthetics','Restorative Materials','Endodontic',
  'Surgical Supplies','Ortho Materials','Impression Materials',
  'Infection Control','Preventive','X-Ray','Office / Stationery','Miscellaneous'
];
var INV_UNITS = ['Box','Pack','Bottle','Vial','Piece','Roll','Tube','Syringe','Sachet','Sheet','Set','Other'];

var inv_activeFilter = 'all';

function inv_getItems() { return DATA.inventory || []; }

function inv_stockStatus(item) {
  const qty = Number(item.quantity || 0);
  const min = Number(item.minStock || 0);
  if (qty === 0)       return 'out';
  if (min > 0 && qty <= min) return 'low';
  return 'ok';
}

function inv_render() {
  inv_renderStats();
  inv_populateCatFilter();
  inv_renderList();
}

function inv_renderStats() {
  const el = document.getElementById('inv-stats');
  if (!el) return;
  const items = inv_getItems();
  const total     = items.length;
  const outCount  = items.filter(i => inv_stockStatus(i) === 'out').length;
  const lowCount  = items.filter(i => inv_stockStatus(i) === 'low').length;
  const okCount   = items.filter(i => inv_stockStatus(i) === 'ok').length;
  const totalVal  = items.reduce((s,i) => s + (Number(i.quantity||0) * Number(i.costPerUnit||0)), 0);
  const cats      = [...new Set(items.map(i => i.category).filter(Boolean))].length;

  el.innerHTML = [
    {icon:'📦', label:'Total Items',    value:total,   bg:'#eff6ff', ic:'#dbeafe'},
    {icon:'✅', label:'Well Stocked',  value:okCount,  bg:'#ecfdf5', ic:'#d1fae5'},
    {icon:'⚠️', label:'Low Stock',     value:lowCount, bg:'#fffbeb', ic:'#fef3c7'},
    {icon:'🔴', label:'Out of Stock',  value:outCount, bg:'#fef2f2', ic:'#fee2e2'},
    {icon:'💰', label:'Stock Value',   value:'₹'+totalVal.toLocaleString('en-IN'), bg:'#f5f3ff', ic:'#ede9fe'},
    {icon:'🗂️', label:'Categories',   value:cats,     bg:'#f0fdfa', ic:'#ccfbf1'},
  ].map(s=>`
    <div class="stat-card">
      <div>
        <div style="font-size:11px;color:#64748b;font-weight:600;text-transform:uppercase;letter-spacing:.4px;margin-bottom:4px">${s.label}</div>
        <div style="font-size:22px;font-weight:800;color:#1e293b">${s.value}</div>
      </div>
      <div class="stat-icon" style="background:${s.ic};font-size:22px">${s.icon}</div>
    </div>`).join('');
}

function inv_populateCatFilter() {
  const sel = document.getElementById('inv-cat-filter');
  if (!sel) return;
  const cats = [...new Set(inv_getItems().map(i => i.category).filter(Boolean))].sort();
  const cur  = sel.value;
  sel.innerHTML = '<option value="">All Categories</option>' +
    cats.map(c => `<option ${c===cur?'selected':''}>${c}</option>`).join('');
}

function inv_setFilter(f) {
  inv_activeFilter = f;
  ['all','low','out'].forEach(x => {
    const b = document.getElementById('inv-chip-'+x);
    if (b) { b.style.background = '#f1f5f9'; b.style.color = '#64748b'; }
  });
  const active = document.getElementById('inv-chip-'+f);
  if (active) { active.style.background = '#eff6ff'; active.style.color = '#1d4ed8'; }
  inv_renderList();
}

function inv_renderList() {
  const el = document.getElementById('inv-list');
  if (!el) return;
  const search  = (document.getElementById('inv-search')?.value || '').toLowerCase();
  const catFilter = document.getElementById('inv-cat-filter')?.value || '';

  let items = inv_getItems().slice().sort((a,b) => (a.name||'').localeCompare(b.name||''));

  if (inv_activeFilter === 'low') items = items.filter(i => inv_stockStatus(i) === 'low');
  if (inv_activeFilter === 'out') items = items.filter(i => inv_stockStatus(i) === 'out');
  if (catFilter) items = items.filter(i => i.category === catFilter);
  if (search)    items = items.filter(i =>
    (i.name||'').toLowerCase().includes(search) ||
    (i.category||'').toLowerCase().includes(search) ||
    (i.supplier||'').toLowerCase().includes(search)
  );

  if (items.length === 0) {
    el.innerHTML = `<div class="empty" style="border:1px solid #e2e8f0;border-radius:14px;padding:44px 20px">
      <span class="empty-icon">📦</span>
      <div class="empty-title">No items found</div>
      <div class="empty-sub">Click "Add Item" to start tracking your stock</div>
    </div>`;
    return;
  }

  const statusMeta = {
    ok:  { label:'✅ OK',        cls:'badge-green',  row:'' },
    low: { label:'⚠️ Low',      cls:'badge-amber',  row:'background:#fffbeb' },
    out: { label:'🔴 Out',      cls:'badge-red',    row:'background:#fef2f2' },
  };

  el.innerHTML = `
    <div class="table-wrap">
      <div class="table-head" style="grid-template-columns:1.8fr 1.2fr 80px 60px 70px 90px 100px 90px">
        <span>Item</span><span>Category</span><span>Qty</span><span>Unit</span>
        <span>Min Qty</span><span>Cost/Unit</span><span>Total Value</span><span>Actions</span>
      </div>
      ${items.map(item => {
        const st  = inv_stockStatus(item);
        const sm  = statusMeta[st];
        const val = Number(item.quantity||0) * Number(item.costPerUnit||0);
        return `
        <div class="table-row" style="grid-template-columns:1.8fr 1.2fr 80px 60px 70px 90px 100px 90px;${sm.row}">
          <div>
            <div style="font-weight:700;font-size:13px;color:#1e293b">${esc(item.name)}</div>
            ${item.supplier?`<div style="font-size:11px;color:#94a3b8">${esc(item.supplier)}</div>`:''}
          </div>
          <div style="font-size:12px;color:#64748b">${esc(item.category||'—')}</div>
          <div style="font-size:15px;font-weight:800;color:${st==='out'?'#dc2626':st==='low'?'#d97706':'#059669'}">${item.quantity||0}</div>
          <div style="font-size:12px;color:#64748b">${esc(item.unit||'—')}</div>
          <div style="font-size:12px;color:#64748b">${item.minStock||0}</div>
          <div style="font-size:12px;color:#374151">₹${Number(item.costPerUnit||0).toLocaleString('en-IN')}</div>
          <div style="font-size:13px;font-weight:700;color:#1e293b">₹${val.toLocaleString('en-IN')}</div>
          <div style="display:flex;gap:4px;flex-wrap:wrap">
            <button class="btn btn-sm" style="background:#ecfdf5;color:#059669;padding:4px 7px;font-size:10px" onclick="inv_restock('${item.id}')">+Stock</button>
            <button class="btn btn-sm" style="background:#f1f5f9;color:#475569;padding:4px 7px;font-size:10px" onclick="inv_showEditForm('${item.id}')">✏️</button>
            <button class="btn btn-red btn-sm" style="padding:4px 7px;font-size:10px" onclick="inv_delete('${item.id}')">🗑️</button>
          </div>
        </div>`;
      }).join('')}
    </div>`;
}

function inv_showForm() {
  document.getElementById('inv-form-wrap').innerHTML = `
    <div class="card card-body" style="max-width:800px;border:2px solid #bfdbfe">
      <div style="font-size:15px;font-weight:700;color:#1e3a5f;margin-bottom:16px" id="inv-form-title">➕ Add Stock Item</div>
      <input type="hidden" id="inv-edit-id" value=""/>
      <div class="form-grid-2">
        <div class="form-group">
          <label class="form-label">Item Name *</label>
          <input class="form-input" id="inv-name" placeholder="e.g. LA Cartridges (Lignox 2%)"/>
        </div>
        <div class="form-group">
          <label class="form-label">Category</label>
          <select class="form-input" id="inv-category">
            <option value="">Select…</option>
            ${INV_CATEGORIES.map(c=>`<option>${c}</option>`).join('')}
          </select>
        </div>
        <div class="form-group">
          <label class="form-label">Current Quantity *</label>
          <input class="form-input" id="inv-qty" type="number" min="0" placeholder="0"/>
        </div>
        <div class="form-group">
          <label class="form-label">Unit</label>
          <select class="form-input" id="inv-unit">
            <option value="">Select…</option>
            ${INV_UNITS.map(u=>`<option>${u}</option>`).join('')}
          </select>
        </div>
        <div class="form-group">
          <label class="form-label">Min Stock (Low Alert Threshold)</label>
          <input class="form-input" id="inv-min" type="number" min="0" placeholder="e.g. 2"/>
        </div>
        <div class="form-group">
          <label class="form-label">Cost per Unit (₹)</label>
          <input class="form-input" id="inv-cost" type="number" min="0" placeholder="0"/>
        </div>
        <div class="form-group">
          <label class="form-label">Supplier / Brand</label>
          <input class="form-input" id="inv-supplier" placeholder="e.g. Dentsply, 3M, Local Dental Store"/>
        </div>
        <div class="form-group">
          <label class="form-label">Last Restocked</label>
          <input class="form-input" id="inv-restock-date" type="date"/>
        </div>
      </div>
      <div class="form-group">
        <label class="form-label">Notes</label>
        <textarea class="form-input" id="inv-notes" rows="2" placeholder="Expiry, storage instructions, ordering notes…"></textarea>
      </div>
      <div style="display:flex;gap:10px;margin-top:4px">
        <button class="btn btn-primary" onclick="inv_save()">💾 Save Item</button>
        <button class="btn btn-ghost"   onclick="inv_hideForm()">Cancel</button>
      </div>
    </div>`;
  document.getElementById('inv-form-wrap').style.display = 'block';
  document.getElementById('inv-form-wrap').scrollIntoView({behavior:'smooth',block:'start'});
  document.getElementById('inv-name').focus();
}

function inv_showEditForm(id) {
  inv_showForm();
  const item = inv_getItems().find(x => x.id === id);
  if (!item) return;
  document.getElementById('inv-form-title').textContent  = '✏️ Edit Stock Item';
  document.getElementById('inv-edit-id').value           = item.id;
  document.getElementById('inv-name').value              = item.name||'';
  document.getElementById('inv-category').value          = item.category||'';
  document.getElementById('inv-qty').value               = item.quantity||0;
  document.getElementById('inv-unit').value              = item.unit||'';
  document.getElementById('inv-min').value               = item.minStock||0;
  document.getElementById('inv-cost').value              = item.costPerUnit||0;
  document.getElementById('inv-supplier').value          = item.supplier||'';
  document.getElementById('inv-restock-date').value      = item.lastRestocked||'';
  document.getElementById('inv-notes').value             = item.notes||'';
}

function inv_hideForm() {
  document.getElementById('inv-form-wrap').style.display = 'none';
  document.getElementById('inv-form-wrap').innerHTML = '';
}

function inv_save() {
  const name = document.getElementById('inv-name').value.trim();
  if (!name) { alert('Please enter an item name.'); return; }
  const qty  = Number(document.getElementById('inv-qty').value) || 0;
  if (qty < 0) { alert('Quantity cannot be negative.'); return; }
  const editId = document.getElementById('inv-edit-id').value;
  const item = {
    id:            editId || ('inv' + Date.now()),
    name,
    category:      document.getElementById('inv-category').value,
    quantity:      qty,
    unit:          document.getElementById('inv-unit').value,
    minStock:      Number(document.getElementById('inv-min').value) || 0,
    costPerUnit:   Number(document.getElementById('inv-cost').value) || 0,
    supplier:      document.getElementById('inv-supplier').value.trim(),
    lastRestocked: document.getElementById('inv-restock-date').value,
    notes:         document.getElementById('inv-notes').value.trim(),
    createdAt:     editId ? (inv_getItems().find(i=>i.id===editId)?.createdAt||todayISO()) : todayISO()
  };
  DATA.inventory = editId
    ? (DATA.inventory||[]).map(i => i.id === editId ? item : i)
    : [...(DATA.inventory||[]), item];
  saveData();
  inv_hideForm();
  inv_render();
}

function inv_restock(id) {
  const item = inv_getItems().find(x => x.id === id);
  if (!item) return;
  const addStr = prompt(`Restock "${item.name}"\nCurrent: ${item.quantity} ${item.unit||''}\n\nHow many units to add?`);
  if (!addStr) return;
  const add = Number(addStr);
  if (isNaN(add) || add <= 0) { alert('Enter a valid positive number.'); return; }
  DATA.inventory = (DATA.inventory||[]).map(i =>
    i.id === id ? {...i, quantity: Number(i.quantity||0) + add, lastRestocked: todayISO()} : i
  );
  saveData();
  inv_render();
}

function inv_delete(id) {
  const item = inv_getItems().find(x => x.id === id);
  if (!confirm(`Delete "${item?.name||'this item'}"? Cannot be undone.`)) return;
  DATA.inventory = (DATA.inventory||[]).filter(i => i.id !== id);
  saveData();
  inv_render();
}


/* ══════════════════════════════════════════════════════
   PATIENT QUEUE / TOKEN SYSTEM — Feature #4
   Prefix: queue_  |  DATA key: DATA.queue
   Logic: Daily queue — auto-clears previous day's data
══════════════════════════════════════════════════════ */

function queue_getToday() { return DATA.queue?.date === todayISO() ? DATA.queue : null; }

function queue_getTokens() {
  const q = queue_getToday();
  return q ? (q.tokens || []) : [];
}

function queue_initDay() {
  if (DATA.queue?.date !== todayISO()) {
    DATA.queue = { date: todayISO(), tokens: [], nextToken: 1 };
    saveData();
  }
}

function queue_render() {
  queue_initDay();
  const el = document.getElementById('queue-date-label');
  if (el) el.textContent = fmtDate(todayISO());
  queue_renderList();
}

function queue_renderStats() {
  const el = document.getElementById('queue-stats');
  if (!el) return;
  const tokens = queue_getTokens();
  const waiting   = tokens.filter(t => t.status === 'waiting').length;
  const inchair   = tokens.filter(t => t.status === 'in-chair').length;
  const done      = tokens.filter(t => t.status === 'done').length;
  const skipped   = tokens.filter(t => t.status === 'skipped').length;
  const total     = tokens.length;
  const nextToken = DATA.queue?.nextToken || 1;

  el.innerHTML = [
    { icon:'🎫', label:'Next Token', value: total === 0 ? '—' : '#' + nextToken,       bg:'#eff6ff', col:'#1d4ed8' },
    { icon:'⏳', label:'Waiting',    value: waiting,                                    bg:'#fffbeb', col:'#d97706' },
    { icon:'🦷', label:'In Chair',   value: inchair,                                    bg:'#ecfdf5', col:'#059669' },
    { icon:'✅', label:'Done',       value: done,                                       bg:'#f0fdf4', col:'#16a34a' },
    { icon:'⏭️', label:'Skipped',   value: skipped,                                    bg:'#fef2f2', col:'#dc2626' },
    { icon:'👥', label:'Total Today',value: total,                                      bg:'#f5f3ff', col:'#7c3aed' },
  ].map(s => `
    <div style="background:${s.bg};border-radius:14px;padding:14px 16px;display:flex;justify-content:space-between;align-items:center">
      <div>
        <div style="font-size:10px;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:.4px;margin-bottom:3px">${s.label}</div>
        <div style="font-size:22px;font-weight:800;color:${s.col}">${s.value}</div>
      </div>
      <span style="font-size:24px">${s.icon}</span>
    </div>`).join('');
}

function queue_renderBoard() {
  const el = document.getElementById('queue-board');
  if (!el) return;
  const tokens = queue_getTokens();

  if (tokens.length === 0) {
    el.innerHTML = `<div class="empty" style="border:1px solid #e2e8f0;border-radius:16px;padding:50px 20px;margin-top:8px">
      <span class="empty-icon">🎫</span>
      <div class="empty-title">Queue is empty</div>
      <div class="empty-sub">Click "Add to Queue" to register today's first patient</div>
    </div>`;
    return;
  }

  const groups = {
    'in-chair': { label:'🦷 In Chair',  tokens:[], color:'#ecfdf5', border:'#16a34a' },
    'waiting':  { label:'⏳ Waiting',   tokens:[], color:'#fffbeb', border:'#d97706' },
    'done':     { label:'✅ Done',      tokens:[], color:'#f8fafc', border:'#94a3b8' },
    'skipped':  { label:'⏭️ Skipped',  tokens:[], color:'#fef2f2', border:'#dc2626' },
  };
  tokens.forEach(t => { if (groups[t.status]) groups[t.status].tokens.push(t); });

  el.innerHTML = Object.entries(groups).map(([status, g]) => {
    if (g.tokens.length === 0) return '';
    return `
      <div style="margin-bottom:20px">
        <div style="font-size:13px;font-weight:800;color:#475569;margin-bottom:10px;text-transform:uppercase;letter-spacing:.5px">${g.label} (${g.tokens.length})</div>
        <div style="display:flex;flex-direction:column;gap:8px">
          ${g.tokens.map(t => queue_tokenCard(t, g.color, g.border)).join('')}
        </div>
      </div>`;
  }).join('');
}

function queue_tokenCard(t, bg, border) {
  const isWaiting  = t.status === 'waiting';
  const isInChair  = t.status === 'in-chair';
  const isDone     = t.status === 'done';
  const isSkipped  = t.status === 'skipped';

  return `
    <div style="background:${bg};border:1.5px solid ${border};border-radius:14px;padding:14px 18px;display:flex;align-items:center;gap:14px;transition:box-shadow .15s">
      <!-- Token number badge -->
      <div style="min-width:52px;height:52px;border-radius:12px;background:white;border:2px solid ${border};display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0">
        <div style="font-size:9px;font-weight:700;color:#94a3b8;text-transform:uppercase">Token</div>
        <div style="font-size:20px;font-weight:900;color:#1e293b;line-height:1">#${t.token}</div>
      </div>

      <!-- Info -->
      <div style="flex:1;min-width:0">
        <div style="font-weight:700;font-size:14px;color:#1e293b">${esc(t.name)}</div>
        <div style="font-size:12px;color:#64748b;margin-top:2px">
          ${t.phone ? '📞 '+esc(t.phone) : ''}
          ${t.complaint ? (t.phone?' · ':'')+esc(t.complaint.slice(0,40)) : ''}
        </div>
        <div style="font-size:11px;color:#94a3b8;margin-top:2px">Added: ${t.addedAt||''}</div>
      </div>

      <!-- Actions -->
      <div style="display:flex;flex-direction:column;gap:5px;flex-shrink:0">
        ${isWaiting  ? `<button class="btn btn-green btn-sm" style="font-size:11px" onclick="queue_setStatus('${t.id}','in-chair')">🦷 Call In</button>` : ''}
        ${isWaiting  ? `<button class="btn btn-sm" style="background:#fef2f2;color:#dc2626;font-size:11px" onclick="queue_setStatus('${t.id}','skipped')">⏭️ Skip</button>` : ''}
        ${isInChair  ? `<button class="btn btn-primary btn-sm" style="font-size:11px" onclick="queue_setStatus('${t.id}','done')">✅ Done</button>` : ''}
        ${isInChair  ? `<button class="btn btn-sm" style="background:#fffbeb;color:#d97706;font-size:11px" onclick="queue_setStatus('${t.id}','waiting')">↩️ Back</button>` : ''}
        ${isSkipped  ? `<button class="btn btn-ghost btn-sm" style="font-size:11px" onclick="queue_setStatus('${t.id}','waiting')">↩️ Restore</button>` : ''}
        ${isDone     ? `<button class="btn btn-ghost btn-sm" style="font-size:11px" onclick="queue_openPatient('${t.id}')">📋 Record</button>` : ''}
        <button class="btn btn-sm" style="background:#f1f5f9;color:#94a3b8;font-size:10px" onclick="queue_remove('${t.id}')">🗑️</button>
      </div>
    </div>`;
}

function queue_addPatient() {
  queue_initDay();
  const patients = (DATA.patients||[]);

  // Build modal
  const overlay = document.createElement('div');
  overlay.id = 'queue-modal-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9990;display:flex;align-items:center;justify-content:center;padding:16px';
  overlay.innerHTML = `
    <div style="background:#fff;border-radius:18px;padding:24px;width:100%;max-width:480px;box-shadow:0 20px 60px rgba(0,0,0,.25)">
      <div style="font-size:16px;font-weight:700;color:#1e3a5f;margin-bottom:16px">🎫 Add to Queue</div>
      <div class="form-group">
        <label class="form-label">Patient Name *</label>
        <input class="form-input" id="queue-input-name" list="queue-pt-datalist" placeholder="Type name or select existing patient" autocomplete="off"/>
        <datalist id="queue-pt-datalist">
          ${patients.map(p=>`<option value="${esc(p.name)}" data-phone="${esc(p.phone||'')}">${esc(p.name)} — ${esc(p.phone||'')}</option>`).join('')}
        </datalist>
      </div>
      <div class="form-group">
        <label class="form-label">Phone</label>
        <input class="form-input" id="queue-input-phone" placeholder="Optional" type="tel"/>
      </div>
      <div class="form-group">
        <label class="form-label">Chief Complaint / Visit Reason</label>
        <input class="form-input" id="queue-input-complaint" placeholder="e.g. Toothache, Scaling, Follow-up"/>
      </div>
      <div style="display:flex;gap:10px;margin-top:8px">
        <button class="btn btn-primary" style="flex:1;padding:12px" onclick="queue_confirmAdd()">🎫 Issue Token</button>
        <button class="btn btn-ghost" onclick="document.getElementById('queue-modal-overlay').remove()">Cancel</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  document.getElementById('queue-input-name').focus();

  // Auto-fill phone when existing patient selected
  document.getElementById('queue-input-name').addEventListener('input', function() {
    const match = patients.find(p => p.name === this.value);
    if (match && match.phone) document.getElementById('queue-input-phone').value = match.phone;
  });
}

function queue_confirmAdd() {
  const name = document.getElementById('queue-input-name')?.value.trim();
  if (!name) { alert('Please enter a patient name.'); return; }
  const phone     = document.getElementById('queue-input-phone')?.value.trim() || '';
  const complaint = document.getElementById('queue-input-complaint')?.value.trim() || '';

  queue_initDay();
  const now = new Date();
  const timeStr = now.toLocaleTimeString('en-IN', {hour:'2-digit', minute:'2-digit', hour12:true});

  const token = {
    id:        'qt' + Date.now(),
    token:     DATA.queue.nextToken,
    name,
    phone,
    complaint,
    status:    'waiting',
    addedAt:   timeStr,
    date:      todayISO()
  };

  DATA.queue.tokens = [...(DATA.queue.tokens||[]), token];
  DATA.queue.nextToken = (DATA.queue.nextToken||1) + 1;
  saveData();

  document.getElementById('queue-modal-overlay')?.remove();
  queue_render();
}

function queue_setStatus(id, newStatus) {
  queue_initDay();
  DATA.queue.tokens = (DATA.queue.tokens||[]).map(t =>
    t.id === id ? {...t, status: newStatus} : t
  );
  saveData();
  queue_render();
}

function queue_remove(id) {
  if (!confirm('Remove this token from the queue?')) return;
  queue_initDay();
  DATA.queue.tokens = (DATA.queue.tokens||[]).filter(t => t.id !== id);
  saveData();
  queue_render();
}

function queue_openPatient(tokenId) {
  const t = queue_getTokens().find(x => x.id === tokenId);
  if (!t) return;
  const pt = (DATA.patients||[]).find(p => p.name === t.name || p.phone === t.phone);
  if (pt) { openPatient(pt.id); }
  else { alert('Patient not found in records. Add them via Patients → New Patient first.'); }
}

function queue_clearDay() {
  if (!confirm('Clear all tokens for today? This cannot be undone.')) return;
  DATA.queue = { date: todayISO(), tokens: [], nextToken: 1 };
  saveData();
  queue_render();
}


