/* ══════════════════════════════════════════════════
   TXPLAN WHATSAPP SEND
══════════════════════════════════════════════════ */
function txplan_whatsapp() {
  if (!activePt) return;
  var items = txplan_getItems().filter(function(i){ return i.status !== 'cancelled'; });
  if (!items.length) { alert('No procedures in the treatment plan.'); return; }
  if (!activePt.phone) { alert('No phone number for this patient.'); return; }
  var total = items.reduce(function(s,i){ return s+Number(i.estimatedCost||0); }, 0);
  var list = items.map(function(i,n){
    return (n+1)+'. '+i.procedure+(i.toothNo?' (Tooth #'+i.toothNo+')':'')+(i.estimatedCost?' — ₹'+Number(i.estimatedCost).toLocaleString('en-IN'):'');
  }).join(String.fromCharCode(10));
  var msg = [
    CLINIC, DOCTOR+' | '+PHONE, '─────────────────',
    'Dear '+activePt.name+',',
    '',
    'Your Treatment Plan & Estimate:',
    '',
    list,
    '',
    'Estimated Total: ₹'+total.toLocaleString('en-IN'),
    '',
    'To schedule or discuss, call: '+PHONE,
    TIMING+' | '+CITY
  ].join(String.fromCharCode(10));
  window.open('https://wa.me/91'+activePt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}


/* ══════════════════════════════════════════════════
   TXPLAN → BILLING PUSH
   One-tap: adds selected tx item to patient billing
══════════════════════════════════════════════════ */
function txplan_pushToBilling(itemId) {
  if (!activePt) return;
  var item = (activePt.treatmentPlan||[]).find(function(i){ return i.id===itemId; });
  if (!item) return;
  if (!item.estimatedCost || Number(item.estimatedCost) <= 0) {
    alert('No cost set for this procedure. Edit it to add a cost first.');
    return;
  }
  // Check if already billed
  var alreadyBilled = (activePt.billing||[]).some(function(b){
    return b.txplanId === itemId;
  });
  if (alreadyBilled) {
    alert('This procedure is already in Billing.');
    return;
  }
  if (!confirm('Add "'+item.procedure+'" (₹'+Number(item.estimatedCost).toLocaleString('en-IN')+') to billing?')) return;
  if (!activePt.billing) activePt.billing = [];
  activePt.billing.push({
    id: 'b'+Date.now(),
    item: item.procedure+(item.toothNo?' #'+item.toothNo:''),
    amount: Number(item.estimatedCost),
    paid: false,
    date: todayISO(),
    txplanId: itemId,
    note: 'From treatment plan'
  });
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id === activePt.id; });
  if (ptIdx >= 0) DATA.patients[ptIdx] = activePt;
  saveData();
  txplan_renderTab();
  alert('Added to Billing. Go to Billing tab to record payment.');
}


