/* ══════════════════════════════════════════════════
   AUTO BACKUP ENHANCEMENT
   Track last backup time, prompt if overdue
══════════════════════════════════════════════════ */
function autoBackup_check() {
  var last = localStorage.getItem('hos_last_backup');
  if (!last) return; // first time, don't nag
  var daysSince = Math.floor((Date.now() - Number(last)) / 86400000);
  if (daysSince >= 3) {
    var warn = document.getElementById('backup-warn-banner');
    if (!warn) {
      warn = document.createElement('div');
      warn.id = 'backup-warn-banner';
      warn.style.cssText = 'position:fixed;bottom:16px;right:16px;background:#7f1d1d;color:#fef2f2;font-size:12px;font-weight:600;padding:10px 16px;border-radius:10px;z-index:9999;display:flex;align-items:center;gap:10px;box-shadow:0 4px 16px rgba(0,0,0,.3);max-width:320px';
      warn.innerHTML = '<span>💾 No backup for '+daysSince+' days! Back up your data now.</span>'+
        '<button onclick="exportBackup();document.getElementById(\'backup-warn-banner\').remove()" style="background:rgba(255,255,255,.2);border:none;color:#fff;padding:4px 10px;border-radius:6px;cursor:pointer;font-size:11px;white-space:nowrap">Backup Now</button>'+
        '<button onclick="this.parentNode.remove()" style="background:none;border:none;color:#fca5a5;cursor:pointer;font-size:16px;padding:0 4px">×</button>';
      document.body.appendChild(warn);
    }
  }
}

// Patch exportBackup to record timestamp
(function(){
  var origExport = window.exportBackup;
  if (typeof origExport === 'function') {
    window.exportBackup = function() {
      origExport.apply(this, arguments);
      localStorage.setItem('hos_last_backup', Date.now().toString());
      var warn = document.getElementById('backup-warn-banner');
      if (warn) warn.remove();
    };
  }
})();

setTimeout(autoBackup_check, 3000);


