/* ─── 1. DAILY REPORT ─────────────────────────────
   One-click printable + WhatsApp daily summary
──────────────────────────────────────────────── */
function generateDailyReport() {
  var today = todayISO();
  var pts   = DATA.patients || [];

  var seenToday = pts.filter(function(p){
    return (p.createdAt||'').startsWith(today) ||
           (p.records||[]).some(function(r){ return (r.date||'').startsWith(today); });
  });

  var todayBilling = pts.flatMap(function(p){ return p.billing||[]; })
    .filter(function(b){ return (b.date||'').startsWith(today); });
  var todayRevenue = todayBilling.filter(function(b){ return b.paid; })
    .reduce(function(s,b){ return s+Number(b.amount||0); }, 0);
  var todayPending = todayBilling.filter(function(b){ return !b.paid; })
    .reduce(function(s,b){ return s+Number(b.amount||0); }, 0);

  var todayRecords = pts.flatMap(function(p){
    return (p.records||[]).filter(function(r){ return (r.date||'').startsWith(today); })
      .map(function(r){ return {patient:p.name, diagnosis:r.diagnosis, treatment:r.treatment}; });
  });

  var todayAppts = (DATA.appointments||[]).filter(function(a){ return a.date===today; });
  var missedAppts = todayAppts.filter(function(a){
    if(!a.time) return false;
    var now = new Date(); var h=now.getHours(); var m=now.getMinutes();
    var parts = a.time.split(':'); var ah=parseInt(parts[0]); var am=parseInt(parts[1]||0);
    return (ah*60+am) < (h*60+m);
  });

  var txDone = pts.flatMap(function(p){
    return (p.treatmentPlan||[]).filter(function(i){
      return i.status==='completed' && (i.updatedAt||'').startsWith(today);
    });
  });

  var allTx  = pts.flatMap(function(p){ return p.treatmentPlan||[]; }).filter(function(i){ return i.status!=='cancelled'; });
  var doneTx = allTx.filter(function(i){ return i.status==='completed'||i.status==='in-progress'; });
  var convPct= allTx.length>0 ? Math.round(doneTx.length/allTx.length*100) : 0;

  // Print popup
  var pw = window.open('','_blank','width=900,height=1100');
  if(!pw){ alert('Allow pop-ups to generate report.'); return; }

  var recRows = todayRecords.slice(0,20).map(function(r,i){
    return '<tr style="border-bottom:1px solid #f1f5f9"><td style="padding:7px 8px;font-size:10.5pt">'+(i+1)+'. '+esc(r.patient)+'</td>'+
      '<td style="padding:7px 8px;font-size:10.5pt">'+esc(r.diagnosis||'—')+'</td>'+
      '<td style="padding:7px 8px;font-size:10.5pt">'+esc(r.treatment||'—')+'</td></tr>';
  }).join('');

  var html = '<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>Daily Report — '+fmtDate(today)+'</title>'+
    '<style>@page{size:A4;margin:18mm 16mm}body{font-family:Arial,sans-serif;color:#1e293b;margin:0}'+
    '.hdr{background:linear-gradient(135deg,#1e3a5f,#0369a1);color:#fff;padding:18px 22px;border-radius:10px;margin-bottom:20px;display:flex;justify-content:space-between;align-items:center}'+
    '.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:18px}'+
    '.card{background:#f8fafc;border:1.5px solid #e2e8f0;border-radius:10px;padding:14px 18px}'+
    '.val{font-size:22pt;font-weight:800}.lbl{font-size:9pt;color:#64748b;font-weight:600;margin-bottom:4px}'+
    'table{width:100%;border-collapse:collapse}thead th{background:#1e3a5f;color:#fff;padding:9px 8px;font-size:9.5pt;text-align:left}'+
    '.footer{background:#1e3a5f;color:#fff;padding:11px 18px;border-radius:10px;text-align:center;font-size:9pt;margin-top:18px}'+
    '@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body>'+
    '<div class="hdr"><div><div style="font-size:17pt;font-weight:800">'+CLINIC+'</div>'+
    '<div style="opacity:.85;font-size:9pt">'+DOCTOR+' | Reg. '+REG+'</div></div>'+
    '<div style="text-align:right"><div style="font-size:14pt;font-weight:800">DAILY REPORT</div>'+
    '<div style="font-size:11pt;margin-top:3px">'+fmtDate(today)+'</div></div></div>'+

    '<div class="grid">'+
    '<div class="card"><div class="lbl">Patients Seen Today</div><div class="val" style="color:#1d4ed8">'+seenToday.length+'</div></div>'+
    '<div class="card"><div class="lbl">Revenue Collected</div><div class="val" style="color:#059669">₹'+todayRevenue.toLocaleString('en-IN')+'</div></div>'+
    '<div class="card"><div class="lbl">Pending (Today)</div><div class="val" style="color:#d97706">₹'+todayPending.toLocaleString('en-IN')+'</div></div>'+
    '<div class="card"><div class="lbl">Appointments Today</div><div class="val" style="color:#7c3aed">'+todayAppts.length+'<span style="font-size:11pt;font-weight:400;color:#dc2626"> ('+missedAppts.length+' missed)</span></div></div>'+
    '<div class="card"><div class="lbl">Treatments Done</div><div class="val" style="color:#0d9488">'+todayRecords.length+'</div></div>'+
    '<div class="card"><div class="lbl">Overall Conversion</div><div class="val" style="color:#7c3aed">'+convPct+'%</div></div>'+
    '</div>'+

    (recRows ? '<table style="margin-bottom:18px"><thead><tr><th>Patient</th><th>Diagnosis</th><th>Treatment</th></tr></thead><tbody>'+recRows+'</tbody></table>' : '')+

    '<div class="footer">'+PHONE+' &nbsp;|&nbsp; '+TIMING+' &nbsp;|&nbsp; '+CITY+'</div>'+
    '</body></html>';

  pw.document.write(html); pw.document.close();
  pw.onload = function(){ pw.focus(); pw.print(); };
}

