/* ─── 2. PROCEDURE PERFORMANCE TRACKER ───────────
   Count and rank procedures by frequency & revenue
──────────────────────────────────────────────── */
function getProcedureStats() {
  var pts = DATA.patients||[];
  var map = {};

  // From treatment plans
  pts.forEach(function(p){
    (p.treatmentPlan||[]).filter(function(i){return i.status!=='cancelled';}).forEach(function(item){
      var name = (item.procedure||'Other').trim();
      if(!map[name]) map[name]={name:name,count:0,revenue:0,done:0};
      map[name].count++;
      map[name].revenue += Number(item.estimatedCost||0);
      if(item.status==='completed') map[name].done++;
    });
  });

  // From billing items (fill gaps)
  pts.forEach(function(p){
    (p.billing||[]).filter(function(b){return b.paid;}).forEach(function(b){
      var name = (b.item||'Other').replace(/#\d+/,'').trim();
      // Only add if not already from txplan
      if(!map[name]){
        map[name]={name:name,count:1,revenue:Number(b.amount||0),done:1};
      }
    });
  });

  return Object.values(map).sort(function(a,b){return b.revenue-a.revenue;});
}


