function renderStaffLog() {
  var el = document.getElementById('staff-log-content');
  if(!el) return;
  var logs = (DATA.staffLog||[]).slice().sort(function(a,b){return (b.date||'').localeCompare(a.date||'');});
  var h='';
  h+='<div class="card" style="margin-bottom:16px"><div style="font-size:13px;font-weight:700;margin-bottom:12px">📝 Log Staff Attendance</div>';
  h+='<div class="form-grid-2">';
  h+='<div class="form-group"><label class="form-label">Staff Name</label><input class="form-input" id="staff-name" placeholder="e.g. Priya (Assistant)"/></div>';
  h+='<div class="form-group"><label class="form-label">Status</label><select class="form-input" id="staff-status"><option value="present">✅ Present</option><option value="absent">❌ Absent</option><option value="half">🌓 Half Day</option></select></div>';
  h+='</div>';
  h+='<div class="form-group"><label class="form-label">Notes</label><input class="form-input" id="staff-note" placeholder="Any remarks..."/></div>';
  h+='<button class="btn btn-primary" onclick="staffLog_save()" style="margin-top:6px">💾 Save</button></div>';

  if(logs.length===0){
    h+='<div class="empty"><span class="empty-icon">👤</span><div class="empty-title">No staff logs yet</div></div>';
  } else {
    // Group by date
    var byDate={};
    logs.forEach(function(l){if(!byDate[l.date])byDate[l.date]=[];byDate[l.date].push(l);});
    Object.keys(byDate).sort(function(a,b){return b.localeCompare(a);}).forEach(function(date){
      h+='<div style="margin-bottom:14px"><div style="font-size:11px;font-weight:800;color:#94a3b8;text-transform:uppercase;margin-bottom:6px">'+fmtDate(date)+'</div>';
      byDate[date].forEach(function(l){
        var sc={present:'#059669',absent:'#dc2626',half:'#d97706'}[l.status]||'#64748b';
        var sl={present:'✅ Present',absent:'❌ Absent',half:'🌓 Half Day'}[l.status]||l.status;
        h+='<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:10px 14px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center">';
        h+='<div><div style="font-size:13px;font-weight:700">'+esc(l.name)+'</div>';
        if(l.note) h+='<div style="font-size:11px;color:#64748b">'+esc(l.note)+'</div>';
        h+='</div>';
        h+='<span style="font-size:11px;font-weight:700;color:'+sc+'">'+sl+'</span>';
        h+='</div>';
      });
      h+='</div>';
    });
  }
  el.innerHTML = h;
}


/* ─── 4. MISSED APPOINTMENTS BADGE ───────────────
   Show count of today missed appts on dashboard
──────────────────────────────────────────────── */
function getMissedAppointments() {
  var today = todayISO();
  var now = new Date();
  var nowMins = now.getHours()*60 + now.getMinutes();
  return (DATA.appointments||[]).filter(function(a){
    if(a.date !== today || !a.time) return false;
    var parts = a.time.split(':');
    var apptMins = parseInt(parts[0]||0)*60 + parseInt(parts[1]||0);
    return apptMins < nowMins;
  });
}


/* ─── 5. OVERDUE BILLING HIGHLIGHT ───────────────
   Flag billing unpaid for >7 days in dues dashboard
──────────────────────────────────────────────── */
function isOverdueBilling(bill) {
  if(bill.paid) return false;
  if(!bill.date) return false;
  var daysSince = Math.floor((new Date(todayISO())-new Date(bill.date))/86400000);
  return daysSince > 7;
}


/* ─── 6. ANALYTICS ENHANCEMENTS ──────────────────
   Avg revenue per patient, missed opportunity calc
──────────────────────────────────────────────── */
function getAnalyticsExtra() {
  var pts = DATA.patients||[];
  var totalRev = pts.flatMap(function(p){return p.billing||[];})
    .filter(function(b){return b.paid;})
    .reduce(function(s,b){return s+Number(b.amount||0);},0);
  var avgRev = pts.length>0 ? Math.round(totalRev/pts.length) : 0;

  // Missed opportunity = planned tx not yet converted * estimated cost
  var missedOpp = pts.flatMap(function(p){return p.treatmentPlan||[];})
    .filter(function(i){return i.status==='planned';})
    .reduce(function(s,i){return s+Number(i.estimatedCost||0);},0);

  // Top procedure
  var stats = getProcedureStats();
  var topProc = stats[0]||null;

  return {avgRev:avgRev, missedOpp:missedOpp, topProc:topProc, stats:stats.slice(0,5)};
}


/* ─── 7. REPORT PAGE ENHANCEMENTS ────────────────
   Add procedure breakdown + daily report button
   to existing renderReport
──────────────────────────────────────────────── */
function renderProcedureBreakdown() {
  var el = document.getElementById('proc-breakdown');
  if(!el) return;
  var stats = getProcedureStats().slice(0,8);
  if(!stats.length){el.innerHTML='<div style="color:#94a3b8;font-size:12px">No procedure data yet</div>';return;}
  var maxRev = stats[0].revenue||1;
  var h='';
  h+='<div style="margin-bottom:4px;font-size:11px;font-weight:700;color:#64748b;display:grid;grid-template-columns:1fr auto auto;gap:8px;padding:0 4px">';
  h+='<span>Procedure</span><span>Count</span><span>Revenue</span></div>';
  stats.forEach(function(s,i){
    var pct=Math.round((s.revenue/maxRev)*100);
    h+='<div style="margin-bottom:8px">';
    h+='<div style="display:grid;grid-template-columns:1fr auto auto;gap:8px;align-items:center;margin-bottom:3px">';
    h+='<span style="font-size:12px;font-weight:600;color:#1e293b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(s.name)+'</span>';
    h+='<span style="font-size:11px;font-weight:700;color:#64748b;text-align:right">'+s.count+'</span>';
    h+='<span style="font-size:11px;font-weight:700;color:#1e293b;text-align:right">₹'+s.revenue.toLocaleString('en-IN')+'</span>';
    h+='</div>';
    h+='<div style="height:6px;background:#f1f5f9;border-radius:99px;overflow:hidden">';
    h+='<div style="height:100%;width:'+pct+'%;background:'+(['#3b82f6','#8b5cf6','#06b6d4','#10b981','#f59e0b','#ef4444','#64748b','#ec4899'][i%8])+';border-radius:99px;transition:width .5s"></div>';
    h+='</div></div>';
  });
  el.innerHTML=h;
}

