function steril_render() {
  var el = document.getElementById('steril-content');
  if(!el) return;
  var logs = (DATA.sterilLog||[]).slice().sort(function(a,b){ return (b.date+b.time).localeCompare(a.date+a.time); });
  var h = '';

  h += '<div class="card" style="margin-bottom:16px">';
  h += '<div style="font-size:13px;font-weight:700;margin-bottom:14px">&#128203; Log Sterilization Cycle</div>';
  h += '<div class="form-grid-2">';
  h += '<div class="form-group"><label class="form-label">Cycle No. *</label><input class="form-input" id="steril-cycle" placeholder="e.g. 42" type="number" min="1"/></div>';
  h += '<div class="form-group"><label class="form-label">Temperature (&#176;C)</label><input class="form-input" id="steril-temp" placeholder="134" type="number"/></div>';
  h += '<div class="form-group"><label class="form-label">Instruments Sterilized</label><input class="form-input" id="steril-instr" placeholder="e.g. Scalers, Forceps, Mirrors"/></div>';
  h += '<div class="form-group"><label class="form-label">Result</label><select class="form-input" id="steril-result"><option value="pass">&#10003; Pass</option><option value="fail">&#10005; Fail</option><option value="pending">&#9203; Pending indicator</option></select></div>';
  h += '</div>';
  h += '<div class="form-group"><label class="form-label">Notes</label><input class="form-input" id="steril-notes" placeholder="Any observations..."/></div>';
  h += '<button class="btn btn-primary" onclick="steril_save()" style="margin-top:6px">&#128190; Save Cycle</button>';
  h += '</div>';

  if(!logs.length) {
    h += '<div class="empty"><span class="empty-icon">&#127950;</span><div class="empty-title">No cycles logged</div><div class="empty-sub">Log your first sterilization cycle above</div></div>';
  } else {
    // Group by date
    var byDate = {};
    logs.forEach(function(l){ if(!byDate[l.date]) byDate[l.date]=[]; byDate[l.date].push(l); });
    Object.keys(byDate).sort(function(a,b){return b.localeCompare(a);}).forEach(function(date){
      h += '<div style="margin-bottom:16px"><div style="font-size:11px;font-weight:800;color:#94a3b8;text-transform:uppercase;margin-bottom:8px;display:flex;justify-content:space-between">';
      h += '<span>'+fmtDate(date)+'</span><span>'+byDate[date].length+' cycle'+(byDate[date].length!==1?'s':'')+'</span></div>';
      byDate[date].forEach(function(l){
        var rc = l.result==='pass'?'#059669':l.result==='fail'?'#dc2626':'#d97706';
        var rb = l.result==='pass'?'#ecfdf5':l.result==='fail'?'#fef2f2':'#fffbeb';
        var rl = l.result==='pass'?'&#10003; PASS':l.result==='fail'?'&#10005; FAIL':'&#9203; PENDING';
        h += '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:12px;padding:12px 14px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center;gap:12px">';
        h += '<div><div style="font-size:13px;font-weight:700;color:#1e293b">Cycle #'+esc(l.cycle)+(l.temp?' &nbsp;&#183;&nbsp; '+l.temp+'&#176;C':'')+'</div>';
        h += '<div style="font-size:11px;color:#64748b;margin-top:2px">'+(l.instruments?esc(l.instruments)+' &nbsp;&bull;&nbsp; ':'')+'&#128336; '+l.time+'</div>';
        if(l.notes) h += '<div style="font-size:11px;color:#94a3b8;margin-top:2px">'+esc(l.notes)+'</div>';
        h += '</div>';
        h += '<span style="font-size:11px;font-weight:800;color:'+rc+';background:'+rb+';border-radius:8px;padding:4px 10px;flex-shrink:0">'+rl+'</span>';
        h += '</div>';
      });
      h += '</div>';
    });
  }
  el.innerHTML = h;
}

function renderSterilPage() { steril_render(); }


/* ══════════════════════════════════════════════════
   EMI / INSTALLMENT TRACKER
   For high-value cases: implants, aligners, etc.
   Added inside patient billing tab.
══════════════════════════════════════════════════ */
function emi_openForm(patientId) {
  var pt = (DATA.patients||[]).find(function(p){ return p.id===patientId; });
  if(!pt) return;
  var total = prompt('Total treatment amount (₹):', '');
  if(!total || isNaN(Number(total))) return;
  var count = prompt('Number of installments:', '3');
  if(!count || isNaN(Number(count))) return;
  var startDate = prompt('First installment date (YYYY-MM-DD):', todayISO());
  if(!startDate) return;

  var totalAmt = Number(total);
  var numInst  = Number(count);
  var perInst  = Math.round(totalAmt / numInst);

  if(!pt.emiPlans) pt.emiPlans = [];
  var plan = {
    id: 'emi'+Date.now(),
    total: totalAmt,
    installments: [],
    createdAt: todayISO(),
    note: ''
  };

  for(var i=0; i<numInst; i++){
    var d = new Date(startDate);
    d.setMonth(d.getMonth() + i);
    plan.installments.push({
      id: 'inst'+Date.now()+i,
      number: i+1,
      amount: i===numInst-1 ? (totalAmt - perInst*(numInst-1)) : perInst,
      due: d.toISOString().slice(0,10),
      paid: false,
      paidDate: null
    });
  }

  pt.emiPlans.push(plan);
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===patientId; });
  if(ptIdx>=0) DATA.patients[ptIdx] = pt;
  if(activePt && activePt.id===patientId) activePt = pt;
  saveData();
  alert('EMI plan created! '+numInst+' installments of approx. ₹'+perInst.toLocaleString('en-IN')+' each.');
  switchTab('billing');
}

function emi_markPaid(patientId, planId, instId) {
  var pt = (DATA.patients||[]).find(function(p){ return p.id===patientId; });
  if(!pt||!pt.emiPlans) return;
  var plan = pt.emiPlans.find(function(e){ return e.id===planId; });
  if(!plan) return;
  var inst = plan.installments.find(function(i){ return i.id===instId; });
  if(!inst) return;
  inst.paid = true;
  inst.paidDate = todayISO();
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===patientId; });
  if(ptIdx>=0) DATA.patients[ptIdx] = pt;
  if(activePt && activePt.id===patientId) activePt = pt;
  saveData(); switchTab('billing');
}

function emi_deletePlan(patientId, planId) {
  if(!confirm('Delete this EMI plan?')) return;
  var pt = (DATA.patients||[]).find(function(p){ return p.id===patientId; });
  if(!pt) return;
  pt.emiPlans = (pt.emiPlans||[]).filter(function(e){ return e.id!==planId; });
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===patientId; });
  if(ptIdx>=0) DATA.patients[ptIdx] = pt;
  if(activePt && activePt.id===patientId) activePt = pt;
  saveData(); switchTab('billing');
}

function emi_renderSection(pt) {
  var plans = pt.emiPlans||[];
  var h = '<div style="margin-top:20px;padding-top:16px;border-top:2px dashed #e2e8f0">';
  h += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">';
  h += '<div style="font-size:13px;font-weight:700;color:#1e293b">&#128179; EMI / Installment Plans</div>';
  h += '<button class="btn btn-sm" style="background:#7c3aed;color:#fff;border:none" data-pid="'+pt.id+'" onclick="emi_openForm(this.dataset.pid)">+ New EMI Plan</button>';
  h += '</div>';
  if(!plans.length){
    h += '<div style="font-size:12px;color:#94a3b8;text-align:center;padding:12px">No EMI plans. Add one for high-value treatments.</div>';
  } else {
    plans.forEach(function(plan){
      var paid   = plan.installments.filter(function(i){return i.paid;}).reduce(function(s,i){return s+i.amount;},0);
      var remain = plan.total - paid;
      var overdue = plan.installments.filter(function(i){return !i.paid && i.due < todayISO();}).length;
      h += '<div style="background:#faf5ff;border:1.5px solid #c4b5fd;border-radius:12px;padding:14px 16px;margin-bottom:10px">';
      h += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">';
      h += '<div><div style="font-size:13px;font-weight:700;color:#7c3aed">Total: ₹'+plan.total.toLocaleString('en-IN')+'</div>';
      h += '<div style="font-size:11px;color:#64748b;margin-top:2px">Paid: ₹'+paid.toLocaleString('en-IN')+' &bull; Remaining: <strong style="color:'+(remain>0?'#dc2626':'#059669')+'">₹'+remain.toLocaleString('en-IN')+'</strong>'+(overdue?' &bull; <span style="color:#dc2626;font-weight:700">'+overdue+' overdue!</span>':'')+'</div></div>';
      h += '<button class="btn btn-red btn-sm" data-pid="'+pt.id+'" data-planid="'+plan.id+'" onclick="emi_deletePlan(this.dataset.pid,this.dataset.planid)">&#128465;</button>';
      h += '</div>';
      plan.installments.forEach(function(inst){
        var isOverdue = !inst.paid && inst.due < todayISO();
        var bg = inst.paid?'#f0fdf4':isOverdue?'#fef2f2':'#fff';
        var border = inst.paid?'#6ee7b7':isOverdue?'#fca5a5':'#e2e8f0';
        h += '<div style="background:'+bg+';border:1px solid '+border+';border-radius:8px;padding:8px 12px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center;gap:10px">';
        h += '<div><div style="font-size:12px;font-weight:700;color:#1e293b">Inst. '+inst.number+' — ₹'+inst.amount.toLocaleString('en-IN')+'</div>';
        h += '<div style="font-size:10px;color:#64748b">Due: '+fmtDate(inst.due)+(inst.paidDate?' &bull; Paid: '+fmtDate(inst.paidDate):'')+(isOverdue?' &#9888; OVERDUE':'')+' </div></div>';
        if(!inst.paid){
          h += '<button class="btn btn-sm" style="background:#059669;color:#fff;border:none;font-size:11px" data-pid="'+pt.id+'" data-planid="'+plan.id+'" data-instid="'+inst.id+'" onclick="emi_markPaid(this.dataset.pid,this.dataset.planid,this.dataset.instid)">&#10003; Mark Paid</button>';
        } else {
          h += '<span style="font-size:11px;font-weight:700;color:#059669">&#10003; Paid</span>';
        }
        h += '</div>';
      });
      h += '</div>';
    });
  }
  h += '</div>';
  return h;
}


/* ══════════════════════════════════════════════════
   GOOGLE REVIEW AUTOMATION
   Prompt to send review request after marking
   treatment as complete.
══════════════════════════════════════════════════ */
var GOOGLE_REVIEW_URL = localStorage.getItem('hos_review_url') || '';

function review_setURL() {
  var url = prompt('Paste your Google Review link:\n(Get it from Google Business Profile → Share → Copy link)', GOOGLE_REVIEW_URL||'https://g.page/r/YOUR_REVIEW_LINK/review');
  if(url===null) return;
  GOOGLE_REVIEW_URL = url.trim();
  localStorage.setItem('hos_review_url', GOOGLE_REVIEW_URL);
  alert('Google Review link saved!');
}

function review_send(patientName, patientPhone) {
  if(!patientPhone) { alert('No phone number for this patient.'); return; }
  if(!GOOGLE_REVIEW_URL) {
    if(confirm('Google Review link not set yet. Set it now?')) review_setURL();
    return;
  }
  var nl = String.fromCharCode(10); // real newline
  var msg = 'Dear '+patientName+','+nl+nl+
    'Thank you for visiting *The Home Of Smiles Dental Clinic*!'+nl+nl+
    'We hope you had a great experience with Dr. Tanmay Jain.'+nl+nl+
    'We would really appreciate if you could leave us a Google Review'+nl+
    'It takes just 30 seconds and helps other patients find us!'+nl+nl+
    'Leave a review here:'+nl+
    GOOGLE_REVIEW_URL+nl+nl+
    'Thank you for trusting us with your smile!'+nl+nl+
    CLINIC+' | '+PHONE;
  window.open('https://wa.me/91'+patientPhone.replace(/\\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

// Auto-prompt after marking billing as paid
function review_promptAfterPayment(pt) {
  if(!pt || !pt.phone) return;
  setTimeout(function(){
    if(confirm('Send a Google Review request to '+pt.name+' via WhatsApp?')){
      review_send(pt.name, pt.phone);
    }
  }, 500);
}



/* ══════════════════════════════════════════════════
   IMAGES / X-RAYS / REPORTS — ONE-TAP SHARE
   
   Strategy:
   • Mobile (Android/iOS): Web Share API with files
     → Opens native share sheet → WhatsApp, Drive, etc.
   • Desktop: Creates a self-contained HTML page
     → User saves as PDF or prints
   
   Handles: photos, X-rays, AI PDF reports (base64)
══════════════════════════════════════════════════ */

async function imgs_shareAll() {
  if (!activePt) return;

  var images  = activePt.images      || [];
  var reports = activePt.xrayReports || [];

  if (!images.length && !reports.length) {
    alert('No images or reports found for this patient.');
    return;
  }

  // ── Try Web Share API (mobile — Android Chrome / Safari iOS) ──
  if (navigator.canShare && typeof navigator.share === 'function') {
    try {
      var files = [];

      // Convert images (base64 → File)
      for (var i = 0; i < images.length; i++) {
        var img = images[i];
        if (!img.src) continue;
        try {
          var blob = imgs_base64ToBlob(img.src);
          var ext  = img.src.startsWith('data:image/png') ? 'png' : 'jpg';
          var fname = (img.category||'Image').replace(/[^a-zA-Z0-9]/g,'_') + '_' + (i+1) + '.' + ext;
          files.push(new File([blob], fname, { type: blob.type }));
        } catch(e) { console.warn('Image convert error:', e); }
      }

      // Convert PDF reports (base64 → File)
      for (var j = 0; j < reports.length; j++) {
        var rpt = reports[j];
        if (!rpt.data) continue;
        try {
          var pdfBlob = imgs_base64ToBlob('data:application/pdf;base64,' + rpt.data);
          files.push(new File([pdfBlob], (rpt.name||'Report_'+(j+1))+'.pdf', { type: 'application/pdf' }));
        } catch(e) { console.warn('PDF convert error:', e); }
      }

      if (files.length === 0) {
        alert('No shareable files found.');
        return;
      }

      // Check if files can be shared
      var shareData = {
        title: 'Records — ' + activePt.name,
        text:  activePt.name + ' | ' + CLINIC + '\nImages & X-rays',
        files: files
      };

      if (navigator.canShare(shareData)) {
        await navigator.share(shareData);
        return; // Done — native share sheet handled it
      }
    } catch(e) {
      if (e.name !== 'AbortError') {
        // Fall through to desktop method
        console.warn('Web Share API failed:', e.message);
      } else {
        return; // User cancelled
      }
    }
  }

  // ── Desktop fallback: print/save page with all images ──
  imgs_shareDesktop();
}


function imgs_base64ToBlob(dataUrl) {
  var arr   = dataUrl.split(',');
  var mime  = arr[0].match(/:(.*?);/)[1];
  var bstr  = atob(arr[1]);
  var n     = bstr.length;
  var u8arr = new Uint8Array(n);
  while (n--) u8arr[n] = bstr.charCodeAt(n);
  return new Blob([u8arr], { type: mime });
}


function imgs_shareDesktop() {
  var images  = activePt.images      || [];
  var reports = activePt.xrayReports || [];

  // Group images by category
  var grouped = {};
  images.forEach(function(img) {
    var cat = img.category || 'Uncategorized';
    if (!grouped[cat]) grouped[cat] = [];
    grouped[cat].push(img);
  });

  var imgHTML = Object.keys(grouped).map(function(cat) {
    var catImgs = grouped[cat].map(function(img) {
      return '<div style="break-inside:avoid;margin-bottom:12px">' +
        '<img src="' + img.src + '" style="width:100%;border-radius:8px;border:1px solid #e2e8f0;display:block"/>' +
        '<div style="font-size:9pt;color:#64748b;margin-top:4px;text-align:center">' +
        esc(img.category||'') + (img.date?' · '+fmtDate(img.date):'') +
        (img.note?' · '+esc(img.note):'') + '</div></div>';
    }).join('');
    return '<div style="margin-bottom:20px">' +
      '<div style="font-size:10pt;font-weight:800;color:#1e3a5f;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid #1e3a5f">' + esc(cat) + ' (' + grouped[cat].length + ')</div>' +
      '<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:10px">' + catImgs + '</div></div>';
  }).join('');

  var rptHTML = reports.length ? reports.map(function(r, i) {
    return '<div style="background:#fef2f2;border:1px solid #fca5a5;border-radius:8px;padding:12px 16px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center">' +
      '<div><div style="font-weight:700;font-size:11pt">📄 ' + esc(r.name||'AI X-ray Report '+(i+1)) + '</div>' +
      '<div style="font-size:9pt;color:#64748b">' + fmtDate(r.date||'') + '</div></div>' +
      '<a href="data:application/pdf;base64,' + r.data + '" download="' + esc(r.name||'report') + '.pdf" ' +
      'style="background:#dc2626;color:#fff;padding:6px 14px;border-radius:8px;font-size:10pt;font-weight:700;text-decoration:none">⬇ Download PDF</a>' +
      '</div>';
  }).join('') : '';

  var html = '<!DOCTYPE html><html><head><meta charset="UTF-8"/>' +
    '<meta name="viewport" content="width=device-width,initial-scale=1"/>' +
    '<title>Images — ' + esc(activePt.name) + '</title>' +
    '<style>' +
    '@page{size:A4;margin:15mm}' +
    'body{font-family:Arial,sans-serif;color:#1e293b;margin:0;padding:16px}' +
    '.hdr{background:linear-gradient(135deg,#1e3a5f,#0369a1);color:#fff;padding:14px 18px;border-radius:10px;margin-bottom:18px;display:flex;justify-content:space-between;align-items:center}' +
    '@media print{.no-print{display:none!important};body{padding:0}}' +
    '</style></head><body>' +

    '<div class="hdr">' +
      '<div>' +
        '<div style="font-size:16pt;font-weight:800">' + esc(activePt.name) + '</div>' +
        '<div style="opacity:.8;font-size:10pt">' + (activePt.age?activePt.age+'y · ':'') + (activePt.phone||'') + '</div>' +
      '</div>' +
      '<div style="text-align:right">' +
        '<div style="font-size:11pt;font-weight:700">' + CLINIC + '</div>' +
        '<div style="font-size:9pt;opacity:.8">' + DOCTOR + ' | ' + PHONE + '</div>' +
        '<div style="font-size:9pt;opacity:.8">' + fmtDate(todayISO()) + '</div>' +
      '</div>' +
    '</div>' +

    '<div class="no-print" style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:10px 14px;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center">' +
      '<span style="font-size:12px;color:#1d4ed8;font-weight:600">💡 Save as PDF: Press Ctrl+P → Change destination to "Save as PDF" → Save</span>' +
      '<button onclick="window.print()" style="background:#1d4ed8;color:#fff;border:none;padding:7px 16px;border-radius:8px;cursor:pointer;font-size:12px;font-weight:700">🖨️ Print / Save PDF</button>' +
    '</div>' +

    (rptHTML ? '<div style="margin-bottom:20px"><div style="font-size:10pt;font-weight:800;color:#dc2626;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid #dc2626">AI X-ray Reports (' + reports.length + ')</div>' + rptHTML + '</div>' : '') +
    imgHTML +

    (images.length === 0 && reports.length === 0 ? '<div style="text-align:center;padding:40px;color:#94a3b8">No images or reports found.</div>' : '') +

    '<div style="margin-top:20px;padding-top:12px;border-top:1px solid #e2e8f0;text-align:center;font-size:9pt;color:#94a3b8">' +
      CLINIC + ' | ' + PHONE + ' | ' + CITY +
    '</div>' +
    '</body></html>';

  var pw = window.open('', '_blank', 'width=960,height=1100');
  if (!pw) { alert('Allow pop-ups to view the image report.'); return; }
  pw.document.write(html);
  pw.document.close();
}


/* ── Per-image share button ── */
function imgs_shareOne(imgId) {
  var img = (activePt.images||[]).find(function(i){ return i.id===imgId; });
  if (!img || !img.src) return;

  // Mobile: share single image as file
  if (navigator.canShare && navigator.share) {
    try {
      var blob  = imgs_base64ToBlob(img.src);
      var ext   = img.src.startsWith('data:image/png') ? 'png' : 'jpg';
      var file  = new File([blob], (img.category||'Image')+'.'+ext, { type: blob.type });
      if (navigator.canShare({ files: [file] })) {
        navigator.share({ title: img.category||'Image', files: [file] });
        return;
      }
    } catch(e) {}
  }

  // Desktop: open image in new tab (right-click → Save / share)
  var pw = window.open('', '_blank');
  if (pw) { pw.document.write('<html><body style="margin:0;background:#000"><img src="'+img.src+'" style="max-width:100%;max-height:100vh;display:block;margin:auto"/></body></html>'); pw.document.close(); }
}

/* ── Per-report download ── */
function imgs_shareReport(rptId) {
  var rpt = (activePt.xrayReports||[]).find(function(r){ return r.id===rptId; });
  if(!rpt||!rpt.data) return;
  // Try Web Share API on mobile
  if(navigator.canShare && navigator.share) {
    try {
      var blob = imgs_base64ToBlob(rpt.data); // rpt.data is already a full data URL
      var file = new File([blob], (rpt.name||'XRayReport')+'.pdf', {type:'application/pdf'});
      if(navigator.canShare({files:[file]})){
        navigator.share({title:rpt.name||'X-Ray Report',files:[file]});
        return;
      }
    } catch(e) {}
  }
  // Fallback: download
  downloadXrayReport(rptId);
}

function imgs_downloadReport(rptId) {
  var rpt = (activePt.xrayReports||[]).find(function(r){ return r.id===rptId; });
  if (!rpt || !rpt.data) return;
  var a = document.createElement('a');
  a.href     = 'data:application/pdf;base64,' + rpt.data;
  a.download = (rpt.name||'XRayReport') + '.pdf';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
}



