/* ── FEATURE 3: Rx auto-suggest from diagnosis ── */
var RX_KEYWORD_MAP = {
  'rct':        'rct_postop',
  'root canal': 'rct_postop',
  'extraction': 'extraction_postop',
  'ext':        'extraction_postop',
  'scaling':    'scaling_postop',
  'gingivit':   'scaling_postop',
  'periapical': 'rct_postop',
  'abscess':    'abscess',
  'ulcer':      'aphthous',
  'aphthous':   'aphthous',
};

function rx_suggestFromDiagnosis(diagText) {
  var lower = (diagText||'').toLowerCase();
  for(var kw in RX_KEYWORD_MAP){
    if(lower.includes(kw)) return RX_KEYWORD_MAP[kw];
  }
  return null;
}

// Hook into record saving — suggest Rx after record saved
// cs_saveRecord auto-suggest removed to avoid override conflict


/* ── FEATURE 5: Pending Treatment Follow-up ───── */
function renderPendingTx() {
  var el = document.getElementById('pending-tx-content');
  if(!el) return;
  var today = todayISO();
  var pts = DATA.patients||[];

  // Get patients with planned (not started) treatment plan items
  var pendingList = [];
  pts.forEach(function(p){
    var planned = (p.treatmentPlan||[]).filter(function(i){return i.status==='planned';});
    if(!planned.length) return;
    var totalValue = planned.reduce(function(s,i){return s+Number(i.estimatedCost||0);},0);
    var lastVisit = (p.records||[]).map(function(r){return r.date||'';}).sort().slice(-1)[0]||'';
    var daysSince = lastVisit ? Math.floor((new Date(today)-new Date(lastVisit))/86400000) : 999;
    pendingList.push({pt:p, planned:planned, totalValue:totalValue, lastVisit:lastVisit, daysSince:daysSince});
  });

  // Sort by highest value first
  pendingList.sort(function(a,b){ return b.totalValue-a.totalValue; });

  var totalOpp = pendingList.reduce(function(s,x){return s+x.totalValue;},0);

  var h = '';
  // Summary
  h += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:20px">';
  h += '<div class="stat-card"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:4px">Pending Cases</div><div style="font-size:24px;font-weight:800;color:#dc2626">'+pendingList.length+'</div></div><div class="stat-icon" style="background:#fef2f2">📋</div></div>';
  h += '<div class="stat-card"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:4px">Total Opportunity</div><div style="font-size:24px;font-weight:800;color:#059669">'+fmtMoney(totalOpp)+'</div></div><div class="stat-icon" style="background:#ecfdf5">💰</div></div>';
  h += '<div class="stat-card"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:4px">Not Visited 30d+</div><div style="font-size:24px;font-weight:800;color:#d97706">'+pendingList.filter(function(x){return x.daysSince>=30;}).length+'</div></div><div class="stat-icon" style="background:#fffbeb">⏰</div></div>';
  h += '</div>';

  if(!pendingList.length){
    h += '<div class="empty"><span class="empty-icon">🎉</span><div class="empty-title">No pending treatments!</div><div class="empty-sub">All planned treatments have been started or completed</div></div>';
  } else {
    h += '<div style="display:flex;flex-direction:column;gap:10px">';
    pendingList.forEach(function(x){
      var p=x.pt; var isOld=x.daysSince>=30;
      h += '<div style="background:#fff;border:1.5px solid '+(isOld?'#fcd34d':'#e2e8f0')+';border-radius:14px;padding:14px 16px">';
      h += '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap">';
      h += '<div>';
      h += '<div style="font-size:14px;font-weight:700;color:#1e293b">'+esc(p.name)+'</div>';
      h += '<div style="font-size:11px;color:#64748b;margin-top:2px">'+(p.phone||'No phone')+' &bull; '+x.planned.length+' procedure'+(x.planned.length!==1?'s':'');
      h += (x.lastVisit?' &bull; Last visit: '+fmtDate(x.lastVisit)+(isOld?' <span style="color:#dc2626;font-weight:700">('+x.daysSince+' days ago!)</span>':''):' &bull; <span style="color:#dc2626">No visits recorded</span>')+'</div>';
      h += '<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:6px">';
      x.planned.slice(0,3).forEach(function(i){
        h += '<span style="font-size:10px;background:#eff6ff;color:#1d4ed8;border-radius:5px;padding:2px 8px;font-weight:600">'+esc(i.procedure)+(i.estimatedCost?' ₹'+Number(i.estimatedCost).toLocaleString('en-IN'):' ')+'</span>';
      });
      if(x.planned.length>3) h += '<span style="font-size:10px;color:#94a3b8;padding:2px 8px">+' +(x.planned.length-3)+' more</span>';
      h += '</div></div>';
      h += '<div style="text-align:right;flex-shrink:0">';
      h += '<div style="font-size:18px;font-weight:800;color:#059669">'+fmtMoney(x.totalValue)+'</div>';
      h += '<div style="display:flex;gap:6px;margin-top:6px;flex-wrap:wrap;justify-content:flex-end">';
      h += '<button class="btn btn-primary btn-sm" data-pid="'+p.id+'" onclick="openPatient(this.dataset.pid)">👤 Open</button>';
      if(p.phone) h += '<button class="btn btn-sm" style="background:#25d366;color:#fff;border:none" data-pid="'+p.id+'" onclick="pendingTx_followup(this.dataset.pid)">📲 Follow Up</button>';
      h += '</div></div></div></div>';
    });
    h += '</div>';
  }
  el.innerHTML = h;
}

function pendingTx_followup(ptId) {
  var pt=(DATA.patients||[]).find(function(p){return p.id===ptId;});
  if(!pt||!pt.phone) return;
  var planned=(pt.treatmentPlan||[]).filter(function(i){return i.status==='planned';});
  var txList=planned.slice(0,3).map(function(i){return '• '+i.procedure+(i.estimatedCost?' (₹'+Number(i.estimatedCost).toLocaleString('en-IN')+')':'');}).join(String.fromCharCode(10));
  var nl=String.fromCharCode(10);
  var msg='Dear '+pt.name+','+nl+nl+
    'We hope you are doing well!'+nl+nl+
    'We wanted to follow up regarding your pending treatment plan at '+CLINIC+':'+nl+nl+txList+nl+nl+
    'Starting your treatment on time helps avoid complications and additional costs later.'+nl+nl+
    'Please call us to schedule: '+PHONE+nl+TIMING;
  window.open('https://wa.me/91'+pt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}


/* ── FEATURE 7: Lab Tracker Full Workflow ────── */
var LAB_STATUSES = ['Sent to Lab','Lab Working','Ready at Lab','Received','Delivered to Patient'];



function lab_updateStatus(id, newStatus){
  var idx=(DATA.labJobs||[]).findIndex(function(j){return j.id===id;});
  if(idx<0)return;
  DATA.labJobs[idx].status=newStatus;
  if(newStatus==='Received') DATA.labJobs[idx].receivedDate=todayISO();
  if(newStatus==='Delivered to Patient') DATA.labJobs[idx].deliveredDate=todayISO();
  saveData(); lab_render();
}

function lab_deleteJob(id){
  if(!confirm('Delete this lab job?'))return;
  DATA.labJobs=(DATA.labJobs||[]).filter(function(j){return j.id!==id;});
  saveData(); lab_render();
}

function lab_render(){
  var el=document.getElementById('lab-list');
  if(!el)return;
  var jobs=(DATA.labJobs||[]).slice().sort(function(a,b){return (b.sentDate||'').localeCompare(a.sentDate||'');});
  var today=todayISO();
  var overdue=jobs.filter(function(j){return j.dueDate&&j.dueDate<today&&j.status!=='Delivered to Patient';}).length;

  var h='';
  // Add job form
  h+='<div class="card" style="margin-bottom:18px">';
  h+='<div style="font-size:13px;font-weight:700;margin-bottom:14px">🔬 New Lab Job</div>';
  h+='<div class="form-grid-2">';
  h+='<div class="form-group"><label class="form-label">Patient Name *</label><input class="form-input" id="lab-pt" placeholder="Patient name" list="lab-pt-list"/><datalist id="lab-pt-list">';
  (DATA.patients||[]).forEach(function(p){h+='<option>'+esc(p.name)+'</option>';});
  h+='</datalist></div>';
  h+='<div class="form-group"><label class="form-label">Lab Name *</label><input class="form-input" id="lab-name" placeholder="e.g. Kota Dental Lab"/></div>';
  h+='<div class="form-group"><label class="form-label">Work Type</label><select class="form-input" id="lab-worktype">';
  ['Crown','Bridge','Denture','Partial Denture','Inlay/Onlay','Veneer','Implant Crown','Night Guard','Sports Guard','Orthodontic Appliance','Other'].forEach(function(t){h+='<option>'+t+'</option>';});
  h+='</select></div>';
  h+='<div class="form-group"><label class="form-label">Cost (₹)</label><input class="form-input" id="lab-cost" type="number" placeholder="0" min="0"/></div>';
  h+='<div class="form-group"><label class="form-label">Sent Date</label><input class="form-input" id="lab-sent" type="date" value="'+todayISO()+'"/></div>';
  h+='<div class="form-group"><label class="form-label">Expected Return</label><input class="form-input" id="lab-due" type="date"/></div>';
  h+='</div>';
  h+='<div class="form-group"><label class="form-label">Notes</label><input class="form-input" id="lab-notes" placeholder="Shade, specifications..."/></div>';
  h+='<button id="lab-save-btn" class="btn btn-primary" onclick="lab_saveJob()" style="margin-top:6px">💾 Save Lab Job</button></div>';

  // Stats
  var pending=jobs.filter(function(j){return j.status!=='Delivered to Patient';});
  h+='<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px">';
  h+='<div class="stat-card" style="flex:1;min-width:120px"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:2px">Active Jobs</div><div style="font-size:22px;font-weight:800;color:#1d4ed8">'+pending.length+'</div></div><div class="stat-icon" style="background:#eff6ff">🔬</div></div>';
  h+='<div class="stat-card" style="flex:1;min-width:120px"><div><div style="font-size:11px;color:#64748b;font-weight:600;margin-bottom:2px">Overdue</div><div style="font-size:22px;font-weight:800;color:#dc2626">'+overdue+'</div></div><div class="stat-icon" style="background:#fef2f2">⚠️</div></div>';
  h+='</div>';

  if(!jobs.length){
    h+='<div class="empty"><span class="empty-icon">🔬</span><div class="empty-title">No lab jobs yet</div></div>';
  } else {
    var statusColors={'Sent to Lab':'#64748b','Lab Working':'#d97706','Ready at Lab':'#059669','Received':'#1d4ed8','Delivered to Patient':'#7c3aed'};
    jobs.forEach(function(j){
      var isDue=j.dueDate&&j.dueDate<today&&j.status!=='Delivered to Patient';
      var done=j.status==='Delivered to Patient';
      h+='<div style="background:#fff;border:1.5px solid '+(isDue?'#fca5a5':done?'#c4b5fd':'#e2e8f0')+';border-radius:14px;padding:14px 16px;margin-bottom:10px">';
      h+='<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap">';
      h+='<div><div style="font-size:13px;font-weight:700;color:#1e293b">'+esc(j.patientName)+' — '+esc(j.workType)+'</div>';
      h+='<div style="font-size:11px;color:#64748b;margin-top:2px">🏥 '+esc(j.labName)+' &bull; Sent: '+fmtDate(j.sentDate)+(j.dueDate?' &bull; Due: <strong style="color:'+(isDue?'#dc2626':'#1e293b')+'">'+fmtDate(j.dueDate)+'</strong>':'')+(j.cost?' &bull; ₹'+Number(j.cost).toLocaleString('en-IN'):'')+' </div>';
      if(j.notes) h+='<div style="font-size:11px;color:#94a3b8;margin-top:3px">'+esc(j.notes)+'</div>';
      h+='</div>';
      h+='<span style="font-size:10px;font-weight:800;color:'+(statusColors[j.status]||'#64748b')+';background:#f8fafc;border-radius:8px;padding:4px 10px;flex-shrink:0">'+j.status+'</span>';
      h+='</div>';
      h+='<div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:10px;padding-top:8px;border-top:1px solid #f1f5f9">';
      LAB_STATUSES.forEach(function(s){
        if(s===j.status)return;
        h+='<button class="btn btn-sm" style="font-size:10px;padding:4px 10px;background:#f8fafc;border:1px solid #e2e8f0" data-jid="'+j.id+'" data-st="'+s+'" onclick="lab_updateStatus(this.dataset.jid,this.dataset.st)">→ '+s+'</button>';
      });
      h+='<button class="btn btn-sm" style="font-size:10px;padding:4px 10px;background:#eff6ff;color:#1d4ed8;border:none" data-jid="'+j.id+'" onclick="lab_editJob(this.dataset.jid)">✏️ Edit</button>';
      h+='<button class="btn btn-red btn-sm" style="font-size:10px;padding:4px 8px;margin-left:auto" data-jid="'+j.id+'" onclick="lab_deleteJob(this.dataset.jid)">🗑</button>';
      h+='</div></div>';
    });
  }
  el.innerHTML=h;
}


/* ── FEATURE 8: Consent Form Digital Signature ─ */
var consent_signPad = null;
var consent_signing = null;

function consent_openSign(tplId) {
  var tpl = (DATA.consentTemplates||[]).find(function(t){return t.id===tplId;});
  var builtin = CONSENT_TEMPLATES ? CONSENT_TEMPLATES.find(function(t){return t.id===tplId;}) : null;
  var source = tpl || builtin;
  if(!source){alert('Template not found.');return;}
  if(!activePt){alert('Open a patient first.');return;}
  consent_signing = {tplId:tplId, name:source.label, body:source.body||source.content||''};

  var modal = document.getElementById('consent-sign-modal');
  if(!modal){
    modal = document.createElement('div');
    modal.id = 'consent-sign-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
    document.body.appendChild(modal);
  }
  modal.style.display='flex';
  modal.innerHTML = '<div style="background:#fff;border-radius:16px;padding:24px;max-width:560px;width:100%;max-height:90vh;overflow-y:auto">' +
    '<div style="font-size:15px;font-weight:800;color:#1e293b;margin-bottom:6px">✍️ Patient Consent</div>' +
    '<div style="font-size:12px;color:#64748b;margin-bottom:14px">'+esc(source.label)+'</div>' +
    '<div style="background:#f8fafc;border-radius:8px;padding:12px;font-size:11px;color:#374151;max-height:200px;overflow-y:auto;margin-bottom:16px;line-height:1.6">'+esc(consent_signing.body)+'</div>' +
    '<div style="font-size:12px;font-weight:700;color:#1e293b;margin-bottom:6px">Patient Signature <span style="font-weight:400;color:#94a3b8">(sign below)</span></div>' +
    '<canvas id="consent-canvas" width="480" height="150" style="border:2px solid #e2e8f0;border-radius:8px;touch-action:none;width:100%;background:#fff;cursor:crosshair"></canvas>' +
    '<div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap">' +
    '<button class="btn btn-sm" onclick="consent_clearSig()" style="background:#f1f5f9;color:#475569;border:1px solid #e2e8f0">Clear</button>' +
    '<div style="flex:1"></div>' +
    '<button class="btn btn-primary" onclick="consent_saveSig()">✅ Save Signed Consent</button>' +
    '<button class="btn" onclick="document.getElementById(\'consent-sign-modal\').style.display=\'none\'" style="background:#f1f5f9;color:#475569;border:1px solid #e2e8f0">Cancel</button>' +
    '</div></div>';

  // Init signature pad
  setTimeout(function(){
    var canvas=document.getElementById('consent-canvas');
    if(!canvas)return;
    // Scale canvas for device pixel ratio
    var rect=canvas.getBoundingClientRect();
    canvas.width=rect.width*window.devicePixelRatio||480;
    canvas.height=150*window.devicePixelRatio||150;
    var ctx=canvas.getContext('2d');
    ctx.scale(window.devicePixelRatio||1,window.devicePixelRatio||1);
    ctx.strokeStyle='#1e293b'; ctx.lineWidth=2; ctx.lineCap='round';
    var drawing=false,lastX=0,lastY=0;
    function getPos(e){
      var r=canvas.getBoundingClientRect();
      if(e.touches) return {x:(e.touches[0].clientX-r.left),y:(e.touches[0].clientY-r.top)};
      return {x:e.clientX-r.left,y:e.clientY-r.top};
    }
    canvas.addEventListener('mousedown',function(e){drawing=true;var p=getPos(e);lastX=p.x;lastY=p.y;},true);
    canvas.addEventListener('mousemove',function(e){if(!drawing)return;var p=getPos(e);ctx.beginPath();ctx.moveTo(lastX,lastY);ctx.lineTo(p.x,p.y);ctx.stroke();lastX=p.x;lastY=p.y;},true);
    canvas.addEventListener('mouseup',function(){drawing=false;},true);
    canvas.addEventListener('touchstart',function(e){e.preventDefault();drawing=true;var p=getPos(e);lastX=p.x;lastY=p.y;},{passive:false});
    canvas.addEventListener('touchmove',function(e){e.preventDefault();if(!drawing)return;var p=getPos(e);ctx.beginPath();ctx.moveTo(lastX,lastY);ctx.lineTo(p.x,p.y);ctx.stroke();lastX=p.x;lastY=p.y;},{passive:false});
    canvas.addEventListener('touchend',function(){drawing=false;},{passive:false});
  },100);
}

function consent_clearSig(){
  var canvas=document.getElementById('consent-canvas');
  if(!canvas)return;
  canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);
}

function consent_saveSig(){
  var canvas=document.getElementById('consent-canvas');
  if(!canvas){alert('Signature pad not found.');return;}
  var sigData=canvas.toDataURL('image/png');
  if(!activePt){alert('No patient selected.');return;}
  if(!activePt.signedConsents) activePt.signedConsents=[];
  activePt.signedConsents.push({
    id:'sc'+Date.now(),
    tplId:consent_signing.tplId,
    name:consent_signing.name,
    signedAt:new Date().toISOString(),
    date:todayISO(),
    signature:sigData,
    patientName:activePt.name
  });
  var idx=DATA.patients.findIndex(function(p){return p.id===activePt.id;});
  if(idx>=0) DATA.patients[idx]=activePt;
  saveData();
  document.getElementById('consent-sign-modal').style.display='none';
  alert('✅ Consent saved with signature for '+activePt.name+'!');
  consent_render();
}


/* ── FEATURE 10: Appointment Confirmation WA ─── */
function appt_sendConfirmation(apptId) {
  var appt=(DATA.appointments||[]).find(function(a){return a.id===apptId;});
  if(!appt)return;
  var pt=(DATA.patients||[]).find(function(p){return p.id===appt.patientId;});
  var phone=(pt&&pt.phone)||appt.phone||'';
  if(!phone){alert('No phone number for this patient.');return;}
  var nl=String.fromCharCode(10);
  var fmt12=function(t){if(!t)return '';var p=t.split(':');var h=parseInt(p[0]);var m=p[1]||'00';return((h%12)||12)+':'+m+(h>=12?' PM':' AM');};
  var msg='Dear '+(appt.patientName||'Patient')+','+nl+nl+
    'Your appointment at *'+CLINIC+'* is CONFIRMED! ✅'+nl+nl+
    '📅 Date: '+fmtDate(appt.date)+nl+
    '⏰ Time: '+fmt12(appt.time)+nl+
    (appt.notes?'📋 For: '+appt.notes+nl:'')+nl+
    'Please arrive 10 minutes early. Bring any previous X-rays.'+nl+nl+
    'To reschedule: '+PHONE+nl+TIMING;
  window.open('https://wa.me/91'+phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}


/* ── FEATURE 11: Post-Treatment Care Instructions ── */
var CARE_INSTRUCTIONS = {
  'RCT':         ['Avoid biting on treated tooth for 24-48 hours','Take prescribed medications on time','Some sensitivity is normal for 1-2 days','Crown placement will be planned — do not delay','Call us immediately if severe pain or swelling occurs'],
  'Extraction':  ['Bite on gauze for 30-45 minutes','Avoid spitting, smoking, or using straw for 24 hours','Apply ice pack on cheek for 10 min on/off for first 2-3 hours','Eat soft, cold foods today','Do not disturb the blood clot — it protects healing','Rinse gently with warm salt water from tomorrow'],
  'Scaling':     ['Some sensitivity and bleeding is normal for 2-3 days','Avoid very hot/cold foods for 48 hours','Use soft toothbrush gently','Rinse with warm salt water twice daily for 3 days','Follow-up in 1 week if excessive bleeding'],
  'Filling':     ['Avoid chewing on the filled tooth for 1 hour (if composite)','Sensitivity to hot/cold may last a few days — normal','If bite feels uneven, visit us for adjustment'],
  'Crown':       ['Temporary crown: avoid sticky or hard foods','Permanent crown: gentle brushing and flossing','Some sensitivity around the gum is normal for a few days'],
  'Implant':     ['Take all medications as prescribed','Apply cold compress for 20 min intervals today','Do not disturb the surgical site','Eat only soft foods for 1 week','No smoking — it affects healing significantly','Call us immediately for unusual swelling or bleeding'],
  'Bleaching':   ['Avoid staining foods for 48 hours: coffee, tea, red wine, curries','Use sensitive toothpaste if sensitivity occurs','Do not smoke for 48 hours','Some tooth sensitivity is normal — it subsides in 24-48 hours'],
  'Default':     ['Take prescribed medicines on time','If pain or swelling increases, call us immediately','Avoid very hard or sticky foods for 24 hours','Follow up as scheduled']
};

function care_send(ptId, procedure) {
  var pt=(DATA.patients||[]).find(function(p){return p.id===ptId;});
  if(!pt||!pt.phone){alert('No phone number for this patient.');return;}
  var key=Object.keys(CARE_INSTRUCTIONS).find(function(k){return (procedure||'').toLowerCase().includes(k.toLowerCase());}) || 'Default';
  var steps=CARE_INSTRUCTIONS[key];
  var nl=String.fromCharCode(10);
  var msg='Dear '+pt.name+','+nl+nl+
    'Thank you for visiting *'+CLINIC+'* today! 😊'+nl+nl+
    '*Post-Treatment Care — '+key+'*'+nl+
    '─────────────────'+nl+
    steps.map(function(s,i){return (i+1)+'. '+s;}).join(nl)+nl+nl+
    'Any questions? Call us anytime: '+PHONE+nl+TIMING;
  window.open('https://wa.me/91'+pt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

function care_promptAfterRecord(ptId, procedure) {
  if(!procedure) return;
  setTimeout(function(){
    var hasCare = Object.keys(CARE_INSTRUCTIONS).some(function(k){return procedure.toLowerCase().includes(k.toLowerCase());});
    if(hasCare && confirm('Send post-treatment care instructions for "'+procedure+'" to patient via WhatsApp?')){
      care_send(ptId, procedure);
    }
  }, 400);
}


/* ── FEATURE 12: Birthday Greetings ─────────── */
function birthday_getToday() {
  var today=todayISO();
  var mm=today.slice(5,7); var dd=today.slice(8,10);
  return (DATA.patients||[]).filter(function(p){
    if(!p.dob) return false;
    var pdob=p.dob;
    return pdob.slice(5,7)===mm && pdob.slice(8,10)===dd;
  });
}

function birthday_sendWA(ptId) {
  var pt=(DATA.patients||[]).find(function(p){return p.id===ptId;});
  if(!pt||!pt.phone){alert('No phone number.');return;}
  var nl=String.fromCharCode(10);
  var msg='🎂 Dear '+pt.name+','+nl+nl+
    'Wishing you a very *Happy Birthday!* 🎉'+nl+nl+
    'May your smile always be bright and healthy! 😁'+nl+nl+
    'As a birthday gift from us, enjoy a *complimentary dental check-up* this month.'+nl+nl+
    'Call us to book: '+PHONE+nl+TIMING+nl+nl+
    'With warm wishes,'+nl+DOCTOR+nl+CLINIC;
  window.open('https://wa.me/91'+pt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

function birthday_remindAll() {
  var bdays=birthday_getToday();
  if(!bdays.length){alert('No patient birthdays today!');return;}
  if(!confirm('Send birthday wishes to '+bdays.length+' patient'+(bdays.length!==1?'s':'')+' via WhatsApp?'))return;
  bdays.forEach(function(pt,i){
    setTimeout(function(){birthday_sendWA(pt.id);},i*1500);
  });
}



