/* ─── 3. BEFORE / AFTER PHOTO VIEWER ────────────
   Side-by-side comparison from patient images tab.
   Selects photos tagged 'Before' and 'After'.
──────────────────────────────────────────────── */
function beforeAfter_open(ptId) {
  var pt = ptId ? (DATA.patients||[]).find(function(p){return p.id===ptId;}) : activePt;
  if(!pt){ alert('Open a patient first.'); return; }

  var befores = (pt.images||[]).filter(function(i){ return i.category==='Before'; });
  var afters  = (pt.images||[]).filter(function(i){ return i.category==='After';  });

  if(!befores.length && !afters.length){
    alert('No Before/After photos found.\n\nWhen capturing photos, set category to "Before" or "After" to use this feature.');
    return;
  }

  var modal = document.getElementById('ba-modal');
  if(!modal){
    modal = document.createElement('div');
    modal.id = 'ba-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.9);z-index:9990;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;padding:16px;overflow-y:auto';
    document.body.appendChild(modal);
  }

  var selBefore = befores.length ? befores[0] : null;
  var selAfter  = afters.length  ? afters[0]  : null;

  function buildHTML(sb, sa){
    var bOpts = befores.map(function(img,i){
      return '<button onclick="beforeAfter_select(\'b\','+i+')" style="font-size:10px;padding:4px 10px;border-radius:6px;border:none;cursor:pointer;background:'+(sb&&sb.id===img.id?'#3b82f6':'#334155')+';color:#fff">'+(img.date?fmtDate(img.date):'Photo '+(i+1))+'</button>';
    }).join('');
    var aOpts = afters.map(function(img,i){
      return '<button onclick="beforeAfter_select(\'a\','+i+')" style="font-size:10px;padding:4px 10px;border-radius:6px;border:none;cursor:pointer;background:'+(sa&&sa.id===img.id?'#10b981':'#334155')+';color:#fff">'+(img.date?fmtDate(img.date):'Photo '+(i+1))+'</button>';
    }).join('');

    return '<div style="background:#1e293b;border-radius:14px;padding:18px;max-width:900px;width:100%">'+
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">'+
      '<div style="color:#f1f5f9;font-size:15px;font-weight:800">📸 Before / After — '+esc(pt.name)+'</div>'+
      '<div style="display:flex;gap:8px">'+
      '<button onclick="beforeAfter_print()" style="background:#7c3aed;border:none;border-radius:8px;padding:7px 14px;color:#fff;font-size:12px;font-weight:700;cursor:pointer">🖨️ Print</button>'+
      '<button onclick="document.getElementById(\'ba-modal\').style.display=\'none\'" style="background:#dc2626;border:none;border-radius:8px;padding:7px 14px;color:#fff;font-size:12px;font-weight:700;cursor:pointer">✕ Close</button>'+
      '</div></div>'+
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">'+
      '<div>'+
      '<div style="font-size:10px;font-weight:800;color:#ef4444;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px">● BEFORE</div>'+
      (sb ? '<img src="'+sb.url+'" style="width:100%;border-radius:10px;border:3px solid #ef4444;display:block"/>' : '<div style="background:#334155;border-radius:10px;height:220px;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:12px">No Before photo selected</div>')+
      (befores.length>1 ? '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">'+bOpts+'</div>' : '')+
      '</div>'+
      '<div>'+
      '<div style="font-size:10px;font-weight:800;color:#10b981;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px">● AFTER</div>'+
      (sa ? '<img src="'+sa.url+'" style="width:100%;border-radius:10px;border:3px solid #10b981;display:block"/>' : '<div style="background:#334155;border-radius:10px;height:220px;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:12px">No After photo yet</div>')+
      (afters.length>1  ? '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">'+aOpts+'</div>' : '')+
      '</div></div>'+
      ((!sb && !sa) ? '<div style="text-align:center;color:#94a3b8;padding:20px">No photos to compare yet</div>' : '')+
      '</div>';
  }

  window._baState = {pt:pt, befores:befores, afters:afters, selBefore:selBefore, selAfter:selAfter};
  modal.style.display='flex';
  modal.innerHTML = buildHTML(selBefore, selAfter);
}

function beforeAfter_select(side, idx){
  var state = window._baState;
  if(!state) return;
  if(side==='b') state.selBefore = state.befores[idx];
  else           state.selAfter  = state.afters[idx];
  var modal = document.getElementById('ba-modal');
  if(modal) modal.innerHTML = (function(){
    // rebuild
    var sb=state.selBefore, sa=state.selAfter, pt=state.pt;
    var befores=state.befores, afters=state.afters;
    var bOpts = befores.map(function(img,i){return '<button onclick="beforeAfter_select(\'b\','+i+')" style="font-size:10px;padding:4px 10px;border-radius:6px;border:none;cursor:pointer;background:'+(sb&&sb.id===img.id?'#3b82f6':'#334155')+';color:#fff">'+(img.date?fmtDate(img.date):'Photo '+(i+1))+'</button>';}).join('');
    var aOpts = afters.map(function(img,i){return '<button onclick="beforeAfter_select(\'a\','+i+')" style="font-size:10px;padding:4px 10px;border-radius:6px;border:none;cursor:pointer;background:'+(sa&&sa.id===img.id?'#10b981':'#334155')+';color:#fff">'+(img.date?fmtDate(img.date):'Photo '+(i+1))+'</button>';}).join('');
    return '<div style="background:#1e293b;border-radius:14px;padding:18px;max-width:900px;width:100%">'+
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><div style="color:#f1f5f9;font-size:15px;font-weight:800">📸 Before / After — '+esc(pt.name)+'</div>'+
      '<div style="display:flex;gap:8px"><button onclick="beforeAfter_print()" style="background:#7c3aed;border:none;border-radius:8px;padding:7px 14px;color:#fff;font-size:12px;font-weight:700;cursor:pointer">🖨️ Print</button>'+
      '<button onclick="document.getElementById(\'ba-modal\').style.display=\'none\'" style="background:#dc2626;border:none;border-radius:8px;padding:7px 14px;color:#fff;font-size:12px;font-weight:700;cursor:pointer">✕ Close</button></div></div>'+
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">'+
      '<div><div style="font-size:10px;font-weight:800;color:#ef4444;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px">● BEFORE</div>'+
      (sb?'<img src="'+sb.url+'" style="width:100%;border-radius:10px;border:3px solid #ef4444;display:block"/>':'<div style="background:#334155;border-radius:10px;height:220px;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:12px">No Before photo</div>')+
      (befores.length>1?'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">'+bOpts+'</div>':'')+
      '</div><div><div style="font-size:10px;font-weight:800;color:#10b981;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px">● AFTER</div>'+
      (sa?'<img src="'+sa.url+'" style="width:100%;border-radius:10px;border:3px solid #10b981;display:block"/>':'<div style="background:#334155;border-radius:10px;height:220px;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:12px">No After photo yet</div>')+
      (afters.length>1?'<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">'+aOpts+'</div>':'')+
      '</div></div></div>';
  })();
}

function beforeAfter_print(){
  var state = window._baState;
  if(!state) return;
  var sb=state.selBefore, sa=state.selAfter, pt=state.pt;
  var pw=window.open('','_blank','width=800,height=600');
  if(!pw) return;
  pw.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>Before/After — '+esc(pt.name)+'</title>'+
    '<style>@page{size:A4 landscape;margin:15mm}body{font-family:Arial,sans-serif;margin:0;padding:12px}'+
    '.hdr{background:#1e3a5f;color:#fff;padding:12px 18px;border-radius:10px;margin-bottom:16px;display:flex;justify-content:space-between}'+
    '.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}img{width:100%;border-radius:10px}'+
    '@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body>'+
    '<div class="hdr"><div><strong style="font-size:16pt">'+esc(pt.name)+'</strong><br><span style="opacity:.8;font-size:10pt">'+CLINIC+' | '+DOCTOR+'</span></div>'+
    '<div style="text-align:right"><strong style="font-size:14pt">Before / After Comparison</strong><br><span style="opacity:.8;font-size:10pt">'+fmtDate(todayISO())+'</span></div></div>'+
    '<div class="grid">'+
    '<div><div style="font-size:11pt;font-weight:800;color:#dc2626;margin-bottom:8px;text-transform:uppercase">BEFORE</div>'+(sb?'<img src="'+sb.url+'"/>':'<p style="color:#94a3b8">No Before photo</p>')+'</div>'+
    '<div><div style="font-size:11pt;font-weight:800;color:#059669;margin-bottom:8px;text-transform:uppercase">AFTER</div>'+(sa?'<img src="'+sa.url+'"/>':'<p style="color:#94a3b8">No After photo yet</p>')+'</div>'+
    '</div><div style="margin-top:16px;text-align:center;font-size:9pt;color:#94a3b8">'+PHONE+' | '+TIMING+' | '+CITY+'</div>'+
    '</body></html>');
  pw.document.close();
  pw.onload=function(){pw.focus();pw.print();};
}


/* ─── 8. RECALL — BULK AUTO SEND ─────────────── */
function recall_sendAllDue(){
  var pts = DATA.patients||[];
  var today = todayISO();
  var duePts = pts.filter(function(p){
    if(!p.phone) return false;
    var last = recall_getLastVisit(p);
    var due  = recall_getDueDate(last);
    return due && due <= today;
  });

  if(!duePts.length){ alert('No patients with overdue recall today.'); return; }
  if(!confirm('Send recall WhatsApp to '+duePts.length+' patient(s) due for recall?\n\nThis will open '+duePts.length+' WhatsApp tabs.')) return;

  duePts.forEach(function(p, i){
    setTimeout(function(){ recall_sendWA(p.id); }, i * 1800);
  });
}

function recall_sendWeekDue(){
  var pts = DATA.patients||[];
  var today = todayISO();
  var d = new Date(today); d.setDate(d.getDate()+7);
  var weekEnd = d.toISOString().slice(0,10);
  var duePts = pts.filter(function(p){
    if(!p.phone) return false;
    var last = recall_getLastVisit(p);
    var due  = recall_getDueDate(last);
    return due && due >= today && due <= weekEnd;
  });
  if(!duePts.length){ alert('No patients due for recall this week.'); return; }
  if(!confirm('Send recall reminder to '+duePts.length+' patient(s) due this week?')) return;
  duePts.forEach(function(p,i){ setTimeout(function(){ recall_sendWA(p.id); }, i*1800); });
}


/* ─── 9. ORTHO ENHANCED TRACKING ─────────────── */
function ortho_saveEnhanced(){
  if(!activePt) return;
  var totalSets   = parseInt((document.getElementById('oe-total-sets')||{}).value||0);
  var donesets    = parseInt((document.getElementById('oe-done-sets')||{}).value||0);
  var compliance  = (document.getElementById('oe-compliance')||{}).value||'Good';
  var nextReview  = (document.getElementById('oe-next-review')||{}).value||'';
  var payPlan     = (document.getElementById('oe-pay-plan')||{}).value||'';
  var notes       = ((document.getElementById('oe-notes')||{}).value||'').trim();

  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  if(ptIdx<0) return;
  if(!DATA.patients[ptIdx].orthoDetails) DATA.patients[ptIdx].orthoDetails={};
  Object.assign(DATA.patients[ptIdx].orthoDetails, {
    totalSets:totalSets, doneSets:donesets, compliance:compliance,
    nextReview:nextReview, paymentPlan:payPlan, clinicalNotes:notes,
    lastUpdated:todayISO()
  });
  activePt = DATA.patients[ptIdx];
  saveData();
  alert('✅ Ortho details updated!');
  renderOrthoDetailTab();
}

function ortho_sendProgressWA(){
  if(!activePt||!activePt.phone) { alert('No phone number.'); return; }
  var od = activePt.orthoDetails||{};
  var nl = String.fromCharCode(10);
  var pct = od.totalSets>0 ? Math.round((od.doneSets||0)/od.totalSets*100) : 0;
  var msg = 'Dear '+activePt.name+','+nl+nl+
    'Your orthodontic treatment update from *'+CLINIC+'*:'+nl+nl+
    '📊 Progress: '+(od.doneSets||0)+' / '+(od.totalSets||'?')+' sets completed ('+pct+'%)'+nl+
    '😊 Compliance: '+(od.compliance||'Good')+nl+
    (od.nextReview?'📅 Next review: '+fmtDate(od.nextReview)+nl:'')+nl+
    'Keep wearing your aligners 20-22 hours daily for best results!'+nl+nl+
    'Questions? Call: '+PHONE+nl+TIMING;
  window.open('https://wa.me/91'+activePt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

// Renders enhanced ortho panel — injected inside renderOrthoDetailTab
function ortho_renderEnhancedPanel(od){
  var doneSets   = od.doneSets||0;
  var totalSets  = od.totalSets||0;
  var pct        = totalSets>0 ? Math.min(100,Math.round(doneSets/totalSets*100)) : 0;
  var compliance = od.compliance||'';
  var compColors = {'Excellent':'#059669','Good':'#0d9488','Fair':'#d97706','Poor':'#dc2626'};
  var compColor  = compColors[compliance]||'#64748b';

  var h='<div class="card" style="margin-top:14px">';
  h+='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">';
  h+='<div style="font-size:13px;font-weight:800;color:#1e293b">📊 Aligner Progress Tracker</div>';
  h+='<button class="btn btn-sm" style="background:#25d366;color:#fff;border:none" onclick="ortho_sendProgressWA()">📲 Send Update</button>';
  h+='</div>';

  // Progress bar
  if(totalSets>0){
    h+='<div style="margin-bottom:14px">';
    h+='<div style="display:flex;justify-content:space-between;margin-bottom:5px">';
    h+='<span style="font-size:12px;font-weight:700;color:#1e293b">Sets: '+doneSets+' / '+totalSets+'</span>';
    h+='<span style="font-size:12px;font-weight:800;color:#7c3aed">'+pct+'%</span></div>';
    h+='<div style="background:#f1f5f9;border-radius:99px;height:10px"><div style="width:'+pct+'%;background:linear-gradient(90deg,#7c3aed,#6d28d9);border-radius:99px;height:100%;transition:width .6s"></div></div>';
    if(compliance) h+='<div style="margin-top:6px;font-size:11px;font-weight:700;color:'+compColor+'">Compliance: '+compliance+'</div>';
    h+='</div>';
  }

  // Edit form
  h+='<div class="form-grid-2" style="margin-bottom:10px">';
  h+='<div class="form-group"><label class="form-label">Total Aligner Sets</label><input class="form-input" id="oe-total-sets" type="number" min="0" value="'+totalSets+'" placeholder="e.g. 28"/></div>';
  h+='<div class="form-group"><label class="form-label">Sets Completed</label><input class="form-input" id="oe-done-sets" type="number" min="0" value="'+doneSets+'" placeholder="e.g. 10"/></div>';
  h+='<div class="form-group"><label class="form-label">Compliance</label><select class="form-input" id="oe-compliance">';
  ['Excellent','Good','Fair','Poor'].forEach(function(v){ h+='<option'+(v===compliance?' selected':'')+'>'+v+'</option>'; });
  h+='</select></div>';
  h+='<div class="form-group"><label class="form-label">Next Review Date</label><input class="form-input" id="oe-next-review" type="date" value="'+(od.nextReview||'')+'"/></div>';
  h+='</div>';
  h+='<div class="form-group"><label class="form-label">Payment Plan / Milestones</label><input class="form-input" id="oe-pay-plan" placeholder="e.g. ₹5000 per 10 sets" value="'+esc(od.paymentPlan||'')+'"/></div>';
  h+='<div class="form-group"><label class="form-label">Clinical Notes</label><input class="form-input" id="oe-notes" placeholder="Observations, instructions..." value="'+esc(od.clinicalNotes||'')+'"/></div>';
  h+='<button class="btn btn-primary" onclick="ortho_saveEnhanced()" style="margin-top:6px">💾 Save Progress</button>';
  h+='</div>';
  return h;
}


/* ─── 11. PATIENT SATISFACTION SURVEY ─────────── */
function survey_send(ptId){
  var pt=(DATA.patients||[]).find(function(p){return p.id===ptId;}) || activePt;
  if(!pt||!pt.phone){ alert('No phone number.'); return; }
  var nl = String.fromCharCode(10);
  var msg = 'Dear '+pt.name+','+nl+nl+
    'Thank you for visiting *'+CLINIC+'* today! 😊'+nl+nl+
    'We value your feedback. Please rate us:'+nl+nl+
    '⭐ 1 = Very poor'+nl+
    '⭐⭐ 2 = Poor'+nl+
    '⭐⭐⭐ 3 = Average'+nl+
    '⭐⭐⭐⭐ 4 = Good'+nl+
    '⭐⭐⭐⭐⭐ 5 = Excellent'+nl+nl+
    'Just reply with your rating (1-5). We read every response!'+nl+nl+
    'Thank you for trusting us 🙏'+nl+
    CLINIC+' | '+PHONE;
  window.open('https://wa.me/91'+pt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

function survey_recordRating(ptId, rating){
  var ptIdx=(DATA.patients||[]).findIndex(function(p){return p.id===ptId;});
  if(ptIdx<0) return;
  if(!DATA.patients[ptIdx].surveys) DATA.patients[ptIdx].surveys=[];
  DATA.patients[ptIdx].surveys.push({rating:rating, date:todayISO(), id:'sv'+Date.now()});
  if(ptIdx>=0 && activePt && activePt.id===ptId) activePt=DATA.patients[ptIdx];
  saveData();
  alert('Rating '+rating+'/5 recorded for '+DATA.patients[ptIdx].name);
}

function survey_getAvgRating(){
  var all=[];
  (DATA.patients||[]).forEach(function(p){
    (p.surveys||[]).forEach(function(s){ all.push(Number(s.rating)); });
  });
  if(!all.length) return 0;
  return (all.reduce(function(a,b){return a+b;},0)/all.length).toFixed(1);
}


/* ─── 12. QR SELF-REGISTRATION ───────────────── */
function qr_generateRegistration(){
  // Build a self-contained registration form URL
  // Since we're local, we embed the form as a data URL QR points to
  var formHTML = '<!DOCTYPE html><html><head><meta charset="UTF-8"/>'+
    '<meta name="viewport" content="width=device-width,initial-scale=1"/>'+
    '<title>Register — '+CLINIC+'</title>'+
    '<style>*{box-sizing:border-box}body{font-family:-apple-system,sans-serif;background:#f0f4f8;padding:20px;max-width:480px;margin:0 auto}'+
    '.card{background:#fff;border-radius:16px;padding:24px;box-shadow:0 4px 20px rgba(0,0,0,.1)}'+
    'h2{color:#1e3a5f;margin:0 0 4px;font-size:20px}.sub{color:#64748b;font-size:12px;margin-bottom:20px}'+
    'label{display:block;font-size:12px;font-weight:700;color:#374151;margin-bottom:4px;margin-top:14px}'+
    'input,select,textarea{width:100%;padding:10px 12px;border:1.5px solid #e2e8f0;border-radius:8px;font-size:14px;outline:none}'+
    'input:focus,select:focus{border-color:#3b82f6}'+
    '.btn{display:block;width:100%;padding:14px;background:#1e3a5f;color:#fff;border:none;border-radius:10px;font-size:15px;font-weight:700;cursor:pointer;margin-top:20px}'+
    '.hdr{background:#1e3a5f;color:#fff;padding:16px 24px;border-radius:16px;margin-bottom:20px;text-align:center}'+
    '.success{background:#ecfdf5;border:2px solid #6ee7b7;border-radius:12px;padding:20px;text-align:center;display:none}'+
    '</style></head><body>'+
    '<div class="hdr"><div style="font-size:20px;font-weight:800">The Home Of Smiles</div>'+
    '<div style="opacity:.8;font-size:12px">Dr. Tanmay Jain | Patient Registration</div></div>'+
    '<div class="card">'+
    '<h2>New Patient Registration</h2><div class="sub">Fill in your details — we\'ll add you to the system</div>'+
    '<div id="form-wrap">'+
    '<label>Full Name *</label><input id="r-name" placeholder="Your full name" required/>'+
    '<label>Phone Number *</label><input id="r-phone" type="tel" placeholder="10-digit mobile number" maxlength="10"/>'+
    '<label>Age</label><input id="r-age" type="number" min="1" max="120" placeholder="Age"/>'+
    '<label>Gender</label><select id="r-gender"><option value="">Select</option><option>Male</option><option>Female</option><option>Other</option></select>'+
    '<label>Chief Complaint / Reason for Visit</label><textarea id="r-complaint" rows="3" placeholder="What brings you in today?"></textarea>'+
    '<label>Medical History / Allergies</label><input id="r-history" placeholder="Any medications or allergies?"/>'+
    '<button class="btn" onclick="submitForm()">✅ Submit Registration</button>'+
    '</div>'+
    '<div class="success" id="success-msg">'+
    '<div style="font-size:40px;margin-bottom:10px">✅</div>'+
    '<div style="font-size:18px;font-weight:800;color:#059669;margin-bottom:8px">Registered!</div>'+
    '<div style="color:#374151;font-size:14px">Thank you! Please show this screen to our receptionist.</div>'+
    '<div id="ref-code" style="margin-top:12px;font-size:24px;font-weight:800;color:#1e3a5f;background:#f0f9ff;border-radius:8px;padding:10px"></div>'+
    '</div></div>'+
    '<script>function submitForm(){'+
    'var n=document.getElementById("r-name").value.trim();'+
    'var p=document.getElementById("r-phone").value.trim();'+
    'if(!n||!p){alert("Name and phone are required.");return;}'+
    'var data={name:n,phone:p,age:document.getElementById("r-age").value,'+
    'gender:document.getElementById("r-gender").value,'+
    'complaint:document.getElementById("r-complaint").value,'+
    'history:document.getElementById("r-history").value,'+
    'timestamp:new Date().toISOString()};'+
    'var code="HOS-"+Math.random().toString(36).substr(2,6).toUpperCase();'+
    'localStorage.setItem("hos_pending_reg_"+code,JSON.stringify(data));'+
    'document.getElementById("form-wrap").style.display="none";'+
    'document.getElementById("success-msg").style.display="block";'+
    'document.getElementById("ref-code").textContent=code;'+
    '}<\/script></body></html>';

  // Show QR modal with instructions
  var encoded = 'data:text/html;base64,' + btoa(unescape(encodeURIComponent(formHTML)));

  var modal = document.getElementById('qr-modal');
  if(!modal){
    modal = document.createElement('div');
    modal.id = 'qr-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:9990;display:flex;align-items:center;justify-content:center;padding:20px';
    document.body.appendChild(modal);
  }
  modal.style.display='flex';
  modal.innerHTML = '<div style="background:#fff;border-radius:16px;padding:24px;max-width:500px;width:100%;text-align:center">'+
    '<div style="font-size:16px;font-weight:800;color:#1e293b;margin-bottom:6px">📱 Patient Self-Registration</div>'+
    '<div style="font-size:12px;color:#64748b;margin-bottom:16px">Patient fills their own details on their phone</div>'+
    '<div id="qr-canvas-wrap" style="margin:0 auto 16px;width:200px;height:200px;background:#f8fafc;border:2px solid #e2e8f0;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:11px;color:#94a3b8">'+
    'QR Code appears here<br><br><a href="'+encoded+'" target="_blank" style="color:#3b82f6;font-weight:700">📋 Open Form</a></div>'+
    '<div style="background:#eff6ff;border-radius:8px;padding:12px;font-size:12px;color:#1d4ed8;margin-bottom:14px">'+
    '💡 <strong>How to use:</strong> Click "Open Form" → Patient fills details on their phone → Show the code at reception</div>'+
    '<div style="display:flex;gap:8px;justify-content:center">'+
    '<button onclick="qr_importPending()" class="btn btn-primary btn-sm">📥 Import Pending Registrations</button>'+
    '<button onclick="document.getElementById(\'qr-modal\').style.display=\'none\'" class="btn btn-sm" style="background:#f1f5f9;color:#475569;border:1px solid #e2e8f0">Close</button>'+
    '</div></div>';
}

function qr_importPending(){
  var imported = 0;
  for(var i=0; i<localStorage.length; i++){
    var key = localStorage.key(i);
    if(!key.startsWith('hos_pending_reg_')) continue;
    try{
      var data = JSON.parse(localStorage.getItem(key));
      // Check for duplicate phone
      var exists = (DATA.patients||[]).some(function(p){return p.phone===data.phone;});
      if(!exists && data.name && data.phone){
        var newPt = {
          id: 'pt'+Date.now()+imported,
          name: data.name, phone: data.phone,
          age: data.age||'', gender: data.gender||'',
          complaint: data.complaint||'',
          medHistory: data.history||'',
          type: 'regular', createdAt: data.timestamp||todayISO(),
          billing:[], records:[], images:[], prescriptions:[],
          treatmentPlan:[], xrayReports:[], signedConsents:[]
        };
        if(!DATA.patients) DATA.patients=[];
        DATA.patients.push(newPt);
        imported++;
        localStorage.removeItem(key); i--;
      }
    } catch(e){}
  }
  if(imported>0){ saveData(); alert('✅ Imported '+imported+' new patient'+(imported!==1?'s':'')+' from self-registration!'); }
  else alert('No pending registrations found.');
}

