    '<div style="display:flex;gap:8px;margin-top:16px;flex-wrap:wrap">'+
    '<button onclick="patientEdu_print(\''+procedure+'\')" style="background:#1e3a5f;color:#fff;border:none;border-radius:10px;padding:10px 18px;font-size:13px;font-weight:700;cursor:pointer">🖨️ Print for Patient</button>'+
    (activePt&&activePt.phone?'<button onclick="patientEdu_sendWA(\''+procedure+'\')" style="background:#25d366;color:#fff;border:none;border-radius:10px;padding:10px 18px;font-size:13px;font-weight:700;cursor:pointer">📲 Send via WhatsApp</button>':'')+
    '</div></div>';
