function patientEdu_print(procedure){
  var edu=PATIENT_EDU[procedure]; if(!edu)return;
  var pw=window.open('','_blank','width=800,height=700');
  if(!pw)return;
  var stepsHTML=edu.steps.map(function(s,i){return '<div style="display:flex;gap:10px;margin-bottom:8px"><div style="background:'+edu.border+';color:#fff;border-radius:50%;width:20px;height:20px;min-width:20px;display:flex;align-items:center;justify-content:center;font-size:10pt;font-weight:800">'+(i+1)+'</div><div style="font-size:10pt">'+s+'</div></div>';}).join('');
  var faqHTML=edu.faq.map(function(qa){return '<div style="margin-bottom:8px;padding:8px 10px;background:'+edu.color+';border-radius:6px;border-left:3px solid '+edu.border+'"><strong style="font-size:9pt">Q: '+qa[0]+'</strong><div style="font-size:9pt;margin-top:3px">A: '+qa[1]+'</div></div>';}).join('');
  pw.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>'+edu.title+'</title>'+
    '<style>@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;color:#1e293b;margin:0;padding:12px}'+
    '.hdr{background:#1e3a5f;color:#fff;padding:14px 18px;border-radius:10px;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center}'+
    '@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body>'+
    '<div class="hdr"><div><strong style="font-size:18pt">'+edu.icon+' '+edu.title+'</strong></div>'+
    '<div style="text-align:right;font-size:10pt"><div>'+CLINIC+'</div><div>'+DOCTOR+' | '+PHONE+'</div></div></div>'+
    '<div style="font-size:11pt;font-weight:800;color:#1e3a5f;margin-bottom:8px">How it works:</div>'+stepsHTML+
    '<div style="font-size:11pt;font-weight:800;color:#1e3a5f;margin:14px 0 8px">Common Questions:</div>'+faqHTML+
    '<div style="margin-top:16px;text-align:center;font-size:9pt;color:#94a3b8">'+TIMING+' | '+PHONE+' | '+CITY+'</div>'+
    '</body></html>');
  pw.document.close(); pw.onload=function(){pw.focus();pw.print();};
}

function patientEdu_sendWA(procedure){
  if(!activePt||!activePt.phone)return;
  var edu=PATIENT_EDU[procedure]; if(!edu)return;
  var nl=String.fromCharCode(10);
  var msg='Dear '+activePt.name+','+nl+nl+
    edu.icon+' *'+edu.title+' — What to Expect*'+nl+
    '─────────────────'+nl+nl;
  edu.steps.forEach(function(s,i){ msg+=(i+1)+'. '+s+nl; });
  msg+=nl+'*Common Questions:*'+nl;
  edu.faq.forEach(function(qa){ msg+=nl+'Q: '+qa[0]+nl+'A: '+qa[1]+nl; });
  msg+=nl+'Questions? Call: '+PHONE+nl+TIMING;
  window.open('https://wa.me/91'+activePt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}



function renderEduGrid(){
  var el = document.getElementById('edu-grid');
  if(!el) return;
  var procedures = Object.keys(PATIENT_EDU);
  el.innerHTML = procedures.map(function(key){
    var edu = PATIENT_EDU[key];
    return '<div class="edu-card" data-proc="'+key+'" style="background:#fff;border:2px solid '+edu.border+';border-radius:14px;padding:18px;cursor:pointer;text-align:center">'+
      '<div style="font-size:36px;margin-bottom:8px">'+edu.icon+'</div>'+
      '<div style="font-size:13px;font-weight:800;color:#1e293b">'+edu.title+'</div>'+
      '<div style="font-size:10px;color:#94a3b8;margin-top:4px">Tap to view / share</div>'+
      '</div>';
  }).join('');
  // Use event delegation — works perfectly on mobile
  el.onclick = function(e){
    var card = e.target.closest('.edu-card');
    if(card && card.dataset.proc) patientEdu_open(card.dataset.proc);
  };
}

/* ══════════════════════════════════════════════════
   WAITING ROOM KIOSK — OFFLINE SELF-REGISTRATION
   Runs on clinic's own tablet. No internet needed.
   Patient fills form → stored in localStorage →
   Receptionist imports with one click.
══════════════════════════════════════════════════ */

