/* Inject SVG animation into patientEdu_open */




function patientEdu_open(procedure) {
  patientEdu_openBase(procedure);
  // Inject SVG animation after modal opens
  var svg = PATIENT_EDU_SVG[procedure];
  if (!svg) return;
  setTimeout(function() {
    var modal = document.getElementById('edu-modal');
    if (!modal) return;
    var inner = modal.querySelector('div');
    if (!inner) return;
    if (inner.querySelector('.edu-anim-wrap')) return; // already injected
    var animDiv = document.createElement('div');
    animDiv.className = 'edu-anim-wrap';
    animDiv.style.cssText = 'margin-bottom:14px;border-radius:10px;overflow:hidden;background:#f8fafc;border:1.5px solid #e2e8f0';
    animDiv.innerHTML = svg;
    // Insert after the header (first child div)
    var firstChild = inner.firstElementChild;
    if (firstChild && firstChild.nextSibling) {
      inner.insertBefore(animDiv, firstChild.nextSibling);
    } else {
      inner.appendChild(animDiv);
    }
  }, 60);
}


