/* ─────────────────────────────────────────────────────────────────
   FEATURE 13: MEDICAL HISTORY ALERT FLAGS
   Scans patient medHistory for critical keywords.
   Shows a red blocking banner when opening a patient.
───────────────────────────────────────────────────────────────── */
var MED_ALERT_KEYWORDS = {
  'Diabetes / Diabetic':        ['diabet','diabetic','sugar'],
  'Hypertension / BP':          ['hypertens','bp patient','blood pressure','amlodipine','telmisartan','metoprolol','atenolol'],
  'Blood Thinner / Anticoagulant': ['warfarin','clopidogrel','aspirin','ecosprin','acitrom','blood thin','anticoagul'],
  'Penicillin Allergy':         ['penicillin','amoxicillin allergy','pcn allerg'],
  'Latex Allergy':              ['latex allerg'],
  'Heart Disease / Cardiac':    ['cardiac','heart disease','angina','bypass','stent','valve','pacemaker','heart attack','mi '],
  'Asthma / Respiratory':       ['asthma','copd','bronchitis','inhaler','salbutamol'],
  'Bleeding Disorder':          ['bleed','haemophilia','hemophilia','platelet'],
  'Pregnancy':                  ['pregnant','pregnanc','trimester'],
  'Thyroid Disorder':           ['thyroid','hypothyroid','hyperthyroid','thyroxine'],
  'Seizure / Epilepsy':         ['seizure','epilep','phenytoin','valproate','carbamazepine'],
  'Bisphosphonates (MRONJ risk)': ['bisphosphon','zoledronic','alendronate','risedronate'],
};

function med_checkAlerts(pt) {
  if (!pt || !pt.medHistory) return [];
  var text = (pt.medHistory + ' ' + (pt.complaint||'')).toLowerCase();
  var alerts = [];
  for (var condition in MED_ALERT_KEYWORDS) {
    var keywords = MED_ALERT_KEYWORDS[condition];
    if (keywords.some(function(kw){ return text.includes(kw); })) {
      alerts.push(condition);
    }
  }
  return alerts;
}

function med_showAlertBanner(pt) {
  var existing = document.getElementById('med-alert-banner');
  if (existing) existing.remove();
  var alerts = med_checkAlerts(pt);
  if (!alerts.length) return;

  var banner = document.createElement('div');
  banner.id = 'med-alert-banner';
  banner.style.cssText = 'background:#7f1d1d;color:#fef2f2;padding:10px 18px;display:flex;align-items:flex-start;gap:12px;justify-content:space-between;flex-wrap:wrap;border-bottom:3px solid #ef4444;position:sticky;top:0;z-index:100';

  var alertList = alerts.map(function(a){
    return '<span style="background:rgba(239,68,68,.3);border:1px solid #f87171;border-radius:6px;padding:2px 8px;font-size:11px;font-weight:700;white-space:nowrap">⚠ '+a+'</span>';
  }).join(' ');

  banner.innerHTML = '<div style="flex:1"><div style="font-size:12px;font-weight:800;margin-bottom:5px">🚨 MEDICAL ALERT — '+esc(pt.name)+'</div>'+
    '<div style="display:flex;flex-wrap:wrap;gap:5px">'+alertList+'</div>'+
    '<div style="font-size:10px;margin-top:5px;opacity:.8">'+esc(pt.medHistory||'')+'</div></div>'+
    '<button onclick="document.getElementById(\'med-alert-banner\').style.display=\'none\'" style="background:rgba(255,255,255,.15);border:none;color:#fef2f2;padding:4px 10px;border-radius:6px;cursor:pointer;font-size:12px;flex-shrink:0">✕</button>';

  var detailPage = document.getElementById('page-patient-detail');
  if (detailPage) detailPage.insertBefore(banner, detailPage.firstChild);
}

// Patch openPatient to show medical alert
function openPatient(id) {
  openPatient_orig(id);
  setTimeout(function(){
    if (activePt) med_showAlertBanner(activePt);
    if (typeof grp_initForPatient === 'function') grp_initForPatient();
    setTimeout(dues_checkBanner, 200);
  }, 120);
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 1: NO-SHOW TRACKER
   Marks appointments as no-show. Counts per patient.
   Badge on patient card. Filter in appointments page.
───────────────────────────────────────────────────────────────── */
function appt_markNoShow(apptId) {
  var idx = (DATA.appointments||[]).findIndex(function(a){ return a.id === apptId; });
  if (idx < 0) return;
  DATA.appointments[idx].status = 'noshow';
  DATA.appointments[idx].noShowAt = todayISO();
  // Increment patient noShow count
  var pt = (DATA.patients||[]).find(function(p){ return p.id === DATA.appointments[idx].patientId; });
  if (pt) {
    var ptIdx = DATA.patients.findIndex(function(p){ return p.id === pt.id; });
    DATA.patients[ptIdx].noShowCount = (DATA.patients[ptIdx].noShowCount||0) + 1;
  }
  saveData(); renderAppointments();
}

function appt_markComplete(apptId) {
  var idx = (DATA.appointments||[]).findIndex(function(a){ return a.id === apptId; });
  if (idx < 0) return;
  DATA.appointments[idx].status = 'done';
  DATA.appointments[idx].completedAt = todayISO();
  saveData(); renderAppointments();
  // Offer to open patient record
  var appt = DATA.appointments[idx];
  if (appt.patientId) {
    var pt = (DATA.patients||[]).find(function(p){ return p.id===appt.patientId; });
    if (pt && confirm('\u2705 Appointment marked done for '+pt.name+'\n\nAdd clinical record for this visit?')) {
      openPatient(appt.patientId);
      setTimeout(function(){
        switchTab('records');
        setTimeout(function(){ cs_showForm(); }, 100);
      }, 200);
    }
  }
}

function appt_getNoShowPatients() {
  return (DATA.patients||[])
    .filter(function(p){ return (p.noShowCount||0) >= 2; })
    .sort(function(a,b){ return (b.noShowCount||0)-(a.noShowCount||0); });
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 2: TREATMENT PACKAGE BUILDER
   Create named bundles of procedures at package price.
   Apply to patient billing in one tap.
───────────────────────────────────────────────────────────────── */
function pkg_render() {
  var el = document.getElementById('pkg-content');
  if (!el) return;
  var pkgs = DATA.packages || [];
  var h = '';

  // Add form
  h += '<div class="card" style="margin-bottom:16px">';
  h += '<div style="font-size:13px;font-weight:800;margin-bottom:14px">📦 Create New Package</div>';
  h += '<div class="form-grid-2">';
  h += '<div class="form-group"><label class="form-label">Package Name *</label><input class="form-input" id="pkg-name" placeholder="e.g. Smile Makeover Package"/></div>';
  h += '<div class="form-group"><label class="form-label">Package Price (₹) *</label><input class="form-input" id="pkg-price" type="number" min="0" placeholder="e.g. 12000"/></div>';
  h += '</div>';
  h += '<div class="form-group"><label class="form-label">Procedures Included (one per line)</label>';
  h += '<textarea class="form-input" id="pkg-items" rows="4" placeholder="Scaling & Polishing — ₹800&#10;Bleaching — ₹3000&#10;2 Composite Fillings — ₹2400&#10;(etc.)"></textarea></div>';
  h += '<div class="form-group"><label class="form-label">Description / Offer Text</label>';
  h += '<input class="form-input" id="pkg-desc" placeholder="e.g. Complete smile transformation — Save ₹1200!"/></div>';
  h += '<button class="btn btn-primary" onclick="pkg_save()">💾 Save Package</button>';
  h += '</div>';

  if (!pkgs.length) {
    h += '<div class="empty"><span class="empty-icon">📦</span><div class="empty-title">No packages yet</div><div class="empty-sub">Create your first treatment bundle above</div></div>';
  } else {
    pkgs.forEach(function(pkg) {
      var items = (pkg.items||'').split('\n').filter(Boolean);
      h += '<div class="card" style="margin-bottom:12px">';
      h += '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap">';
      h += '<div style="flex:1"><div style="font-size:14px;font-weight:800;color:#1e293b">'+esc(pkg.name)+'</div>';
      if (pkg.desc) h += '<div style="font-size:12px;color:#059669;font-weight:600;margin-top:2px">'+esc(pkg.desc)+'</div>';
      h += '<div style="margin-top:8px;display:flex;flex-direction:column;gap:3px">';
      items.forEach(function(item){ h += '<div style="font-size:12px;color:#374151">✓ '+esc(item)+'</div>'; });
      h += '</div></div>';
      h += '<div style="text-align:right;flex-shrink:0">';
      h += '<div style="font-size:22px;font-weight:800;color:#059669">₹'+Number(pkg.price).toLocaleString('en-IN')+'</div>';
      h += '<div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;justify-content:flex-end">';
      if (activePt) h += '<button class="btn btn-primary btn-sm" data-pkgid="'+pkg.id+'" onclick="pkg_applyToPatient(this.dataset.pkgid)">➕ Apply to Patient</button>';
      h += '<button class="btn btn-sm" style="background:#25d366;color:#fff;border:none" data-pkgid="'+pkg.id+'" onclick="pkg_sendWA(this.dataset.pkgid)">📲 WhatsApp</button>';
      h += '<button class="btn btn-red btn-sm" data-pkgid="'+pkg.id+'" onclick="pkg_delete(this.dataset.pkgid)">🗑</button>';
      h += '</div></div></div></div>';
    });
  }
  el.innerHTML = h;
}

function pkg_save() {
  var name  = ((document.getElementById('pkg-name')||{}).value||'').trim();
  var price = Number((document.getElementById('pkg-price')||{}).value||0);
  var items = ((document.getElementById('pkg-items')||{}).value||'').trim();
  var desc  = ((document.getElementById('pkg-desc')||{}).value||'').trim();
  if (!name || !price) { alert('Package name and price are required.'); return; }
  if (!DATA.packages) DATA.packages = [];
  DATA.packages.push({ id:'pkg'+Date.now(), name:name, price:price, items:items, desc:desc, createdAt:todayISO() });
  saveData(); pkg_render();
  document.getElementById('pkg-name').value='';
  document.getElementById('pkg-price').value='';
  document.getElementById('pkg-items').value='';
  document.getElementById('pkg-desc').value='';
}

function pkg_delete(id) {
  if (!confirm('Delete this package?')) return;
  DATA.packages = (DATA.packages||[]).filter(function(p){ return p.id!==id; });
  saveData(); pkg_render();
}

function pkg_applyToPatient(pkgId) {
  if (!activePt) { alert('Open a patient first, then apply the package.'); return; }
  var pkg = (DATA.packages||[]).find(function(p){ return p.id===pkgId; });
  if (!pkg) return;
  if (!confirm('Add package "'+pkg.name+'" (₹'+Number(pkg.price).toLocaleString('en-IN')+') to '+activePt.name+'\'s billing?')) return;
  if (!activePt.billing) activePt.billing = [];
  activePt.billing.push({
    id: 'b'+Date.now(), item: pkg.name,
    amount: Number(pkg.price), paid: false,
    date: todayISO(), note: 'Treatment package: '+(pkg.items||'').replace(/\n/g,', ').slice(0,100)
  });
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  if (ptIdx >= 0) DATA.patients[ptIdx] = activePt;
  saveData(); alert('✅ Package added to '+activePt.name+'\'s billing!');
}

function pkg_sendWA(pkgId) {
  if (!activePt || !activePt.phone) { alert('Open a patient with a phone number first.'); return; }
  var pkg = (DATA.packages||[]).find(function(p){ return p.id===pkgId; });
  if (!pkg) return;
  var nl = String.fromCharCode(10);
  var items = (pkg.items||'').split('\n').filter(Boolean).map(function(i,n){ return (n+1)+'. '+i; }).join(nl);
  var msg = 'Dear '+activePt.name+','+nl+nl+
    '🎁 Special Package Offer from *'+CLINIC+'*'+nl+nl+
    '*'+pkg.name+'*'+nl+
    (pkg.desc ? pkg.desc+nl+nl : nl)+
    'What\'s included:'+nl+items+nl+nl+
    '💰 Package Price: *₹'+Number(pkg.price).toLocaleString('en-IN')+'*'+nl+nl+
    'Book today: '+PHONE+nl+TIMING;
  window.open('https://wa.me/91'+activePt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

function pkg_renderPage() { pkg_render(); }


/* ─────────────────────────────────────────────────────────────────
   FEATURE 4: REVENUE FORECASTING
   Projects next 30 days based on scheduled appointments
   + planned (unstarted) treatment values.
───────────────────────────────────────────────────────────────── */
function forecast_calculate() {
  var today = todayISO();
  var pts   = DATA.patients || [];
  var d30   = new Date(today); d30.setDate(d30.getDate()+30);
  var d30str = d30.toISOString().slice(0,10);

  // Scheduled appointments in next 30 days
  var upcomingAppts = (DATA.appointments||[]).filter(function(a){
    return a.date > today && a.date <= d30str && a.status !== 'noshow' && a.status !== 'cancelled';
  });

  // Average revenue per patient visit (from last 90 days)
  var d90 = new Date(today); d90.setDate(d90.getDate()-90);
  var d90str = d90.toISOString().slice(0,10);
  var last90bills = pts.flatMap(function(p){ return p.billing||[]; })
    .filter(function(b){ return b.paid && (b.date||'') >= d90str; });
  var avgPerVisit = last90bills.length > 0
    ? Math.round(last90bills.reduce(function(s,b){ return s+Number(b.amount||0); },0) / last90bills.length)
    : 1200; // default fallback

  var apptForecast = upcomingAppts.length * avgPerVisit;

  // Planned treatments (pipeline)
  var pipeline = pts.flatMap(function(p){ return p.treatmentPlan||[]; })
    .filter(function(i){ return i.status === 'planned'; })
    .reduce(function(s,i){ return s+Number(i.estimatedCost||0); }, 0);

  // Recall patients due in 30 days (potential revenue)
  var recallDue30 = pts.filter(function(p){
    var last = recall_getLastVisit ? recall_getLastVisit(p) : null;
    var due  = last && recall_getDueDate ? recall_getDueDate(last) : null;
    return due && due <= d30str && due > today;
  }).length;

  // Packages available (show as opportunity)
  var pkgOpportunity = (DATA.packages||[]).reduce(function(s,p){ return s+Number(p.price||0); },0);

  return {
    apptCount:    upcomingAppts.length,
    avgPerVisit:  avgPerVisit,
    apptForecast: apptForecast,
    pipeline:     pipeline,
    total:        apptForecast + Math.round(pipeline * 0.35), // 35% conversion estimate
    recallDue30:  recallDue30,
    pkgOpportunity: pkgOpportunity,
  };
}

function forecast_renderWidget() {
  var el = document.getElementById('forecast-widget');
  if (!el) return;
  var f = forecast_calculate();

  el.innerHTML = '<div style="background:linear-gradient(135deg,#1e3a5f,#0369a1);border-radius:14px;padding:16px;color:#fff;margin-bottom:16px">' +
    '<div style="font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:1px;opacity:.8;margin-bottom:10px">📈 30-Day Revenue Forecast</div>' +
    '<div style="font-size:32px;font-weight:800;margin-bottom:4px">'+fmtMoney(f.total)+'</div>' +
    '<div style="font-size:11px;opacity:.7;margin-bottom:14px">Estimated collectible in next 30 days</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">' +
    '<div style="background:rgba(255,255,255,.12);border-radius:8px;padding:10px">' +
    '<div style="font-size:10px;opacity:.8;font-weight:700">SCHEDULED APTS × AVG</div>' +
    '<div style="font-size:16px;font-weight:800;margin-top:2px">'+f.apptCount+' × '+fmtMoney(f.avgPerVisit)+'</div>' +
    '<div style="font-size:11px;opacity:.7">=&nbsp;'+fmtMoney(f.apptForecast)+'</div>' +
    '</div>' +
    '<div style="background:rgba(255,255,255,.12);border-radius:8px;padding:10px">' +
    '<div style="font-size:10px;opacity:.8;font-weight:700">TX PIPELINE (35% conv.)</div>' +
    '<div style="font-size:16px;font-weight:800;margin-top:2px">'+fmtMoney(f.pipeline)+'</div>' +
    '<div style="font-size:11px;opacity:.7">'+Math.round(f.pipeline*0.35/1000)+'K expected</div>' +
    '</div>' +
    '</div>' +
    (f.recallDue30 > 0 ? '<div style="background:rgba(251,191,36,.2);border-radius:8px;padding:8px 10px;margin-top:10px;font-size:11px;font-weight:700;color:#fef3c7">🔔 '+f.recallDue30+' recall patients due this month — if they come: +'+fmtMoney(f.recallDue30*f.avgPerVisit)+'</div>' : '') +
    '</div>';
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 11: PERIODONTAL CHARTING
   6-point probing per tooth, BOP, mobility, recession, furcation.
   Stored in p.perioChart = {toothNo: {probing:[],bop:[],mobility,recession,furcation}}
───────────────────────────────────────────────────────────────── */
var PERIO_TEETH = [
  // Upper right → left: 18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28
  18,17,16,15,14,13,12,11, 21,22,23,24,25,26,27,28,
  // Lower left → right: 38,37,36,35,34,33,32,31,41,42,43,44,45,46,47,48
  48,47,46,45,44,43,42,41, 31,32,33,34,35,36,37,38
];

function perio_render() {
  var el = document.getElementById('perio-chart-content');
  if (!el || !activePt) return;
  var pc = activePt.perioChart || {};

  var h = '';
  h += '<div style="margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">';
  h += '<div><div style="font-size:13px;font-weight:800;color:#1e293b">Periodontal Charting — '+esc(activePt.name)+'</div>';
  h += '<div style="font-size:11px;color:#64748b;margin-top:2px">6 probing points per tooth (facial: MB-B-DB | lingual: ML-L-DL)</div></div>';
  h += '<div style="display:flex;gap:8px;flex-wrap:wrap">';
  h += '<button class="btn btn-primary btn-sm" onclick="perio_save()">💾 Save Chart</button>';
  h += '<button class="btn btn-sm" style="background:#059669;color:#fff;border:none" onclick="perio_printChart()">🖨️ Print</button>';
  h += '</div></div>';

  // Colour scale legend
  h += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;font-size:10px;font-weight:700">';
  h += '<span style="color:#059669">■ 1-3mm Healthy</span>';
  h += '<span style="color:#d97706">■ 4mm Warning</span>';
  h += '<span style="color:#dc2626">■ 5-6mm Moderate</span>';
  h += '<span style="color:#7f1d1d">■ 7mm+ Severe</span>';
  h += '</div>';

  // Helper: depth color
  function depthColor(d) {
    var n = parseInt(d)||0;
    if (n >= 7) return '#7f1d1d';
    if (n >= 5) return '#dc2626';
    if (n >= 4) return '#d97706';
    return '#059669';
  }

  function renderArch(teeth, label) {
    var archH = '<div style="margin-bottom:16px">';
    archH += '<div style="font-size:11px;font-weight:800;color:#1e3a5f;margin-bottom:8px;text-transform:uppercase;letter-spacing:.5px">'+label+'</div>';
    archH += '<div style="overflow-x:auto"><table style="border-collapse:collapse;min-width:600px;width:100%">';
    
    // Tooth numbers row
    archH += '<tr>';
    teeth.forEach(function(t){
      archH += '<td style="text-align:center;font-size:10px;font-weight:800;color:#1e3a5f;padding:2px 3px;border:1px solid #e2e8f0">#'+t+'</td>';
    });
    archH += '</tr>';

    // Facial probing (MB, B, DB)
    ['MB','B','DB'].forEach(function(pt_label, pt_idx) {
      archH += '<tr>';
      teeth.forEach(function(t){
        var toothData = pc[t] || {};
        var probing = toothData.probing || ['','','','','',''];
        var val = probing[pt_idx] || '';
        var color = val ? depthColor(val) : '#94a3b8';
        archH += '<td style="text-align:center;padding:1px;border:1px solid #f1f5f9">';
        archH += '<input type="number" min="0" max="15" value="'+val+'" '+
          'data-tooth="'+t+'" data-idx="'+pt_idx+'" '+
          'style="width:28px;height:22px;text-align:center;border:none;border-radius:3px;font-size:11px;font-weight:700;background:'+
          (val?depthColor(val)+'22':'#f8fafc')+';color:'+color+';outline:none" '+
          'oninput="perio_updateCell(this,'+t+','+pt_idx+')"'+
          '/>';
        archH += '</td>';
      });
      archH += '</tr>';
    });

    // BOP row
    archH += '<tr style="background:#fef2f2">';
    teeth.forEach(function(t){
      var toothData = pc[t] || {};
      var bop = toothData.bop || [false,false,false,false,false,false];
      var facialBOP = bop[0]||bop[1]||bop[2];
      archH += '<td style="text-align:center;padding:2px;border:1px solid #f1f5f9">';
      archH += '<input type="checkbox" title="BOP Facial" '+(facialBOP?'checked':'')+' '+
        'data-tooth="'+t+'" data-bopidx="0" onchange="perio_updateBOP(this,'+t+',0)" style="cursor:pointer"/>';
      archH += '</td>';
    });
    archH += '</tr>';

    // Lingual probing (ML, L, DL)
    ['ML','L','DL'].forEach(function(pt_label, pt_idx) {
      var real_idx = pt_idx + 3;
      archH += '<tr>';
      teeth.forEach(function(t){
        var toothData = pc[t] || {};
        var probing = toothData.probing || ['','','','','',''];
        var val = probing[real_idx] || '';
        var color = val ? depthColor(val) : '#94a3b8';
        archH += '<td style="text-align:center;padding:1px;border:1px solid #f1f5f9">';
        archH += '<input type="number" min="0" max="15" value="'+val+'" '+
          'data-tooth="'+t+'" data-idx="'+real_idx+'" '+
          'style="width:28px;height:22px;text-align:center;border:none;border-radius:3px;font-size:11px;font-weight:700;background:'+
          (val?depthColor(val)+'22':'#f8fafc')+';color:'+color+';outline:none" '+
          'oninput="perio_updateCell(this,'+t+','+real_idx+')"'+
          '/>';
        archH += '</td>';
      });
      archH += '</tr>';
    });

    // Mobility row
    archH += '<tr style="background:#eff6ff">';
    teeth.forEach(function(t){
      var toothData = pc[t] || {};
      archH += '<td style="text-align:center;padding:1px;border:1px solid #f1f5f9">';
      archH += '<select data-tooth="'+t+'" onchange="perio_updateMobility(this,'+t+')" '+
        'style="width:32px;height:22px;font-size:10px;border:none;background:transparent;cursor:pointer">';
      [0,1,2,3].forEach(function(m){
        archH += '<option '+(toothData.mobility===m?'selected':'')+'>'+m+'</option>';
      });
      archH += '</select></td>';
    });
    archH += '</tr>';

    // Labels
    archH += '<tr style="background:#f8fafc">';
    teeth.forEach(function(){
      archH += '<td style="text-align:center;font-size:8px;color:#94a3b8;padding:2px;border:1px solid #f1f5f9">mob</td>';
    });
    archH += '</tr>';

    archH += '</table></div></div>';
    return archH;
  }

  h += renderArch([18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28], '↑ Upper Arch (Facial MB-B-DB | Lingual ML-L-DL | BOP | Mobility)');
  h += renderArch([48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38], '↓ Lower Arch (Facial MB-B-DB | Lingual ML-L-DL | BOP | Mobility)');

  // Summary stats
  var allProbing = [];
  Object.values(pc).forEach(function(td){ (td.probing||[]).forEach(function(v){ if(v) allProbing.push(parseInt(v)); }); });
  if (allProbing.length > 0) {
    var maxP = Math.max.apply(null, allProbing);
    var avgP = (allProbing.reduce(function(s,v){return s+v;},0)/allProbing.length).toFixed(1);
    var pockets4plus = allProbing.filter(function(v){return v>=4;}).length;
    h += '<div class="card" style="background:#f0fdf4;margin-top:12px">';
    h += '<div style="font-size:12px;font-weight:800;color:#065f46;margin-bottom:8px">📊 Perio Summary</div>';
    h += '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">';
    h += '<div><div style="font-size:9px;color:#64748b;font-weight:700">MAX DEPTH</div><div style="font-size:18px;font-weight:800;color:'+(maxP>=5?'#dc2626':'#059669')+'">'+maxP+'mm</div></div>';
    h += '<div><div style="font-size:9px;color:#64748b;font-weight:700">AVG DEPTH</div><div style="font-size:18px;font-weight:800;color:#1e293b">'+avgP+'mm</div></div>';
    h += '<div><div style="font-size:9px;color:#64748b;font-weight:700">POCKETS ≥4mm</div><div style="font-size:18px;font-weight:800;color:'+(pockets4plus>0?'#d97706':'#059669')+'">'+pockets4plus+'</div></div>';
    h += '</div></div>';
  }

  el.innerHTML = h;
}

function perio_updateCell(input, toothNum, probingIdx) {
  if (!activePt) return;
  if (!activePt.perioChart) activePt.perioChart = {};
  if (!activePt.perioChart[toothNum]) activePt.perioChart[toothNum] = {probing:['','','','','',''],bop:[],mobility:0};
  activePt.perioChart[toothNum].probing[probingIdx] = input.value;
  // Update color live
  var v = parseInt(input.value)||0;
  var colors = {7:'#7f1d1d',5:'#dc2626',4:'#d97706'};
  var color = v >= 7 ? '#7f1d1d' : v >= 5 ? '#dc2626' : v >= 4 ? '#d97706' : '#059669';
  input.style.background = input.value ? color+'22' : '#f8fafc';
  input.style.color = input.value ? color : '#94a3b8';
}

function perio_updateBOP(input, toothNum, bopIdx) {
  if (!activePt) return;
  if (!activePt.perioChart) activePt.perioChart = {};
  if (!activePt.perioChart[toothNum]) activePt.perioChart[toothNum] = {probing:['','','','','',''],bop:[],mobility:0};
  activePt.perioChart[toothNum].bop[bopIdx] = input.checked;
}

function perio_updateMobility(select, toothNum) {
  if (!activePt) return;
  if (!activePt.perioChart) activePt.perioChart = {};
  if (!activePt.perioChart[toothNum]) activePt.perioChart[toothNum] = {probing:['','','','','',''],bop:[],mobility:0};
  activePt.perioChart[toothNum].mobility = parseInt(select.value)||0;
}

function perio_save() {
  if (!activePt) return;
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id === activePt.id; });
  if (ptIdx >= 0) DATA.patients[ptIdx] = activePt;
  saveData(); showSavedToast();
}

function perio_printChart() {
  if (!activePt) return;
  alert('Perio chart saved. Use browser print (Ctrl+P) with the page visible to print the chart.');
  window.print();
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 14: CLINICAL PHOTOGRAPHY PROTOCOL (8-slot)
   Structured photo sets for systematic documentation.
   8 standard slots per session.
───────────────────────────────────────────────────────────────── */
var PHOTO_SLOTS = [
  { id:'frontal_smile',    label:'Frontal Smile',       type:'extra-oral', icon:'😊', desc:'Natural smile, lips apart' },
  { id:'retracted_frontal',label:'Retracted Frontal',   type:'intra-oral', icon:'🦷', desc:'Full retraction, teeth visible' },
  { id:'right_lateral',   label:'Right Lateral',        type:'intra-oral', icon:'➡', desc:'Right side, occlusion visible' },
  { id:'left_lateral',    label:'Left Lateral',         type:'intra-oral', icon:'⬅', desc:'Left side, occlusion visible' },
  { id:'upper_occlusal',  label:'Upper Occlusal',       type:'intra-oral', icon:'⬆', desc:'Mirror view of upper arch' },
  { id:'lower_occlusal',  label:'Lower Occlusal',       type:'intra-oral', icon:'⬇', desc:'Mirror view of lower arch' },
  { id:'right_buccal',    label:'Right Buccal',         type:'intra-oral', icon:'🔍', desc:'Right buccal segment, occlusion' },
  { id:'left_buccal',     label:'Left Buccal',          type:'intra-oral', icon:'🔎', desc:'Left buccal segment, occlusion' },
];

function photoProtocol_renderSession(sessionId) {
  var el = document.getElementById('photo-protocol-panel');
  if (!el || !activePt) return;

  var sessions = activePt.photoSessions || [];
  var session = sessions.find(function(s){ return s.id === sessionId; }) || null;

  if (!session) {
    // Create new session
    session = { id: 'ps'+Date.now(), date: todayISO(), label: '', photos: {} };
  }

  var h = '<div style="background:#1e3a5f;border-radius:12px;padding:14px 18px;color:#fff;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">';
  h += '<div><div style="font-size:14px;font-weight:800">📸 Clinical Photo Protocol</div>';
  h += '<div style="font-size:11px;opacity:.8;margin-top:2px">'+esc(activePt.name)+' &bull; '+fmtDate(session.date)+'</div></div>';
  h += '<div style="display:flex;gap:8px;flex-wrap:wrap">';
  h += '<input class="form-input" id="photo-session-label" placeholder="Session label (e.g. Pre-treatment)" value="'+esc(session.label||'')+'" style="font-size:12px;padding:6px 10px;background:rgba(255,255,255,.15);border-color:rgba(255,255,255,.3);color:#fff"/>';
  h += '<button class="btn btn-sm" style="background:#059669;color:#fff;border:none" onclick="photoProtocol_saveSession(\''+session.id+'\')">💾 Save Set</button>';
  h += '</div></div>';

  h += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:14px">';

  PHOTO_SLOTS.forEach(function(slot) {
    var photo = (session.photos||{})[slot.id] || null;
    h += '<div style="background:#fff;border:2px solid '+(photo?'#059669':'#e2e8f0')+';border-radius:12px;overflow:hidden">';
    if (photo) {
      h += '<div style="position:relative">';
      h += '<img src="'+photo+'" style="width:100%;height:110px;object-fit:cover;display:block"/>';
      h += '<button onclick="photoProtocol_removePhoto(\''+session.id+'\',\''+slot.id+'\')" style="position:absolute;top:4px;right:4px;background:rgba(220,38,38,.85);border:none;border-radius:50%;width:22px;height:22px;color:#fff;cursor:pointer;font-size:12px;display:flex;align-items:center;justify-content:center">✕</button>';
      h += '</div>';
    } else {
      h += '<label for="pp-'+slot.id+'" style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:110px;cursor:pointer;background:#f8fafc">';
      h += '<span style="font-size:24px">'+slot.icon+'</span>';
      h += '<span style="font-size:9px;color:#94a3b8;margin-top:4px;font-weight:700;text-transform:uppercase">Tap to capture</span>';
      h += '</label>';
      h += '<input type="file" id="pp-'+slot.id+'" accept="image/*" capture="environment" style="display:none" data-sessionid="'+session.id+'" data-slotid="'+slot.id+'" onchange="photoProtocol_capturePhoto(this)"/>';
    }
    h += '<div style="padding:8px 10px">';
    h += '<div style="font-size:11px;font-weight:800;color:#1e293b">'+slot.label+'</div>';
    h += '<div style="font-size:9px;color:#64748b;margin-top:1px">'+slot.type+' &bull; '+slot.desc+'</div>';
    h += (photo ? '<div style="font-size:9px;color:#059669;margin-top:3px;font-weight:700">✓ Captured</div>' : '');
    h += '</div></div>';
  });
  h += '</div>';

  // Previous sessions
  if (sessions.length > 0) {
    h += '<div style="font-size:12px;font-weight:800;color:#64748b;margin-bottom:8px;text-transform:uppercase;letter-spacing:.5px">Previous Sessions</div>';
    h += '<div style="display:flex;flex-direction:column;gap:6px">';
    sessions.slice().reverse().forEach(function(s){
      var count = Object.keys(s.photos||{}).length;
      h += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:10px 14px;display:flex;justify-content:space-between;align-items:center">';
      h += '<div><div style="font-size:12px;font-weight:700">'+fmtDate(s.date)+(s.label?' — '+esc(s.label):'')+'</div>';
      h += '<div style="font-size:10px;color:#64748b">'+count+'/'+PHOTO_SLOTS.length+' photos taken</div></div>';
      h += '<button class="btn btn-sm" data-sid="'+s.id+'" onclick="photoProtocol_renderSession(this.dataset.sid)">View</button>';
      h += '</div>';
    });
    h += '</div>';
  }

  h += '<button class="btn btn-primary btn-sm" style="margin-top:12px" onclick="photoProtocol_renderSession(\'new\')">+ New Photo Session</button>';

  // Store current session ref
  el._currentSession = session;
  el.innerHTML = h;
}

function photoProtocol_capturePhoto(input) {
  var sessionId = input.dataset.sessionid;
  var slotId    = input.dataset.slotid;
  var file = input.files && input.files[0];
  if (!file || !activePt) return;

  showLoading('Uploading photo to cloud...');

  var reader = new FileReader();
  reader.onload = function(e) {
    // Compress
    var img = new Image();
    img.onload = function() {
      var canvas = document.createElement('canvas');
      var max = 1200;
      var ratio = Math.min(max/img.width, max/img.height, 1);
      canvas.width  = Math.round(img.width * ratio);
      canvas.height = Math.round(img.height * ratio);
      canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
      var dataUrl = canvas.toDataURL('image/jpeg', 0.82);

      // Upload to Cloudinary
      uploadToCloudinary(dataUrl)
        .then(async function(secureUrl) {
          var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
          if (!DATA.patients[ptIdx].photoSessions) DATA.patients[ptIdx].photoSessions = [];
          var sessions = DATA.patients[ptIdx].photoSessions;
          var sIdx = sessions.findIndex(function(s){ return s.id===sessionId; });
          if (sIdx < 0) {
            // New session
            var labelEl = document.getElementById('photo-session-label');
            var newSess = { id:sessionId, date:todayISO(), label:labelEl?labelEl.value:'', photos:{} };
            newSess.photos[slotId] = secureUrl;
            sessions.push(newSess);
          } else {
            if (!sessions[sIdx].photos) sessions[sIdx].photos = {};
            sessions[sIdx].photos[slotId] = secureUrl;
          }
          activePt = DATA.patients[ptIdx];
          await saveData();
          photoProtocol_renderSession(sessionId);
        })
        .catch(function(err) {
          console.error('Session photo upload failed:', err);
          alert('Failed to upload photo: ' + err.message);
        })
        .finally(function() {
          hideLoading();
        });
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function photoProtocol_removePhoto(sessionId, slotId) {
  if (!activePt || !confirm('Remove this photo?')) return;
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  var sessions = DATA.patients[ptIdx].photoSessions||[];
  var sIdx = sessions.findIndex(function(s){ return s.id===sessionId; });
  if (sIdx >= 0 && sessions[sIdx].photos) {
    delete sessions[sIdx].photos[slotId];
    activePt = DATA.patients[ptIdx];
    saveData();
    photoProtocol_renderSession(sessionId);
  }
}

function photoProtocol_saveSession(sessionId) {
  if (!activePt) return;
  var label = (document.getElementById('photo-session-label')||{}).value||'';
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  var sessions = DATA.patients[ptIdx].photoSessions||[];
  var sIdx = sessions.findIndex(function(s){ return s.id===sessionId; });
  if (sIdx < 0) {
    // New session with no photos yet — create placeholder
    sessions.push({id:sessionId, date:todayISO(), label:label, photos:{}});
    DATA.patients[ptIdx].photoSessions = sessions;
  } else {
    sessions[sIdx].label = label;
  }
  activePt = DATA.patients[ptIdx];
  saveData(); showSavedToast();
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 16: CHAIR UTILIZATION
   Based on records (each record = one patient visit).
   Calculates productive hours per day.
───────────────────────────────────────────────────────────────── */
function chairUtil_calculate() {
  var pts = DATA.patients||[];
  var today = todayISO();

  // Records per day in last 30 days
  var d30 = new Date(today); d30.setDate(d30.getDate()-30);
  var d30str = d30.toISOString().slice(0,10);

  var byDay = {};
  pts.forEach(function(p){
    (p.records||[]).forEach(function(r){
      if ((r.date||'') >= d30str) {
        if (!byDay[r.date]) byDay[r.date] = 0;
        byDay[r.date]++;
      }
    });
  });

  var days = Object.keys(byDay);
  var avgPatientsPerDay = days.length > 0
    ? (days.reduce(function(s,d){ return s+byDay[d]; },0)/days.length).toFixed(1)
    : 0;
  var maxInDay = days.length > 0 ? Math.max.apply(null, days.map(function(d){ return byDay[d]; })) : 0;
  var avgTimePerPt = 35; // minutes (industry standard)
  var workdayMins  = 330; // 5.5 hrs (10am-1pm + 5pm-8pm = 6hrs minus breaks)
  var utilPct = avgPatientsPerDay > 0
    ? Math.min(100, Math.round((avgPatientsPerDay * avgTimePerPt / workdayMins) * 100))
    : 0;
  var peakDay = days.sort(function(a,b){ return byDay[b]-byDay[a]; })[0];
  var todayPts = byDay[today]||0;
  var potentialExtra = Math.floor((workdayMins - avgPatientsPerDay*avgTimePerPt) / avgTimePerPt);

  return {
    avgPatientsPerDay: avgPatientsPerDay,
    utilPct: utilPct,
    maxInDay: maxInDay,
    peakDay: peakDay,
    todayPts: todayPts,
    potentialSlots: Math.max(0, potentialExtra),
    activeDays: days.length,
  };
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 17: PROCEDURE PROFITABILITY
   Standard material costs per procedure for net margin.
───────────────────────────────────────────────────────────────── */
var PROC_COSTS = {
  'RCT':           { materials: 550, time: 90 },
  'Root Canal':    { materials: 550, time: 90 },
  'Crown':         { materials: 1200, time: 60 },
  'Implant':       { materials: 12000, time: 120 },
  'Scaling':       { materials: 50, time: 35 },
  'Polishing':     { materials: 30, time: 20 },
  'Extraction':    { materials: 80, time: 30 },
  'Composite':     { materials: 150, time: 45 },
  'Filling':       { materials: 150, time: 45 },
  'Bleaching':     { materials: 800, time: 60 },
  'Aligner':       { materials: 8000, time: 45 },
  'Braces':        { materials: 2500, time: 90 },
  'Consultation':  { materials: 0, time: 15 },
  'X-Ray':         { materials: 40, time: 10 },
  'GIC':           { materials: 80, time: 30 },
  'DPC':           { materials: 250, time: 45 },
  'IPC':           { materials: 200, time: 40 },
};

function procProfit_calculate() {
  var pts = DATA.patients||[];
  var stats = {};

  pts.forEach(function(p){
    (p.billing||[]).filter(function(b){ return b.paid; }).forEach(function(b){
      var key = null;
      var item = (b.item||'').toLowerCase();
      for (var proc in PROC_COSTS) {
        if (item.includes(proc.toLowerCase())) { key = proc; break; }
      }
      if (!key) key = 'Other';
      if (!stats[key]) stats[key] = { revenue:0, count:0, materials: PROC_COSTS[key]?PROC_COSTS[key].materials:0, time: PROC_COSTS[key]?PROC_COSTS[key].time:30 };
      stats[key].revenue += Number(b.amount||0);
      stats[key].count++;
    });
  });

  return Object.entries(stats).map(function(e){
    var key=e[0]; var s=e[1];
    var totalMat   = s.materials * s.count;
    var netProfit  = s.revenue - totalMat;
    var margin     = s.revenue > 0 ? Math.round((netProfit/s.revenue)*100) : 0;
    var revenuePerHour = s.time > 0 ? Math.round((s.revenue/s.count) / (s.time/60)) : 0;
    return { name:key, revenue:s.revenue, count:s.count, totalMat:totalMat, netProfit:netProfit, margin:margin, revenuePerHour:revenuePerHour };
  }).sort(function(a,b){ return b.netProfit-a.netProfit; });
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 19: DIAGNOSIS AUTO-SUGGEST (Claude AI API)
   Types diagnosis → API returns differential suggestions.
───────────────────────────────────────────────────────────────── */
var diagSuggestTimeout = null;
var diagSuggestCache = {};

async function diagSuggest_fetch(text) {
  if (!text || text.length < 3) return [];
  if (diagSuggestCache[text]) return diagSuggestCache[text];

  try {
    var response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 300,
        messages: [{
          role: 'user',
          content: 'I am a dentist. Patient presents with: "'+text+'". List 4-5 likely dental diagnoses as a JSON array of strings. Return ONLY the JSON array, no other text. Example: ["Diagnosis 1","Diagnosis 2"]'
        }]
      })
    });
    var data = await response.json();
    var raw = (data.content&&data.content[0]&&data.content[0].text)||'[]';
    var clean = raw.replace(/```json|```/g,'').trim();
    var parsed = JSON.parse(clean);
    diagSuggestCache[text] = parsed;
    return parsed;
  } catch(e) {
    return [];
  }
}

function diagSuggest_init(inputId, dropdownId) {
  var input = document.getElementById(inputId);
  var dropdown = document.getElementById(dropdownId);
  if (!input || !dropdown) return;

  input.addEventListener('input', function() {
    clearTimeout(diagSuggestTimeout);
    var val = input.value.trim();
    if (val.length < 3) { dropdown.style.display='none'; return; }

    diagSuggestTimeout = setTimeout(async function() {
      var suggestions = await diagSuggest_fetch(val);
      if (!suggestions.length) { dropdown.style.display='none'; return; }
      dropdown.innerHTML = suggestions.map(function(s){
        return '<div class="diag-suggest-item" onclick="diagSuggest_select(\''+inputId+'\',\''+dropdownId+'\',this.textContent)" style="padding:8px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid #f1f5f9;color:#1e293b">'+esc(s)+'</div>';
      }).join('');
      dropdown.style.display = 'block';
    }, 600);
  });

  document.addEventListener('click', function(e) {
    if (!dropdown.contains(e.target) && e.target !== input) {
      dropdown.style.display = 'none';
    }
  });
}

function diagSuggest_select(inputId, dropdownId, value) {
  var input = document.getElementById(inputId);
  if (input) input.value = value;
  var dropdown = document.getElementById(dropdownId);
  if (dropdown) dropdown.style.display = 'none';
}


