var kbd_shortcuts_enabled = true;

document.addEventListener('keydown', function(e) {
  // Disable when typing in input/textarea/select
  if (!kbd_shortcuts_enabled) return;
  var tag = document.activeElement && document.activeElement.tagName;
  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
  // Disable if modal open
  if (document.getElementById('edu-modal') && document.getElementById('edu-modal').style.display !== 'none') return;

  switch(e.key) {
    case 'n': case 'N':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); goPage('add-patient'); } break;
    case 'p': case 'P':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); goPage('patients'); } break;
    case 'a': case 'A':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); goPage('appointments'); } break;
    case 'd': case 'D':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); goPage('dashboard'); } break;
    case 'b': case 'B':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); goPage('billing'); } break;
    case 'e': case 'E':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); goPage('expenses'); } break;
    case 'r': case 'R':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); goPage('recall'); } break;
    case '/':
    case 's': case 'S':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); goPage('search'); setTimeout(function(){ var si=document.getElementById('gsearch-input'); if(si)si.focus(); },100); } break;
    case 'm': case 'M':
      if (!e.ctrlKey && !e.metaKey) { e.preventDefault(); morningHuddle_open(); } break;
    case 'Escape':
      // Close any open modal
      ['edu-modal','ba-modal','qr-modal','consent-sign-modal','huddle-modal'].forEach(function(id){
        var el = document.getElementById(id); if(el) el.style.display='none';
      });
      // Remove med alert banner
      var ban = document.getElementById('med-alert-banner'); if(ban) ban.remove();
      break;
  }
}, true);

// Show shortcut hint
