/* ─────────────────────────────────────────────────────────────────
   FEATURE 6: VITAL SIGNS LOG
   BP, Pulse, SpO2 per visit — logged inside clinical record form
   Appears automatically when medical alert flags are active.
───────────────────────────────────────────────────────────────── */
var VITALS_NORMAL = {bp_sys:[90,140], bp_dia:[60,90], pulse:[60,100], spo2:[95,100]};

function vitals_flag(key, val) {
  val = parseInt(val);
  if (!val) return '';
  var n = VITALS_NORMAL[key];
  var ok = val >= n[0] && val <= n[1];
  return ok ? '<span style="color:#059669;font-size:10px;font-weight:700"> ✓</span>'
            : '<span style="color:#dc2626;font-size:10px;font-weight:700"> ⚠</span>';
}

function vitals_renderForm() {
  return '<div style="background:#1e3a5f;border-radius:10px;padding:12px;margin-bottom:10px">' +
    '<div style="font-size:11px;font-weight:800;color:#7dd3fc;margin-bottom:8px;text-transform:uppercase;letter-spacing:.5px">📊 Vital Signs</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">' +
    '<div><label style="font-size:10px;color:#93c5fd;font-weight:700">Systolic BP (mmHg)</label>' +
    '<input id="vs-bp-sys" type="number" class="form-input" placeholder="e.g. 120" style="margin-top:3px" oninput="vitals_liveFlag(this,\'bp_sys\')"/><span id="vs-flag-bps"></span></div>' +
    '<div><label style="font-size:10px;color:#93c5fd;font-weight:700">Diastolic BP (mmHg)</label>' +
    '<input id="vs-bp-dia" type="number" class="form-input" placeholder="e.g. 80" style="margin-top:3px" oninput="vitals_liveFlag(this,\'bp_dia\')"/><span id="vs-flag-bpd"></span></div>' +
    '<div><label style="font-size:10px;color:#93c5fd;font-weight:700">Pulse (bpm)</label>' +
    '<input id="vs-pulse" type="number" class="form-input" placeholder="e.g. 72" style="margin-top:3px" oninput="vitals_liveFlag(this,\'pulse\')"/><span id="vs-flag-pulse"></span></div>' +
    '<div><label style="font-size:10px;color:#93c5fd;font-weight:700">SpO₂ (%)</label>' +
    '<input id="vs-spo2" type="number" class="form-input" placeholder="e.g. 98" style="margin-top:3px" oninput="vitals_liveFlag(this,\'spo2\')"/><span id="vs-flag-spo2"></span></div>' +
    '</div></div>';
}

function vitals_liveFlag(input, key) {
  var flagMap = {bp_sys:'vs-flag-bps', bp_dia:'vs-flag-bpd', pulse:'vs-flag-pulse', spo2:'vs-flag-spo2'};
  var el = document.getElementById(flagMap[key]);
  if (el) el.innerHTML = vitals_flag(key, input.value);
}

function vitals_getFromForm() {
  var get = function(id) { return (document.getElementById(id)||{}).value || ''; };
  var sys=get('vs-bp-sys'), dia=get('vs-bp-dia'), pulse=get('vs-pulse'), spo2=get('vs-spo2');
  if (!sys && !dia && !pulse && !spo2) return null;
  return { bp: sys&&dia ? sys+'/'+dia+' mmHg' : '', pulse: pulse ? pulse+' bpm' : '', spo2: spo2 ? spo2+'%' : '', recordedAt: todayISO() };
}

function vitals_renderBadge(vitals) {
  if (!vitals) return '';
  var parts = [];
  if (vitals.bp) parts.push('BP: '+vitals.bp);
  if (vitals.pulse) parts.push('♥ '+vitals.pulse);
  if (vitals.spo2) parts.push('O₂: '+vitals.spo2);
  return parts.length ? '<span style="font-size:10px;background:#eff6ff;color:#1d4ed8;padding:2px 8px;border-radius:5px;margin-left:8px">📊 '+parts.join(' | ')+'</span>' : '';
}


