function shade_renderPicker() {
  var html = '<div style="background:#f8fafc;border-radius:10px;padding:12px;margin-bottom:10px;border:1.5px solid #e2e8f0">';
  html += '<div style="font-size:11px;font-weight:800;color:#64748b;margin-bottom:8px;text-transform:uppercase;letter-spacing:.5px">🎨 Shade Guide — Vita Classical</div>';
  html += '<div id="shade-selected-display" style="margin-bottom:8px;font-size:13px;font-weight:700;color:#1e293b">'+(_selectedShade?'Selected: '+_selectedShade:'Tap a shade below')+'</div>';
  Object.entries(VITA_SHADES).forEach(function(entry) {
    var group = entry[0], shades = entry[1];
    html += '<div style="margin-bottom:6px"><span style="font-size:9px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px">'+group+'</span>';
    html += '<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:3px">';
    shades.forEach(function(sh) {
      var bg = SHADE_COLORS[sh]||'#f5f5f0';
      var isSel = _selectedShade === sh;
      html += '<button onclick="shade_select(\''+sh+'\')" style="background:'+bg+';border:'+(isSel?'2.5px solid #1d4ed8':'1.5px solid #cbd5e1')+';border-radius:6px;padding:4px 8px;cursor:pointer;font-size:11px;font-weight:'+(isSel?'800':'600')+';color:#374151;min-width:38px">'+sh+'</button>';
    });
    html += '</div></div>';
  });
  html += '<input type="hidden" id="shade-value" value="'+esc(_selectedShade||'')+'"/>';
  html += '</div>';
  return html;
}

function shade_select(shade) {
  _selectedShade = shade;
  // Re-render picker in place
  var container = document.getElementById('shade-picker-wrap');
  if (container) { container.innerHTML = shade_renderPicker(); }
  var inp = document.getElementById('shade-value');
  if (inp) inp.value = shade;
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 8: RCT / ENDO WORKING LENGTH TRACKER
   Per tooth: number of canals, WL per canal, MAF, technique,
   sealer, obturation date. Inside Records tab under patient.
───────────────────────────────────────────────────────────────── */
var RCT_CANALS_BY_TOOTH = {
  // Upper
  11:1,12:1,13:1,14:1,15:1,16:3,17:3,18:3,
  21:1,22:1,23:1,24:1,25:1,26:3,27:3,28:3,
  // Lower
  31:1,32:1,33:1,34:1,35:1,36:2,37:2,38:2,
  41:1,42:1,43:1,44:1,45:1,46:2,47:2,48:2,
};

var RCT_CANAL_NAMES = {
  1:['Canal 1'],
  2:['Mesial','Distal'],
  3:['MB','DB','Palatal'],
  4:['MB1','MB2','DB','Palatal'],
};

function rct_renderTracker() {
  if (!activePt) return;
  var el = document.getElementById('rct-tracker-content');
  if (!el) return;
  var rctCases = (activePt.rctLog||[]);

  var h = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:8px">';
  h += '<div style="font-size:13px;font-weight:800;color:#1e293b">🦷 RCT / Endo Log — '+esc(activePt.name)+'</div>';
  h += '<button class="btn btn-primary btn-sm" onclick="rct_showAddForm()">➕ New RCT Case</button>';
  h += '</div>';

  h += '<div id="rct-add-form-wrap" style="display:none;margin-bottom:16px"></div>';

  /* Summary strip */
  if (rctCases.length) {
    var completedCases = rctCases.filter(function(r){ return r.obturationDate; }).length;
    var pendingCases   = rctCases.length - completedCases;
    h += '<div style="display:flex;gap:10px;background:linear-gradient(135deg,#0f172a,#1e3a5f);border-radius:12px;padding:12px 14px;margin-bottom:12px;color:#fff">';
    h += '<div style="flex:1;text-align:center"><div style="font-size:10px;font-weight:700;color:#94a3b8;margin-bottom:2px">TOTAL</div><div style="font-size:22px;font-weight:800">'+rctCases.length+'</div></div>';
    h += '<div style="flex:1;text-align:center"><div style="font-size:10px;font-weight:700;color:#94a3b8;margin-bottom:2px">DONE</div><div style="font-size:22px;font-weight:800;color:#34d399">'+completedCases+'</div></div>';
    h += '<div style="flex:1;text-align:center"><div style="font-size:10px;font-weight:700;color:#94a3b8;margin-bottom:2px">PENDING</div><div style="font-size:22px;font-weight:800;color:#f87171">'+pendingCases+'</div></div>';
    h += '</div>';
  }

  if (!rctCases.length) {
    h += '<div class="empty"><span class="empty-icon">🦷</span><div class="empty-title">No RCT cases logged</div><div class="empty-sub">Add the first endo case above</div></div>';
  } else {
    rctCases.slice().reverse().forEach(function(rct) {
      var canals = rct.canals||[];
      h += '<div class="card" style="margin-bottom:12px">';
      h += '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;flex-wrap:wrap">';
      h += '<div style="flex:1">';
      h += '<div style="font-size:14px;font-weight:800;color:#1e293b">Tooth #'+esc(String(rct.toothNo||''))+'</div>';
      h += '<div style="font-size:11px;color:#64748b;margin-top:2px">'+fmtDate(rct.date)+(rct.obturationDate?' • Obturation: '+fmtDate(rct.obturationDate):'')+'</div>';
      if (rct.technique) h += '<div style="font-size:11px;color:#374151;margin-top:3px">Technique: '+esc(rct.technique)+'</div>';
      if (rct.sealer)    h += '<div style="font-size:11px;color:#374151">Sealer: '+esc(rct.sealer)+'</div>';
      h += '<div style="margin-top:8px;display:flex;flex-wrap:wrap;gap:6px">';
      canals.forEach(function(canal) {
        h += '<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:5px 10px;font-size:11px">';
        h += '<div style="font-weight:700;color:#1d4ed8">'+esc(canal.name)+'</div>';
        h += '<div style="color:#374151">WL: '+esc(String(canal.wl||'—'))+'mm | MAF: #'+esc(String(canal.maf||'—'))+'</div>';
        h += '</div>';
      });
      h += '</div>';
      if (rct.notes) h += '<div style="font-size:11px;color:#64748b;margin-top:6px;font-style:italic">'+esc(rct.notes)+'</div>';
      h += '</div>';
      h += '<div style="display:flex;gap:6px;flex-shrink:0">';
      h += '<button class="btn btn-sm" data-rctid="'+rct.id+'" onclick="rct_showVisit(this.dataset.rctid)" style="font-size:10px">+ Visit</button>';
      h += '<button class="btn btn-sm" style="font-size:10px;background:#eff6ff;color:#1d4ed8;border:none" data-rctid="'+rct.id+'" onclick="rct_editCase(this.dataset.rctid)">✏️ Edit</button>';
      h += '<button class="btn btn-sm btn-red" data-rctid="'+rct.id+'" onclick="rct_delete(this.dataset.rctid)" style="font-size:10px">🗑</button>';
      h += '</div>';
      h += '</div>';
      // Visits
      if (rct.visits && rct.visits.length) {
        h += '<div style="margin-top:10px;border-top:1px solid #f1f5f9;padding-top:8px">';
        h += '<div style="font-size:10px;font-weight:700;color:#94a3b8;margin-bottom:6px;text-transform:uppercase">Visit Log</div>';
        rct.visits.forEach(function(v,i) {
          h += '<div style="font-size:11px;color:#374151;padding:4px 0;border-bottom:1px solid #f8fafc">';
          h += '<span style="color:#64748b">'+fmtDate(v.date)+'</span> — '+esc(v.notes||'Visit '+(i+1));
          h += '</div>';
        });
        h += '</div>';
      }
      h += '</div>';
    });
  }
  el.innerHTML = h;
}

function rct_showAddForm() {
  var wrap = document.getElementById('rct-add-form-wrap');
  if (!wrap) return;

  var techOptions = ['Rotary (ProTaper)','Rotary (WaveOne)','Hand Filing','Reciprocating','Hybrid'].map(function(t){
    return '<option>'+t+'</option>';
  }).join('');
  var sealerOptions = ['AH Plus','ZOE','Apexit Plus','Sealapex','Bioroot','MTA Fillapex'].map(function(s){
    return '<option>'+s+'</option>';
  }).join('');

  wrap.style.display = 'block';
  wrap.innerHTML = '<div class="card" style="background:#f0f9ff;border:1.5px solid #bae6fd">' +
    '<div style="font-size:13px;font-weight:800;color:#0369a1;margin-bottom:12px">🦷 New RCT Case</div>' +
    '<div class="form-grid-2">' +
    '<div class="form-group"><label class="form-label">Tooth Number *</label>' +
    '<input id="rct-tooth" class="form-input" type="number" min="11" max="48" placeholder="e.g. 26" oninput="rct_updateCanals()"/></div>' +
    '<div class="form-group"><label class="form-label">Date</label>' +
    '<input id="rct-date" class="form-input" type="date" value="'+todayISO()+'"/></div>' +
    '</div>' +
    '<div id="rct-canals-section" style="margin-bottom:12px"></div>' +
    '<div class="form-grid-2">' +
    '<div class="form-group"><label class="form-label">Technique</label>' +
    '<select id="rct-technique" class="form-input"><option value="">Select...</option>'+techOptions+'</select></div>' +
    '<div class="form-group"><label class="form-label">Sealer</label>' +
    '<select id="rct-sealer" class="form-input"><option value="">Select...</option>'+sealerOptions+'</select></div>' +
    '</div>' +
    '<div class="form-grid-2">' +
    '<div class="form-group"><label class="form-label">Obturation Date</label>' +
    '<input id="rct-obtdate" class="form-input" type="date"/></div>' +
    '<div class="form-group"><label class="form-label">Notes</label>' +
    '<input id="rct-notes" class="form-input" placeholder="e.g. calcified MB canal, curved root..."/></div>' +
    '</div>' +
    '<div style="display:flex;gap:8px">' +
    '<button class="btn btn-primary btn-sm" id="rct-save-btn" onclick="rct_save()">💾 Save RCT Case</button>' +
    '<button class="btn btn-sm" onclick="document.getElementById(\'rct-add-form-wrap\').style.display=\'none\'">Cancel</button>' +
    '</div></div>';
}

function rct_updateCanals() {
  var toothNo = parseInt((document.getElementById('rct-tooth')||{}).value||0);
  var numCanals = RCT_CANALS_BY_TOOTH[toothNo] || 1;
  var names = RCT_CANAL_NAMES[numCanals] || ['Canal 1'];
  var section = document.getElementById('rct-canals-section');
  if (!section) return;

  var h = '<div style="font-size:11px;font-weight:700;color:#0369a1;margin-bottom:6px">Canals: '+numCanals+' expected for tooth #'+toothNo+'</div>';
  h += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px">';
  names.forEach(function(name, i) {
    h += '<div style="background:#fff;border:1px solid #bae6fd;border-radius:8px;padding:8px">';
    h += '<div style="font-size:11px;font-weight:800;color:#0369a1;margin-bottom:5px">'+name+'</div>';
    h += '<input class="form-input" id="rct-wl-'+i+'" type="number" step="0.5" placeholder="Working Length (mm)" style="margin-bottom:4px"/>';
    h += '<input class="form-input" id="rct-maf-'+i+'" type="number" placeholder="MAF size (e.g. 35)"/>';
    h += '</div>';
  });
  h += '</div>';
  section.innerHTML = h;
}

function rct_save() {
  var toothNo = parseInt((document.getElementById('rct-tooth')||{}).value||0);
  if (!toothNo) { alert('Tooth number required'); return; }
  // Check if editing existing entry
  var saveBtn = document.getElementById('rct-save-btn');
  var editId  = saveBtn ? saveBtn.getAttribute('data-editid') : null;
  var numCanals = RCT_CANALS_BY_TOOTH[toothNo] || 1;
  var names = RCT_CANAL_NAMES[numCanals] || ['Canal 1'];
  var canals = names.map(function(name, i) {
    return {
      name: name,
      wl: (document.getElementById('rct-wl-'+i)||{}).value || '',
      maf: (document.getElementById('rct-maf-'+i)||{}).value || ''
    };
  });
  var rctCase = {
    id: 'rct'+Date.now(),
    toothNo: toothNo,
    date: (document.getElementById('rct-date')||{}).value || todayISO(),
    canals: canals,
    technique: (document.getElementById('rct-technique')||{}).value || '',
    sealer: (document.getElementById('rct-sealer')||{}).value || '',
    obturationDate: (document.getElementById('rct-obtdate')||{}).value || '',
    notes: (document.getElementById('rct-notes')||{}).value || '',
    visits: []
  };
  var idx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  var saveBtn2 = document.getElementById('rct-save-btn');
  var editId2  = saveBtn2 ? saveBtn2.getAttribute('data-editid') : null;
  if (editId2) {
    DATA.patients[idx].rctLog = (DATA.patients[idx].rctLog||[]).map(function(r){
      if (r.id!==editId2) return r;
      return Object.assign({},r,{toothNo:rctCase.toothNo,date:rctCase.date,canals:rctCase.canals,technique:rctCase.technique,sealer:rctCase.sealer,obturationDate:rctCase.obturationDate,notes:rctCase.notes});
    });
    if (saveBtn2) { saveBtn2.removeAttribute('data-editid'); saveBtn2.textContent='💾 Save RCT Case'; }
  } else {
    if (!DATA.patients[idx].rctLog) DATA.patients[idx].rctLog = [];
    DATA.patients[idx].rctLog.push(rctCase);
  }
  activePt = DATA.patients[idx];
  saveData();
  document.getElementById('rct-add-form-wrap').style.display = 'none';
  rct_renderTracker();
}



function rct_showVisit(rctId) {
  var note = prompt('Visit notes (e.g. 2nd visit — access refined, canals irrigated with NaOCl):');
  if (!note) return;
  var idx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  var rctIdx = (DATA.patients[idx].rctLog||[]).findIndex(function(r){ return r.id===rctId; });
  if (rctIdx<0) return;
  if (!DATA.patients[idx].rctLog[rctIdx].visits) DATA.patients[idx].rctLog[rctIdx].visits=[];
  DATA.patients[idx].rctLog[rctIdx].visits.push({date:todayISO(), notes:note});
  activePt = DATA.patients[idx];
  saveData(); rct_renderTracker();
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 3: ADVANCE PAYMENT / CREDIT BALANCE (WALLET)
   Per patient: credit wallet with deposit/deduct history.
   Shown at top of billing tab. Outstanding dues deducts credit.
───────────────────────────────────────────────────────────────── */
function credit_renderWallet() {
  if (!activePt) return '';
  var wallet = activePt.creditWallet||{balance:0, transactions:[]};
  var balance = Number(wallet.balance||0);
  var color = balance>0 ? '#059669' : balance<0 ? '#dc2626' : '#374151';
  var bg    = balance>0 ? '#ecfdf5' : balance<0 ? '#fef2f2' : '#f8fafc';

  var h = '<div style="background:'+bg+';border:1.5px solid '+(balance>0?'#6ee7b7':balance<0?'#fca5a5':'#e2e8f0')+';border-radius:12px;padding:14px;margin-bottom:16px">';
  h += '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">';
  h += '<div>';
  h += '<div style="font-size:11px;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:.5px">💳 Credit Wallet</div>';
  h += '<div style="font-size:26px;font-weight:800;color:'+color+'">'+fmtMoney(Math.abs(balance))+'</div>';
  h += '<div style="font-size:11px;color:#64748b">'+(balance>0?'Credit available — will be applied to next bill':balance<0?'Outstanding balance':balance===0?'No credit / no due':'')+'</div>';
  h += '</div>';
  h += '<div style="display:flex;gap:8px;flex-wrap:wrap">';
  h += '<button class="btn btn-sm" style="background:#059669;color:#fff;border:none" onclick="credit_deposit()">+ Add Credit</button>';
  if (balance>0) h += '<button class="btn btn-sm" style="background:#d97706;color:#fff;border:none" onclick="credit_deduct()">- Deduct</button>';
  h += '</div></div>';

  // Last 5 transactions
  var txns = (wallet.transactions||[]).slice().reverse().slice(0,5);
  if (txns.length) {
    h += '<div style="margin-top:10px;border-top:1px solid '+(balance>0?'#6ee7b7':'#e2e8f0')+';padding-top:8px">';
    txns.forEach(function(t) {
      h += '<div style="display:flex;justify-content:space-between;font-size:11px;padding:3px 0;color:#374151">';
      h += '<span>'+fmtDate(t.date)+' — '+esc(t.note||'')+'</span>';
      h += '<span style="font-weight:700;color:'+(t.amount>0?'#059669':'#dc2626')+'">'+(t.amount>0?'+':'')+fmtMoney(t.amount)+'</span>';
      h += '</div>';
    });
    h += '</div>';
  }
  h += '</div>';
  return h;
}

function credit_deposit() {
  var amt = parseFloat(prompt('Amount to add as advance credit (₹):'));
  if (!amt || amt<=0) return;
  var note = prompt('Payment note (e.g. Cash advance for braces, UPI from patient):')||'Advance deposit';
  credit_transact(amt, note);
}

function credit_deduct() {
  var wallet = activePt.creditWallet||{balance:0};
  var amt = parseFloat(prompt('Amount to deduct from credit (₹):\nCurrent balance: ₹'+Number(wallet.balance||0).toLocaleString('en-IN')));
  if (!amt || amt<=0) return;
  var note = prompt('Deduction reason:')||'Applied to treatment';
  credit_transact(-amt, note);
}

function credit_transact(amount, note) {
  var idx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  if (!DATA.patients[idx].creditWallet) DATA.patients[idx].creditWallet = {balance:0, transactions:[]};
  DATA.patients[idx].creditWallet.balance = Number(DATA.patients[idx].creditWallet.balance||0) + amount;
  DATA.patients[idx].creditWallet.transactions.push({id:'cr'+Date.now(), date:todayISO(), amount:amount, note:note});
  activePt = DATA.patients[idx];
  saveData();
  renderBillingTab();
}



