/* ─────────────────────────────────────────────────────────────────
   FEATURE 1: BEFORE/AFTER COMPARISON SLIDER
   Picks two photo sessions → side-by-side slider + WhatsApp
───────────────────────────────────────────────────────────────── */


function beforeAfter_preview() {
  if (!activePt) return;
  var sessions = activePt.photoSessions||[];
  var bIdx  = parseInt((document.getElementById('ba-before-sel')||{}).value||0);
  var aIdx  = parseInt((document.getElementById('ba-after-sel')||{}).value||sessions.length-1);
  var slotId = (document.getElementById('ba-slot-sel')||{}).value||'retracted_frontal';
  var bSess = sessions[bIdx]||{};
  var aSess = sessions[aIdx]||{};
  var bPhoto = (bSess.photos||{})[slotId];
  var aPhoto = (aSess.photos||{})[slotId];
  var preview = document.getElementById('ba-preview');
  if (!preview) return;

  if (!bPhoto && !aPhoto) {
    preview.innerHTML = '<div style="color:#94a3b8;font-size:12px;text-align:center">No photos in this slot for selected sessions.<br>Try a different slot or capture photos first.</div>';
    return;
  }

  preview.innerHTML =
    '<div style="flex:1;text-align:center">' +
    '<div style="font-size:10px;color:#94a3b8;margin-bottom:4px;font-weight:700">BEFORE</div>' +
    (bPhoto ? '<img src="'+bPhoto+'" style="width:100%;max-height:160px;object-fit:cover;border-radius:8px;border:2px solid #dc2626"/>'
            : '<div style="height:120px;background:#334155;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:11px">No photo</div>') +
    '<div style="font-size:10px;color:#64748b;margin-top:4px">'+fmtDate(bSess.date||'')+(bSess.label?' — '+bSess.label:'')+'</div></div>' +
    '<div style="font-size:24px;color:#fff;padding:0 8px">⟷</div>' +
    '<div style="flex:1;text-align:center">' +
    '<div style="font-size:10px;color:#94a3b8;margin-bottom:4px;font-weight:700">AFTER</div>' +
    (aPhoto ? '<img src="'+aPhoto+'" style="width:100%;max-height:160px;object-fit:cover;border-radius:8px;border:2px solid #059669"/>'
            : '<div style="height:120px;background:#334155;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#64748b;font-size:11px">No photo</div>') +
    '<div style="font-size:10px;color:#64748b;margin-top:4px">'+fmtDate(aSess.date||'')+(aSess.label?' — '+aSess.label:'')+'</div></div>';
}

function beforeAfter_shareWA() {
  if (!activePt || !activePt.phone) { alert('No phone number on file for this patient.'); return; }
  var nl = String.fromCharCode(10);
  var msg = 'Dear '+activePt.name+','+nl+nl+
    'Your smile transformation at *'+CLINIC+'*! '+nl+nl+
    'Check out the remarkable difference in your dental health before and after treatment.'+nl+nl+
    'We are so proud of your commitment to your smile! '+nl+nl+
    'Share your smile story — a review helps other patients find great dental care! '+nl+
    'Thank you for trusting us. &#128522;'+nl+nl+PHONE;
  window.open('https://wa.me/91'+activePt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 5: DIGITAL CONSENT SIGNATURE
   Canvas signature pad — saves as image in signedConsents[]
───────────────────────────────────────────────────────────────── */
var _sigCanvas=null, _sigCtx=null, _sigDrawing=false, _sigCurrentConsentId=null;

function sig_open(consentId, consentTitle) {
  _sigCurrentConsentId = consentId;
  var modal = document.getElementById('consent-sign-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'consent-sign-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:9990;display:flex;align-items:flex-end;justify-content:center;padding:0';
    document.body.appendChild(modal);
  }
  modal.style.display = 'flex';
  modal.innerHTML = '<div style="background:#fff;border-radius:20px 20px 0 0;padding:24px;width:100%;max-width:520px">' +
    '<div style="font-size:15px;font-weight:800;color:#1e293b;margin-bottom:4px">✍ Patient Signature</div>' +
    '<div style="font-size:12px;color:#64748b;margin-bottom:14px">'+esc(consentTitle||'Consent Form')+'</div>' +
    '<div style="font-size:11px;color:#64748b;margin-bottom:6px">Sign in the box below:</div>' +
    '<canvas id="sig-canvas" width="460" height="180" style="border:2px solid #e2e8f0;border-radius:10px;width:100%;max-width:460px;background:#fff;touch-action:none"></canvas>' +
    '<div style="display:flex;gap:8px;margin-top:12px">' +
    '<button onclick="sig_save()" style="flex:1;background:#059669;border:none;color:#fff;border-radius:8px;padding:11px;cursor:pointer;font-weight:700">💾 Save Signature</button>' +
    '<button onclick="sig_clear()" style="background:#f1f5f9;border:none;color:#374151;border-radius:8px;padding:11px;cursor:pointer;font-size:12px">Clear</button>' +
    '<button onclick="document.getElementById(\'consent-sign-modal\').style.display=\'none\'" style="background:#f1f5f9;border:none;color:#374151;border-radius:8px;padding:11px;cursor:pointer;font-size:12px">Cancel</button>' +
    '</div></div>';

  setTimeout(function() {
    _sigCanvas = document.getElementById('sig-canvas');
    if (!_sigCanvas) return;
    _sigCtx = _sigCanvas.getContext('2d');
    _sigCtx.strokeStyle = '#1e293b';
    _sigCtx.lineWidth = 2.5;
    _sigCtx.lineCap = 'round';
    _sigCtx.lineJoin = 'round';

    var getPos = function(e) {
      var rect = _sigCanvas.getBoundingClientRect();
      var scaleX = _sigCanvas.width / rect.width;
      var scaleY = _sigCanvas.height / rect.height;
      var src = e.touches ? e.touches[0] : e;
      return { x: (src.clientX - rect.left)*scaleX, y: (src.clientY - rect.top)*scaleY };
    };
    _sigCanvas.addEventListener('mousedown',  function(e){ _sigDrawing=true; var p=getPos(e); _sigCtx.beginPath(); _sigCtx.moveTo(p.x,p.y); });
    _sigCanvas.addEventListener('mousemove',  function(e){ if(!_sigDrawing)return; var p=getPos(e); _sigCtx.lineTo(p.x,p.y); _sigCtx.stroke(); });
    _sigCanvas.addEventListener('mouseup',    function(){ _sigDrawing=false; });
    _sigCanvas.addEventListener('touchstart', function(e){ e.preventDefault(); _sigDrawing=true; var p=getPos(e); _sigCtx.beginPath(); _sigCtx.moveTo(p.x,p.y); }, {passive:false});
    _sigCanvas.addEventListener('touchmove',  function(e){ e.preventDefault(); if(!_sigDrawing)return; var p=getPos(e); _sigCtx.lineTo(p.x,p.y); _sigCtx.stroke(); }, {passive:false});
    _sigCanvas.addEventListener('touchend',   function(){ _sigDrawing=false; });
  }, 100);
}

function sig_clear() { if (_sigCtx && _sigCanvas) _sigCtx.clearRect(0,0,_sigCanvas.width,_sigCanvas.height); }

function sig_save() {
  if (!_sigCanvas || !activePt) return;
  var dataUrl = _sigCanvas.toDataURL('image/png');
  var idx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  if (!DATA.patients[idx].signedConsents) DATA.patients[idx].signedConsents=[];
  // Remove old signature for same consent if exists
  DATA.patients[idx].signedConsents = DATA.patients[idx].signedConsents.filter(function(s){ return s.consentId!==_sigCurrentConsentId; });
  DATA.patients[idx].signedConsents.push({
    id:'sig'+Date.now(), consentId:_sigCurrentConsentId,
    signatureData:dataUrl, signedAt:todayISO(), signedBy:activePt.name
  });
  activePt = DATA.patients[idx];
  saveData();
  document.getElementById('consent-sign-modal').style.display='none';
  showSavedToast();
  if (typeof consent_render === 'function') consent_render();
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 9: TREATMENT COMPLETION CERTIFICATE
   Prints a professional certificate for completed cases
───────────────────────────────────────────────────────────────── */
function cert_print(type) {
  if (!activePt) return;
  var types = {
    ortho:    { title:'Orthodontic Treatment Completion', icon:'🦷', body:'This certifies that the orthodontic treatment has been successfully completed. The patient has achieved optimal dental alignment and occlusion as planned.' },
    implant:  { title:'Dental Implant Osseointegration Complete', icon:'🔩', body:'This certifies that the dental implant procedure has been completed and osseointegration confirmed. The implant is fully functional and integrated.' },
    rct:      { title:'Root Canal Treatment Complete', icon:'✅', body:'This certifies that the root canal treatment has been successfully completed. The tooth has been thoroughly cleaned, shaped, and obturated.' },
    rehab:    { title:'Full Mouth Rehabilitation Complete', icon:'😊', body:'This certifies the successful completion of full mouth rehabilitation. A comprehensive restoration of dental health, function, and aesthetics has been achieved.' },
  };
  var t = types[type] || types.ortho;
  var done = (activePt.treatmentPlan||[]).filter(function(i){ return i.status==='completed'; });
  var today = new Date();
  var dateStr = today.toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'});

  var win = window.open('','_blank','width=700,height=550');
  win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>Certificate — '+activePt.name+'</title>');
  win.document.write('<style>');
  win.document.write('body{font-family:Georgia,serif;margin:0;padding:40px;background:#fff;color:#1e293b}');
  win.document.write('.cert{border:8px double #1e3a5f;padding:48px;min-height:480px;position:relative;text-align:center}');
  win.document.write('.ornament{font-size:48px;margin-bottom:16px}');
  win.document.write('.clinic{font-size:14px;font-weight:700;color:#64748b;letter-spacing:2px;text-transform:uppercase}');
  win.document.write('.title{font-size:26px;font-weight:700;color:#1e3a5f;margin:20px 0 10px}');
  win.document.write('.subtitle{font-size:13px;color:#94a3b8;margin-bottom:28px;letter-spacing:1px}');
  win.document.write('.patient{font-size:32px;font-weight:700;color:#1e3a5f;border-bottom:2px solid #1e3a5f;display:inline-block;padding-bottom:6px;margin:0 auto 24px}');
  win.document.write('.body-text{font-size:14px;color:#374151;line-height:1.8;max-width:480px;margin:0 auto 28px}');
  win.document.write('.footer{display:flex;justify-content:space-between;align-items:flex-end;margin-top:48px;border-top:1px solid #e2e8f0;padding-top:20px}');
  win.document.write('.sig-block{text-align:center}.sig-line{border-top:1px solid #374151;width:180px;margin:0 auto 6px}.sig-name{font-size:12px;color:#374151;font-weight:700}');
  win.document.write('.seal{font-size:11px;color:#94a3b8;text-align:center}');
  win.document.write('@media print{body{margin:0;padding:20px}.cert{page-break-inside:avoid}}');
  win.document.write('</style></head><body>');
  win.document.write('<div class="cert">');
  win.document.write('<div class="ornament">'+t.icon+'</div>');
  win.document.write('<div class="clinic">'+esc(CLINIC)+'</div>');
  win.document.write('<div class="title">Certificate of '+esc(t.title)+'</div>');
  win.document.write('<div class="subtitle">This is to certify that</div>');
  win.document.write('<div class="patient">'+esc(activePt.name)+'</div>');
  win.document.write('<p class="body-text">'+t.body+'</p>');
  if (done.length) {
    win.document.write('<p class="body-text" style="font-size:12px;color:#64748b">Procedures completed: '+done.map(function(i){return esc(i.procedure);}).join(', ')+'</p>');
  }
  win.document.write('<div class="footer">');
  win.document.write('<div class="seal">'+esc(dateStr)+'<br/>Date of Issue</div>');
  win.document.write('<div class="sig-block"><div class="sig-line"></div><div class="sig-name">Dr. Tanmay Jain</div><div style="font-size:10px;color:#94a3b8">B.D.S., M.I.D.A. | Reg. A-9965</div></div>');
  win.document.write('<div class="seal">'+esc(CLINIC)+'<br/>'+esc(PHONE)+'</div>');
  win.document.write('</div></div>');
  win.document.write('<script>window.onload=function(){window.print();}<\/script>');
  win.document.write('</body></html>');
  win.document.close();
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 11: LAB BILL RECONCILIATION
   Per billing item: optional lab cost → shows net margin
───────────────────────────────────────────────────────────────── */
function lab_recon_renderSummary() {
  if (!activePt) return '';
  var bills = (activePt.billing||[]).filter(function(b){ return b.labCost && b.labCost > 0; });
  if (!bills.length) return '<div style="font-size:11px;color:#94a3b8;padding:8px 0">No lab work logged yet. Add lab cost to a billing item to see margin.</div>';
  var totalRev=0, totalLab=0;
  bills.forEach(function(b){ totalRev+=Number(b.amount||0); totalLab+=Number(b.labCost||0); });
  var margin = totalRev>0 ? Math.round(((totalRev-totalLab)/totalRev)*100) : 0;
  var h = '<div style="background:#f0fdf4;border:1.5px solid #6ee7b7;border-radius:10px;padding:12px;margin-top:12px">';
  h += '<div style="font-size:11px;font-weight:800;color:#065f46;margin-bottom:8px;text-transform:uppercase;letter-spacing:.5px">🔬 Lab Bill Reconciliation</div>';
  h += '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:10px">';
  h += '<div><div style="font-size:9px;color:#64748b;font-weight:700">REVENUE</div><div style="font-size:18px;font-weight:800;color:#059669">'+fmtMoney(totalRev)+'</div></div>';
  h += '<div><div style="font-size:9px;color:#64748b;font-weight:700">LAB COST</div><div style="font-size:18px;font-weight:800;color:#dc2626">'+fmtMoney(totalLab)+'</div></div>';
  h += '<div><div style="font-size:9px;color:#64748b;font-weight:700">NET MARGIN</div><div style="font-size:18px;font-weight:800;color:#059669">'+margin+'%</div></div>';
  h += '</div>';
  bills.forEach(function(b) {
    var net = Number(b.amount||0)-Number(b.labCost||0);
    var m = Number(b.amount)>0 ? Math.round((net/Number(b.amount))*100) : 0;
    h += '<div style="font-size:11px;display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid #d1fae5;color:#374151">';
    h += '<span>'+esc(b.item||'Item')+'</span>';
    h += '<span>Rev: '+fmtMoney(b.amount)+' | Lab: '+fmtMoney(b.labCost)+' | Net: <strong>'+fmtMoney(net)+'</strong> ('+m+'%)</span>';
    h += '</div>';
  });
  h += '</div>';
  return h;
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 12: MONTHLY REVENUE GOAL TRACKER
   Set target → dashboard progress bar
───────────────────────────────────────────────────────────────── */
function goal_getMonthlyTarget() {
  return parseFloat(localStorage.getItem('hos_monthly_goal')||'0');
}

function goal_setTarget() {
  var cur = goal_getMonthlyTarget();
  var val = parseFloat(prompt('Set monthly revenue target (₹):\nCurrent: '+(cur?fmtMoney(cur):'Not set'), cur||''));
  if (!val || isNaN(val) || val <= 0) return;
  localStorage.setItem('hos_monthly_goal', String(val));
  goal_renderWidget();
}

function goal_getThisMonthRevenue() {
  var now = new Date();
  var ym = now.getFullYear()+'-'+(String(now.getMonth()+1).padStart(2,'0'));
  return (DATA.patients||[])
    .flatMap(function(p){ return p.billing||[]; })
    .filter(function(b){ return b.paid && (b.date||'').startsWith(ym); })
    .reduce(function(s,b){ return s+Number(b.amount||0); },0);
}

function goal_renderWidget() {
  var el = document.getElementById('goal-widget');
  if (!el) return;
  var target = goal_getMonthlyTarget();
  var actual = goal_getThisMonthRevenue();
  if (!target) {
    el.innerHTML = '<div onclick="goal_setTarget()" style="cursor:pointer;background:#f8fafc;border:1.5px dashed #e2e8f0;border-radius:12px;padding:12px;text-align:center;margin-bottom:14px">' +
      '<div style="font-size:11px;color:#94a3b8">🎯 Tap to set monthly revenue goal</div></div>';
    return;
  }
  var pct  = Math.min(100, Math.round((actual/target)*100));
  var now  = new Date();
  var daysLeft = new Date(now.getFullYear(),now.getMonth()+1,0).getDate() - now.getDate();
  var color = pct>=100?'#059669':pct>=60?'#d97706':'#dc2626';
  var monthName = now.toLocaleString('en-IN',{month:'long'});

  el.innerHTML = '<div style="background:#1e3a5f;border-radius:12px;padding:14px;margin-bottom:14px;color:#fff">' +
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">' +
    '<div style="font-size:11px;font-weight:800;opacity:.8;text-transform:uppercase;letter-spacing:.5px">🎯 '+monthName+' Goal</div>' +
    '<button onclick="goal_setTarget()" style="background:rgba(255,255,255,.1);border:none;color:#7dd3fc;font-size:10px;padding:3px 8px;border-radius:5px;cursor:pointer">Edit</button>' +
    '</div>' +
    '<div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:8px">' +
    '<div><div style="font-size:22px;font-weight:800">'+fmtMoney(actual)+'</div><div style="font-size:10px;opacity:.6">collected this month</div></div>' +
    '<div style="text-align:right"><div style="font-size:18px;font-weight:800;color:'+color+'">'+pct+'%</div><div style="font-size:10px;opacity:.6">of '+fmtMoney(target)+'</div></div>' +
    '</div>' +
    '<div style="background:rgba(255,255,255,.15);border-radius:6px;height:10px;overflow:hidden">' +
    '<div style="background:'+color+';height:100%;width:'+pct+'%;border-radius:6px;transition:width .5s"></div>' +
    '</div>' +
    '<div style="font-size:10px;opacity:.6;margin-top:6px">'+(pct>=100?'&#127881; Target achieved! Great month!':daysLeft+' days left — need '+fmtMoney(Math.max(0,target-actual))+' more')+'</div>' +
    '</div>';
}


/* ─────────────────────────────────────────────────────────────────
   FEATURE 15: PROCEDURE TIMER (CHAIRSIDE STOPWATCH)
   Dedicated timer per patient visit — auto-start option,
   manual start/stop, logs time to record.
   cs_timerSeconds already exists — this wraps it with a display.
───────────────────────────────────────────────────────────────── */
var _procTimerRunning=false, _procTimerInterval=null, _procTimerSecs=0;





function procTimer_reset() {
  procTimer_stop();
  _procTimerSecs = 0;
  cs_timerSeconds = 0;
  procTimer_updateDisplay();
}

function procTimer_updateDisplay() {
  var el = document.getElementById('proc-timer-display');
  if (!el) return;
  var h = Math.floor(_procTimerSecs/3600);
  var m = Math.floor((_procTimerSecs%3600)/60);
  var s = _procTimerSecs%60;
  var timeStr = (h>0?h+'h ':'')+(m>0||h>0?m+'m ':'')+s+'s';
  el.innerHTML =
    '<div style="display:flex;align-items:center;gap:10px;background:#1e293b;border-radius:10px;padding:10px 14px;margin-bottom:12px">' +
    '<div style="font-family:monospace;font-size:22px;font-weight:800;color:'+(_procTimerRunning?'#34d399':'#94a3b8')+'">'+timeStr+'</div>' +
    '<button onclick="procTimer_start()" style="background:#059669;border:none;color:#fff;border-radius:6px;padding:5px 10px;cursor:pointer;font-size:11px;font-weight:700;'+((_procTimerRunning)?'opacity:.5;pointer-events:none':'')+'">&#9654;</button>' +
    '<button onclick="procTimer_stop()" style="background:#d97706;border:none;color:#fff;border-radius:6px;padding:5px 10px;cursor:pointer;font-size:11px;font-weight:700">&#9646;&#9646;</button>' +
    '<button onclick="procTimer_reset()" style="background:#334155;border:none;color:#94a3b8;border-radius:6px;padding:5px 10px;cursor:pointer;font-size:11px">&#8635;</button>' +
    '<div style="font-size:10px;color:#64748b">Will be saved with record</div>' +
    '</div>';
}


