/* ─── 1. DRUG × ALLERGY INTERACTION CHECK ──────────── */
var DRUG_ALLERGY_RULES = [
  { allergyKeywords:['penicillin','pcn'],          dangerDrugs:['amoxicillin','amoxyclav','augmentin','ampicillin','penicillin'], message:'⚠ PENICILLIN ALLERGY — Amoxicillin/Augmentin is contraindicated. Use Azithromycin or Clindamycin instead.' },
  { allergyKeywords:['aspirin','nsaid'],            dangerDrugs:['aspirin','ibuprofen','diclofenac','nimesulide','naproxen'], message:'⚠ ASPIRIN/NSAID SENSITIVITY — Avoid NSAIDs. Use Paracetamol for pain relief.' },
  { allergyKeywords:['sulfa','sulfonamide'],        dangerDrugs:['metronidazole'], message:'⚠ SULFA ALLERGY — Metronidazole cross-reactivity possible. Monitor closely.' },
  { allergyKeywords:['latex'],                     dangerDrugs:['lignocaine','lidocaine'], message:'⚠ LATEX ALLERGY — Use latex-free gloves and equipment. LA safe but check cartridge stopper.' },
  { allergyKeywords:['warfarin','clopidogrel','blood thin','anticoagul','acitrom','ecosprin'], dangerDrugs:['aspirin','ibuprofen','diclofenac','naproxen','nimesulide'], message:'⚠ ANTICOAGULANT — NSAIDs increase bleeding risk. Use Paracetamol only.' },
  { allergyKeywords:['metronidazole','flagyl'],     dangerDrugs:['metronidazole','flagyl'], message:'⚠ Metronidazole allergy on file.' },
  { allergyKeywords:['codeine','opioid'],           dangerDrugs:['codeine','tramadol'], message:'⚠ OPIOID SENSITIVITY — Avoid codeine/tramadol.' },
];

function drug_checkAllergy(medName) {
  if (!activePt || !medName) return null;
  var hist = ((activePt.medHistory||'') + ' ' + (activePt.complaint||'')).toLowerCase();
  var med  = medName.toLowerCase();
  for (var i=0; i<DRUG_ALLERGY_RULES.length; i++) {
    var rule = DRUG_ALLERGY_RULES[i];
    var allergyPresent = rule.allergyKeywords.some(function(kw){ return hist.includes(kw); });
    if (!allergyPresent) continue;
    var drugMatch = rule.dangerDrugs.some(function(d){ return med.includes(d); });
    if (drugMatch) return rule.message;
  }
  return null;
}

function drug_checkAllMeds() {
  // Called when Rx is about to be printed/saved
  if (!activePt) return;
  var meds = (activePt.prescriptions||[]).flatMap(function(rx){ return rx.medicines||[]; });
  var alerts = [];
  meds.forEach(function(m) {
    var warn = drug_checkAllergy(m.name||'');
    if (warn && !alerts.includes(warn)) alerts.push(warn);
  });
  return alerts;
}

// Inline check triggered on medicine name input blur
function drug_checkMedInput(inputEl) {
  if (!inputEl || !inputEl.value) return;
  var warn = drug_checkAllergy(inputEl.value);
  var warnId = 'drug-warn-' + inputEl.id;
  var existing = document.getElementById(warnId);
  if (existing) existing.remove();
  if (warn) {
    var div = document.createElement('div');
    div.id = warnId;
    div.style.cssText = 'background:#7f1d1d;color:#fef2f2;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:700;margin-top:3px';
    div.textContent = warn;
    inputEl.parentNode.appendChild(div);
    inputEl.style.borderColor = '#ef4444';
  } else {
    if (inputEl.style.borderColor === 'rgb(239, 68, 68)') inputEl.style.borderColor = '';
  }
}


/* ─── 5. REVENUE BY PROCEDURE CHART ────────────────── */
function procChart_render(containerId) {
  var el = document.getElementById(containerId||'proc-chart-container');
  if (!el) return;
  var pts = DATA.patients||[];
  var procTotals = {};
  pts.forEach(function(p) {
    (p.billing||[]).filter(function(b){ return b.paid; }).forEach(function(b) {
      var key = (b.item||'Other').split(' ')[0].split('/')[0].trim();
      if (key.length < 2) key = 'Other';
      if (!procTotals[key]) procTotals[key] = 0;
      procTotals[key] += Number(b.amount||0);
    });
  });
  var sorted = Object.entries(procTotals).sort(function(a,b){ return b[1]-a[1]; }).slice(0,10);
  if (!sorted.length) { el.innerHTML='<div style="font-size:12px;color:#94a3b8;text-align:center;padding:20px">No billing data yet</div>'; return; }
  var max = sorted[0][1];
  var colors = ['#1e3a5f','#0369a1','#0284c7','#0ea5e9','#38bdf8','#7dd3fc','#3b82f6','#6366f1','#8b5cf6','#a78bfa'];
  var html = '<div style="margin-bottom:8px;font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.5px">💰 Revenue by Procedure</div>';
  html += sorted.map(function(entry, i) {
    var pct = Math.round((entry[1]/max)*100);
    return '<div style="margin-bottom:8px">' +
      '<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:3px">' +
      '<span style="font-weight:600;color:#1e293b">'+esc(entry[0])+'</span>' +
      '<span style="font-weight:700;color:'+colors[i]+'">'+fmtMoney(entry[1])+'</span></div>' +
      '<div style="background:#f1f5f9;border-radius:4px;height:8px;overflow:hidden">' +
      '<div style="background:'+colors[i]+';height:100%;width:'+pct+'%;border-radius:4px;transition:width .5s"></div>' +
      '</div></div>';
  }).join('');
  el.innerHTML = '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:12px;padding:14px">' + html + '</div>';
}


/* ─── 7. PROFESSIONAL INVOICE GENERATOR ────────────── */
var _invoiceCounter = parseInt(localStorage.getItem('hos_invoice_num')||'1000');

function invoice_generate(ptId, billIds) {
  var pt = ptId ? (DATA.patients||[]).find(function(p){ return p.id===ptId; }) : activePt;
  if (!pt) return;
  _invoiceCounter++;
  localStorage.setItem('hos_invoice_num', String(_invoiceCounter));
  var invoiceNo = 'HOS-'+_invoiceCounter;
  var bills = billIds
    ? (pt.billing||[]).filter(function(b){ return billIds.includes(b.id); })
    : (pt.billing||[]).filter(function(b){ return b.paid; });
  if (!bills.length) { alert('No paid bills to invoice.'); return; }
  var total = bills.reduce(function(s,b){ return s+Number(b.amount||0); },0);
  var today = new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'long',year:'numeric'});

  var win = window.open('','_blank','width=700,height=900');
  win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>Invoice '+invoiceNo+'</title>');
  win.document.write('<style>');
  win.document.write('body{font-family:Arial,sans-serif;margin:0;padding:32px;color:#1a1a1a;font-size:11pt}');
  win.document.write('.header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #1e3a5f;padding-bottom:18px;margin-bottom:18px}');
  win.document.write('.clinic-name{font-size:20pt;font-weight:800;color:#1e3a5f;margin-bottom:4px}');
  win.document.write('.invoice-badge{background:#1e3a5f;color:#fff;padding:8px 18px;border-radius:8px;text-align:center}');
  win.document.write('.label{font-size:9pt;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px;font-weight:700}');
  win.document.write('table{width:100%;border-collapse:collapse;margin:18px 0}');
  win.document.write('th{background:#1e3a5f;color:#fff;padding:10px 12px;text-align:left;font-size:10pt}');
  win.document.write('td{padding:10px 12px;border-bottom:1px solid #f1f5f9;font-size:10.5pt}');
  win.document.write('tr:nth-child(even) td{background:#f8fafc}');
  win.document.write('.total-row td{font-weight:800;font-size:12pt;border-top:2px solid #1e3a5f;background:#eff6ff!important}');
  win.document.write('.footer{margin-top:32px;padding-top:18px;border-top:1px solid #e2e8f0;display:flex;justify-content:space-between;align-items:flex-end}');
  win.document.write('.seal{text-align:center;min-width:160px}');
  win.document.write('.seal-line{border-top:1.5px solid #1e3a5f;padding-top:6px;font-size:10pt;font-weight:700}');
  win.document.write('@media print{@page{margin:15mm}}');
  win.document.write('</style></head><body>');


  win.document.write('<div class="header">');
  win.document.write('<div><div class="clinic-name">'+esc(CLINIC)+'</div>');
  win.document.write('<div style="font-size:10pt;color:#374151">'+esc(DOCTOR)+' | '+esc(QUAL)+'</div>');
  win.document.write('<div style="font-size:10pt;color:#374151">Reg. No. '+esc(REG)+'</div>');
  win.document.write('<div style="font-size:9pt;color:#64748b;margin-top:4px">'+esc(PHONE)+'</div></div>');
  win.document.write('<div class="invoice-badge"><div style="font-size:8pt;letter-spacing:1px;opacity:.7">INVOICE</div><div style="font-size:16pt;font-weight:800">'+invoiceNo+'</div><div style="font-size:9pt;opacity:.7">'+today+'</div></div>');
  win.document.write('</div>');

  win.document.write('<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:18px">');
  win.document.write('<div><div class="label">Bill To</div>');
  win.document.write('<div style="font-size:13pt;font-weight:700;margin:4px 0">'+esc(pt.name)+'</div>');
  if (pt.phone) win.document.write('<div style="font-size:10pt;color:#374151">📞 '+esc(pt.phone)+'</div>');
  if (pt.address) win.document.write('<div style="font-size:9pt;color:#64748b">'+esc(pt.address)+'</div>');
  win.document.write('<div style="font-size:9pt;color:#94a3b8;margin-top:4px">Patient ID: '+esc(pt.id)+'</div></div>');
  win.document.write('<div><div class="label">Details</div>');
  win.document.write('<div style="margin-top:4px;font-size:10pt">Invoice No: <strong>'+invoiceNo+'</strong></div>');
  win.document.write('<div style="font-size:10pt">Date: <strong>'+today+'</strong></div>');
  win.document.write('<div style="font-size:10pt">Registered: '+fmtDate(pt.createdAt)+'</div></div>');
  win.document.write('</div>');

  win.document.write('<table>');
  win.document.write('<tr><th>#</th><th>Treatment / Procedure</th><th>Date</th><th style="text-align:right">Amount</th></tr>');
  bills.forEach(function(b,i) {
    win.document.write('<tr><td>'+(i+1)+'</td><td>'+esc(b.item||'Treatment')+'</td><td>'+fmtDate(b.date)+'</td><td style="text-align:right;font-weight:600">₹'+Number(b.amount).toLocaleString('en-IN')+'</td></tr>');
  });
  win.document.write('<tr class="total-row"><td colspan="3" style="text-align:right">Total</td><td style="text-align:right;color:#059669">₹'+total.toLocaleString('en-IN')+'</td></tr>');
  win.document.write('</table>');

  win.document.write('<div style="background:#ecfdf5;border-radius:8px;padding:10px 14px;font-size:11pt;font-weight:700;color:#059669;margin-bottom:18px">✅ PAID IN FULL</div>');
  win.document.write('<div class="footer"><div style="font-size:9pt;color:#94a3b8"><em>This is a computer generated invoice.</em><br/>'+esc(CLINIC)+'</div>');
  win.document.write('<div class="seal"><div class="seal-line">'+esc(DOCTOR)+'</div><div style="font-size:9pt;color:#64748b">Authorized Signatory</div></div></div>');
  win.document.write('<script>window.onload=function(){window.print();window.onafterprint=function(){window.close();};};<\/script>');
  win.document.write('</body></html>');
  win.document.close();
}


/* ─── 9. AUTO BIRTHDAY WHATSAPP ON STARTUP ──────────── */
function birthday_autoCheck() {
  var today = todayISO();
  var mm_dd  = today.slice(5); // MM-DD
  var birthdays = (DATA.patients||[]).filter(function(p) {
    if (!p.dob || !p.phone) return false;
    return p.dob.slice(5) === mm_dd;
  });
  if (!birthdays.length) return;
  var names = birthdays.map(function(p){ return p.name; }).join(', ');
  var modal = document.createElement('div');
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9990;display:flex;align-items:center;justify-content:center;padding:16px';
  var btns = birthdays.map(function(p) {
    return '<button onclick="birthday_sendSingle(\''+p.id+'\');this.style.opacity=\'0.4\';this.disabled=true" style="display:flex;align-items:center;justify-content:space-between;width:100%;background:#f8fafc;border:1.5px solid #e2e8f0;border-radius:8px;padding:10px 14px;margin-bottom:6px;cursor:pointer;font-size:13px;font-weight:600;color:#1e293b">' +
      '<span>🎂 '+esc(p.name)+'</span>' +
      '<span style="background:#25d366;color:#fff;border-radius:6px;padding:3px 10px;font-size:11px">Send 📲</span></button>';
  }).join('');
  modal.innerHTML = '<div style="background:#fff;border-radius:18px;padding:24px;max-width:360px;width:100%">' +
    '<div style="font-size:16px;font-weight:800;color:#1e293b;margin-bottom:4px">🎂 Birthday Today!</div>' +
    '<div style="font-size:12px;color:#64748b;margin-bottom:16px">'+birthdays.length+' patient'+(birthdays.length>1?'s':'')+' have a birthday today</div>' +
    btns +
    '<div style="display:flex;gap:8px;margin-top:10px">' +
    '<button onclick="birthday_sendAll(\''+birthdays.map(function(p){return p.id;}).join(',')+'\');this.closest(\'[style*=fixed]\').remove()" style="flex:1;background:#25d366;border:none;color:#fff;border-radius:8px;padding:10px;cursor:pointer;font-weight:700;font-size:13px">📲 Send All</button>' +
    '<button onclick="this.closest(\'[style*=fixed]\').remove()" style="background:#f1f5f9;border:none;color:#64748b;border-radius:8px;padding:10px;cursor:pointer;font-size:12px">Later</button>' +
    '</div></div>';
  document.body.appendChild(modal);
}

function birthday_sendSingle(ptId) {
  var p = (DATA.patients||[]).find(function(x){ return x.id===ptId; });
  if (!p||!p.phone) return;
  var nl = String.fromCharCode(10);
  var msg = '🎂 Happy Birthday, '+p.name+'!'+nl+nl+
    'Wishing you a year filled with great health and beautiful smiles! 😊'+nl+nl+
    'Warm regards,'+nl+DOCTOR+nl+CLINIC+nl+PHONE;
  window.open('https://wa.me/91'+p.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

function birthday_sendAll(idsCsv) {
  var ids = idsCsv.split(',');
  ids.forEach(function(id){ setTimeout(function(){ birthday_sendSingle(id); }, 600); });
}


/* ─── 11. APPOINTMENT 24H REMINDER AUTO-CHECK ───────── */
function appt_autoReminderCheck() {
  var tomorrow = new Date(); tomorrow.setDate(tomorrow.getDate()+1);
  var tomorrowStr = tomorrow.toISOString().slice(0,10);
  var upcoming = (DATA.appointments||[]).filter(function(a) {
    return a.date === tomorrowStr && a.status !== 'noshow' && a.status !== 'cancelled' && !a.reminded24h;
  });
  if (!upcoming.length) return;
  var modal = document.createElement('div');
  modal.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#1e3a5f;color:#fff;border-radius:14px;padding:16px 20px;z-index:9990;max-width:380px;width:90%;box-shadow:0 8px 32px rgba(0,0,0,.4)';
  modal.innerHTML = '<div style="font-size:12px;font-weight:800;color:#7dd3fc;margin-bottom:8px;text-transform:uppercase;letter-spacing:.5px">📅 '+upcoming.length+' Appointment'+(upcoming.length>1?'s':'')+' Tomorrow</div>' +
    upcoming.slice(0,3).map(function(a) {
      var pt = (DATA.patients||[]).find(function(p){ return p.id===a.patientId; });
      return '<div style="display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid rgba(255,255,255,.1)">' +
        '<span style="font-size:12px">'+(a.time||'')+'&nbsp;&nbsp;'+esc(a.patientName||'')+'</span>' +
        (pt&&pt.phone?'<button data-apptid="'+a.id+'" data-ptphone="'+pt.phone+'" data-ptname="'+esc(a.patientName||'')+'" data-time="'+esc(a.time||'')+'" onclick="appt_sendReminderFromBtn(this)" style="background:#25d366;border:none;color:#fff;border-radius:6px;padding:3px 8px;font-size:10px;cursor:pointer;flex-shrink:0">📲</button>':'') +
        '</div>';
    }).join('') +
    (upcoming.length>3?'<div style="font-size:10px;color:#94a3b8;margin-top:6px">+' + (upcoming.length-3)+' more</div>':'') +
    '<div style="display:flex;gap:8px;margin-top:10px">' +
    '<button onclick="appt_remindAllTomorrow(\''+upcoming.map(function(a){return a.id;}).join(',')+'\')" style="flex:1;background:#3b82f6;border:none;color:#fff;border-radius:8px;padding:8px;cursor:pointer;font-weight:700;font-size:11px">📲 Remind All</button>' +
    '<button onclick="this.parentNode.parentNode.remove()" style="background:rgba(255,255,255,.15);border:none;color:#fff;border-radius:8px;padding:8px 12px;cursor:pointer;font-size:11px">Dismiss</button>' +
    '</div>';
  document.body.appendChild(modal);
}

function appt_sendReminderFromBtn(btn) {
  var phone = btn.dataset.ptphone; var name = btn.dataset.ptname; var time = btn.dataset.time;
  var nl = String.fromCharCode(10);
  var msg = 'Dear '+name+','+nl+nl+
    'This is a friendly reminder for your appointment *tomorrow at '+time+'* at *'+CLINIC+'*.'+nl+nl+
    'Please confirm your attendance by replying YES.'+nl+'If you need to reschedule, call: '+PHONE+nl+nl+TIMING;
  window.open('https://wa.me/91'+phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
  // Mark reminded
  var apptIdx = (DATA.appointments||[]).findIndex(function(a){ return a.id===btn.dataset.apptid; });
  if (apptIdx>=0) { DATA.appointments[apptIdx].reminded24h=true; saveData(); }
  btn.style.opacity='0.4'; btn.disabled=true;
}

function appt_remindAllTomorrow(idsCsv) {
  var ids = idsCsv.split(',').filter(Boolean);
  ids.forEach(function(id,i) {
    setTimeout(function() {
      var btn = document.querySelector('[data-apptid="'+id+'"]');
      if (btn) appt_sendReminderFromBtn(btn);
    }, i*500);
  });
}


