function bil_updateBalance() {
  var total   = parseFloat((document.getElementById('bil-amt')||{}).value||0);
  var paidNow = parseFloat((document.getElementById('bil-paid-now')||{}).value||0);
  var preview = document.getElementById('bil-balance-preview');
  if (!preview) return;
  if (!total) { preview.style.display='none'; return; }
  preview.style.display = 'block';
  var balance = total - paidNow;
  if (balance <= 0) {
    preview.innerHTML = '✅ Fully paid — ₹'+total.toLocaleString('en-IN');
    preview.style.background='#ecfdf5'; preview.style.color='#059669';
  } else if (paidNow > 0) {
    preview.innerHTML = '⏳ Partial: ₹'+paidNow.toLocaleString('en-IN')+' paid, ₹'+balance.toLocaleString('en-IN')+' remaining';
    preview.style.background='#fffbeb'; preview.style.color='#d97706';
  } else {
    preview.innerHTML = '🔴 Nothing paid yet — ₹'+total.toLocaleString('en-IN')+' due';
    preview.style.background='#fef2f2'; preview.style.color='#dc2626';
  }
}

function bil_addPayment(billId) {
  var bill = (activePt.billing||[]).find(function(b){ return b.id===billId; });
  if (!bill) return;
  var due = Math.max(0, Number(bill.totalAmount||bill.amount||0) - Number(bill.paidAmount||0));

  /* Remove old modal if exists */
  var old = document.getElementById('bil-pay-modal');
  if (old) old.remove();

  var modal = document.createElement('div');
  modal.id = 'bil-pay-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9900;display:flex;align-items:flex-end;justify-content:center;padding:16px';

  var sheet = document.createElement('div');
  sheet.style.cssText = 'background:#fff;border-radius:20px 20px 0 0;width:100%;max-width:520px;padding:20px';
  sheet.innerHTML =
    '<div style="font-size:15px;font-weight:800;color:#1e293b;margin-bottom:4px">💰 Add Payment</div>'
    +'<div style="font-size:12px;color:#64748b;margin-bottom:16px">'+esc(bill.item)+' — Balance: ₹'+due.toLocaleString('en-IN')+'</div>'
    +'<div class="form-grid-2" style="gap:10px;margin-bottom:14px">'
    +'<div class="form-group"><label class="form-label">Amount ✱</label>'
    +'<input id="bpm-amt" type="number" class="form-input" value="'+due+'" placeholder="₹"/></div>'
    +'<div class="form-group"><label class="form-label">Mode</label>'
    +'<select id="bpm-mode" class="form-input"><option>Cash</option><option>UPI</option><option>Card</option><option>Online</option></select></div>'
    +'<div class="form-group"><label class="form-label">Date</label>'
    +'<input id="bpm-date" type="date" class="form-input" value="'+todayISO()+'"/></div>'
    +'<div class="form-group"><label class="form-label">Note</label>'
    +'<input id="bpm-note" class="form-input" placeholder="e.g. 2nd instalment"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button id="bpm-cancel" style="flex:1;background:#f1f5f9;border:none;border-radius:12px;padding:12px;font-size:13px;font-weight:700;cursor:pointer">Cancel</button>'
    +'<button id="bpm-save" style="flex:2;background:#059669;color:#fff;border:none;border-radius:12px;padding:12px;font-size:13px;font-weight:700;cursor:pointer">✅ Record Payment</button>'
    +'</div>';

  modal.appendChild(sheet);
  document.body.appendChild(modal);

  document.getElementById('bpm-cancel').addEventListener('click', function(){ modal.remove(); });
  modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });
  document.getElementById('bpm-save').addEventListener('click', function(){
    var amt  = parseFloat(document.getElementById('bpm-amt').value||0);
    var mode = document.getElementById('bpm-mode').value;
    var date = document.getElementById('bpm-date').value||todayISO();
    var note = document.getElementById('bpm-note').value||mode+' payment';
    if (!amt || amt<=0) { alert('Enter a valid amount.'); return; }

    var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
    var bIdx  = DATA.patients[ptIdx].billing.findIndex(function(b){ return b.id===billId; });
    if (bIdx<0) { modal.remove(); return; }

    var b = DATA.patients[ptIdx].billing[bIdx];
    if (!b.payments) b.payments = [];
    b.payments.push({id:'pmt'+Date.now(), amount:amt, date:date, mode:mode, note:note});
    b.paidAmount  = Math.round((Number(b.paidAmount||0) + amt) * 100) / 100;
    b.amount      = b.totalAmount||b.amount;
    b.paid        = Math.round(b.paidAmount*100) >= Math.round((b.totalAmount||b.amount||0)*100);
    b.paymentMode = mode;
    DATA.patients[ptIdx].billing[bIdx] = b;
    activePt = DATA.patients[ptIdx];
    saveData();
    modal.remove();
    renderBillingTab();
    renderPatientHeader();
    showToast && showToast('₹'+amt.toLocaleString('en-IN')+' recorded via '+mode);
  });
}

