/* ─────────────────────────────────────────────────────────
   SIDEBAR DRAG-TO-REORDER — within sections only
   Order saved per section in localStorage.
   Never moves items across section boundaries.
───────────────────────────────────────────────────────── */
var NAV_ORDER_KEY = 'hos_nav_order_v2';

function navDrag_init() {
  // Restore saved order first
  navDrag_restoreOrder();
  // Then attach drag listeners
  document.querySelectorAll('.nav-section-items').forEach(function(section) {
    section.querySelectorAll('.nav-item').forEach(function(item) {
      item.setAttribute('draggable', 'true');

      item.addEventListener('dragstart', function(e) {
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', item.id);
        e.dataTransfer.setData('text/section', section.dataset.section);
        item.classList.add('dragging');
      });

      item.addEventListener('dragend', function() {
        item.classList.remove('dragging');
        document.querySelectorAll('.nav-item').forEach(function(i) {
          i.classList.remove('drag-over');
        });
        navDrag_saveOrder();
      });

      item.addEventListener('dragover', function(e) {
        e.preventDefault();
        // Only allow drop within same section
        var srcSection = e.dataTransfer.getData('text/section');
        if (srcSection && srcSection !== section.dataset.section) return;
        item.classList.add('drag-over');
      });

      item.addEventListener('dragleave', function() {
        item.classList.remove('drag-over');
      });

      item.addEventListener('drop', function(e) {
        e.preventDefault();
        item.classList.remove('drag-over');
        var srcId = e.dataTransfer.getData('text/plain');
        var srcSection = e.dataTransfer.getData('text/section');
        // Block cross-section drops
        if (srcSection !== section.dataset.section) return;
        var draggedEl = document.getElementById(srcId);
        if (!draggedEl || draggedEl === item) return;
        // Insert before the target
        section.insertBefore(draggedEl, item);
        navDrag_saveOrder();
      });
    });
  });
}

function navDrag_saveOrder() {
  var order = {};
  document.querySelectorAll('.nav-section-items').forEach(function(section) {
    var sName = section.dataset.section;
    order[sName] = Array.from(section.querySelectorAll('.nav-item')).map(function(i) { return i.id; });
  });
  localStorage.setItem(NAV_ORDER_KEY, JSON.stringify(order));
}

function navDrag_restoreOrder() {
  var savedRaw = localStorage.getItem(NAV_ORDER_KEY);
  if (!savedRaw) return;
  try {
    var saved = JSON.parse(savedRaw);
    Object.keys(saved).forEach(function(sName) {
      var section = document.getElementById('nav-sect-' + sName);
      if (!section) return;
      var ids = saved[sName];
      ids.forEach(function(id) {
        var el = document.getElementById(id);
        if (el && el.parentNode === section) {
          section.appendChild(el); // re-append in saved order
        }
      });
    });
  } catch(e) {
    localStorage.removeItem(NAV_ORDER_KEY);
  }
}

// Init drag after DOM is ready
setTimeout(navDrag_init, 400);
