function pedo_calcDoses() {
  var wt = parseFloat((document.getElementById('pedo-weight')||{}).value||0);
  var el = document.getElementById('pedo-dose-results');
  if (!el) return;
  if (!wt || wt <= 0) { el.innerHTML='<div style="color:#94a3b8;text-align:center;padding:16px">Enter weight above</div>'; return; }

  var html = '<div style="font-size:10px;font-weight:800;color:#dc2626;background:#fef2f2;border-radius:6px;padding:6px 10px;margin-bottom:10px">&#9888; Always verify dosing. These are guide doses only. Clinical judgement required.</div>';
  html += '<table style="width:100%;border-collapse:collapse">';
  html += '<tr style="background:#1e3a5f;color:#fff"><th style="padding:6px 8px;text-align:left;font-size:10px;border-radius:4px 0 0 0">Drug</th><th style="padding:6px 8px;text-align:center;font-size:10px">Dose</th><th style="padding:6px 8px;text-align:center;font-size:10px">Freq</th><th style="padding:6px 8px;text-align:left;font-size:10px;border-radius:0 4px 0 0">Form</th></tr>';
  PEDO_DRUGS.forEach(function(drug) {
    var calcDose = Math.min(drug.dose * wt, drug.max);
    var doseStr  = calcDose % 1 === 0 ? calcDose.toFixed(0) : calcDose.toFixed(1);
    html += '<tr style="border-bottom:1px solid #f1f5f9">';
    html += '<td style="padding:7px 8px;font-weight:700;color:#1e293b;font-size:11px">'+esc(drug.name)+'</td>';
    html += '<td style="padding:7px 8px;text-align:center;font-size:12px;font-weight:800;color:#059669">'+doseStr+' mg</td>';
    html += '<td style="padding:7px 8px;text-align:center;font-size:11px;color:#374151">'+drug.freq+'</td>';
    html += '<td style="padding:7px 8px;font-size:10px;color:#64748b">'+esc(drug.form)+'<br/><span style="color:#94a3b8">'+esc(drug.note||'')+'</span></td>';
    html += '</tr>';
  });
  html += '</table>';
  html += '<div style="font-size:10px;color:#94a3b8;margin-top:8px;padding:6px;background:#f8fafc;border-radius:6px">Weight: <strong>'+wt+' kg</strong> | Doses calculated per weight</div>';
  el.innerHTML = html;
}


/* ─── 7. FEE SCHEDULE / PROCEDURE PRICE LIST ─────────────────────
   Master price list. When adding billing, auto-fill from this list.
───────────────────────────────────────────────────────────────── */
var FEE_SCHEDULE_KEY = 'hos_fee_schedule';

function feeSchedule_load() {
  var raw = localStorage.getItem(FEE_SCHEDULE_KEY);
  if (!raw) return [
    { id:'fs1', procedure:'Scaling & Polishing',        price:800,  category:'Preventive' },
    { id:'fs2', procedure:'Composite Restoration',       price:1500, category:'Restorative' },
    { id:'fs3', procedure:'RCT — Anterior',              price:3500, category:'Endodontic' },
    { id:'fs4', procedure:'RCT — Premolar',              price:4500, category:'Endodontic' },
    { id:'fs5', procedure:'RCT — Molar',                 price:5500, category:'Endodontic' },
    { id:'fs6', procedure:'PFM Crown',                   price:4500, category:'Prosthetic' },
    { id:'fs7', procedure:'Zirconia Crown',               price:8000, category:'Prosthetic' },
    { id:'fs8', procedure:'Dental Implant',              price:35000,category:'Surgical' },
    { id:'fs9', procedure:'Extraction — Simple',         price:500,  category:'Surgical' },
    { id:'fs10',procedure:'Extraction — Surgical',       price:1500, category:'Surgical' },
    { id:'fs11',procedure:'Metal Braces',                price:25000,category:'Orthodontic' },
    { id:'fs12',procedure:'Ceramic Braces',              price:35000,category:'Orthodontic' },
    { id:'fs13',procedure:'Clear Aligners',              price:60000,category:'Orthodontic' },
    { id:'fs14',procedure:'Teeth Whitening',             price:8000, category:'Cosmetic' },
    { id:'fs15',procedure:'Consultation',                price:200,  category:'General' },
  ];
  try { return JSON.parse(raw); } catch(e) { return []; }
}

function feeSchedule_save(list) {
  localStorage.setItem(FEE_SCHEDULE_KEY, JSON.stringify(list));
}

function feeSchedule_renderPage() {
  var el = document.getElementById('fee-schedule-content');
  if (!el) return;
  var list = feeSchedule_load();
  var cats = [...new Set(list.map(function(f){ return f.category; }))];

  var html = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:8px">';
  html += '<div style="font-size:13px;font-weight:800;color:#1e293b">'+list.length+' procedures</div>';
  html += '<button class="btn btn-primary btn-sm" onclick="feeSchedule_showAddForm()">+ Add Procedure</button>';
  html += '</div>';
  html += '<div id="fee-add-form" style="display:none;margin-bottom:14px"></div>';

  cats.forEach(function(cat) {
    var items = list.filter(function(f){ return f.category===cat; });
    html += '<div style="margin-bottom:16px">';
    html += '<div style="font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">'+esc(cat)+'</div>';
    items.forEach(function(f) {
      html += '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:10px 14px;margin-bottom:6px;display:flex;justify-content:space-between;align-items:center">';
      html += '<span style="font-size:13px;font-weight:600;color:#1e293b">'+esc(f.procedure)+'</span>';
      html += '<div style="display:flex;align-items:center;gap:10px">';
      html += '<span style="font-size:14px;font-weight:800;color:#059669">'+fmtMoney(f.price)+'</span>';
      html += '<button class="btn btn-sm" style="background:#eff6ff;color:#1d4ed8;font-size:10px" data-fsid="'+f.id+'" onclick="feeSchedule_editItem(this.dataset.fsid)">Edit</button>';
      html += '<button class="btn btn-sm" style="background:#fef2f2;color:#dc2626;font-size:10px" data-fsid="'+f.id+'" onclick="feeSchedule_deleteItem(this.dataset.fsid)">&#x1F5D1;</button>';
      html += '</div></div>';
    });
    html += '</div>';
  });
  el.innerHTML = html;
}

function feeSchedule_showAddForm(existingId) {
  var list = feeSchedule_load();
  var item = existingId ? list.find(function(f){ return f.id===existingId; }) : null;
  var wrap = document.getElementById('fee-add-form');
  if (!wrap) return;
  wrap.style.display = 'block';
  wrap.innerHTML = '<div class="card" style="background:#f0f9ff;border:1.5px solid #bae6fd">' +
    '<div style="font-size:12px;font-weight:800;color:#0369a1;margin-bottom:10px">'+(item?'Edit':'Add')+' Procedure</div>' +
    '<div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px;margin-bottom:8px">' +
    '<input id="fs-proc" class="form-input" placeholder="Procedure name" value="'+esc(item?item.procedure:'')+'"/>' +
    '<input id="fs-price" class="form-input" type="number" placeholder="Price (₹)" value="'+(item?item.price:'')+'"/>' +
    '<input id="fs-cat" class="form-input" list="fs-cat-list" placeholder="Category" value="'+esc(item?item.category:'General')+'"/>' +
    '<datalist id="fs-cat-list"><option>Preventive</option><option>Restorative</option><option>Endodontic</option><option>Prosthetic</option><option>Surgical</option><option>Orthodontic</option><option>Cosmetic</option><option>General</option></datalist>' +
    '</div>' +
    '<div style="display:flex;gap:8px">' +
    '<button class="btn btn-primary btn-sm" data-fsid="'+(item?item.id:'')+'" onclick="feeSchedule_saveItem(this.dataset.fsid)">&#x1F4BE; Save</button>' +
    '<button class="btn btn-sm" onclick="document.getElementById(\'fee-add-form\').style.display=\'none\'">Cancel</button>' +
    '</div></div>';
}

function feeSchedule_saveItem(editId) {
  var proc  = (document.getElementById('fs-proc')||{}).value.trim();
  var price = parseFloat((document.getElementById('fs-price')||{}).value||0);
  var cat   = (document.getElementById('fs-cat')||{}).value.trim()||'General';
  if (!proc||!price) { alert('Procedure and price required.'); return; }
  var list = feeSchedule_load();
  if (editId) {
    list = list.map(function(f){ return f.id===editId ? Object.assign({},f,{procedure:proc,price:price,category:cat}) : f; });
  } else {
    list.push({id:'fs'+Date.now(), procedure:proc, price:price, category:cat});
  }
  feeSchedule_save(list);
  document.getElementById('fee-add-form').style.display = 'none';
  feeSchedule_renderPage();
}

function feeSchedule_editItem(id) { feeSchedule_showAddForm(id); }

function feeSchedule_deleteItem(id) {
  if (!confirm('Delete this procedure from fee schedule?')) return;
  var list = feeSchedule_load().filter(function(f){ return f.id!==id; });
  feeSchedule_save(list);
  feeSchedule_renderPage();
}

// Quick-pick from fee schedule when adding billing
function feeSchedule_renderQuickPick() {
  var list = feeSchedule_load();
  var cats = [...new Set(list.map(function(f){ return f.category; }))];
  var opts = list.map(function(f) {
    return '<option data-price="'+f.price+'" value="'+esc(f.procedure)+'">'+esc(f.procedure)+' — '+fmtMoney(f.price)+'</option>';
  }).join('');
  return '<div style="margin-bottom:8px">' +
    '<label style="font-size:11px;font-weight:700;color:#64748b;display:block;margin-bottom:4px">Quick-pick from Fee Schedule</label>' +
    '<select class="form-input" id="fs-quickpick" onchange="feeSchedule_applyQuickPick()">' +
    '<option value="">— Select procedure —</option>' + opts + '</select></div>';
}

function feeSchedule_applyQuickPick() {
  var sel = document.getElementById('fs-quickpick');
  if (!sel || !sel.value) return;
  var opt = sel.options[sel.selectedIndex];
  var price = opt.getAttribute('data-price');
  var itemEl = document.getElementById('bil-item');
  var amtEl  = document.getElementById('bil-amt');
  if (itemEl) itemEl.value = sel.value;
  if (amtEl)  { amtEl.value = price; bil_updateBalance(); }
  sel.selectedIndex = 0;
}



/* ─── 9. LAB COST P&L PER PROCEDURE ─────────────────────────────
   In analytics page: revenue/lab/margin grouped by procedure name
───────────────────────────────────────────────────────────────── */
function labPL_render(containerId) {
  var el = document.getElementById(containerId||'lab-pl-container');
  if (!el) return;
  var bills = (DATA.patients||[]).flatMap(function(p){ return p.billing||[]; })
    .filter(function(b){ return b.labCost && b.labCost>0 && b.paid; });
  if (!bills.length) {
    el.innerHTML = '<div style="font-size:12px;color:#94a3b8;text-align:center;padding:12px">No lab cost data yet. Add lab costs when recording billing entries.</div>';
    return;
  }
  var byProc = {};
  bills.forEach(function(b) {
    var key = (b.item||'Other').split(' ').slice(0,3).join(' ');
    if (!byProc[key]) byProc[key] = {rev:0,lab:0,count:0};
    byProc[key].rev   += Number(b.amount||b.totalAmount||0);
    byProc[key].lab   += Number(b.labCost||0);
    byProc[key].count += 1;
  });
  var rows = Object.entries(byProc).sort(function(a,b){ return (b[1].rev-b[1].lab)-(a[1].rev-a[1].lab); });
  var totalRev = rows.reduce(function(s,r){return s+r[1].rev;},0);
  var totalLab = rows.reduce(function(s,r){return s+r[1].lab;},0);
  var totalNet = totalRev - totalLab;

  var html = '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:12px;overflow:hidden">';
  html += '<div style="background:#1e3a5f;padding:12px 16px;display:grid;grid-template-columns:2fr 1fr 1fr 1fr 60px;gap:8px">';
  ['Procedure','Revenue','Lab Cost','Net Profit','Margin'].forEach(function(h) {
    html += '<div style="font-size:10px;font-weight:700;color:#7dd3fc;text-transform:uppercase">'+h+'</div>';
  });
  html += '</div>';
  rows.forEach(function(entry, i) {
    var k=entry[0], v=entry[1];
    var net    = v.rev - v.lab;
    var margin = v.rev > 0 ? Math.round((net/v.rev)*100) : 0;
    var netCol = net > 0 ? '#059669' : '#dc2626';
    html += '<div style="display:grid;grid-template-columns:2fr 1fr 1fr 1fr 60px;gap:8px;padding:10px 16px;border-bottom:1px solid #f1f5f9;background:'+(i%2===0?'#fff':'#f8fafc')+'">';
    html += '<div style="font-size:12px;font-weight:600;color:#1e293b">'+esc(k)+'<div style="font-size:10px;color:#94a3b8">'+v.count+' cases</div></div>';
    html += '<div style="font-size:12px;font-weight:700;color:#1e293b">'+fmtMoney(v.rev)+'</div>';
    html += '<div style="font-size:12px;color:#dc2626">'+fmtMoney(v.lab)+'</div>';
    html += '<div style="font-size:12px;font-weight:800;color:'+netCol+'">'+fmtMoney(net)+'</div>';
    html += '<div style="font-size:12px;font-weight:700;color:'+netCol+'">'+margin+'%</div>';
    html += '</div>';
  });
  html += '<div style="display:grid;grid-template-columns:2fr 1fr 1fr 1fr 60px;gap:8px;padding:12px 16px;background:#eff6ff">';
  html += '<div style="font-size:12px;font-weight:800;color:#1d4ed8">TOTAL</div>';
  html += '<div style="font-size:12px;font-weight:800;color:#1e293b">'+fmtMoney(totalRev)+'</div>';
  html += '<div style="font-size:12px;font-weight:800;color:#dc2626">'+fmtMoney(totalLab)+'</div>';
  var totMargin = totalRev > 0 ? Math.round((totalNet/totalRev)*100) : 0;
  html += '<div style="font-size:12px;font-weight:800;color:#059669">'+fmtMoney(totalNet)+'</div>';
  html += '<div style="font-size:12px;font-weight:800;color:#059669">'+totMargin+'%</div>';
  html += '</div></div>';
  el.innerHTML = '<div style="font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">&#128202; Lab Cost P&L by Procedure</div>' + html;
}


/* ─── 10. EDITABLE WA MESSAGE TEMPLATES ─────────────────────────
   All WA messages stored in localStorage, editable from Settings
───────────────────────────────────────────────────────────────── */
var WA_MSG_KEY = 'hos_wa_messages';
var WA_MSG_DEFAULTS = {
  birthday:     'Dear {name},\n\n&#127874; Happy Birthday!\n\nWishing you a year of great health and beautiful smiles!\n\n&#128522; Warm regards,\n{doctor}\n{clinic}\n{phone}',
  appt_reminder:'Dear {name},\n\nThis is a friendly reminder for your appointment *tomorrow at {time}* at *{clinic}*.\n\nPlease confirm by replying YES. To reschedule, call: {phone}\n\n{timing}',
  dues_gentle:  'Dear {name},\n\nThis is a gentle reminder regarding your outstanding balance of ₹{amount} at {clinic}.\n\nKindly clear at your convenience.\n\nFor queries: {phone}',
  dues_medium:  'Dear {name},\n\nYour outstanding balance of ₹{amount} has been pending for {days} days.\n\nPlease arrange payment at your earliest.\n\n{clinic} | {phone}',
  dues_firm:    'Dear {name},\n\nYour payment of ₹{amount} has been pending for over {days} days.\n\nWe request immediate settlement.\n\n{clinic} | {phone}',
  post_rct:     'Dear {name},\n\nPost RCT care instructions:\n1. Avoid chewing on treated tooth for 24-48 hrs\n2. Mild sensitivity is normal\n3. Take prescribed painkillers if needed\n4. Crown placement recommended soon\n\nContact us: {phone}',
  tx_complete:  'Dear {name},\n\n&#127881; Congratulations on completing your {treatment} at *{clinic}*!\n\nYour dental health has improved significantly. Thank you for trusting us.\n\nDo share your experience on Google — it helps others!\n\n{doctor} | {phone}',
};

function waMsgs_load() {
  var raw = localStorage.getItem(WA_MSG_KEY);
  if (!raw) return Object.assign({}, WA_MSG_DEFAULTS);
  try { return Object.assign({}, WA_MSG_DEFAULTS, JSON.parse(raw)); }
  catch(e) { return Object.assign({}, WA_MSG_DEFAULTS); }
}

function waMsgs_get(key) {
  return waMsgs_load()[key] || WA_MSG_DEFAULTS[key] || '';
}

function waMsgs_renderPage() {
  var el = document.getElementById('wa-templates-content');
  if (!el) return;
  var msgs = waMsgs_load();
  var labels = {
    birthday:     '&#127874; Birthday Message',
    appt_reminder:'&#128197; Appointment Reminder (24h)',
    dues_gentle:  '&#128178; Dues Reminder — Gentle (<30 days)',
    dues_medium:  '&#128198; Dues Reminder — Medium (30-60 days)',
    dues_firm:    '&#128680; Dues Reminder — Firm (60+ days)',
    post_rct:     '&#129463; Post-RCT Care Instructions',
    tx_complete:  '&#9989; Treatment Completion Message',
  };
  var vars = '{name} {phone} {clinic} {doctor} {amount} {days} {time} {timing} {treatment}';

  var html = '<div style="font-size:11px;background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:8px 12px;margin-bottom:14px;color:#92400e">Available variables: <code>'+vars+'</code></div>';
  Object.entries(labels).forEach(function(entry) {
    var key = entry[0], label = entry[1];
    html += '<div class="card" style="margin-bottom:12px">';
    html += '<div style="font-size:12px;font-weight:800;color:#1e293b;margin-bottom:6px">'+label+'</div>';
    html += '<textarea id="wa-tpl-'+key+'" rows="4" class="form-input" style="font-size:11px;font-family:monospace;resize:vertical">'+esc(msgs[key]||'')+'</textarea>';
    html += '<div style="display:flex;gap:6px;margin-top:6px">';
    html += '<button class="btn btn-sm btn-primary" data-key="'+key+'" onclick="waMsgs_saveOne(this.dataset.key)">&#x1F4BE; Save</button>';
    html += '<button class="btn btn-sm" data-key="'+key+'" onclick="waMsgs_reset(this.dataset.key)">&#x21BA; Reset Default</button>';
    html += '</div></div>';
  });
  html += '<button class="btn btn-sm btn-primary" onclick="waMsgs_saveAll()" style="width:100%;margin-top:8px">&#x1F4BE; Save All Templates</button>';
  el.innerHTML = html;
}

function waMsgs_saveOne(key) {
  var el = document.getElementById('wa-tpl-'+key);
  if (!el) return;
  var msgs = waMsgs_load();
  msgs[key] = el.value;
  localStorage.setItem(WA_MSG_KEY, JSON.stringify(msgs));
  showSavedToast();
}

function waMsgs_saveAll() {
  var msgs = waMsgs_load();
  var labels = ['birthday','appt_reminder','dues_gentle','dues_medium','dues_firm','post_rct','tx_complete'];
  labels.forEach(function(key) {
    var el = document.getElementById('wa-tpl-'+key);
    if (el) msgs[key] = el.value;
  });
  localStorage.setItem(WA_MSG_KEY, JSON.stringify(msgs));
  showSavedToast();
}

function waMsgs_reset(key) {
  if (!confirm('Reset to default message?')) return;
  var msgs = waMsgs_load();
  msgs[key] = WA_MSG_DEFAULTS[key];
  localStorage.setItem(WA_MSG_KEY, JSON.stringify(msgs));
  var el = document.getElementById('wa-tpl-'+key);
  if (el) el.value = WA_MSG_DEFAULTS[key];
  showSavedToast();
}

function waMsgs_fill(template, vars) {
  return template
    .replace(/\{name\}/g,      vars.name||'')
    .replace(/\{phone\}/g,     vars.phone||PHONE)
    .replace(/\{clinic\}/g,    vars.clinic||CLINIC)
    .replace(/\{doctor\}/g,    vars.doctor||DOCTOR)
    .replace(/\{amount\}/g,    vars.amount||'')
    .replace(/\{days\}/g,      vars.days||'')
    .replace(/\{time\}/g,      vars.time||'')
    .replace(/\{timing\}/g,    vars.timing||TIMING||'')
    .replace(/\{treatment\}/g, vars.treatment||'');
}


/* ─── 12. TREATMENT COMPLETION SHARING ──────────────────────────
   After cert_print, option to also WA the patient
───────────────────────────────────────────────────────────────── */
function txComplete_shareWA(treatmentType) {
  if (!activePt || !activePt.phone) { alert('No phone number for this patient.'); return; }
  var tplRaw = waMsgs_get('tx_complete');
  var msg    = waMsgs_fill(tplRaw, {
    name:      activePt.name,
    treatment: treatmentType||'dental treatment',
    clinic:    CLINIC, doctor:DOCTOR, phone:PHONE
  });
  window.open('https://wa.me/91'+activePt.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(msg),'_blank');
}

