/* ─── 14. LAB TURNAROUND TIME ────────────────────────────────────
   Average / max / min days from sent to received per lab
───────────────────────────────────────────────────────────────── */
function labTA_render(containerId) {
  var el = document.getElementById(containerId||'lab-ta-container');
  if (!el) return;
  var jobs = (DATA.labJobs||[]).filter(function(j){
    return j.sentDate && j.receivedDate;
  });
  if (!jobs.length) {
    el.innerHTML = '<div style="font-size:12px;color:#94a3b8;text-align:center;padding:12px">No completed lab jobs yet (need sent + received dates).</div>';
    return;
  }
  var byLab = {};
  jobs.forEach(function(j) {
    var labName = j.labName || 'Unknown Lab';
    var days = Math.round((new Date(j.receivedDate+'T00:00:00') - new Date(j.sentDate+'T00:00:00')) / 86400000);
    if (days < 0) return;
    if (!byLab[labName]) byLab[labName] = {days:[], name:labName};
    byLab[labName].days.push(days);
  });

  var html = '<div style="font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">&#9200; Lab Turnaround Time</div>';
  html += '<div style="display:grid;gap:8px">';
  Object.values(byLab).sort(function(a,b){
    var avgA = a.days.reduce(function(s,d){return s+d;},0)/a.days.length;
    var avgB = b.days.reduce(function(s,d){return s+d;},0)/b.days.length;
    return avgA - avgB;
  }).forEach(function(lab) {
    var avg = (lab.days.reduce(function(s,d){return s+d;},0)/lab.days.length).toFixed(1);
    var max = Math.max.apply(null, lab.days);
    var min = Math.min.apply(null, lab.days);
    var col = avg <= 7 ? '#059669' : avg <= 14 ? '#d97706' : '#dc2626';
    html += '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:10px;padding:12px 14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">';
    html += '<div><div style="font-size:13px;font-weight:700;color:#1e293b">'+esc(lab.name)+'</div>';
    html += '<div style="font-size:10px;color:#64748b">'+lab.days.length+' job'+(lab.days.length>1?'s':'')+' completed</div></div>';
    html += '<div style="display:flex;gap:16px;text-align:center">';
    html += '<div><div style="font-size:20px;font-weight:800;color:'+col+'">'+avg+'d</div><div style="font-size:9px;color:#94a3b8">AVERAGE</div></div>';
    html += '<div><div style="font-size:16px;font-weight:700;color:#64748b">'+min+'d</div><div style="font-size:9px;color:#94a3b8">BEST</div></div>';
    html += '<div><div style="font-size:16px;font-weight:700;color:#dc2626">'+max+'d</div><div style="font-size:9px;color:#94a3b8">WORST</div></div>';
    html += '</div></div>';
  });
  html += '</div>';
  el.innerHTML = html;
}


