// Override cs_renderContent to detect chairside and simplify form
var _cs_renderContent_orig = cs_renderContent;


function cs_applyChairsideStyle() {
  // Enlarge diagnosis/treatment text
  ['cs-diag','cs-treat','cs-notes'].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) { el.style.fontSize = '16px'; el.style.padding = '12px 14px'; }
  });
  // Collapse advanced section by default in chairside
  var details = document.querySelector('#cs-content details');
  if (details) details.removeAttribute('open');
}


/* ─── 20. PATIENT VISIT FREQUENCY INSIGHT ───────────────────────
   Shows in patient list card and patient header
───────────────────────────────────────────────────────────────── */
function visitFreq_calc(pt) {
  var recs  = (pt.records||[]).filter(function(r){ return r.date; });
  var appts = (DATA.appointments||[]).filter(function(a){ return a.patientId===pt.id && a.status==='done'; });
  var total = recs.length + appts.length;
  if (!total) return { label:'Never visited', color:'#94a3b8', badge:'⚪', daysAgo:null };

  var allDates = recs.map(function(r){return r.date;}).concat(appts.map(function(a){return a.date;}));
  allDates.sort();
  var lastDate = allDates[allDates.length-1];
  var daysAgo  = Math.floor((new Date() - new Date(lastDate+'T00:00:00')) / 86400000);

  var category, color, badge;
  if (daysAgo <= 30)       { category='Active';    color='#059669'; badge='🟢'; }
  else if (daysAgo <= 90)  { category='Recent';    color='#0284c7'; badge='🔵'; }
  else if (daysAgo <= 180) { category='Irregular'; color='#d97706'; badge='🟡'; }
  else                     { category='Lapsed';    color='#dc2626'; badge='🔴'; }

  var freq = '';
  if (total >= 2) {
    var firstDate = allDates[0];
    var spanDays  = Math.floor((new Date(lastDate+'T00:00:00') - new Date(firstDate+'T00:00:00')) / 86400000);
    var perMonth  = spanDays > 0 ? (total / (spanDays/30)).toFixed(1) : total;
    freq = ' • '+perMonth+'x/mo avg';
  }

  return {
    label:    category + (daysAgo === 0 ? ' — today' : daysAgo === 1 ? ' — yesterday' : ' — '+daysAgo+'d ago') + freq,
    color:    color,
    badge:    badge,
    daysAgo:  daysAgo,
    total:    total,
    category: category,
  };
}

function visitFreq_badge(pt) {
  var info = visitFreq_calc(pt);
  return '<span style="font-size:10px;font-weight:600;color:'+info.color+';margin-left:6px">'+info.badge+' '+info.label+'</span>';
}


