  var win = window.open('','_blank','width=700,height=900');
  win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"/><title>Consent — '+esc(tpl.label)+'</title>');
  win.document.write('<style>');
  win.document.write('body{font-family:Arial,sans-serif;padding:28px;color:#1a1a1a;font-size:11pt;line-height:1.6}');
  win.document.write('.header{text-align:center;border-bottom:2px solid #1e3a5f;padding-bottom:14px;margin-bottom:18px}');
  win.document.write('.clinic-name{font-size:16pt;font-weight:800;color:#1e3a5f}');
  win.document.write('.form-title{font-size:14pt;font-weight:700;margin:16px 0 12px;color:#1e3a5f;text-align:center;text-transform:uppercase;letter-spacing:.5px}');
  win.document.write('.field-row{display:flex;align-items:baseline;gap:8px;margin-bottom:12px}');
  win.document.write('.field-label{font-weight:700;min-width:130px;color:#374151;font-size:10pt}');
  win.document.write('.field-line{flex:1;border-bottom:1.5px solid #1a1a1a;min-width:120px;height:20px}');
  win.document.write('.section-head{font-size:11pt;font-weight:800;color:#1e3a5f;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px}');
  win.document.write('.sig-block{display:flex;justify-content:space-between;margin-top:40px}');
  win.document.write('.sig-col{text-align:center;min-width:180px}');
  win.document.write('.sig-line{border-top:1.5px solid #1a1a1a;margin:0 auto 6px;width:180px}');
  win.document.write('@media print{body{padding:15px}@page{margin:15mm;size:A4 portrait}}');
  win.document.write('</style></head><body>');

  win.document.write('<div class="header">');
  win.document.write('<div class="clinic-name">'+esc(CLINIC)+'</div>');
  win.document.write('<div style="font-size:10pt;color:#64748b">'+esc(DOCTOR)+' | '+esc(QUAL)+' | Reg. '+esc(REG)+'</div>');
  win.document.write('</div>');

  win.document.write('<div class="form-title">Informed Consent — '+esc(tpl.label)+'</div>');

  win.document.write('<div class="field-row"><span class="field-label">Patient Name</span><span class="field-line">'+(pt?'<b>'+esc(pt.name)+'</b>':'')+'</span></div>');
  win.document.write('<div class="field-row"><span class="field-label">Age / Gender</span><span class="field-line">'+(pt?(esc(pt.age||'')+' '+(pt.gender||'')):'')+'</span></div>');
  win.document.write('<div class="field-row"><span class="field-label">Date</span><span class="field-line">'+today+'</span></div>');

  win.document.write('<div class="section-head">Treatment Proposed</div>');
  win.document.write('<p>'+esc(tpl.label)+'. I understand the nature, purpose, and expected benefits of this treatment as explained to me by '+esc(DOCTOR)+'.</p>');

  win.document.write('<div class="section-head">Risks and Possible Complications</div>');
  win.document.write('<div>'+riskList+'</div>');

  win.document.write('<div class="section-head">Declaration</div>');
  win.document.write('<p>I, <b>'+(pt?esc(pt.name):'______________________')+'</b>, confirm that I have been informed about the proposed treatment, its risks, alternatives, and consequences of no treatment. I have had the opportunity to ask questions and all my questions have been answered satisfactorily. I give my consent to proceed with the treatment.</p>');

  win.document.write('<div class="sig-block">');
  win.document.write('<div class="sig-col"><div class="sig-line"></div><div style="font-size:10pt">Patient / Guardian Signature</div><div style="font-size:9pt;color:#64748b">Date: ________</div></div>');
  win.document.write('<div class="sig-col"><div class="sig-line"></div><div style="font-size:10pt">'+esc(DOCTOR)+'</div><div style="font-size:9pt;color:#64748b">Treating Dentist</div></div>');
