/* ─── 6. RX PRINT CALIBRATION TOOL ──────────────────────────── */
var RX_MARGINS_KEY = 'hos_rx_margins';

function rxCalib_load() {
  var raw = localStorage.getItem(RX_MARGINS_KEY);
  try { return raw ? JSON.parse(raw) : { top:47, bottom:38, left:14, right:12 }; }
  catch(e) { return { top:47, bottom:38, left:14, right:12 }; }
}

function rxCalib_save(m) {
  localStorage.setItem(RX_MARGINS_KEY, JSON.stringify(m));
}

function rxCalib_showTool() {
  var m = rxCalib_load();
  var modal = document.createElement('div');
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.65);z-index:9990;display:flex;align-items:center;justify-content:center;padding:16px';
  modal.innerHTML = '<div style="background:#fff;border-radius:18px;padding:24px;max-width:420px;width:100%">' +
    '<div style="font-size:16px;font-weight:800;color:#1e293b;margin-bottom:6px">🖨️ Rx Print Calibration</div>' +
    '<div style="font-size:11px;color:#64748b;margin-bottom:16px;background:#fffbeb;border-radius:8px;padding:8px 12px">Adjust margins to match your pre-printed Rx pad. Print the test grid, hold it against your pad, adjust until the content area lines up.</div>' +

    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px">' +
    '<div><label style="font-size:11px;font-weight:700;color:#374151">Top margin (mm)<br/><span style="color:#64748b;font-weight:400">Header height on pad</span></label>' +
    '<div style="display:flex;align-items:center;gap:8px;margin-top:6px">' +
    '<input id="cal-top" type="range" min="20" max="80" value="'+m.top+'" style="flex:1" oninput="rxCalib_updatePreview()"/>' +
    '<span id="cal-top-val" style="font-weight:700;font-size:13px;min-width:35px">'+m.top+'mm</span></div></div>' +

    '<div><label style="font-size:11px;font-weight:700;color:#374151">Bottom margin (mm)<br/><span style="color:#64748b;font-weight:400">Footer height on pad</span></label>' +
    '<div style="display:flex;align-items:center;gap:8px;margin-top:6px">' +
    '<input id="cal-bot" type="range" min="15" max="60" value="'+m.bottom+'" style="flex:1" oninput="rxCalib_updatePreview()"/>' +
    '<span id="cal-bot-val" style="font-weight:700;font-size:13px;min-width:35px">'+m.bottom+'mm</span></div></div>' +

    '<div><label style="font-size:11px;font-weight:700;color:#374151">Left margin (mm)</label>' +
    '<div style="display:flex;align-items:center;gap:8px;margin-top:6px">' +
    '<input id="cal-left" type="range" min="5" max="40" value="'+m.left+'" style="flex:1" oninput="rxCalib_updatePreview()"/>' +
    '<span id="cal-left-val" style="font-weight:700;font-size:13px;min-width:35px">'+m.left+'mm</span></div></div>' +

    '<div><label style="font-size:11px;font-weight:700;color:#374151">Right margin (mm)</label>' +
    '<div style="display:flex;align-items:center;gap:8px;margin-top:6px">' +
    '<input id="cal-right" type="range" min="5" max="40" value="'+m.right+'" style="flex:1" oninput="rxCalib_updatePreview()"/>' +
    '<span id="cal-right-val" style="font-weight:700;font-size:13px;min-width:35px">'+m.right+'mm</span></div></div>' +
    '</div>' +

    '<div id="cal-preview" style="background:#f0f4fa;border-radius:10px;padding:10px;text-align:center;font-size:11px;color:#374151;margin-bottom:12px">Top: '+m.top+'mm | Bottom: '+m.bottom+'mm | Left/Right: '+m.left+'/'+m.right+'mm</div>' +

    '<div style="display:flex;gap:8px">' +
    '<button onclick="rxCalib_printTest()" style="flex:1;background:#1e3a5f;border:none;color:#fff;border-radius:8px;padding:10px;cursor:pointer;font-weight:700;font-size:12px">🖨️ Print Test Grid</button>' +
    '<button onclick="rxCalib_applySave()" style="flex:1;background:#059669;border:none;color:#fff;border-radius:8px;padding:10px;cursor:pointer;font-weight:700;font-size:12px">✅ Save Margins</button>' +
    '<button onclick="rxCalib_reset(this)" style="background:#f1f5f9;border:none;color:#64748b;border-radius:8px;padding:10px;cursor:pointer;font-size:11px">↺ Reset</button>' +
    '<button onclick="this.closest(\'[style*=position:fixed]\').remove()" style="background:#f1f5f9;border:none;color:#64748b;border-radius:8px;padding:10px;cursor:pointer;font-size:11px">✕</button>' +
    '</div></div>';
  document.body.appendChild(modal);
}

function rxCalib_updatePreview() {
  var top   = (document.getElementById('cal-top')||{}).value||46;
  var bot   = (document.getElementById('cal-bot')||{}).value||38;
  var left   = (document.getElementById('cal-left')||{}).value||14;
  var right = (document.getElementById('cal-right')||{}).value||14;
  var tv=document.getElementById('cal-top-val');   if(tv) tv.textContent=top+'mm';
  var bv=document.getElementById('cal-bot-val');   if(bv) bv.textContent=bot+'mm';
  var lv=document.getElementById('cal-left-val');  if(lv) lv.textContent=left+'mm';
  var rv=document.getElementById('cal-right-val'); if(rv) rv.textContent=right+'mm';
  var prev=document.getElementById('cal-preview');
  if(prev) prev.textContent='Top: '+top+'mm | Bottom: '+bot+'mm | Left: '+left+'mm | Right: '+right+'mm';
}

function rxCalib_getValues() {
  return {
    top:    parseInt((document.getElementById('cal-top')||{}).value||46),
    bottom: parseInt((document.getElementById('cal-bot')||{}).value||38),
    left:   parseInt((document.getElementById('cal-left')||{}).value||14),
    right:    parseInt((document.getElementById('cal-right')||{}).value||14)
  };
}

function rxCalib_applySave() {
  rxCalib_save(rxCalib_getValues());
  showSavedToast();
  var modal = document.querySelector('[style*="position:fixed"][style*="z-index:9990"]');
  if (modal) modal.remove();
}

function rxCalib_reset(btn) {
  rxCalib_save({top:47,bottom:38,left:14,right:12});
  var m = {top:47,bottom:38,left:14,right:12};
  ['top','bot','left','right'].forEach(function(k) {
    var el = document.getElementById('cal-'+k); if(el) el.value = k==='bot'?m.bottom:m[k];
  });
  rxCalib_updatePreview();
  showSavedToast();
}

function rxCalib_printTest() {
  var m = rxCalib_getValues();
  var win = window.open('','_blank','width=700,height=900');
  win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"/>');
  win.document.write('<style>@page{size:A4 portrait;margin:'+m.top+'mm '+m.right+'mm '+m.bottom+'mm '+m.left+'mm}');
  win.document.write('body{margin:0;font-family:Arial,sans-serif;font-size:10pt}');
  win.document.write('.content-area{border:2px dashed #1e3a5f;min-height:80px;padding:12px;background:repeating-linear-gradient(45deg,#f8fafc,#f8fafc 10px,#eff6ff 10px,#eff6ff 20px)}');
  win.document.write('.label{font-size:9pt;color:#64748b;margin-bottom:4px}');
  win.document.write('</style></head><body>');
  win.document.write('<p style="font-size:8pt;color:#94a3b8;text-align:center;margin-bottom:8px">CALIBRATION TEST — Top:'+m.top+'mm Bottom:'+m.bottom+'mm Left:'+m.left+'mm Right:'+m.right+'mm</p>');
  win.document.write('<div class="content-area">');
  win.document.write('<div class="label">▲ This box should align with the WRITABLE AREA of your Rx pad (below the header, above the footer)</div>');
  win.document.write('<div style="margin-top:20px;font-size:10pt;color:#374151">Sample content area — Patient Name, Date, Medicines will appear here.<br/><br/>If this box does not align with your pad, adjust the margins and print again.</div>');
  win.document.write('<div style="margin-top:30px;border-top:1px dashed #94a3b8;padding-top:8px;font-size:8pt;color:#94a3b8">Bottom edge of content area ▼</div>');
  win.document.write('</div>');
  win.document.write('<script>window.onload=function(){window.print();window.onafterprint=function(){window.close();};};<\/script>');
  win.document.write('</body></html>');
  win.document.close();
}


