/* ─── A. LAB ENTRY EDIT ──────────────────────────────────── */
function lab_editJob(jobId) {
  var j = (DATA.labJobs||[]).find(function(x){ return x.id===jobId; });
  if (!j) return;
  // Populate the form at top of page
  var set = function(id,val){ var el=document.getElementById(id); if(el) el.value=val||''; };
  set('lab-pt',       j.patientName||'');
  set('lab-name',     j.labName||'');
  set('lab-worktype', j.workType||'Crown');
  set('lab-cost',     j.cost||'');
  set('lab-sent',     j.sentDate||'');
  set('lab-due',      j.dueDate||'');
  set('lab-notes',    j.notes||'');
  // Mark form as edit mode
  var btn = document.getElementById('lab-save-btn');
  if (btn) { btn.textContent='💾 Update Lab Job'; btn.setAttribute('data-editid', jobId); }
  // Scroll to top of lab page
  var el = document.getElementById('lab-list');
  if (el) el.scrollIntoView({behavior:'smooth', block:'start'});
}

function lab_saveJob() {
  var pt    = (document.getElementById('lab-pt')||{}).value.trim();
  var name  = (document.getElementById('lab-name')||{}).value.trim();
  var wtype = (document.getElementById('lab-worktype')||{}).value||'Crown';
  var cost  = (document.getElementById('lab-cost')||{}).value||0;
  var sent  = (document.getElementById('lab-sent')||{}).value||todayISO();
  var due   = (document.getElementById('lab-due')||{}).value||'';
  var notes = (document.getElementById('lab-notes')||{}).value||'';
  if (!pt||!name) { alert('Patient name and lab name required.'); return; }

  var btn    = document.getElementById('lab-save-btn');
  var editId = btn ? btn.getAttribute('data-editid') : null;

  // Find patient id
  var ptMatch = (DATA.patients||[]).find(function(p){ return p.name.toLowerCase()===pt.toLowerCase(); });

  if (editId) {
    DATA.labJobs = (DATA.labJobs||[]).map(function(j) {
      if (j.id!==editId) return j;
      return Object.assign({},j,{patientName:pt,patientId:ptMatch?ptMatch.id:j.patientId,labName:name,workType:wtype,cost:Number(cost),sentDate:sent,dueDate:due,notes:notes});
    });
    if (btn) { btn.textContent='💾 Save Lab Job'; btn.removeAttribute('data-editid'); }
  } else {
    if (!DATA.labJobs) DATA.labJobs=[];
    DATA.labJobs.push({id:'lab'+Date.now(),patientName:pt,patientId:ptMatch?ptMatch.id:'',labName:name,workType:wtype,cost:Number(cost),sentDate:sent,dueDate:due,notes:notes,status:'Sent to Lab'});
  }
  // Clear form
  ['lab-pt','lab-name','lab-cost','lab-due','lab-notes'].forEach(function(id){ var el=document.getElementById(id); if(el) el.value=''; });
  var se=document.getElementById('lab-sent'); if(se) se.value=todayISO();
  saveData(); lab_render();
}


/* ─── B. PROCEDURE TIMERS ────────────────────────────────────
   Quick-tap countdown timers for common chairside procedures
   Shown as a compact timer strip inside the record form
─────────────────────────────────────────────────────────── */
var procTimer_active = null;   // {id, seconds, remaining, intervalId}

function procTimer_renderStrip() {
  var TIMERS = [
    { id:'etch',  label:'Etch',    secs:30, color:'#dc2626', bg:'#fef2f2', icon:'🧪' },
    { id:'bond',  label:'Bond',    secs:20, color:'#7c3aed', bg:'#f5f3ff', icon:'💧' },
    { id:'cure',  label:'L-Cure',  secs:20, color:'#059669', bg:'#ecfdf5', icon:'💡' },
    { id:'hypo',  label:'NaOCl',   secs:30, color:'#0284c7', bg:'#eff6ff', icon:'🧫' },
    { id:'edta',  label:'EDTA',    secs:60, color:'#d97706', bg:'#fffbeb', icon:'⚗️' },
    { id:'set',   label:'Set/Wait',secs:90, color:'#64748b', bg:'#f8fafc', icon:'⏳' },
  ];
  var html = '<div id="proc-timer-strip" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:8px 10px;margin-bottom:8px">';
  html += '<div style="font-size:9px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">⏱ Quick Timers</div>';
  html += '<div style="display:flex;gap:6px;flex-wrap:wrap">';
  TIMERS.forEach(function(t) {
    html += '<button id="ptbtn-'+t.id+'" style="background:'+t.bg+';color:'+t.color+';border:1.5px solid '+t.color+'30;border-radius:8px;padding:5px 10px;cursor:pointer;font-size:11px;font-weight:700;display:flex;align-items:center;gap:4px" '+
      'data-tid="'+t.id+'" data-secs="'+t.secs+'" data-label="'+t.label+'" '+
      'onclick="procTimer_start(this.dataset.tid,parseInt(this.dataset.secs),this.dataset.label,this)">'+
      t.icon+' '+t.label+' <span style="opacity:.7">'+t.secs+'s</span></button>';
  });
  html += '</div>';
  html += '<div id="proc-timer-display" style="display:none;margin-top:8px;display:none"></div>';
  html += '</div>';
  return html;
}

function procTimer_start(id, secs, label, btn) {
  // Clear any running timer
  if (procTimer_active && procTimer_active.intervalId) {
    clearInterval(procTimer_active.intervalId);
    // Reset old button
    var oldBtn = document.getElementById('ptbtn-'+procTimer_active.id);
    if (oldBtn) oldBtn.style.opacity='1';
  }
  var display = document.getElementById('proc-timer-display');
  if (!display) return;
  display.style.display = 'block';
  var remaining = secs;
  if (btn) btn.style.opacity = '.5';

  procTimer_active = { id:id, secs:secs, remaining:remaining, intervalId:null };

  var update = function() {
    if (!document.getElementById('proc-timer-display')) {
      clearInterval(procTimer_active.intervalId);
      return;
    }
    remaining--;
    procTimer_active.remaining = remaining;
    if (remaining <= 0) {
      clearInterval(procTimer_active.intervalId);
      procTimer_doneSound();
    display.innerHTML = '<div style="background:#059669;color:#fff;border-radius:8px;padding:8px 12px;text-align:center;font-weight:800;font-size:13px">✅ '+label+' done! ('+secs+'s)</div>';
      if (btn) btn.style.opacity='1';
      // Auto-hide after 3s
      setTimeout(function(){ if(display) display.style.display='none'; }, 3000);
      return;
    }
    var pct = Math.round(((secs-remaining)/secs)*100);
    var color = remaining<=5?'#dc2626':remaining<=10?'#d97706':'#1d4ed8';
    display.innerHTML = '<div style="display:flex;align-items:center;gap:10px">' +
      '<div style="font-size:22px;font-weight:800;color:'+color+';min-width:44px">'+remaining+'s</div>' +
      '<div style="flex:1"><div style="font-size:11px;font-weight:700;color:#374151">'+label+' timer</div>' +
      '<div style="background:#e2e8f0;border-radius:4px;height:6px;overflow:hidden;margin-top:4px"><div style="background:'+color+';height:100%;width:'+pct+'%;transition:width .9s linear;border-radius:4px"></div></div></div>' +
      '<button onclick="procTimer_stop()" style="background:#fef2f2;border:none;color:#dc2626;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:11px;font-weight:700">Stop</button></div>';
  };
  update();
  procTimer_active.intervalId = setInterval(update, 1000);
}

function procTimer_stop() {
  if (procTimer_active && procTimer_active.intervalId) {
    clearInterval(procTimer_active.intervalId);
    var btn = document.getElementById('ptbtn-'+procTimer_active.id);
    if (btn) btn.style.opacity='1';
  }
  var display = document.getElementById('proc-timer-display');
  if (display) display.style.display='none';
  procTimer_active = null;
}


/* ─── C. RCT ENTRY EDIT ──────────────────────────────────── */
function rct_editCase(rctId) {
  var rct = (activePt ? (activePt.rctLog||[]) : []).find(function(r){ return r.id===rctId; });
  if (!rct) return;

  // Show the add form
  rct_showAddForm();
  setTimeout(function() {
    var set = function(id,val){ var el=document.getElementById(id); if(el) el.value=val||''; };
    set('rct-tooth',       rct.toothNo||'');
    set('rct-date',        rct.date||todayISO());
    set('rct-technique',   rct.technique||'');
    set('rct-sealer',      rct.sealer||'');
    set('rct-obturation',  rct.obturationDate||'');
    set('rct-notes',       rct.notes||'');
    // Canals
    (rct.canals||[]).forEach(function(canal, i) {
      var nameEl = document.getElementById('rct-canal-'+i+'-name');
      var wlEl   = document.getElementById('rct-canal-'+i+'-wl');
      var mafEl  = document.getElementById('rct-canal-'+i+'-maf');
      if (nameEl) nameEl.value = canal.name||'';
      if (wlEl)   wlEl.value   = canal.wl||'';
      if (mafEl)  mafEl.value  = canal.maf||'';
    });
    // Mark as edit
    var saveBtn = document.getElementById('rct-save-btn');
    if (saveBtn) { saveBtn.setAttribute('data-editid', rctId); saveBtn.textContent='💾 Update RCT Case'; }
  }, 100);
}

function rct_delete(rctId) {
  if (!confirm('Delete this RCT case? Cannot be undone.')) return;
  var idx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  DATA.patients[idx].rctLog = (DATA.patients[idx].rctLog||[]).filter(function(r){ return r.id!==rctId; });
  activePt = DATA.patients[idx];
  saveData(); rct_renderTracker();
}


/* ─── D. DAY VIEW APPOINTMENT CALENDAR ──────────────────── */
var calDayView = null;

function dayView_nav(dir) {
  if (!calDayView) calDayView = todayISO();
  var d = new Date(calDayView+'T00:00:00');
  d.setDate(d.getDate() + parseInt(dir));
  calDayView = d.toISOString().slice(0,10);
  renderAppointments();
}

function appt_setStatus(apptId, status) {
  var idx = (DATA.appointments||[]).findIndex(function(a){ return a.id===apptId; });
  if (idx<0) return;
  DATA.appointments[idx].status = status;
  saveData(); renderAppointments();
  if (status==='done') {
    var a = DATA.appointments[idx];
    var pt = (DATA.patients||[]).find(function(p){ return p.id===a.patientId; });
    if (pt && confirm('✅ Done — '+pt.name+'\n\nAdd clinical record now?')) {
      openPatient(a.patientId);
      setTimeout(function(){ switchTab('records'); }, 200);
    }
  }
}

function showApptFormForDate(date, time) {
  showApptForm();
  setTimeout(function(){
    var de=document.getElementById('appt-date'); if(de) de.value=date;
    var te=document.getElementById('appt-time'); if(te&&time) te.value=time;
  }, 50);
}

function _renderDayView(appts) {
  if (!calDayView) calDayView = todayISO();
  var viewDate = calDayView;
  var today    = todayISO();
  var d = new Date(viewDate+'T00:00:00');
  var dateLabel = d.toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  var isToday   = (viewDate===today);

  var SLOTS = [];
  for (var h=10;h<13;h++){ SLOTS.push(h+':00'); SLOTS.push(h+':30'); }
  SLOTS.push('break');
  for (var h=17;h<20;h++){ SLOTS.push(h+':00'); SLOTS.push(h+':30'); }

  var dayAppts = (appts||[]).filter(function(a){ return a.date===viewDate; });
  var slotMap  = {};
  dayAppts.forEach(function(a) {
    var t = a.time||'10:00';
    var tM = (function(s){ var p=s.split(':').map(Number); return p[0]*60+(p[1]||0); })(t);
    var near = SLOTS.filter(function(s){return s!=='break';}).reduce(function(best,slot){
      var sM=(function(s){var p=s.split(':').map(Number);return p[0]*60+(p[1]||0);})(slot);
      var bM=(function(s){var p=s.split(':').map(Number);return p[0]*60+(p[1]||0);})(best);
      return Math.abs(sM-tM)<Math.abs(bM-tM)?slot:best;
    },SLOTS[0]);
    if(!slotMap[near]) slotMap[near]=[];
    slotMap[near].push(a);
  });

  var fmt12=function(t){if(!t)return'';var p=t.split(':').map(Number);return((p[0]%12)||12)+':'+(p[1]<10?'0':'')+p[1]+' '+(p[0]>=12?'PM':'AM');};
  var sCol=function(s){return s==='done'?'#059669':s==='inchair'?'#7c3aed':s==='arrived'?'#0284c7':s==='noshow'?'#dc2626':'#94a3b8';};
  var sLbl=function(s){return s==='done'?'✅ Done':s==='inchair'?'🪑 In Chair':s==='arrived'?'✔ Arrived':s==='noshow'?'❌ No Show':'⏳ Scheduled';};

  var h = '<div style="max-width:520px;margin:0 auto">';
  h += '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">';
  h += '<button class="btn btn-sm" data-dir="-1" onclick="dayView_nav(this.dataset.dir)">‹ Prev</button>';
  h += '<div style="text-align:center"><div style="font-size:13px;font-weight:800;color:#1e293b">'+dateLabel+'</div>';
  h += '<div style="font-size:11px;color:#64748b">'+dayAppts.length+' appt'+(dayAppts.length!==1?'s':'')+(isToday?' • Today':'')+'</div></div>';
  h += '<button class="btn btn-sm" data-dir="1" onclick="dayView_nav(this.dataset.dir)">Next ›</button>';
  h += '</div>';

  SLOTS.forEach(function(slot) {
    if (slot==='break') {
      h += '<div style="display:flex;align-items:center;gap:8px;margin:6px 0"><div style="flex:1;height:1px;background:#e2e8f0"></div><span style="font-size:10px;color:#94a3b8">☀ Lunch 1–5 PM</span><div style="flex:1;height:1px;background:#e2e8f0"></div></div>';
      return;
    }
    var sa = slotMap[slot]||[];
    var empty = sa.length===0;
    h += '<div style="display:flex;gap:8px;margin-bottom:5px;align-items:flex-start">';
    h += '<div style="width:50px;flex-shrink:0;text-align:right;padding-top:10px"><span style="font-size:10px;font-weight:700;color:'+(empty?'#cbd5e1':'#374151')+'">'+fmt12(slot)+'</span></div>';
    if (empty) {
      h += '<div style="flex:1;height:34px;border:1px dashed #e2e8f0;border-radius:8px;cursor:pointer" onclick="showApptFormForDate(\''+viewDate+'\',\''+slot+'\')" title="Add at '+fmt12(slot)+'"></div>';
    } else {
      h += '<div style="flex:1;display:flex;flex-direction:column;gap:4px">';
      sa.forEach(function(a) {
        var sc=sCol(a.status||'');
        h += '<div style="background:#fff;border:1.5px solid '+sc+';border-left:4px solid '+sc+';border-radius:10px;padding:8px 12px">';
        h += '<div style="font-size:13px;font-weight:700;color:#1e293b">'+esc(a.patientName||'')+'</div>';
        if (a.notes) h += '<div style="font-size:11px;color:#64748b">'+esc(a.notes)+'</div>';
        h += '<div style="font-size:10px;font-weight:700;color:'+sc+';margin:4px 0">'+sLbl(a.status||'')+'</div>';
        h += '<div style="display:flex;gap:4px;flex-wrap:wrap">';
        if (!a.status||a.status==='')      h += '<button class="btn btn-sm" style="font-size:10px;background:#e0f2fe;color:#0284c7;border:none" data-aid="'+a.id+'" onclick="appt_setStatus(this.dataset.aid,\'arrived\')">✔ Arrived</button>';
        if (a.status==='arrived')           h += '<button class="btn btn-sm" style="font-size:10px;background:#ede9fe;color:#7c3aed;border:none" data-aid="'+a.id+'" onclick="appt_setStatus(this.dataset.aid,\'inchair\')">🪑 In Chair</button>';
        if (a.status==='arrived'||a.status==='inchair') {
          h += '<button class="btn btn-sm" style="font-size:10px;background:#ecfdf5;color:#059669;border:none" data-aid="'+a.id+'" onclick="appt_setStatus(this.dataset.aid,\'done\')">✅ Done</button>';
          h += '<button class="btn btn-sm" style="font-size:10px;background:#fef2f2;color:#dc2626;border:none" data-aid="'+a.id+'" onclick="appt_setStatus(this.dataset.aid,\'noshow\')">❌ No Show</button>';
        }
        if (a.patientId) h += '<button class="btn btn-sm" style="font-size:10px;background:#f8fafc;color:#374151;border:1px solid #e2e8f0" data-ptid="'+a.patientId+'" onclick="openPatient(this.dataset.ptid)">👁 Open</button>';
        h += '</div></div>';
      });
      h += '</div>';
    }
    h += '</div>';
  });

  var done=dayAppts.filter(function(a){return a.status==='done';}).length;
  var inC =dayAppts.filter(function(a){return a.status==='inchair';}).length;
  var wait=dayAppts.filter(function(a){return a.status==='arrived';}).length;
  if (dayAppts.length) {
    h += '<div style="margin-top:12px;background:#1e293b;border-radius:12px;padding:12px 14px;display:flex;justify-content:space-between;color:#fff">';
    h += '<div><div style="font-size:10px;color:#94a3b8">Done</div><div style="font-size:18px;font-weight:800;color:#34d399">'+done+'/'+dayAppts.length+'</div></div>';
    h += '<div><div style="font-size:10px;color:#94a3b8">In Chair</div><div style="font-size:18px;font-weight:800;color:#a78bfa">'+inC+'</div></div>';
    h += '<div><div style="font-size:10px;color:#94a3b8">Waiting</div><div style="font-size:18px;font-weight:800;color:#60a5fa">'+wait+'</div></div>';
    h += '</div>';
  }
  h += '</div>';
  return h;
}


/* ─── E. SMART MORNING BRIEF ─────────────────────────────── */
function dash_renderMorningBrief() {
  var el = document.getElementById('morning-brief');
  if (!el) return;
  var today = todayISO();
  var now   = new Date();

  var todayAppts = (DATA.appointments||[])
    .filter(function(a){ return a.date===today && a.status!=='noshow'; })
    .sort(function(a,b){ return (a.time||'').localeCompare(b.time||''); });

  var done    = todayAppts.filter(function(a){ return a.status==='done'; }).length;
  var total   = todayAppts.length;
  var inChair = todayAppts.find(function(a){ return a.status==='inchair'; });
  var arrived = todayAppts.find(function(a){ return a.status==='arrived'; });

  var h = '';
  var active = inChair||arrived;
  if (active) {
    var ac = active.status==='inchair'?'#7c3aed':'#0284c7';
    var ns = active.status==='inchair'?'done':'inchair';
    h += '<div style="background:'+ac+';border-radius:14px;padding:14px 16px;margin-bottom:10px;color:#fff;cursor:pointer" data-aid="'+active.id+'" data-ns="'+ns+'" onclick="appt_setStatus(this.dataset.aid,this.dataset.ns)">';
    h += '<div style="font-size:10px;font-weight:700;opacity:.7;text-transform:uppercase">'+(active.status==='inchair'?'🪑 In Chair — tap to mark done':'✔ Arrived — tap to seat')+'</div>';
    h += '<div style="font-size:18px;font-weight:800;margin-top:2px">'+esc(active.patientName||'')+'</div>';
    if (active.notes) h += '<div style="font-size:11px;opacity:.8;margin-top:2px">'+esc(active.notes)+'</div>';
    h += '</div>';
  }

  if (total>0) {
    var n12=function(t){if(!t)return'';var p=t.split(':').map(Number);return((p[0]%12)||12)+':'+(p[1]<10?'0':'')+p[1]+(p[0]>=12?'p':'a');};
    h += '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:14px;padding:12px 14px;margin-bottom:10px">';
    h += '<div style="display:flex;justify-content:space-between;margin-bottom:8px">';
    h += '<span style="font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase">📅 Today</span>';
    h += '<span style="font-size:11px;color:#059669;font-weight:700">'+done+'/'+total+' done</span></div>';
    todayAppts.slice(0,5).forEach(function(a) {
      var sc=a.status==='done'?'#059669':a.status==='inchair'?'#7c3aed':a.status==='arrived'?'#0284c7':'#cbd5e1';
      h += '<div style="display:flex;align-items:center;gap:8px;padding:4px 0;border-bottom:1px solid #f8fafc">';
      h += '<span style="font-size:10px;color:#94a3b8;min-width:30px">'+n12(a.time)+'</span>';
      h += '<div style="width:6px;height:6px;border-radius:50%;background:'+sc+';flex-shrink:0"></div>';
      h += '<span style="font-size:12px;font-weight:600;color:#1e293b;flex:1">'+esc(a.patientName||'')+'</span>';
      h += '</div>';
    });
    if (total>5) h += '<div style="font-size:10px;color:#94a3b8;margin-top:4px">+'+(total-5)+' more</div>';
    h += '</div>';
  }

  var lastBackup = localStorage.getItem('hos_last_backup');
  var days = lastBackup ? Math.floor((Date.now()-new Date(lastBackup+'T00:00:00'))/86400000) : 999;
  if (days>3) {
    h += '<div style="display:flex;align-items:center;gap:10px;background:#fef2f2;border:1px solid #fca5a5;border-radius:10px;padding:10px 12px;margin-bottom:6px;cursor:pointer" onclick="goPage(\'backup\')">';
    h += '<span>💾</span><span style="font-size:12px;font-weight:600;color:#dc2626">'+(days>900?'No backup on record':'Last backup '+days+' days ago — back up now')+'</span></div>';
  }

  el.innerHTML = h;
}


/* ─── F. SIDEBAR FOOTER ──────────────────────────────────── */
function sidebar_renderFooter() {
  var el = document.getElementById('sidebar-footer');
  if (!el) return;
  var lastBackup = localStorage.getItem('hos_last_backup');
  var bText, bColor;
  if (!lastBackup) { bText='⚠ Never backed up'; bColor='#dc2626'; }
  else {
    var days=Math.floor((Date.now()-new Date(lastBackup+'T00:00:00'))/86400000);
    bText  = days===0?'✅ Backed up today':days===1?'📁 Yesterday':days<=3?'📁 '+days+'d ago':'⚠ '+days+'d — backup now';
    bColor = days<=1?'#059669':days<=3?'#d97706':'#dc2626';
  }
  el.innerHTML = '<div style="border-top:1px solid rgba(255,255,255,.06);padding:10px 12px;font-size:10px">'
    +'<div style="display:flex;justify-content:space-between;margin-bottom:3px">'
    +'<span style="font-weight:700;color:#94a3b8">v68</span>'
    +'<span style="color:#64748b">'+((DATA.patients||[]).length)+' patients</span>'
    +'</div>'
    +'<div style="font-weight:600;color:'+bColor+';cursor:pointer" onclick="goPage(\'backup\')">'+bText+'</div>'
    +'</div>';
}


