var _painVal = null, _reliefVal = null;
var PAIN_LABELS = ['No pain','Barely noticeable','Mild','Annoying','Moderate','Distressing','Intense','Very intense','Severe','Unbearable','Worst possible'];
var RELIEF_LABELS = ['No relief','Minimal relief','Some relief','Good relief','Full relief'];

function painScale_selectPain(val, type) {
  _painVal = val;
  for (var i=0; i<=10; i++) {
    var btn = document.getElementById('pain-btn-'+i);
    if (!btn) continue;
    var col = i<=3?'#059669':i<=6?'#d97706':'#dc2626';
    btn.style.background = (i===val) ? col : '#f8fafc';
    btn.style.color      = (i===val) ? '#fff' : '#374151';
    btn.style.borderColor= (i===val) ? col : '#e2e8f0';
  }
  var lbl = document.getElementById('pain-label');
  if (lbl) { var col=val<=3?'#059669':val<=6?'#d97706':'#dc2626'; lbl.textContent='Pain: '+val+'/10 — '+(PAIN_LABELS[val]||''); lbl.style.color=col; }
}

function painScale_selectRelief(val) {
  _reliefVal = val;
  var colors = ['#dc2626','#d97706','#d97706','#059669','#059669'];
  for (var j=0; j<5; j++) {
    var btn = document.getElementById('relief-btn-'+j);
    if (!btn) continue;
    btn.style.background  = (j===val) ? colors[j] : '#f8fafc';
    btn.style.color       = (j===val) ? '#fff' : '#374151';
    btn.style.borderColor = (j===val) ? colors[j] : '#e2e8f0';
  }
  var lbl = document.getElementById('relief-label');
  if (lbl) { lbl.textContent='Relief: '+(RELIEF_LABELS[val]||''); lbl.style.color=colors[val]||'#059669'; }
}

function painScale_getValues() {
  return { pain: _painVal, relief: _reliefVal };
}

function painScale_reset() { _painVal=null; _reliefVal=null; }
/* ═══════════════════════════════════════════════════════════
   PROCEDURE TIME TRACKER
   - Live stopwatch in record form (Start/Stop)
   - Saves startTime, endTime, durationMins to record
   - Analytics: revenue per hour per procedure type
═══════════════════════════════════════════════════════════ */

/* ─── LIVE STOPWATCH IN RECORD FORM ─────────────────────── */
var procTrack_startTs  = null;   // epoch ms when started
var procTrack_intervalId = null; // setInterval id for display

function procTrack_renderWidget() {
  return '<div id="proc-track-widget" style="background:linear-gradient(135deg,#0f172a 0%,#1e3a5f 100%);border-radius:14px;padding:14px 16px;margin-bottom:12px;color:#fff">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px">'
    + '<div style="flex:1;min-width:0">'
    + '<div style="font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px">⏱ Procedure Timer</div>'
    + '<div id="proc-track-display" style="font-size:32px;font-weight:800;font-family:monospace;color:#34d399;letter-spacing:2px;line-height:1.2">00:00</div>'
    + '<div id="proc-track-status" style="font-size:11px;color:#64748b;margin-top:2px">Tap Start when you begin • or enter time manually below</div>'
    + '</div>'
    + '<div style="display:flex;flex-direction:column;gap:6px;align-items:flex-end">'
    + '<button id="proc-track-start-btn" onclick="procTrack_start()" style="background:#059669;border:none;color:#fff;border-radius:10px;padding:10px 20px;cursor:pointer;font-weight:800;font-size:13px;min-width:90px">▶ Start</button>'
    + '<button id="proc-track-stop-btn" onclick="procTrack_stop()" style="background:#dc2626;border:none;color:#fff;border-radius:10px;padding:10px 20px;cursor:pointer;font-weight:800;font-size:13px;min-width:90px;display:none">⏹ Stop</button>'
    + '</div>'
    + '</div>'
    + '<div id="proc-track-result" style="display:none;margin-top:10px;border-top:1px solid rgba(255,255,255,.1);padding-top:10px">'
    + '<div id="proc-track-summary" style="font-size:12px;color:#94a3b8"></div>'
    + '</div>'
    /* Manual entry section — always visible */
    + '<div style="margin-top:10px;border-top:1px solid rgba(255,255,255,.08);padding-top:10px">'
    + '<div style="font-size:10px;font-weight:700;color:#64748b;margin-bottom:6px">✏️ Enter manually if timer wasn\'t used:</div>'
    + '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
    /* Option A: simple minutes */
    + '<div style="display:flex;align-items:center;gap:6px;background:rgba(255,255,255,.06);border-radius:8px;padding:6px 10px;flex:1;min-width:130px">'
    + '<label style="font-size:11px;color:#94a3b8;white-space:nowrap">Duration:</label>'
    + '<input id="proc-manual-mins" type="number" min="1" max="480" placeholder="e.g. 25" style="background:transparent;border:none;color:#fff;font-size:13px;font-weight:700;width:60px;outline:none;text-align:center"/>'
    + '<span style="font-size:11px;color:#64748b">min</span>'
    + '</div>'
    /* Option B: start + end time */
    + '<div style="display:flex;align-items:center;gap:4px;background:rgba(255,255,255,.06);border-radius:8px;padding:6px 10px;flex:1;min-width:160px">'
    + '<input id="proc-manual-start" type="time" style="background:transparent;border:none;color:#94a3b8;font-size:12px;width:80px;outline:none" oninput="procTrack_calcManual()"/>'
    + '<span style="font-size:10px;color:#475569">→</span>'
    + '<input id="proc-manual-end" type="time" style="background:transparent;border:none;color:#94a3b8;font-size:12px;width:80px;outline:none" oninput="procTrack_calcManual()"/>'
    + '</div>'
    + '<div id="proc-manual-result" style="font-size:11px;color:#34d399;font-weight:700"></div>'
    + '</div>'
    + '</div>'
    + '</div>';
}

/* Auto-calculate duration when start+end time entered */
function procTrack_calcManual() {
  var s = (document.getElementById('proc-manual-start')||{}).value;
  var e = (document.getElementById('proc-manual-end')||{}).value;
  if (!s || !e) return;
  var sp = s.split(':').map(Number);
  var ep = e.split(':').map(Number);
  var startMins = sp[0]*60+(sp[1]||0);
  var endMins   = ep[0]*60+(ep[1]||0);
  if (endMins <= startMins) { endMins += 24*60; } /* overnight edge case */
  var diff = endMins - startMins;
  if (diff > 0 && diff < 480) {
    var minsEl = document.getElementById('proc-manual-mins');
    if (minsEl) minsEl.value = diff;
    var res = document.getElementById('proc-manual-result');
    if (res) res.textContent = diff + ' min';
  }
}


function procTrack_start() {
  procTrack_startTs = Date.now();
  var startBtn = document.getElementById('proc-track-start-btn');
  var stopBtn  = document.getElementById('proc-track-stop-btn');
  var status   = document.getElementById('proc-track-status');
  if (startBtn) startBtn.style.display = 'none';
  if (stopBtn)  stopBtn.style.display  = 'block';
  if (status)   status.textContent = '🔴 Recording... procedure in progress';

  procTrack_intervalId = setInterval(function() {
    var el = document.getElementById('proc-track-display');
    if (!el || !procTrack_startTs) { clearInterval(procTrack_intervalId); return; }
    var elapsed = Math.floor((Date.now() - procTrack_startTs) / 1000);
    var m = Math.floor(elapsed / 60);
    var s = elapsed % 60;
    el.textContent = String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');
    // Color: green → amber at 30min → red at 60min
    el.style.color = elapsed < 1800 ? '#34d399' : elapsed < 3600 ? '#fbbf24' : '#f87171';
  }, 1000);
}

function procTrack_stop() {
  if (!procTrack_startTs) return;
  procTrack_doneSound();
  clearInterval(procTrack_intervalId);
  var endTs       = Date.now();
  var durationMs  = endTs - procTrack_startTs;
  var durationMin = Math.round(durationMs / 60000);
  var durationSec = Math.floor(durationMs / 1000);
  var m = Math.floor(durationSec / 60);
  var s = durationSec % 60;
  var timeStr = String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');

  var startBtn = document.getElementById('proc-track-start-btn');
  var stopBtn  = document.getElementById('proc-track-stop-btn');
  var display  = document.getElementById('proc-track-display');
  var result   = document.getElementById('proc-track-result');
  var summary  = document.getElementById('proc-track-summary');
  var status   = document.getElementById('proc-track-status');

  if (startBtn) startBtn.style.display = 'block';
  if (stopBtn)  stopBtn.style.display  = 'none';
  if (result)   result.style.display   = 'block';
  if (status)   status.textContent     = '✅ Procedure complete — ' + timeStr + ' recorded';

  // Revenue estimate based on billing tab
  var pts     = DATA.patients||[];
  var allBills= pts.flatMap(function(p){ return (p.billing||[]); });
  var rph     = durationMin > 0 ? Math.round((allBills.reduce(function(s,b){return s+Number(b.totalAmount||b.amount||0);},0) / Math.max(1,pts.length)) / (durationMin/60)) : 0;

  if (summary) {
    summary.innerHTML =
      '<div style="display:flex;gap:16px;flex-wrap:wrap">' +
      '<div><div style="font-size:9px;color:#94a3b8;text-transform:uppercase">Duration</div>' +
      '<div style="font-size:16px;font-weight:800;color:#fff">' + timeStr + '</div></div>' +
      '<div><div style="font-size:9px;color:#94a3b8;text-transform:uppercase">Minutes</div>' +
      '<div style="font-size:16px;font-weight:800;color:#fbbf24">' + durationMin + 'm</div></div>' +
      '</div>' +
      '<div style="font-size:10px;color:#64748b;margin-top:6px">Duration saved with this record automatically</div>';
  }

  // Store for saveRecord to pick up
  window._procTrack_result = {
    startTs:      procTrack_startTs,
    endTs:        endTs,
    durationMins: durationMin,
    durationSecs: durationSec
  };
  procTrack_startTs = null;
}

function procTrack_getResult() {
  return window._procTrack_result || null;
}

function procTrack_reset() {
  clearInterval(procTrack_intervalId);
  procTrack_startTs   = null;
  window._procTrack_result = null;
}

/* ─── EFFICIENCY ANALYTICS ──────────────────────────────────
   Revenue per hour per procedure type.
   Uses: records with durationMins + billing items matching diagnosis.
─────────────────────────────────────────────────────────── */
function procEfficiency_render(containerId) {
  var el = document.getElementById(containerId || 'proc-efficiency-container');
  if (!el) return;

  var pts = DATA.patients || [];

  /* Build: for each record that has durationMins, find matching billing entry */
  var byProc = {};

  pts.forEach(function(p) {
    (p.records || []).forEach(function(r) {
      if (!r.durationMins || r.durationMins < 1) return;
      // Match billing entry by date (same day) or diagnosis keyword
      var matchedBill = null;
      (p.billing || []).forEach(function(b) {
        if ((b.date || '').slice(0,10) === (r.date || '').slice(0,10)) {
          if (!matchedBill || (b.totalAmount || b.amount || 0) > (matchedBill.totalAmount || matchedBill.amount || 0)) {
            matchedBill = b;
          }
        }
      });

      // Categorise by first keyword of diagnosis or treatment
      var rawKey = (r.diagnosis || r.treatment || 'Other');
      var key = rawKey.split(/[\s,.\-]/)[0].trim();
      // Smart mapping
      var keyMap = {
        'Root':'RCT', 'RCT':'RCT', 'Endo':'RCT', 'Obturation':'RCT', 'Canal':'RCT',
        'Scaling':'Scaling', 'Polishing':'Scaling', 'Cleaning':'Scaling',
        'Composite':'Composite', 'Filling':'Composite', 'Restoration':'Composite',
        'Crown':'Crown', 'Cap':'Crown', 'Ceramic':'Crown', 'Zirconia':'Crown',
        'Extraction':'Extraction', 'Exo':'Extraction', 'Extracted':'Extraction',
        'Implant':'Implant',
        'Consultation':'Consultation', 'Consult':'Consultation', 'Review':'Consultation',
        'Braces':'Orthodontic', 'Aligner':'Orthodontic', 'Ortho':'Orthodontic',
        'Deep':'Deep Caries', 'Caries':'Deep Caries',
        'Temporary':'Temp Filling',
      };
      var cat = keyMap[key] || rawKey.split(' ').slice(0,2).join(' ');

      if (!byProc[cat]) byProc[cat] = { count:0, totalMins:0, totalRev:0, sessions:[] };
      var rev = matchedBill ? Number(matchedBill.totalAmount || matchedBill.amount || 0) : 0;
      byProc[cat].count++;
      byProc[cat].totalMins += r.durationMins;
      byProc[cat].totalRev  += rev;
      byProc[cat].sessions.push({ mins: r.durationMins, rev: rev, date: r.date });
    });
  });

  var rows = Object.entries(byProc).filter(function(e){ return e[1].totalMins > 0; });

  if (!rows.length) {
    el.innerHTML =
      '<div style="background:#f8fafc;border:1.5px dashed #e2e8f0;border-radius:12px;padding:20px;text-align:center">' +
      '<div style="font-size:24px;margin-bottom:8px">⏱</div>' +
      '<div style="font-size:13px;font-weight:700;color:#374151">No timed procedures yet</div>' +
      '<div style="font-size:11px;color:#94a3b8;margin-top:4px">Use the ▶ Start / ⏹ Stop timer in the clinical record form to track procedure duration. Revenue per hour will appear here.</div>' +
      '</div>';
    return;
  }

  /* Sort by revenue per hour descending */
  rows.sort(function(a, b) {
    var rphA = a[1].totalMins > 0 ? (a[1].totalRev / a[1].totalMins) * 60 : 0;
    var rphB = b[1].totalMins > 0 ? (b[1].totalRev / b[1].totalMins) * 60 : 0;
    return rphB - rphA;
  });

  var totalMins = rows.reduce(function(s,r){ return s+r[1].totalMins; }, 0);
  var totalRev  = rows.reduce(function(s,r){ return s+r[1].totalRev; }, 0);
  var overallRph = totalMins > 0 ? Math.round((totalRev / totalMins) * 60) : 0;

  var maxRph = rows.reduce(function(mx, r) {
    var rph = r[1].totalMins>0 ? (r[1].totalRev/r[1].totalMins)*60 : 0;
    return Math.max(mx, rph);
  }, 1);

  var html = '<div style="background:linear-gradient(135deg,#0f172a,#1e3a5f);border-radius:14px;padding:16px;margin-bottom:14px;color:#fff;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">';
  html += '<div><div style="font-size:10px;color:#94a3b8;text-transform:uppercase;font-weight:700">Overall Efficiency</div>';
  html += '<div style="font-size:28px;font-weight:800;color:#34d399">₹'+overallRph.toLocaleString('en-IN')+'/hr</div>';
  html += '<div style="font-size:11px;color:#64748b">'+totalMins+' min tracked · '+rows.length+' procedure types</div></div>';
  html += '<div style="text-align:right"><div style="font-size:10px;color:#94a3b8">Total Revenue Tracked</div>';
  html += '<div style="font-size:20px;font-weight:800;color:#fbbf24">'+fmtMoney(totalRev)+'</div></div>';
  html += '</div>';

  html += '<div style="display:flex;flex-direction:column;gap:8px">';
  rows.forEach(function(entry, rank) {
    var name = entry[0];
    var d    = entry[1];
    var avgMins = Math.round(d.totalMins / d.count);
    var rph     = Math.round((d.totalRev / d.totalMins) * 60);
    var rphPct  = Math.round((rph / maxRph) * 100);
    var avgRev  = Math.round(d.totalRev / d.count);
    var rphCol  = rph >= overallRph * 1.2 ? '#34d399' : rph >= overallRph * 0.8 ? '#fbbf24' : '#f87171';
    var medal   = rank === 0 ? '🥇' : rank === 1 ? '🥈' : rank === 2 ? '🥉' : '';

    html += '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:12px;padding:12px 14px">';
    html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;margin-bottom:8px;flex-wrap:wrap">';
    html += '<div style="flex:1"><div style="font-size:13px;font-weight:700;color:#1e293b">'+medal+' '+esc(name)+'</div>';
    html += '<div style="font-size:11px;color:#64748b">'+d.count+' case'+(d.count>1?'s':'')+' · avg '+avgMins+'m · avg rev '+fmtMoney(avgRev)+'</div></div>';
    html += '<div style="text-align:right;flex-shrink:0">';
    html += '<div style="font-size:20px;font-weight:800;color:'+rphCol+'">₹'+rph.toLocaleString('en-IN')+'<span style="font-size:11px;font-weight:600">/hr</span></div>';
    html += '</div></div>';
    // Progress bar
    html += '<div style="background:#f1f5f9;border-radius:4px;height:6px;overflow:hidden">';
    html += '<div style="background:'+rphCol+';height:100%;width:'+rphPct+'%;border-radius:4px;transition:width .4s"></div>';
    html += '</div>';
    // Mini stats row
    html += '<div style="display:flex;gap:14px;margin-top:6px;flex-wrap:wrap">';
    html += '<span style="font-size:10px;color:#94a3b8">⏱ '+Math.round(d.totalMins/60*10)/10+' hrs total chair time</span>';
    if (avgMins < 20) html += '<span style="font-size:10px;color:#059669;font-weight:700">⚡ High volume procedure</span>';
    if (rph > overallRph * 1.3) html += '<span style="font-size:10px;color:#059669;font-weight:700">💰 Best revenue/hr</span>';
    if (rph < overallRph * 0.6) html += '<span style="font-size:10px;color:#dc2626;font-weight:700">⚠ Low yield — review pricing</span>';
    html += '</div></div>';
  });
  html += '</div>';

  el.innerHTML = '<div style="font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">⏱ Revenue Per Hour — Procedure Efficiency</div>' + html;
}


/* ═══════════════════════════════════════════════════════════
   v69: Occlusion / Bite Notes + Communication History
═══════════════════════════════════════════════════════════ */

/* ─── OCCLUSION / BITE NOTES ─────────────────────────────── */
var OCC_FINDINGS = [
  /* Skeletal / Bite */
  { t:'Deep bite',    v:'Deep bite noted', cat:'Bite' },
  { t:'Open bite',    v:'Anterior open bite noted', cat:'Bite' },
  { t:'Crossbite',    v:'Posterior crossbite wrt #__', cat:'Bite' },
  { t:'Edge to edge', v:'Edge to edge occlusion', cat:'Bite' },
  { t:'Class II',     v:'Skeletal Class II tendency', cat:'Bite' },
  { t:'Class III',    v:'Skeletal Class III tendency', cat:'Bite' },
  /* Wear */
  { t:'Attrition',    v:'Generalised attrition noted — occlusal wear', cat:'Wear' },
  { t:'Erosion',      v:'Dental erosion noted — dietary/GERD query', cat:'Wear' },
  { t:'Abrasion',     v:'Cervical abrasion wrt #__ — toothbrush technique discussed', cat:'Wear' },
  { t:'Abfraction',   v:'Abfraction lesion wrt #__ — occlusal overload', cat:'Wear' },
  /* Parafunction */
  { t:'Bruxism',      v:'Bruxism suspected — wear facets noted', cat:'Parafunction' },
  { t:'Clenching',    v:'Clenching habit reported by patient', cat:'Parafunction' },
  { t:'Mouth breathing', v:'Mouth breathing noted — narrow arch', cat:'Parafunction' },
  /* Specific */
  { t:'Overjet ↑',    v:'Increased overjet — approx __ mm', cat:'Specific' },
  { t:'Midline shift',v:'Midline shift — __mm to __ side', cat:'Specific' },
  { t:'TMJ click',    v:'TMJ click noted on opening', cat:'Specific' },
];

function occ_renderStrip() {
  var cats = ['Bite','Wear','Parafunction','Specific'];
  var html = '<div id="occ-wrap" style="background:#f0f9ff;border:1.5px solid #bae6fd;border-radius:12px;margin-bottom:10px;overflow:hidden">';
  html += '<div style="display:flex;align-items:center;padding:7px 12px;border-bottom:1px solid #bae6fd">';
  html += '<span style="font-size:10px;font-weight:800;color:#0369a1;text-transform:uppercase;letter-spacing:.5px">🦷 Occlusion / Bite Notes</span>';
  html += '</div>';

  /* Tab row — data-cat avoids escaping */
  html += '<div style="display:flex;border-bottom:1px solid #bae6fd;overflow-x:auto;scrollbar-width:none">';
  cats.forEach(function(cat, idx) {
    var active = idx === 0;
    html += '<button data-cat="'+cat+'" onclick="occ_showCat(this.dataset.cat)" id="occ-tab-'+cat+'"'
          + ' style="padding:5px 12px;border:none;background:'+(active?'#fff':'#f0f9ff')+';font-size:10px;font-weight:700;color:'+(active?'#0369a1':'#64748b')+';cursor:pointer;white-space:nowrap;border-bottom:'+(active?'2px solid #0369a1':'none')+';flex-shrink:0">'
          + cat + '</button>';
  });
  html += '</div>';

  /* Panels — each finding uses data-key registry */
  cats.forEach(function(cat, idx) {
    var items = OCC_FINDINGS.filter(function(f){ return f.cat===cat; });
    html += '<div id="occ-panel-'+cat+'" style="padding:8px 10px;display:'+(idx===0?'flex':'none')+';flex-wrap:wrap;gap:5px">';
    items.forEach(function(f) {
      var k = _tplStore({ v: f.v });
      html += '<button data-tkey="'+k+'" onclick="occ_insertByKey(this.dataset.tkey)"'
            + ' style="background:#fff;border:1px solid #7dd3fc;border-radius:8px;padding:4px 10px;cursor:pointer;font-size:11px;font-weight:600;color:#0369a1"'
            + '>'
            + f.t + '</button>';
    });
    html += '</div>';
  });
  html += '</div>';
  return html;
}

function occ_showCat(cat) {
  var cats = ['Bite','Wear','Parafunction','Specific'];
  cats.forEach(function(c) {
    var panel = document.getElementById('occ-panel-'+c);
    var tab   = document.getElementById('occ-tab-'+c);
    if (panel) panel.style.display = (c===cat)?'flex':'none';
    if (tab) {
      tab.style.background   = (c===cat)?'#fff':'#f0f9ff';
      tab.style.color        = (c===cat)?'#0369a1':'#64748b';
      tab.style.borderBottom = (c===cat)?'2px solid #0369a1':'none';
    }
  });
}

function occ_insert(text) {
  // Append to existing occlusion field or notes
  var occEl = document.getElementById('rec-occlusion');
  if (occEl) {
    var cur = occEl.value.trim();
    occEl.value = cur ? cur + '. ' + text : text;
    occEl.focus();
    var hp = occEl.value.lastIndexOf('__');
    if (hp >= 0) occEl.setSelectionRange(hp, hp+2);
    return;
  }
  // Fallback: append to notes with Occ: prefix
  var notesEl = document.getElementById('rec-notes');
  if (notesEl) {
    var cur2 = notesEl.value.trim();
    notesEl.value = cur2 ? cur2 + '\nOcc: ' + text : 'Occ: ' + text;
  }
}


/* ─── PATIENT COMMUNICATION HISTORY ──────────────────────── */
var COMM_TYPES = [
  { id:'risks',     label:'⚠️ Explained Risks',         color:'#dc2626', bg:'#fef2f2' },
  { id:'costs',     label:'💰 Discussed Costs',          color:'#d97706', bg:'#fffbeb' },
  { id:'declined',  label:'🚫 Patient Declined',         color:'#7c3aed', bg:'#f5f3ff' },
  { id:'consent',   label:'✅ Consent Obtained',         color:'#059669', bg:'#ecfdf5' },
  { id:'queried',   label:'❓ Patient Queried',          color:'#0284c7', bg:'#eff6ff' },
  { id:'advised',   label:'📋 Treatment Advised',        color:'#374151', bg:'#f8fafc' },
  { id:'followup',  label:'📅 Follow-up Discussed',      color:'#0369a1', bg:'#f0f9ff' },
  { id:'other',     label:'📝 Other',                    color:'#64748b', bg:'#f8fafc' },
];

function commLog_render() {
  var el = document.getElementById('tab-content-commlog');
  if (!el || !activePt) return;
  var log = (activePt.commLog || []).slice().sort(function(a,b){ return (b.ts||0)-(a.ts||0); });

  var typeOpts = COMM_TYPES.map(function(t){
    return '<option value="'+t.id+'">'+t.label+'</option>';
  }).join('');

  var html = '<div style="padding:8px 0">';

  // Add entry form
  html += '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:14px;padding:14px 16px;margin-bottom:14px">';
  html += '<div style="font-size:12px;font-weight:800;color:#1e293b;margin-bottom:10px">+ Log Communication</div>';
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">';
  html += '<select id="comm-type" class="form-input" style="font-size:12px">'+typeOpts+'</select>';
  html += '<input id="comm-date" type="date" class="form-input" value="'+todayISO()+'" style="font-size:12px"/>';
  html += '</div>';
  html += '<textarea id="comm-notes" class="form-input" rows="2" style="font-size:12px;resize:none;margin-bottom:8px" placeholder="Details — e.g. Explained risk of nerve damage during extraction. Patient acknowledged and signed consent."></textarea>';
  // Quick-fill buttons
  html += '<div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px">';
  var quickFills = [
    'Risks of procedure explained in detail',
    'Cost of treatment discussed — patient agreed',
    'Patient declined recommended treatment',
    'Informed consent obtained before procedure',
    'Alternatives discussed — patient chose current plan',
    'Patient expressed concern about pain — reassured',
  ];
  quickFills.forEach(function(q) {
    html += '<button onclick="commLog_quickFill('+JSON.stringify(q)+')" '+
      'style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;padding:3px 8px;cursor:pointer;font-size:10px;color:#374151" '+
      'onmouseover="this.style.background=\'#eff6ff\'" onmouseout="this.style.background=\'#f8fafc\'">'+q.split(' ').slice(0,3).join(' ')+'…</button>';
  });
  html += '</div>';
  html += '<button onclick="commLog_save()" class="btn btn-primary btn-sm" style="font-size:12px">💾 Save Entry</button>';
  html += '<button onclick="refusal_openModal()" class="btn btn-sm" style="background:#7c3aed;color:#fff;border:none;font-size:12px;margin-left:6px">✍️ Refusal Signature</button>';
  html += '</div>';

  // Log entries
  if (!log.length) {
    html += '<div style="text-align:center;padding:20px;color:#94a3b8">';
    html += '<div style="font-size:24px;margin-bottom:6px">📋</div>';
    html += '<div style="font-size:12px;font-weight:700">No communication logged yet</div>';
    html += '<div style="font-size:11px;margin-top:4px">Log every significant discussion — risks, costs, refusals. Protects you legally.</div>';
    html += '</div>';
  } else {
    log.forEach(function(entry) {
      var ct = COMM_TYPES.find(function(t){ return t.id===entry.type; }) || COMM_TYPES[COMM_TYPES.length-1];
      var dt = entry.date ? new Date(entry.date+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}) : '';
      var timeStr = entry.ts ? new Date(entry.ts).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}) : '';
      html += '<div style="background:'+ct.bg+';border:1.5px solid '+ct.color+'20;border-left:4px solid '+ct.color+';border-radius:12px;padding:12px 14px;margin-bottom:8px">';
      html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:6px">';
      html += '<span style="font-size:11px;font-weight:800;color:'+ct.color+'">'+ct.label+'</span>';
      html += '<span style="font-size:10px;color:#94a3b8">'+dt+(timeStr?' · '+timeStr:'')+'</span>';
      html += '</div>';
      if (entry.notes) html += '<div style="font-size:12px;color:#374151;margin-top:6px;line-height:1.5">'+esc(entry.notes)+'</div>';
      if (entry.sig) html += '<img src="'+entry.sig+'" style="width:120px;border:1px solid #e2e8f0;border-radius:6px;margin-bottom:6px"/>';
      html += '<div style="display:flex;justify-content:flex-end;margin-top:6px">';
      html += '<button onclick="commLog_delete(\''+entry.id+'\')" style="background:none;border:none;font-size:10px;color:#94a3b8;cursor:pointer" title="Delete">🗑</button>';
      html += '</div></div>';
    });
  }
  html += '</div>';
  el.innerHTML = html;
}

function commLog_quickFill(text) {
  var el = document.getElementById('comm-notes');
  if (el) el.value = text;
}

function commLog_save() {
  var type  = (document.getElementById('comm-type')||{}).value || 'other';
  var date  = (document.getElementById('comm-date')||{}).value || todayISO();
  var notes = ((document.getElementById('comm-notes')||{}).value||'').trim();
  if (!notes) { alert('Please enter details about the communication.'); return; }

  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  if (ptIdx < 0) return;
  if (!DATA.patients[ptIdx].commLog) DATA.patients[ptIdx].commLog = [];

  DATA.patients[ptIdx].commLog.push({
    id:    'cl'+Date.now(),
    type:  type,
    date:  date,
    ts:    Date.now(),
    notes: notes,
    doctor: DOCTOR,
  });

  activePt = DATA.patients[ptIdx];
  saveData();
  commLog_render();
  showSavedToast();
}

function commLog_delete(entryId) {
  if (!confirm('Delete this communication entry? This cannot be undone.')) return;
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  DATA.patients[ptIdx].commLog = (DATA.patients[ptIdx].commLog||[]).filter(function(e){ return e.id!==entryId; });
  activePt = DATA.patients[ptIdx];
  saveData(); commLog_render();
}


/* ═══════════════════════════════════════════════════════════
   v69c: Treatment Refusal Signature + Redo/Failure Tracker
═══════════════════════════════════════════════════════════ */

/* ─── TREATMENT REFUSAL SIGNATURE ───────────────────────────
   Opens a modal with:
   - Treatment description
   - Patient acknowledgment checkbox
   - Digital signature canvas
   Saves to patient.commLog with type:'refusal' + sig data URL
─────────────────────────────────────────────────────────── */
function refusal_openModal() {
  if (!activePt) { alert('Open a patient first.'); return; }
  var modal = document.getElementById('refusal-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'refusal-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:9990;display:flex;align-items:center;justify-content:center;padding:16px;overflow-y:auto';
    document.body.appendChild(modal);
  }
  modal.style.display = 'flex';
  modal.innerHTML =
    '<div style="background:#fff;border-radius:18px;padding:22px;max-width:460px;width:100%">' +

    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">' +
    '<div>' +
    '<div style="font-size:15px;font-weight:800;color:#7c3aed">🚫 Treatment Refusal</div>' +
    '<div style="font-size:11px;color:#64748b">Patient: <strong>'+esc(activePt.name)+'</strong></div>' +
    '</div>' +
    '<button onclick="document.getElementById(\'refusal-modal\').style.display=\'none\'" style="background:#f1f5f9;border:none;border-radius:50%;width:32px;height:32px;cursor:pointer;font-size:16px">✕</button>' +
    '</div>' +

    '<div class="form-group" style="margin-bottom:10px">' +
    '<label class="form-label">Treatment Refused *</label>' +
    '<input id="ref-treatment" class="form-input" placeholder="e.g. Root Canal Treatment wrt #46"/>' +
    '</div>' +

    '<div class="form-group" style="margin-bottom:10px">' +
    '<label class="form-label">Advised By</label>' +
    '<input id="ref-advised-by" class="form-input" value="'+esc(DOCTOR)+'" style="color:#64748b"/>' +
    '</div>' +

    '<div style="background:#fef2f2;border:1.5px solid #fca5a5;border-radius:10px;padding:12px;margin-bottom:12px">' +
    '<div style="font-size:12px;font-weight:700;color:#dc2626;margin-bottom:8px">⚠️ Patient Declaration</div>' +
    '<div style="font-size:11px;color:#374151;line-height:1.7">I, <strong>'+esc(activePt.name)+'</strong>, have been explained the risks of declining the above treatment including but not limited to: pain, infection, tooth loss, and spread to adjacent teeth. I understand these risks and choose to refuse the recommended treatment.</div>' +
    '<label style="display:flex;align-items:flex-start;gap:8px;margin-top:10px;cursor:pointer">' +
    '<input type="checkbox" id="ref-acknowledge" style="margin-top:2px;accent-color:#dc2626"/> ' +
    '<span style="font-size:11px;font-weight:700;color:#dc2626">I confirm I understand and refuse the recommended treatment</span>' +
    '</label>' +
    '</div>' +

    '<div style="margin-bottom:12px">' +
    '<div style="font-size:11px;font-weight:700;color:#374151;margin-bottom:6px">Patient Signature</div>' +
    '<canvas id="ref-sig-canvas" width="400" height="140" style="border:2px solid #e2e8f0;border-radius:10px;width:100%;background:#f8fafc;touch-action:none;cursor:crosshair"></canvas>' +
    '<div style="display:flex;gap:6px;margin-top:6px">' +
    '<button onclick="refusal_clearSig()" style="background:#f1f5f9;border:none;border-radius:6px;padding:5px 12px;cursor:pointer;font-size:11px;color:#64748b">Clear Signature</button>' +
    '<span style="font-size:10px;color:#94a3b8;margin-left:auto;padding-top:6px">Sign with finger/stylus</span>' +
    '</div>' +
    '</div>' +

    '<button onclick="refusal_save()" style="width:100%;background:#7c3aed;border:none;color:#fff;border-radius:10px;padding:12px;cursor:pointer;font-weight:800;font-size:13px">💾 Save Signed Refusal</button>' +
    '</div>';

  // Attach drawing to canvas
  setTimeout(function() {
    var canvas = document.getElementById('ref-sig-canvas');
    if (!canvas) return;
    var ctx  = canvas.getContext('2d');
    var draw = false, lx=0, ly=0;
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth   = 2;
    ctx.lineCap     = 'round';

    var getPos = function(e, el) {
      var r = el.getBoundingClientRect();
      var t = e.touches ? e.touches[0] : e;
      return { x: (t.clientX-r.left) * (el.width/r.width), y: (t.clientY-r.top) * (el.height/r.height) };
    };
    var down = function(e){ e.preventDefault(); draw=true; var p=getPos(e,canvas); lx=p.x; ly=p.y; };
    var move = function(e){ e.preventDefault(); if(!draw) return; var p=getPos(e,canvas); ctx.beginPath(); ctx.moveTo(lx,ly); ctx.lineTo(p.x,p.y); ctx.stroke(); lx=p.x; ly=p.y; };
    var up   = function(){ draw=false; };
    canvas.addEventListener('mousedown', down);
    canvas.addEventListener('mousemove', move);
    canvas.addEventListener('mouseup',   up);
    canvas.addEventListener('touchstart',down,{passive:false});
    canvas.addEventListener('touchmove', move,{passive:false});
    canvas.addEventListener('touchend',  up);
  }, 50);
}

function refusal_clearSig() {
  var canvas = document.getElementById('ref-sig-canvas');
  if (canvas) canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);
}

function refusal_save() {
  var treatment = (document.getElementById('ref-treatment')||{}).value.trim();
  var ack       = (document.getElementById('ref-acknowledge')||{}).checked;
  var canvas    = document.getElementById('ref-sig-canvas');
  if (!treatment) { alert('Please enter the treatment that was refused.'); return; }
  if (!ack) { alert('Patient must check the acknowledgment box.'); return; }

  // Check if signature is drawn (non-blank canvas)
  var ctx = canvas ? canvas.getContext('2d') : null;
  var isSigned = false;
  if (ctx) {
    var px = ctx.getImageData(0,0,canvas.width,canvas.height).data;
    for (var i=3; i<px.length; i+=4) { if (px[i]>10) { isSigned=true; break; } }
  }
  if (!isSigned) { alert('Patient signature is required.'); return; }

  var sigDataUrl = canvas.toDataURL('image/png');
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  if (!DATA.patients[ptIdx].commLog) DATA.patients[ptIdx].commLog = [];

  DATA.patients[ptIdx].commLog.push({
    id:         'ref'+Date.now(),
    type:       'refusal',
    date:       todayISO(),
    ts:         Date.now(),
    notes:      'REFUSED: '+treatment+'. Risks explained by '+esc((document.getElementById('ref-advised-by')||{}).value||DOCTOR)+'. Patient signed acknowledgment.',
    sig:        sigDataUrl,
    treatment:  treatment,
    doctor:     DOCTOR,
  });

  activePt = DATA.patients[ptIdx];
  saveData();
  document.getElementById('refusal-modal').style.display = 'none';
  switchTab('commlog');
  showSavedToast();
}


/* ─── REDO / FAILURE TRACKER ─────────────────────────────────
   Tracks failed/redone procedures per patient.
   Saves to patient.failureLog[].
   Analytics: failure rate by procedure type.
─────────────────────────────────────────────────────────── */
var FAILURE_CATS = [
  { id:'restoration', label:'💥 Restoration Failure', color:'#dc2626', bg:'#fef2f2',
    desc:'Composite/GIC fell out, recurrent caries, fracture' },
  { id:'rct',         label:'🦷 RCT Retreatment',     color:'#7c3aed', bg:'#f5f3ff',
    desc:'Persistent pain, reinfection, missed canal, failure' },
  { id:'crown',       label:'👑 Crown Issue',          color:'#d97706', bg:'#fffbeb',
    desc:'Fracture, debonding, marginal gap, poor fit' },
  { id:'debond',      label:'🔧 Debonding',            color:'#0284c7', bg:'#eff6ff',
    desc:'Bracket/band debond (ortho), veneer/crown debond' },
  { id:'implant',     label:'🔩 Implant Failure',      color:'#374151', bg:'#f8fafc',
    desc:'Osseointegration failure, mobility, fracture' },
  { id:'extraction',  label:'⚡ Post-extraction',      color:'#059669', bg:'#ecfdf5',
    desc:'Dry socket, infection, delayed healing' },
  { id:'perio',       label:'📊 Perio Relapse',        color:'#0369a1', bg:'#f0f9ff',
    desc:'Pocket depth increase, bone loss progression' },
  { id:'other',       label:'📝 Other',                color:'#64748b', bg:'#f8fafc',
    desc:'Sensitivity, aesthetic failure, other' },
];

var FAILURE_CAUSES = ['Patient non-compliance','Material failure','Technique limitation','Case complexity','Unknown / Unclear'];

function failureLog_render() {
  var el = document.getElementById('tab-content-failures');
  if (!el || !activePt) return;
  var log = (activePt.failureLog || []).slice().sort(function(a,b){ return (b.failDate||b.date||'').localeCompare(a.failDate||a.date||''); });

  var catOpts = FAILURE_CATS.map(function(f){
    return '<option value="'+f.id+'">'+f.label+'</option>';
  }).join('');
  var causeOpts = FAILURE_CAUSES.map(function(c){
    return '<option value="'+c+'">'+c+'</option>';
  }).join('');

  var html = '<div style="padding:8px 0">';

  // Add entry form
  html += '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:14px;padding:14px 16px;margin-bottom:14px">';
  html += '<div style="font-size:12px;font-weight:800;color:#dc2626;margin-bottom:10px">⚠️ Log a Redo / Failure</div>';
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">';
  html += '<select id="fail-cat" class="form-input" style="font-size:12px">'+catOpts+'</select>';
  html += '<input id="fail-tooth" class="form-input" placeholder="Tooth # (e.g. 46)" style="font-size:12px"/>';
  html += '<div style="display:flex;flex-direction:column;gap:2px">';
  html += '<label style="font-size:10px;color:#64748b;font-weight:600">Original Procedure Date</label>';
  html += '<input id="fail-orig-date" type="date" class="form-input" style="font-size:12px"/>';
  html += '</div>';
  html += '<div style="display:flex;flex-direction:column;gap:2px">';
  html += '<label style="font-size:10px;color:#64748b;font-weight:600">Failure / Redo Date</label>';
  html += '<input id="fail-date" type="date" class="form-input" value="'+todayISO()+'" style="font-size:12px"/>';
  html += '</div>';
  html += '</div>';
  html += '<select id="fail-cause" class="form-input" style="font-size:12px;margin-bottom:8px">'+causeOpts+'</select>';
  html += '<textarea id="fail-notes" class="form-input" rows="2" style="font-size:12px;resize:none;margin-bottom:8px" placeholder="What happened? What will you do differently? (honest reflection = growth)"></textarea>';
  html += '<button onclick="failureLog_save()" class="btn btn-sm" style="background:#dc2626;color:#fff;border:none;font-size:12px">💾 Log Failure</button>';
  html += '</div>';

  // Log entries
  if (!log.length) {
    html += '<div style="text-align:center;padding:20px;color:#94a3b8">';
    html += '<div style="font-size:28px;margin-bottom:6px">⚠️</div>';
    html += '<div style="font-size:12px;font-weight:700;color:#374151">No failures logged</div>';
    html += '<div style="font-size:11px;margin-top:4px">Every clinician has redos. Tracking them honestly is what separates good from great.</div>';
    html += '</div>';
  } else {
    log.forEach(function(entry) {
      var fc = FAILURE_CATS.find(function(f){ return f.id===entry.cat; }) || FAILURE_CATS[FAILURE_CATS.length-1];
      var origDate = entry.origDate ? fmtDate(entry.origDate) : '—';
      var failDate = fmtDate(entry.failDate||entry.date||'');
      var daysBetween = (entry.origDate && entry.failDate) ?
        Math.floor((new Date(entry.failDate+'T00:00:00')-new Date(entry.origDate+'T00:00:00'))/86400000) : null;

      html += '<div style="background:'+fc.bg+';border:1.5px solid '+fc.color+'20;border-left:4px solid '+fc.color+';border-radius:12px;padding:12px 14px;margin-bottom:8px">';
      html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:6px;margin-bottom:6px">';
      html += '<div><span style="font-size:12px;font-weight:800;color:'+fc.color+'">'+fc.label+'</span>';
      if (entry.tooth) html += ' <span style="font-size:11px;font-weight:700;color:#374151">— Tooth #'+esc(entry.tooth)+'</span>';
      html += '</div>';
      html += '<span style="font-size:10px;color:#94a3b8">Failed: '+failDate+'</span>';
      html += '</div>';

      if (daysBetween !== null) {
        html += '<div style="font-size:10px;color:#64748b;margin-bottom:4px">Lasted '+daysBetween+' days (Original: '+origDate+')</div>';
      }
      if (entry.cause) html += '<div style="font-size:10px;font-weight:700;color:'+fc.color+';margin-bottom:4px">Cause: '+esc(entry.cause)+'</div>';
      if (entry.notes) html += '<div style="font-size:11px;color:#374151;line-height:1.5;margin-bottom:6px">'+esc(entry.notes)+'</div>';

      html += '<div style="display:flex;justify-content:flex-end">';
      html += '<button onclick="failureLog_delete(\''+entry.id+'\')" style="background:none;border:none;font-size:10px;color:#94a3b8;cursor:pointer">🗑</button>';
      html += '</div></div>';
    });
  }
  html += '</div>';
  el.innerHTML = html;
}

function failureLog_save() {
  var cat   = (document.getElementById('fail-cat')||{}).value;
  var tooth = (document.getElementById('fail-tooth')||{}).value.trim();
  var orig  = (document.getElementById('fail-orig-date')||{}).value;
  var fail  = (document.getElementById('fail-date')||{}).value || todayISO();
  var cause = (document.getElementById('fail-cause')||{}).value;
  var notes = ((document.getElementById('fail-notes')||{}).value||'').trim();

  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  if (!DATA.patients[ptIdx].failureLog) DATA.patients[ptIdx].failureLog = [];

  DATA.patients[ptIdx].failureLog.push({
    id:       'fl'+Date.now(),
    cat:      cat,
    tooth:    tooth,
    origDate: orig,
    failDate: fail,
    cause:    cause,
    notes:    notes,
    date:     fail,
    ts:       Date.now(),
  });

  activePt = DATA.patients[ptIdx];
  saveData(); failureLog_render();
  showSavedToast();
}

function failureLog_delete(entryId) {
  if (!confirm('Delete this failure log entry?')) return;
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  DATA.patients[ptIdx].failureLog = (DATA.patients[ptIdx].failureLog||[]).filter(function(e){ return e.id!==entryId; });
  activePt = DATA.patients[ptIdx];
  saveData(); failureLog_render();
}

/* Analytics: clinic-wide failure rate by procedure */
function failureAnalytics_render(containerId) {
  var el = document.getElementById(containerId||'failure-analytics-container');
  if (!el) return;

  var pts = DATA.patients||[];
  var byCat = {};

  pts.forEach(function(p) {
    (p.failureLog||[]).forEach(function(f) {
      var k = f.cat||'other';
      if (!byCat[k]) byCat[k] = { count:0, totalDays:0, causes:{} };
      byCat[k].count++;
      if (f.origDate && f.failDate) {
        var days = Math.floor((new Date(f.failDate+'T00:00:00')-new Date(f.origDate+'T00:00:00'))/86400000);
        if (days > 0) byCat[k].totalDays += days;
      }
      if (f.cause) {
        byCat[k].causes[f.cause] = (byCat[k].causes[f.cause]||0)+1;
      }
    });
  });

  var total = Object.values(byCat).reduce(function(s,v){ return s+v.count; },0);
  if (!total) {
    el.innerHTML = '<div style="background:#f8fafc;border:1.5px dashed #e2e8f0;border-radius:12px;padding:16px;text-align:center;color:#94a3b8;font-size:12px">No failure data yet. Track redos from patient → ⚠️ Failures tab.</div>';
    return;
  }

  var rows = Object.entries(byCat).sort(function(a,b){ return b[1].count-a[1].count; });
  var html = '<div style="font-size:11px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">⚠️ Redo / Failure Analysis — Clinic Wide</div>';
  html += '<div style="background:#fff;border:1.5px solid #e2e8f0;border-radius:12px;overflow:hidden;margin-bottom:12px">';
  html += '<div style="background:#dc2626;padding:12px 16px;display:flex;justify-content:space-between;align-items:center">';
  html += '<div style="color:#fff;font-size:13px;font-weight:800">'+total+' Failures Tracked</div>';
  html += '<div style="color:#fca5a5;font-size:11px">Across '+pts.filter(function(p){return (p.failureLog||[]).length;}).length+' patients</div>';
  html += '</div>';

  rows.forEach(function(entry) {
    var k=entry[0], v=entry[1];
    var fc = FAILURE_CATS.find(function(f){ return f.id===k; })||FAILURE_CATS[FAILURE_CATS.length-1];
    var pct = Math.round((v.count/total)*100);
    var avgDays = v.totalDays > 0 ? Math.round(v.totalDays/v.count) : null;
    var topCause = Object.entries(v.causes).sort(function(a,b){return b[1]-a[1];})[0];

    html += '<div style="padding:10px 16px;border-bottom:1px solid #f1f5f9;display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center">';
    html += '<span style="font-size:12px;font-weight:700;color:'+fc.color+';min-width:150px">'+fc.label+'</span>';
    html += '<div style="background:#f1f5f9;border-radius:4px;height:8px;overflow:hidden"><div style="background:'+fc.color+';height:100%;width:'+pct+'%;border-radius:4px"></div></div>';
    html += '<div style="text-align:right;font-size:12px;color:#374151;font-weight:700;min-width:60px">'+v.count+' ('+pct+'%)</div>';
    html += '</div>';
    if (avgDays || topCause) {
      html += '<div style="padding:2px 16px 8px;display:flex;gap:12px;flex-wrap:wrap">';
      if (avgDays) html += '<span style="font-size:10px;color:#64748b">⏱ Avg lasted '+avgDays+'d</span>';
      if (topCause) html += '<span style="font-size:10px;color:#64748b">⚑ '+topCause[0]+' ('+topCause[1]+'×)</span>';
      html += '</div>';
    }
  });
  html += '</div>';
  el.innerHTML = html;
}



/* ════════════════════════════════════════════════════════
   GROUP NAVIGATION — Step 1 Tab Consolidation
   All existing switchTab() logic stays IDENTICAL.
   This layer handles group selection + sub-tab rendering.
════════════════════════════════════════════════════════ */
var TAB_GROUPS = {
  clinical: {
    icon:'🩺', label:'Clinical',
    tabs: ['records','rct','tooth-chart','perio'],
    def:  'records'
  },
  finance: {
    icon:'💰', label:'Finance',
    tabs: ['billing'],
    def:  'billing'
  },
  media: {
    icon:'📷', label:'Media',
    tabs: ['images','photos'],
    def:  'images'
  },
  docs: {
    icon:'📋', label:'Docs',
    tabs: ['prescriptions','tx-plan','commlog','failures','ortho-detail','ortho-visits'],
    def:  'prescriptions'
  },
  history: {
    icon:'📅', label:'History',
    tabs: ['timeline'],
    def:  'timeline'
  }
};

var TAB_LABELS = {
  'records':      '🩺 Records',
  'rct':          '🦷 RCT',
  'perio':        '📊 Perio',
  'tooth-chart':  '🦷 Tooth',
  'billing':      '💰 Billing',
  'images':       '📷 Images',
  'photos':       '📸 Photos',
  'prescriptions':'💊 Rx',
  'tx-plan':      '📋 Plan',
  'commlog':      '📞 Comm',
  'failures':     '⚠️ Redo',
  'ortho-detail': '🦷 Ortho',
  'ortho-visits': '📅 Visits',
  'timeline':     '📅 Timeline',
};

var activeGroup = 'clinical';

/* Which group does a tab belong to? */
function grp_forTab(tabId) {
  for (var g in TAB_GROUPS) {
    if (TAB_GROUPS[g].tabs.indexOf(tabId) >= 0) return g;
  }
  return 'clinical';
}

/* Render the sub-tab bar for the given group */
function grp_renderSubBar(groupId, activeTab) {
  var subBar = document.getElementById('pt-sub-tabs');
  if (!subBar) return;
  var group = TAB_GROUPS[groupId];
  if (!group) return;

  var p = activePt || {};
  var isOrtho   = p.type === 'ortho' || (p.type||'').toLowerCase().includes('ortho');
  var hasAligner = !!(DATA && DATA.alignerCases &&
    DATA.alignerCases.some(function(a){ return a.patientId === p.id; }));

  /* Clear and rebuild using DOM — avoids all string-escaping issues */
  subBar.innerHTML = '';
  group.tabs.forEach(function(t) {
    var show = true;
    /* Perio tab: hidden by default unless patient has perio data */
    if (t === 'perio') {
      show = !!(p.perioData && Object.keys(p.perioData||{}).length) || false;
      /* Always show if currently on perio tab */
      if (activeTab === 'perio') show = true;
    }
    if (t === 'ortho-detail' || t === 'ortho-visits') {
      show = isOrtho || hasAligner;
    }

    var btn = document.createElement('button');
    btn.className = 'tab-btn' + (t === activeTab ? ' active' : '');
    btn.id = 'tab-' + t;
    btn.textContent = TAB_LABELS[t] || t;
    btn.style.display = show ? 'inline-flex' : 'none';
    btn.style.alignItems = 'center';

    /* Closure captures the correct tab id */
    (function(tabId) {
      btn.addEventListener('click', function() { switchTab(tabId); });
    })(t);

    subBar.appendChild(btn);
  });
}

/* Switch to a group (+ optionally a specific tab) */
function switchGroup(groupId, tabId) {
  activeGroup = groupId;
  if (activePt && tabId) tabMem_save(activePt.id, groupId, tabId);
  var group = TAB_GROUPS[groupId];
  if (!group) return;

  /* Highlight group buttons */
  Object.keys(TAB_GROUPS).forEach(function(g) {
    var btn = document.getElementById('gtab-'+g);
    if (btn) btn.classList.toggle('active', g === groupId);
  });

  /* Pick which sub-tab to activate */
  var targetTab = tabId || group.def;
  grp_renderSubBar(groupId, targetTab);

  /* Update swipe tab order to current group's tabs */
  tabOrder = group.tabs.filter(function(t) {
    if (t === 'ortho-detail' || t === 'ortho-visits') {
      var p = activePt||{};
      var hasA = !!(DATA && DATA.alignerCases && DATA.alignerCases.some(function(a){ return a.patientId===p.id; }));
      return p.type==='ortho' || hasA;
    }
    return true;
  });

  /* Activate the tab via existing switchTab() */
  switchTab(targetTab);
  /* Save tab memory */
  if (activePt) _tabMemory[activePt.id] = { group: groupId, tab: targetTab };
}

/* Call this whenever a tab is activated programmatically
   (e.g. from openPatient, post-save, etc.) to sync group nav */
function grp_syncNav(tabId) {
  var g = grp_forTab(tabId);
  if (g !== activeGroup) {
    activeGroup = g;
    Object.keys(TAB_GROUPS).forEach(function(gk) {
      var btn = document.getElementById('gtab-'+gk);
      if (btn) btn.classList.toggle('active', gk === g);
    });
  }
  grp_renderSubBar(activeGroup, tabId);
}
/* Init group nav when a patient is opened */
function grp_initForPatient() {
  var ptId = activePt ? activePt.id : null;
  /* Try to restore last-used tab for this patient */
  if (ptId && !tabMem_restore(ptId)) {
    activeGroup = 'clinical';
    setTimeout(function() {
      if (typeof switchGroup === 'function') switchGroup('clinical', 'records');
    }, 80);
  }
}


/* Patch openPatient_orig to init group nav on patient open */
var _openPt_grp_orig = openPatient_orig;



