/* ─── A. PATIENT HEADER BILLING FIX ─────────────────── */
/* Override renderPatientHeader to fix paid/due calculation */


function ptHeader_addStats() {
  ptHeader_addQuickActions();
  ptHeader_addTxPlan();
  var p = activePt;
  if (!p) return;

  var visitCount = (p.records || []).length;
  var totalBilled = (p.billing || []).reduce(function(s,b){ return s+Number(b.totalAmount||b.amount||0); },0);
  var totalPaid   = (p.billing || []).reduce(function(s,b){ return s+Number(b.paidAmount||(b.paid?(b.totalAmount||b.amount||0):0)); },0);
  var due = Math.max(0, totalBilled - totalPaid);

  /* OHI trend */
  var ohis = (p.records||[]).filter(function(r){ return r.ohi; }).map(function(r){ return r.ohi; });
  var lastOhi = ohis.length ? ohis[ohis.length-1] : null;
  var ohiColor = {'Good':'#059669','Average':'#d97706','Poor':'#dc2626'}[lastOhi] || '#94a3b8';

  /* Last pain level */
  var pains = (p.records||[]).filter(function(r){ return r.pain !== null && r.pain !== undefined; });
  var lastPain = pains.length ? pains[pains.length-1].pain : null;

  /* Build compact stats strip */
  var strip = document.createElement('div');
  strip.id = 'pt-quick-stats';
  strip.style.cssText = 'display:flex;gap:8px;overflow-x:auto;padding:8px 14px;background:#f8fafc;border-bottom:1px solid #e2e8f0;scrollbar-width:none';
  strip.innerHTML = [
    stat_chip('📋', visitCount + ' Visit' + (visitCount!==1?'s':''), '#1d4ed8', '#eff6ff'),
    totalBilled > 0 ? stat_chip('💰', fmtMoney(totalBilled) + ' Billed', '#374151', '#f8fafc') : '',
    due > 0 ? stat_chip('⚠️', fmtMoney(due) + ' Due', '#dc2626', '#fef2f2') : '',
    lastOhi ? stat_chip('🦷', 'OHI: ' + lastOhi, ohiColor, ohiColor+'15') : '',
    lastPain !== null ? stat_chip('🤕', 'Pain: ' + lastPain + '/10', lastPain>6?'#dc2626':lastPain>3?'#d97706':'#059669', '#f8fafc') : '',
    (p.rctLog||[]).length > 0 ? stat_chip('🦷', (p.rctLog||[]).length + ' RCT', '#7c3aed', '#f5f3ff') : '',
    (p.commLog||[]).length > 0 ? stat_chip('📞', (p.commLog||[]).length + ' Comm', '#0369a1', '#f0f9ff') : '',
  ].join('');

  /* Insert after pt-detail-header */
  var old = document.getElementById('pt-quick-stats');
  if (old) old.remove();
  var hdr = document.getElementById('pt-detail-header');
  if (hdr && hdr.nextSibling) {
    hdr.parentNode.insertBefore(strip, hdr.nextSibling);
  }
}

function stat_chip(icon, label, color, bg) {
  return '<div style="display:flex;align-items:center;gap:4px;background:'+bg+';border-radius:8px;padding:5px 10px;white-space:nowrap;flex-shrink:0">'
    + '<span>'+icon+'</span>'
    + '<span style="font-size:11px;font-weight:700;color:'+color+'">'+label+'</span>'
    + '</div>';
}


