/* ─── C. VIRTUAL PATIENT LIST ───────────────────────── */
var _ptListPage = 0;
var _ptListPageSize = 40;
var _ptListFiltered = [];

function renderPatientList_paginated(list, append) {
  var el = document.getElementById('patient-list');
  if (!el) return;

  _ptListFiltered = list;
  var start = append ? _ptListPage * _ptListPageSize : 0;
  var slice = list.slice(start, start + _ptListPageSize);
  var hasMore = list.length > start + _ptListPageSize;

  var html = (append ? el.innerHTML.replace(/<div id="load-more-btn"[^]*<\/div>$/,'') : '');

  /* Reuse existing patient card rendering (same as before) */
  slice.forEach(function(p) {
    /* Build card using existing renderSinglePatientCard if available */
    if (typeof renderSinglePatientCard === 'function') {
      html += renderSinglePatientCard(p);
    } else {
      /* Minimal fallback */
      html += '<div onclick="openPatient(\''+p.id+'\')" style="padding:12px 14px;border-bottom:1px solid #f1f5f9;cursor:pointer">'
        + '<div style="font-weight:700;color:#1e293b">'+esc(p.name)+'</div>'
        + '<div style="font-size:11px;color:#64748b">'+p.phone+'</div>'
        + '</div>';
    }
  });

  if (hasMore) {
    html += '<div id="load-more-btn" style="padding:14px;text-align:center">'
      + '<button onclick="ptList_loadMore()" class="btn btn-sm" style="background:#eff6ff;color:#1d4ed8;border:none;font-weight:700">'
      + '↓ Load more ('+(list.length - start - _ptListPageSize)+' remaining)</button>'
      + '</div>';
  }

  el.innerHTML = html;
  _ptListPage = append ? _ptListPage + 1 : 1;
}

function ptList_loadMore() {
  renderPatientList_paginated(_ptListFiltered, true);
}


