/* ─── MISSING: RECORD CARD EXTRA BADGES ── */
function recCard_extraBadges(r) {
  var html = '';
  if (!r) return html;
  if (r.ohi) {
    var ohiCol=r.ohi==='Good'?'#059669':r.ohi==='Average'?'#d97706':'#dc2626';
    var ohiBg =r.ohi==='Good'?'#ecfdf5':r.ohi==='Average'?'#fffbeb':'#fef2f2';
    html+='<span style="font-size:10px;font-weight:700;color:'+ohiCol+';background:'+ohiBg+';border:1px solid '+ohiCol+'30;padding:2px 7px;border-radius:5px">🦷 OHI: '+r.ohi+'</span>';
  }
  if (r.pain!==null&&r.pain!==undefined) {
    var painCol=r.pain<=3?'#059669':r.pain<=6?'#d97706':'#dc2626';
    html+='<span style="font-size:10px;font-weight:700;color:'+painCol+';background:#f8fafc;border:1px solid #e2e8f0;padding:2px 7px;border-radius:5px">🤕 Pain: '+r.pain+'/10</span>';
  }
  if (r.relief!==null&&r.relief!==undefined) {
    var rls=['No relief','Minimal','Some','Good','Full'];
    var rc=r.relief>=3?'#059669':r.relief>=1?'#d97706':'#dc2626';
    html+='<span style="font-size:10px;font-weight:700;color:'+rc+';background:#f8fafc;border:1px solid #e2e8f0;padding:2px 7px;border-radius:5px">😌 '+(rls[r.relief]||'Relief')+'</span>';
  }
  if (r.durationMins) {
    html+='<span style="font-size:10px;font-weight:700;color:#7c3aed;background:#f5f3ff;border:1px solid #ddd6fe;padding:2px 7px;border-radius:5px">⏱ '+r.durationMins+'m</span>';
  }
  return html?'<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:6px">'+html+'</div>':'';
}

