function actionCentre_dismiss(itemId) {
  if (!itemId) return;
  try {
    var today  = todayISO();
    var raw    = localStorage.getItem('hos_ac_dismissed');
    var stored = raw ? JSON.parse(raw) : {};
    /* Reset if different day */
    var ids = (stored.date === today) ? (stored.ids||{}) : {};
    ids[itemId] = 1;
    localStorage.setItem('hos_ac_dismissed', JSON.stringify({ date:today, ids:ids }));
  } catch(e){}
  actionCentre_render();
}

function actionCentre_clearDismissed() {
  localStorage.removeItem('hos_ac_dismissed');
  actionCentre_render();
}

/* Play a beep using Web Audio API (no external files needed) */
function procTimer_beep(freq, dur, vol) {
  try {
    var ctx = new (window.AudioContext || window.webkitAudioContext)();
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.value = freq || 880;
    osc.type = 'sine';
    gain.gain.setValueAtTime(vol || 0.4, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + (dur || 0.5));
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + (dur || 0.5));
  } catch(e) {}
}

function procTimer_doneSound() {
  /* Three rising tones — done! */
  setTimeout(function(){ procTimer_beep(660, 0.15, 0.3); }, 0);
  setTimeout(function(){ procTimer_beep(880, 0.15, 0.3); }, 150);
  setTimeout(function(){ procTimer_beep(1100, 0.4, 0.5); }, 300);
}

function procTrack_doneSound() {
  /* Two low tones — procedure complete */
  setTimeout(function(){ procTimer_beep(440, 0.2, 0.3); }, 0);
  setTimeout(function(){ procTimer_beep(550, 0.5, 0.4); }, 200);
}

/* ── Multi-treatment form state ─────────────────────── */
var _leadRows = [{ name:'Consultation', price:0 }];

function lead_addRow() {
  _leadRows.push({ name: LEAD_TREATMENTS[0], price: 0 });
  lead_renderRows();
}

function lead_removeRow(idx) {
  if (_leadRows.length <= 1) return; // keep at least 1
  _leadRows.splice(idx, 1);
  lead_renderRows();
}

function lead_updateTotal() {
  var total = 0;
  _leadRows.forEach(function(r, i) {
    var nameEl  = document.getElementById('lr-name-'+i);
    var priceEl = document.getElementById('lr-price-'+i);
    if (nameEl)  _leadRows[i].name  = nameEl.value;
    if (priceEl) _leadRows[i].price = Number(priceEl.value)||0;
    total += _leadRows[i].price;
  });
  var totEl = document.getElementById('lead-total-display');
  if (totEl) totEl.textContent = '₹'+total.toLocaleString('en-IN');
}

function lead_renderRows() {
  var wrap = document.getElementById('lead-rows-wrap');
  if (!wrap) return;
  var opts = LEAD_TREATMENTS.map(function(t){ return '<option>'+t+'</option>'; }).join('');
  var h = '';
  _leadRows.forEach(function(row, i) {
    h += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">';
    h += '<select id="lr-name-'+i+'" onchange="lead_updateTotal()" class="form-input" style="flex:2;font-size:12px;padding:6px 8px">';
    h += LEAD_TREATMENTS.map(function(t){
      return '<option'+(t===row.name?' selected':'')+'>'+t+'</option>';
    }).join('');
    h += '</select>';
    h += '<div style="display:flex;align-items:center;background:#f8fafc;border:1.5px solid #e2e8f0;border-radius:8px;overflow:hidden;flex:1">';
    h += '<span style="padding:0 6px;color:#64748b;font-size:12px;font-weight:700">₹</span>';
    h += '<input id="lr-price-'+i+'" type="number" min="0" value="'+(row.price||'')+'" oninput="lead_updateTotal()" placeholder="Amount" style="border:none;background:transparent;width:100%;padding:6px 6px 6px 0;font-size:12px;outline:none;font-family:inherit"/>';
    h += '</div>';
    h += '<button onclick="lead_removeRow('+i+')" style="background:#fef2f2;border:1px solid #fca5a5;color:#dc2626;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:14px;flex-shrink:0;font-weight:700"'+((_leadRows.length<=1)?' disabled':'')+'>✕</button>';
    h += '</div>';
  });
  wrap.innerHTML = h;
  lead_updateTotal();
}

function lead_getRows() {
  lead_updateTotal();
  return _leadRows.filter(function(r){ return r.name; }).map(function(r){
    return { name: r.name, price: r.price||0 };
  });
}

function lead_resetRows() {
  _leadRows = [{ name:'Consultation', price:0 }];
}


/* Parse DD/MM/YYYY → Date object */
function dobToDate(str) {
  if (!str) return null;
  str = str.trim();
  var p;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(str)) {
    p = str.split('/');
    return new Date(p[2]+'-'+p[1]+'-'+p[0]+'T00:00:00');
  }
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) {
    return new Date(str+'T00:00:00');
  }
  return null;
}

/* Format YYYY-MM-DD or Date → DD/MM/YYYY */
function fmtDob(str) {
  if (!str) return '';
  if (str instanceof Date) {
    var dd = String(str.getDate()).padStart(2,'0');
    var mm = String(str.getMonth()+1).padStart(2,'0');
    return dd+'/'+mm+'/'+str.getFullYear();
  }
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) {
    var p = str.split('-');
    return p[2]+'/'+p[1]+'/'+p[0];
  }
  return str; // already formatted
}

/* Convert DD/MM/YYYY → YYYY-MM-DD for storage */
function dobToISO(str) {
  if (!str) return '';
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(str)) {
    var p = str.split('/');
    return p[2]+'-'+p[1]+'-'+p[0];
  }
  return str;
}

/* Precise age: "9 years 3 months 2 days" */
function calcPreciseAge(dobStr) {
  var dob = dobToDate(dobStr);
  if (!dob || isNaN(dob.getTime())) return '';
  var today = new Date();
  var y = today.getFullYear() - dob.getFullYear();
  var m = today.getMonth()   - dob.getMonth();
  var d = today.getDate()    - dob.getDate();
  if (d < 0) {
    m--;
    var prev = new Date(today.getFullYear(), today.getMonth(), 0);
    d += prev.getDate();
  }
  if (m < 0) { y--; m += 12; }
  if (y < 0) return '';
  var parts = [];
  if (y > 0) parts.push(y + (y===1?' year':' years'));
  if (m > 0) parts.push(m + (m===1?' month':' months'));
  if (d > 0 || y === 0) parts.push(d + (d===1?' day':' days'));
  return parts.join(' ');
}

/* Short numeric age for the age field */
function calcAgeFromDob(dobValue, ageFieldId) {
  var dob = dobToDate(dobValue);
  if (!dob || isNaN(dob.getTime())) return;
  var today = new Date();
  var age = today.getFullYear() - dob.getFullYear();
  var mo  = today.getMonth()  - dob.getMonth();
  if (mo < 0 || (mo === 0 && today.getDate() < dob.getDate())) age--;
  if (age >= 0 && age <= 120) {
    var el = document.getElementById(ageFieldId);
    if (el) el.value = age;
  }
  /* Also update precise age hint if present */
  var hintId = ageFieldId.replace('-age','-age-hint');
  var hint = document.getElementById(hintId);
  if (hint) hint.textContent = calcPreciseAge(dobValue);
}

/* Live DD/MM/YYYY formatter with auto-slash insertion */
function dob_format(input, ageFieldId) {
  var v = input.value.replace(/\D/g,'');
  if (v.length > 8) v = v.slice(0,8);
  var out = '';
  if (v.length >= 1) out = v.slice(0,2);
  if (v.length >= 3) out += '/' + v.slice(2,4);
  if (v.length >= 5) out += '/' + v.slice(4,8);
  input.value = out;
  /* Calculate age when full date entered */
  if (v.length === 8) {
    calcAgeFromDob(out, ageFieldId);
  }
}



