/* ─── FEATURE 2: Treatment Estimate Sheet ───────────── */
function printEstimate() {
  if (!activePt) return;
  var p = activePt;
  var today = todayISO();

  /* Pull treatments from: billing (unpaid), treatment plan, or prompt */
  var billItems = (p.billing||[]).filter(function(b){
    return !b.paid && (b.date||'').slice(0,7) >= today.slice(0,7);
  });
  var planItems = (p.treatmentPlan||[]).filter(function(t){ return t.status!=='done'; });

  /* Build estimate rows */
  var rows = [];

  /* Recent billing entries that are pending */
  billItems.forEach(function(b){
    rows.push({ procedure: b.item||'Treatment', amount: Number(b.totalAmount||b.amount||0) });
  });

  /* Treatment plan items with fee schedule lookup */
  if (!rows.length) {
    var fs = [];
    try { fs = JSON.parse(localStorage.getItem('hos_fee_schedule')||'[]'); } catch(e){}
    planItems.forEach(function(t){
      var match = fs.find(function(f){ return (f.name||'').toLowerCase().includes((t.procedure||'').toLowerCase()); });
      rows.push({ procedure: t.procedure||'Treatment', amount: match ? Number(match.fee) : 0 });
    });
  }

  if (!rows.length) {
    /* Generic fallback — open print with blank rows to fill */
    rows = [{ procedure:'', amount:0 },{ procedure:'', amount:0 },{ procedure:'', amount:0 }];
  }

  var total = rows.reduce(function(s,r){ return s+r.amount; }, 0);
  var estNo = 'EST-' + Date.now().toString().slice(-6);

  var rowsHtml = rows.map(function(r, i){
    return '<tr style="border-bottom:1px solid #e2e8f0">'
      + '<td style="padding:8px 4px;font-size:12px">'+(i+1)+'</td>'
      + '<td style="padding:8px;font-size:12px;font-weight:600">'+(r.procedure||'—')+'</td>'
      + '<td style="padding:8px;font-size:12px;text-align:right">'+(r.amount ? '₹'+r.amount.toLocaleString('en-IN') : '—')+'</td>'
      + '</tr>';
  }).join('');

  var win = window.open('','_blank','width=520,height=700');
  win.document.write(
    '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Treatment Estimate</title>'
    + '<style>body{font-family:Arial,sans-serif;margin:0;padding:20px;font-size:12px;color:#1e293b}'
    + '.header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px;border-bottom:3px solid #1e3a5f;padding-bottom:14px}'
    + '.clinic-name{font-size:18px;font-weight:800;color:#1e3a5f}'
    + '.sub{font-size:10px;color:#64748b;margin-top:2px}'
    + 'table{width:100%;border-collapse:collapse}'
    + 'th{background:#1e3a5f;color:#fff;padding:8px;font-size:11px;font-weight:700;text-align:left}'
    + 'th:last-child{text-align:right}'
    + '.total-row{background:#f8fafc;font-weight:800;font-size:13px}'
    + '.footer{margin-top:20px;font-size:10px;color:#94a3b8;border-top:1px solid #e2e8f0;padding-top:12px}'
    + '.signature{margin-top:40px;display:flex;justify-content:space-between}'
    + '.sig-line{border-top:1px solid #1e293b;padding-top:4px;font-size:10px;color:#64748b;width:140px;text-align:center}'
    + '@media print{body{padding:8px}}</style></head><body>'
    + '<div class="header">'
    + '<div><div class="clinic-name">The Home Of Smiles</div>'
    + '<div class="sub">Dr. Tanmay Jain B.D.S., M.I.D.A. | Reg. A-9965</div>'
    + '<div class="sub">Near Allen Sangyan, Landmark City, Kunhadi, Kota</div>'
    + '<div class="sub">📞 '+PHONE+'/div></div>'
    + '<div style="text-align:right"><div style="font-size:13px;font-weight:800;color:#1e3a5f">TREATMENT ESTIMATE</div>'
    + '<div class="sub">'+estNo+'</div>'
    + '<div class="sub">Date: '+fmtDob(today)+'</div>'
    + '<div class="sub">Valid for 30 days</div></div>'
    + '</div>'

    + '<div style="background:#f8fafc;border-radius:8px;padding:10px 14px;margin-bottom:16px;font-size:12px">'
    + '<strong>Patient:</strong> '+esc(p.name||'')
    + (p.age ? '&nbsp;&nbsp;<strong>Age:</strong> '+p.age+'y' : '')
    + (p.phone ? '&nbsp;&nbsp;<strong>Ph:</strong> '+p.phone : '')
    + '</div>'

    + '<table><thead><tr>'
    + '<th style="width:36px">#</th>'
    + '<th>Procedure / Treatment</th>'
    + '<th style="width:100px">Amount</th>'
    + '</tr></thead><tbody>'
    + rowsHtml
    + '<tr class="total-row">'
    + '<td colspan="2" style="padding:10px 8px;text-align:right">TOTAL ESTIMATE</td>'
    + '<td style="padding:10px 8px;text-align:right">₹'+(total?total.toLocaleString('en-IN'):'—')+'</td>'
    + '</tr></tbody></table>'

    + '<div class="footer">'
    + '• This is an estimate only. Final charges may vary based on treatment complexity.<br>'
    + '• Prices valid for 30 days from date of estimate.<br>'
    + '• Additional procedures may be recommended after examination.</div>'

    + '<div class="signature">'
    + '<div class="sig-line">Patient Signature</div>'
    + '<div class="sig-line">Dr. Tanmay Jain</div>'
    + '</div>'

    + '<script>window.onload=function(){window.print();window.onafterprint=function(){window.close();};};<\/script>'
    + '</body></html>'
  );
  win.document.close();
}

