/* ─── FEATURE 4: Appointment share (WA + Calendar) ── */
function appt_sharePrompt(appt) {
  var pt = (DATA.patients||[]).find(function(p){ return p.id===appt.patientId; });
  if (!pt) return;

  var old = document.getElementById('appt-share-prompt');
  if (old) old.remove();

  /* Format date/time */
  var dateFmt = fmtDob(appt.date||'');
  var timeFmt = (function(t){
    if (!t) return '';
    var p=t.split(':').map(Number);
    return ((p[0]%12)||12)+':'+(p[1]<10?'0':'')+p[1]+' '+(p[0]>=12?'PM':'AM');
  })(appt.time||'');

  /* Google Calendar URL */
  var gcalDate = (appt.date||'').replace(/-/g,'');
  var gcalTime = (appt.time||'10:00').replace(':','') + '00';
  /* End = +1 hour */
  var endHr   = parseInt((appt.time||'10:00').split(':')[0]) + 1;
  var endTime = (endHr<10?'0':'')+endHr + (appt.time||':00').slice(2,5).replace(':','') + '00';
  var gcalLink = 'https://calendar.google.com/calendar/render?action=TEMPLATE'
    + '&text=' + encodeURIComponent('Dental Appointment — The Home Of Smiles')
    + '&dates=' + gcalDate+'T'+gcalTime+'/'+gcalDate+'T'+endTime
    + '&details=' + encodeURIComponent((appt.notes||'')+'\nDr. Tanmay Jain | '+PHONE+'')
    + '&location=' + encodeURIComponent('The Home Of Smiles, Near Allen Sangyan, Landmark City, Kota');

  /* WA message */
  var waMsg = 'Dear '+esc(pt.name)+', your appointment at The Home Of Smiles is confirmed.'
    + '\nDate: '+dateFmt+(timeFmt?' | Time: '+timeFmt:'')
    + '\nDr. Tanmay Jain | '+PHONE+''
    + (appt.notes ? '\nNote: '+appt.notes : '');
  var waLink = pt.phone
    ? 'https://wa.me/91'+(pt.phone.replace(/[^0-9]/g,'').slice(-10))+'?text='+encodeURIComponent(waMsg)
    : null;

  var prompt = document.createElement('div');
  prompt.id = 'appt-share-prompt';
  prompt.style.cssText = 'position:fixed;bottom:80px;left:16px;right:16px;background:#1e3a5f;color:#fff;border-radius:14px;padding:14px 16px;z-index:8500;box-shadow:0 8px 24px rgba(0,0,0,.3);transform:translateY(100px);transition:transform .3s';

  var inner = document.createElement('div');
  inner.style.cssText = 'display:flex;align-items:center;gap:10px;flex-wrap:wrap';

  var label = document.createElement('div');
  label.style.cssText = 'flex:1;min-width:0';
  label.innerHTML = '<div style="font-size:12px;font-weight:700">Appointment saved for '+esc(pt.name)+'</div>'
    + '<div style="font-size:11px;opacity:.8">'+dateFmt+(timeFmt?' at '+timeFmt:'')+'</div>';
  inner.appendChild(label);

  if (waLink) {
    var waBtn = document.createElement('a');
    waBtn.href = waLink; waBtn.target = '_blank';
    waBtn.style.cssText = 'background:#25d366;border:none;color:#fff;border-radius:8px;padding:7px 12px;cursor:pointer;font-size:11px;font-weight:700;text-decoration:none;white-space:nowrap;flex-shrink:0';
    waBtn.textContent = '💬 WA';
    inner.appendChild(waBtn);
  }

  var calBtn = document.createElement('a');
  calBtn.href = gcalLink; calBtn.target = '_blank';
  calBtn.style.cssText = 'background:#4285f4;border:none;color:#fff;border-radius:8px;padding:7px 12px;cursor:pointer;font-size:11px;font-weight:700;text-decoration:none;white-space:nowrap;flex-shrink:0';
  calBtn.textContent = '📅 Add to Calendar';
  inner.appendChild(calBtn);

  var closeBtn = document.createElement('button');
  closeBtn.style.cssText = 'background:rgba(255,255,255,.15);border:none;color:#fff;border-radius:8px;padding:7px 10px;cursor:pointer;font-size:11px;flex-shrink:0';
  closeBtn.textContent = '✕';
  closeBtn.addEventListener('click', function(){ prompt.remove(); });
  inner.appendChild(closeBtn);

  prompt.appendChild(inner);
  document.body.appendChild(prompt);
  setTimeout(function(){ prompt.style.transform='translateY(0)'; }, 50);
  setTimeout(function(){ if(prompt.parentElement) prompt.remove(); }, 12000);
}

/* ─── FEATURE 8: Tx Plan → Billing auto-conversion ── */
function txPlan_promptBilling(item) {
  if (!activePt || !item) return;
  /* Look up fee schedule */
  var fs = [];
  try { fs = JSON.parse(localStorage.getItem('hos_fee_schedule')||'[]'); } catch(e){}
  var q = (item.procedure||'').toLowerCase();
  var match = fs.find(function(f){ return (f.name||'').toLowerCase().includes(q)||q.includes((f.name||'').toLowerCase()); });
  var suggestedAmt = match ? Number(match.fee) : 0;

  var old = document.getElementById('txbill-prompt');
  if (old) old.remove();

  var prompt = document.createElement('div');
  prompt.id = 'txbill-prompt';
  prompt.style.cssText = 'position:fixed;bottom:80px;left:16px;right:16px;background:#059669;color:#fff;border-radius:14px;padding:14px 16px;z-index:8600;box-shadow:0 8px 24px rgba(0,0,0,.3);transform:translateY(100px);transition:transform .3s';

  var inner = document.createElement('div');
  inner.style.cssText = 'display:flex;align-items:center;gap:10px;flex-wrap:wrap';

  var label = document.createElement('div');
  label.style.cssText = 'flex:1;min-width:0';
  label.innerHTML = '<div style="font-size:12px;font-weight:700">'+esc(item.procedure)+' marked done</div>'
    + '<div style="font-size:11px;opacity:.8">Add billing entry?'+(suggestedAmt?' — Suggested: ₹'+suggestedAmt.toLocaleString('en-IN'):'')+'</div>';
  inner.appendChild(label);

  var amtInput = document.createElement('input');
  amtInput.type = 'number'; amtInput.placeholder = '₹ Amount';
  amtInput.value = suggestedAmt||'';
  amtInput.style.cssText = 'width:90px;border:none;border-radius:8px;padding:6px 10px;font-size:13px;font-weight:700;color:#1e293b;background:rgba(255,255,255,.9)';
  inner.appendChild(amtInput);

  var addBtn = document.createElement('button');
  addBtn.style.cssText = 'background:#fff;border:none;color:#059669;border-radius:8px;padding:7px 14px;cursor:pointer;font-size:12px;font-weight:800;flex-shrink:0';
  addBtn.textContent = '+ Add Bill';
  addBtn.addEventListener('click', function() {
    var amt = Number(amtInput.value)||0;
    if (!amt) { prompt.remove(); return; }
    var bill = {
      id: 'b'+Date.now(), item: item.procedure,
      amount: amt, totalAmount: amt, paidAmount: 0, paid: false,
      date: todayISO(), paymentMode: 'Cash', payments: []
    };
    var ptIdx2 = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
    if (ptIdx2 >= 0) {
      DATA.patients[ptIdx2].billing = DATA.patients[ptIdx2].billing||[];
      DATA.patients[ptIdx2].billing.push(bill);
      activePt = DATA.patients[ptIdx2];
      saveData();
    }
    prompt.remove();
    showToast('Billing added: '+item.procedure+' ₹'+amt.toLocaleString('en-IN'));
  });
  inner.appendChild(addBtn);

  var skipBtn = document.createElement('button');
  skipBtn.style.cssText = 'background:rgba(255,255,255,.2);border:none;color:#fff;border-radius:8px;padding:7px 10px;cursor:pointer;font-size:11px;flex-shrink:0';
  skipBtn.textContent = 'Skip';
  skipBtn.addEventListener('click', function(){ prompt.remove(); });
  inner.appendChild(skipBtn);

  prompt.appendChild(inner);
  document.body.appendChild(prompt);
  setTimeout(function(){ prompt.style.transform='translateY(0)'; }, 50);
  setTimeout(function(){ if(prompt.parentElement) prompt.remove(); }, 15000);
}

