/* ─── STORAGE SIZE MONITOR ───────────────────────────── */
function storage_renderMonitor() {
  var el = document.getElementById('storage-monitor');
  if (!el) return;

  /* Measure localStorage usage */
  var lsTotal = 0;
  var breakdown = [];
  try {
    for (var key in localStorage) {
      if (!localStorage.hasOwnProperty(key)) continue;
      var val = localStorage.getItem(key) || '';
      var sz  = (key.length + val.length) * 2; /* UTF-16 bytes */
      lsTotal += sz;
      breakdown.push({ key: key, size: sz });
    }
  } catch(e) {}

  var lsUsedKB  = Math.round(lsTotal / 1024);
  var lsLimitKB = 5120; /* 5MB */
  var pct        = Math.min(100, Math.round(lsUsedKB / lsLimitKB * 100));
  var color      = pct >= 80 ? '#dc2626' : pct >= 70 ? '#d97706' : '#059669';

  breakdown.sort(function(a,b){ return b.size-a.size; });

  /* Patient record count */
  var ptCount  = (DATA.patients||[]).length;
  var recCount = (DATA.patients||[]).reduce(function(s,p){ return s+(p.records||[]).length; },0);
  var imgCount = (DATA.patients||[]).reduce(function(s,p){ return s+(p.images||[]).length; },0);
  var imgSizeKB= Math.round((DATA.patients||[]).reduce(function(s,p){
    return s+(p.images||[]).reduce(function(s2,img){ return s2+(img.src||'').length*0.75/1024; },0);
  },0));

  el.innerHTML =
    '<div style="margin-bottom:10px">'
    + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">'
    + '<span style="font-size:11px;font-weight:700;color:#1e293b">localStorage Usage</span>'
    + '<span style="font-size:11px;font-weight:800;color:'+color+'">'+lsUsedKB+' KB / 5,120 KB ('+pct+'%)</span>'
    + '</div>'
    + '<div style="background:#e2e8f0;border-radius:6px;height:8px;overflow:hidden">'
    + '<div style="background:'+color+';width:'+pct+'%;height:8px;border-radius:6px;transition:width .4s"></div>'
    + '</div>'
    + (pct >= 80 ? '<div style="color:#dc2626;font-size:11px;font-weight:700;margin-top:6px">⚠️ Storage almost full — backup and clear old image data</div>' : '')
    + (pct >= 60 && pct < 80 ? '<div style="color:#d97706;font-size:11px;margin-top:4px">Storage usage is moderate — consider backing up</div>' : '')
    + '</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:10px">'
    + '<div style="background:#f8fafc;border-radius:8px;padding:8px;text-align:center">'
    + '<div style="font-size:18px;font-weight:800;color:#1e3a5f">'+ptCount+'</div>'
    + '<div style="font-size:10px;color:#64748b">Patients</div></div>'
    + '<div style="background:#f8fafc;border-radius:8px;padding:8px;text-align:center">'
    + '<div style="font-size:18px;font-weight:800;color:#1e3a5f">'+recCount+'</div>'
    + '<div style="font-size:10px;color:#64748b">Records</div></div>'
    + '<div style="background:#f8fafc;border-radius:8px;padding:8px;text-align:center">'
    + '<div style="font-size:18px;font-weight:800;color:'+(imgSizeKB>2000?'#dc2626':'#1e3a5f')+'">'+imgCount+'</div>'
    + '<div style="font-size:10px;color:#64748b">Images ('+(imgSizeKB>1024?(Math.round(imgSizeKB/1024)+'MB'):(imgSizeKB+'KB'))+')</div></div>'
    + '</div>'
    + '<div style="font-size:10px;color:#64748b">'
    + (imgSizeKB > 1500 ? '<span style="color:#d97706;font-weight:700">💡 Images are the largest data — export & delete old X-rays to free space.</span>' : 'Storage health looks good.')
    + '</div>';
}

/* ─── GLOBAL SEARCH ─────────────────────────────────── */
function globalSearch_open() {
  var existing = document.getElementById('global-search-modal');
  if (existing) { existing.remove(); return; }

  var modal = document.createElement('div');
  modal.id = 'global-search-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.7);z-index:9800;display:flex;flex-direction:column;align-items:center;padding:60px 16px 16px';
  modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });

  var box = document.createElement('div');
  box.style.cssText = 'background:#fff;border-radius:16px;width:100%;max-width:540px;max-height:75vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 60px rgba(0,0,0,.3)';

  var inputWrap = document.createElement('div');
  inputWrap.style.cssText = 'display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid #e2e8f0';
  inputWrap.innerHTML = '<span style="font-size:20px">🔍</span>';
  var inp = document.createElement('input');
  inp.id = 'global-search-inp';
  inp.type = 'text';
  inp.placeholder = 'Search patients, diagnoses, addresses, billing...';
  inp.style.cssText = 'flex:1;border:none;font-size:14px;outline:none;background:transparent;font-family:inherit';
  var closeBtn = document.createElement('button');
  closeBtn.style.cssText = 'background:none;border:none;font-size:20px;cursor:pointer;color:#94a3b8;padding:0;line-height:1';
  closeBtn.textContent = '✕';
  closeBtn.addEventListener('click', function(){ modal.remove(); });
  inputWrap.appendChild(inp);
  inputWrap.appendChild(closeBtn);

  var results = document.createElement('div');
  results.id = 'global-search-results';
  results.style.cssText = 'flex:1;overflow-y:auto;padding:8px';

  var hint = document.createElement('div');
  hint.style.cssText = 'padding:20px;text-align:center;color:#94a3b8;font-size:12px';
  hint.innerHTML = 'Search by:<br><strong>Name · Phone · Diagnosis · Treatment · Address · Outstanding dues</strong>';
  results.appendChild(hint);

  box.appendChild(inputWrap);
  box.appendChild(results);
  modal.appendChild(box);
  document.body.appendChild(modal);
  inp.focus();

  var searchTimer = null;
  inp.addEventListener('input', function(){
    clearTimeout(searchTimer);
    searchTimer = setTimeout(function(){ globalSearch_run(inp.value, results, modal); }, 200);
  });
}

function globalSearch_run(q, resultsEl, modal) {
  q = (q||'').trim().toLowerCase();
  resultsEl.innerHTML = '';
  if (q.length < 2) {
    var hint = document.createElement('div');
    hint.style.cssText = 'padding:20px;text-align:center;color:#94a3b8;font-size:12px';
    hint.textContent = 'Type at least 2 characters to search';
    resultsEl.appendChild(hint);
    return;
  }

  var matches = [];
  var pts = DATA.patients||[];
  pts.forEach(function(p) {
    var hits = [];
    /* Name + Phone */
    if ((p.name||'').toLowerCase().includes(q))   hits.push({ type:'name',   text:p.name });
    if ((p.phone||'').includes(q))                 hits.push({ type:'phone',  text:p.phone });
    if ((p.address||'').toLowerCase().includes(q)) hits.push({ type:'address',text:p.address });
    if ((p.medHistory||'').toLowerCase().includes(q)) hits.push({ type:'medical',text:p.medHistory });

    /* Records */
    (p.records||[]).forEach(function(r){
      if ((r.diagnosis||'').toLowerCase().includes(q))  hits.push({ type:'diagnosis', text:r.diagnosis, date:r.date });
      if ((r.treatment||'').toLowerCase().includes(q))  hits.push({ type:'treatment', text:r.treatment, date:r.date });
    });

    /* Billing */
    (p.billing||[]).forEach(function(b){
      var due = Math.max(0, Number(b.totalAmount||b.amount||0) - Number(b.paidAmount||0));
      if ((b.item||'').toLowerCase().includes(q))   hits.push({ type:'billing', text:b.item+' ₹'+Number(b.totalAmount||b.amount||0).toLocaleString('en-IN'), date:b.date });
      if (q.includes('due') || q.includes('unpaid') || q.includes('balance')) {
        if (due > 0) hits.push({ type:'dues', text:'₹'+due.toLocaleString('en-IN')+' outstanding', date:b.date });
      }
    });

    if (hits.length) matches.push({ patient:p, hits:hits.slice(0,3) });
  });

  matches.sort(function(a,b){ return (a.patient.name||'').localeCompare(b.patient.name||''); });

  if (!matches.length) {
    var noRes = document.createElement('div');
    noRes.style.cssText = 'padding:24px;text-align:center;color:#94a3b8;font-size:13px';
    noRes.textContent = 'No results for "' + q + '"';
    resultsEl.appendChild(noRes);
    return;
  }

  var countEl = document.createElement('div');
  countEl.style.cssText = 'padding:8px 12px 4px;font-size:10px;font-weight:700;color:#94a3b8;text-transform:uppercase';
  countEl.textContent = matches.length + ' patient' + (matches.length>1?'s':'') + ' matched';
  resultsEl.appendChild(countEl);

  var TYPE_COLORS = { name:'#1e3a5f', phone:'#0284c7', address:'#64748b', medical:'#7c3aed',
    diagnosis:'#1e3a5f', treatment:'#059669', billing:'#d97706', dues:'#dc2626' };

  matches.slice(0,20).forEach(function(m) {
    var card = document.createElement('div');
    card.style.cssText = 'background:#f8fafc;border-radius:10px;padding:10px 12px;margin-bottom:6px;cursor:pointer;border:1.5px solid transparent';
    card.addEventListener('mouseover', function(){ this.style.borderColor='#bfdbfe'; this.style.background='#eff6ff'; });
    card.addEventListener('mouseout',  function(){ this.style.borderColor='transparent'; this.style.background='#f8fafc'; });
    card.addEventListener('click', function(){
      modal.remove();
      openPatient(m.patient.id);
    });

    var nameRow = document.createElement('div');
    nameRow.style.cssText = 'font-size:13px;font-weight:800;color:#1e293b;margin-bottom:4px;display:flex;justify-content:space-between';
    nameRow.innerHTML = '<span>'+esc(m.patient.name)+'</span>'
      + '<span style="font-size:10px;font-weight:400;color:#94a3b8">'+(m.patient.phone||'')+'</span>';
    card.appendChild(nameRow);

    m.hits.forEach(function(hit) {
      var hitEl = document.createElement('div');
      hitEl.style.cssText = 'font-size:11px;color:#475569;display:flex;align-items:center;gap:5px;margin-top:2px';
      var badge = document.createElement('span');
      badge.style.cssText = 'font-size:9px;font-weight:700;color:'+(TYPE_COLORS[hit.type]||'#64748b')+';background:'+(TYPE_COLORS[hit.type]||'#64748b')+'18;padding:1px 5px;border-radius:4px;text-transform:uppercase;flex-shrink:0';
      badge.textContent = hit.type;
      var txt = document.createElement('span');
      txt.textContent = (hit.text||'').slice(0,60)+(hit.text&&hit.text.length>60?'...':'');
      hitEl.appendChild(badge);
      hitEl.appendChild(txt);
      card.appendChild(hitEl);
    });

    resultsEl.appendChild(card);
  });

  if (matches.length > 20) {
    var moreEl = document.createElement('div');
    moreEl.style.cssText = 'padding:10px;text-align:center;font-size:11px;color:#94a3b8';
    moreEl.textContent = '+ '+(matches.length-20)+' more results — refine your search';
    resultsEl.appendChild(moreEl);
  }
}

/* Clean up localStorage keys from removed features */
(function cleanupOrphanedKeys() {
  var obsolete = ['cam_key','camfolder_auto','camfolder_known_dirs',
    'npx_known','hos_chairside'];
  obsolete.forEach(function(k){
    try { localStorage.removeItem(k); } catch(e){}
  });
})();

/* ─── PATIENT TAGS ──────────────────────────────────── */
var PRESET_TAGS = [
  { label:'Hypertension',    color:'#dc2626', bg:'#fef2f2' },
  { label:'Diabetic',        color:'#d97706', bg:'#fffbeb' },
  { label:'Anticoagulants',  color:'#7c3aed', bg:'#f5f3ff' },
  { label:'Anxious',         color:'#0284c7', bg:'#eff6ff' },
  { label:'Paediatric',      color:'#059669', bg:'#ecfdf5' },
  { label:'VIP',             color:'#b45309', bg:'#fef3c7' },
  { label:'Referred',        color:'#0891b2', bg:'#ecfeff' },
  { label:'Ortho',           color:'#4f46e5', bg:'#eef2ff' },
];

function tags_render(ptId, containerId) {
  var el = document.getElementById(containerId);
  if (!el) return;
  var ptIdx = (DATA.patients||[]).findIndex(function(p){ return p.id===ptId; });
  if (ptIdx<0) return;
  var pt = DATA.patients[ptIdx];
  var currentTags = pt.tags||[];
  el.innerHTML = '';

  /* Preset tag chips */
  var chipsWrap = document.createElement('div');
  chipsWrap.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px';
  PRESET_TAGS.forEach(function(t) {
    var active = currentTags.includes(t.label);
    var btn = document.createElement('button');
    btn.style.cssText = 'border-radius:20px;padding:4px 10px;font-size:11px;font-weight:700;cursor:pointer;border:1.5px solid '+t.color+';background:'+(active?t.color:'transparent')+';color:'+(active?'#fff':t.color);
    btn.textContent = t.label;
    btn.dataset.tag  = t.label;
    btn.dataset.ptid = ptId;
    btn.addEventListener('click', function(){ tags_toggle(this); });
    chipsWrap.appendChild(btn);
  });
  el.appendChild(chipsWrap);

  /* Custom tag input */
  var row = document.createElement('div');
  row.style.cssText = 'display:flex;gap:6px;margin-top:4px';
  var inp = document.createElement('input');
  inp.id = 'tag-custom-input';
  inp.className = 'form-input';
  inp.placeholder = 'Custom tag...';
  inp.style.cssText = 'flex:1;font-size:12px;padding:5px 10px;height:32px';
  var addBtn = document.createElement('button');
  addBtn.style.cssText = 'background:#1e3a5f;color:#fff;border:none;border-radius:8px;padding:5px 12px;font-size:11px;font-weight:700;cursor:pointer;height:32px';
  addBtn.textContent = '+ Add';
  addBtn.addEventListener('click', function(){ tags_addCustom(ptId); });
  row.appendChild(inp);
  row.appendChild(addBtn);
  el.appendChild(row);
}

function tags_toggle(btn) {
  var tag   = btn.dataset.tag;
  var ptId  = btn.dataset.ptid;
  var ptIdx = (DATA.patients||[]).findIndex(function(p){ return p.id===ptId; });
  if (ptIdx<0) return;
  var tags = DATA.patients[ptIdx].tags||[];
  var i = tags.indexOf(tag);
  if (i>=0) tags.splice(i,1); else tags.push(tag);
  DATA.patients[ptIdx].tags = tags;
  if (activePt && activePt.id===ptId) activePt = DATA.patients[ptIdx];
  saveData();
  /* Update button visually */
  var preset = PRESET_TAGS.find(function(t){ return t.label===tag; });
  var active  = tags.includes(tag);
  if (preset) {
    btn.style.background = active ? preset.color : 'transparent';
    btn.style.color      = active ? '#fff' : preset.color;
  }
  renderPatientHeader();
}

function tags_addCustom(ptId) {
  var inp   = document.getElementById('tag-custom-input');
  var label = inp ? inp.value.trim() : '';
  if (!label) return;
  var ptIdx = (DATA.patients||[]).findIndex(function(p){ return p.id===ptId; });
  if (ptIdx<0) return;
  DATA.patients[ptIdx].tags = DATA.patients[ptIdx].tags||[];
  if (!DATA.patients[ptIdx].tags.includes(label)) {
    DATA.patients[ptIdx].tags.push(label);
    DATA.patients[ptIdx].tags.sort();
    if (activePt && activePt.id===ptId) activePt = DATA.patients[ptIdx];
    saveData();
  }
  if (inp) inp.value='';
  tags_render(ptId, 'tags-panel');
  renderPatientHeader();
}

function tags_renderChips(tags) {
  if (!tags||!tags.length) return '';
  return tags.map(function(tag){
    var preset = PRESET_TAGS.find(function(t){ return t.label===tag; });
    var color  = preset ? preset.color : '#475569';
    var bg     = preset ? preset.bg    : '#f1f5f9';
    return '<span style="font-size:10px;font-weight:700;color:'+color+';background:'+bg+';border-radius:20px;padding:2px 8px;white-space:nowrap">'+tag+'</span>';
  }).join('');
}

function ptHeader_addTags() {
  if (!activePt) return;
  var header = document.getElementById('pt-detail-header');
  if (!header || document.getElementById('pt-tags-chips')) return;
  var tags = activePt.tags||[];
  if (!tags.length) return;
  var chipsDiv = document.createElement('div');
  chipsDiv.id = 'pt-tags-chips';
  chipsDiv.style.cssText = 'display:flex;flex-wrap:wrap;gap:4px;margin-top:8px;padding-top:8px;border-top:1px solid #e2e8f0';
  chipsDiv.innerHTML = tags_renderChips(tags)
    + '<button onclick="tags_openPanel()" style="font-size:10px;font-weight:700;color:#94a3b8;background:none;border:1px dashed #cbd5e1;border-radius:20px;padding:2px 8px;cursor:pointer">+ Edit tags</button>';
  var card = header.querySelector('.card-body') || header.querySelector('.card') || header;
  card.appendChild(chipsDiv);
}

function tags_openPanel() {
  if (!activePt) return;
  var old = document.getElementById('tags-modal');
  if (old) { old.remove(); return; }
  var modal = document.createElement('div');
  modal.id = 'tags-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9900;display:flex;align-items:flex-end;justify-content:center;padding:16px';
  var sheet = document.createElement('div');
  sheet.style.cssText = 'background:#fff;border-radius:20px 20px 0 0;width:100%;max-width:520px;padding:20px';
  sheet.innerHTML = '<div style="font-size:14px;font-weight:800;color:#1e293b;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center">'
    + '<span>🏷️ Patient Tags — '+esc(activePt.name)+'</span>'
    + '<button id="tags-close-btn" style="background:none;border:none;font-size:22px;cursor:pointer;color:#94a3b8">✕</button>'
    + '</div>'
    + '<div id="tags-panel"></div>';
  modal.appendChild(sheet);
  document.body.appendChild(modal);
  document.getElementById('tags-close-btn').addEventListener('click', function(){ modal.remove(); ptHeader_addTags(); });
  modal.addEventListener('click', function(e){ if(e.target===modal){ modal.remove(); ptHeader_addTags(); } });
  tags_render(activePt.id, 'tags-panel');
}

/* ─── BULK PATIENT EXPORT ─────────────────────────── */
function exportPatientsCSV() {
  var pts = DATA.patients||[];
  if (!pts.length) { alert('No patients to export.'); return; }

  var today = todayISO();

  var rows = [
    ['Name','Phone','Age','DOB','Gender','Address','Chief Complaint',
     'Medical History','Tags','Status','Patient Since',
     'Total Records','Last Visit',
     'Total Billed','Total Paid','Outstanding',
     'Recall Date','Notes']
  ];

  pts.forEach(function(p) {
    var total = (p.billing||[]).reduce(function(s,b){ return s+Number(b.totalAmount||b.amount||0); },0);
    var paid  = (p.billing||[]).reduce(function(s,b){ return s+Number(b.paidAmount||(b.paid?Number(b.totalAmount||b.amount||0):0)); },0);
    var due   = Math.max(0, total-paid);
    var recs  = (p.records||[]).slice().sort(function(a,b){ return (b.date||'').localeCompare(a.date||''); });
    var lastVisit = recs.length ? recs[0].date : '';
    rows.push([
      p.name||'',
      p.phone||'',
      p.age||'',
      fmtDob(p.dob||''),
      p.gender||'',
      (p.address||'').replace(/,/g,' '),
      (p.complaint||'').replace(/,/g,' '),
      (p.medHistory||'').replace(/,/g,' '),
      (p.tags||[]).join('; '),
      p.treatmentStatus||'ongoing',
      fmtDob(p.createdAt||''),
      (p.records||[]).length,
      fmtDob(lastVisit),
      total,
      paid,
      due,
      fmtDob(p.recallDate||''),
      ''
    ]);
  });

  /* Build CSV */
  var csv = rows.map(function(row){
    return row.map(function(cell){
      var s = String(cell==null?'':cell);
      if (s.includes(',') || s.includes('"') || s.includes('\n'))
        s = '"' + s.replace(/"/g,'""') + '"';
      return s;
    }).join(',');
  }).join('\n');

  /* Download */
  var blob = new Blob([csv], { type:'text/csv;charset=utf-8;' });
  var url  = URL.createObjectURL(blob);
  var a    = document.createElement('a');
  a.href = url;
  a.download = 'HOS_Patients_' + today + '.csv';
  a.click();
  URL.revokeObjectURL(url);
  showToast && showToast('Exported '+pts.length+' patients');
}

/* ─── APPOINTMENT SLOTS ─────────────────────────────── */
var DEFAULT_WORKING_HOURS = {
  sessions: [
    { start:'10:00', end:'13:00' },
    { start:'17:00', end:'20:00' }
  ],
  slotMins: 15,
  workDays: [1,2,3,4,5,6]  /* Mon-Sat; 0=Sun */
};

function slots_getConfig() {
  try {
    var raw = localStorage.getItem('hos_working_hours');
    return raw ? JSON.parse(raw) : DEFAULT_WORKING_HOURS;
  } catch(e) { return DEFAULT_WORKING_HOURS; }
}

function slots_saveConfig(cfg) {
  localStorage.setItem('hos_working_hours', JSON.stringify(cfg));
}

/* Generate all slot times for a given date */
function slots_forDate(dateStr) {
  var cfg = slots_getConfig();
  var slots = [];
  cfg.sessions.forEach(function(sess) {
    var [sh,sm] = sess.start.split(':').map(Number);
    var [eh,em] = sess.end.split(':').map(Number);
    var cur = sh*60+sm;
    var end = eh*60+em;
    while (cur + cfg.slotMins <= end) {
      var hh = Math.floor(cur/60);
      var mm = cur%60;
      slots.push((hh<10?'0':'')+hh+':'+(mm<10?'0':'')+mm);
      cur += cfg.slotMins;
    }
  });
  /* Mark which slots are taken */
  var taken = {};
  (DATA.appointments||[]).forEach(function(a) {
    if (a.date===dateStr && a.status!=='cancelled') taken[a.time]=true;
  });
  return slots.map(function(t){ return { time:t, taken:!!taken[t] }; });
}

/* Render slot picker into a container */
function slots_renderPicker(dateStr, containerId, onSelect) {
  var el = document.getElementById(containerId);
  if (!el || !dateStr) return;

  var slots = slots_forDate(dateStr);
  if (!slots.length) {
    el.innerHTML = '<div style="font-size:11px;color:#94a3b8;padding:8px">No slots defined for this day. Configure in Settings.</div>';
    return;
  }

  el.innerHTML = '';
  var label = document.createElement('div');
  label.style.cssText = 'font-size:11px;font-weight:700;color:#64748b;margin-bottom:8px';
  label.textContent = 'Available slots:';
  el.appendChild(label);

  var grid = document.createElement('div');
  grid.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(72px,1fr));gap:6px';

  var fmt12 = function(t) {
    var p=t.split(':').map(Number);
    return ((p[0]%12)||12)+':'+(p[1]<10?'0':'')+p[1]+' '+(p[0]>=12?'PM':'AM');
  };

  slots.forEach(function(slot) {
    var btn = document.createElement('button');
    btn.style.cssText = 'border-radius:8px;padding:7px 4px;font-size:11px;font-weight:700;cursor:'+(slot.taken?'not-allowed':'pointer')
      +';border:1.5px solid '+(slot.taken?'#e2e8f0':'#bfdbfe')
      +';background:'+(slot.taken?'#f1f5f9':'#eff6ff')
      +';color:'+(slot.taken?'#cbd5e1':'#1e3a5f')
      +';text-align:center;transition:all .1s';
    btn.textContent = fmt12(slot.time);
    btn.disabled = slot.taken;
    if (!slot.taken) {
      btn.addEventListener('click', function() {
        /* Highlight selected */
        grid.querySelectorAll('button').forEach(function(b){
          b.style.background='#eff6ff'; b.style.color='#1e3a5f'; b.style.borderColor='#bfdbfe';
        });
        btn.style.background='#1e3a5f'; btn.style.color='#fff'; btn.style.borderColor='#1e3a5f';
        if (typeof onSelect==='function') onSelect(slot.time);
      });
    }
    grid.appendChild(btn);
  });

  el.appendChild(grid);
}

/* Settings UI for working hours */
function slots_showSettings() {
  var cfg = slots_getConfig();
  var existing = document.getElementById('slots-settings-modal');
  if (existing) { existing.remove(); return; }

  var modal = document.createElement('div');
  modal.id = 'slots-settings-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9900;display:flex;align-items:flex-end;justify-content:center;padding:16px';

  var sheet = document.createElement('div');
  sheet.style.cssText = 'background:#fff;border-radius:20px 20px 0 0;width:100%;max-width:520px;padding:20px;max-height:80vh;overflow-y:auto';
  sheet.innerHTML =
    '<div style="font-size:14px;font-weight:800;color:#1e293b;margin-bottom:16px;display:flex;justify-content:space-between">'
    + '<span>⏰ Working Hours & Slots</span>'
    + '<button id="slots-close-btn" style="background:none;border:none;font-size:22px;cursor:pointer;color:#94a3b8">✕</button>'
    + '</div>'
    + '<div style="margin-bottom:14px">'
    + '<label style="font-size:11px;font-weight:700;color:#64748b;display:block;margin-bottom:6px">SLOT DURATION (minutes)</label>'
    + '<div style="display:flex;gap:8px">'
    + [10,15,20,30].map(function(m){
        return '<button data-mins="'+m+'" onclick="slots_setDuration(this)" style="flex:1;padding:8px;border-radius:8px;font-weight:700;font-size:13px;cursor:pointer;border:1.5px solid '+(cfg.slotMins===m?'#1e3a5f':'#e2e8f0')+';background:'+(cfg.slotMins===m?'#1e3a5f':'#fff')+';color:'+(cfg.slotMins===m?'#fff':'#1e293b')+'">'+m+'m</button>';
      }).join('')
    + '</div></div>'
    + '<div style="margin-bottom:14px">'
    + '<label style="font-size:11px;font-weight:700;color:#64748b;display:block;margin-bottom:6px">SESSION TIMES</label>'
    + cfg.sessions.map(function(s,i){
        return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">'
          + '<input type="time" id="slot-sess-start-'+i+'" value="'+s.start+'" class="form-input" style="flex:1;font-size:13px"/>'
          + '<span style="color:#94a3b8;font-weight:700">→</span>'
          + '<input type="time" id="slot-sess-end-'+i+'" value="'+s.end+'" class="form-input" style="flex:1;font-size:13px"/>'
          + (cfg.sessions.length>1?'<button data-idx="'+i+'" onclick="slots_removeSession(this)" style="background:none;border:none;color:#dc2626;cursor:pointer;font-size:18px;padding:0 4px">✕</button>':'')
          + '</div>';
      }).join('')
    + '<button onclick="slots_addSession()" style="background:#f1f5f9;border:1px solid #e2e8f0;color:#1e293b;border-radius:8px;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer">+ Add Session</button>'
    + '</div>'
    + '<button onclick="slots_saveSettings()" style="width:100%;background:#059669;color:#fff;border:none;border-radius:12px;padding:14px;font-size:14px;font-weight:700;cursor:pointer">✅ Save</button>';

  modal.appendChild(sheet);
  document.body.appendChild(modal);
  document.getElementById('slots-close-btn').addEventListener('click', function(){ modal.remove(); });
  modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });
}

function slots_setDuration(btn) {
  var mins = parseInt(btn.dataset.mins);
  var btns = btn.parentNode.querySelectorAll('button');
  btns.forEach(function(b){
    b.style.background = b===btn?'#1e3a5f':'#fff';
    b.style.color      = b===btn?'#fff':'#1e293b';
    b.style.borderColor= b===btn?'#1e3a5f':'#e2e8f0';
  });
  var cfg = slots_getConfig(); cfg.slotMins=mins; slots_saveConfig(cfg);
}

function slots_addSession() {
  var cfg = slots_getConfig();
  cfg.sessions.push({ start:'09:00', end:'12:00' });
  slots_saveConfig(cfg);
  slots_showSettings(); /* re-render */
  var old = document.getElementById('slots-settings-modal');
  if (old) { old.remove(); slots_showSettings(); }
}

function slots_removeSession(btn) {
  var idx = parseInt(btn.dataset.idx);
  var cfg = slots_getConfig();
  cfg.sessions.splice(idx,1);
  slots_saveConfig(cfg);
  var old = document.getElementById('slots-settings-modal');
  if (old) { old.remove(); slots_showSettings(); }
}

function slots_saveSettings() {
  var cfg = slots_getConfig();
  cfg.sessions.forEach(function(s,i){
    var startEl = document.getElementById('slot-sess-start-'+i);
    var endEl   = document.getElementById('slot-sess-end-'+i);
    if (startEl) s.start = startEl.value;
    if (endEl)   s.end   = endEl.value;
  });
  slots_saveConfig(cfg);
  var modal = document.getElementById('slots-settings-modal');
  if (modal) modal.remove();
  showToast && showToast('Working hours saved');
}

/* ─── FEATURE 7: Treatment plan summary in patient header ─── */
function ptHeader_addTxPlan() {
  if (!activePt) return;
  var pending = (activePt.treatmentPlan||[]).filter(function(t){
    return t.status !== 'done';
  });
  if (!pending.length) return;

  var header = document.getElementById('pt-detail-header');
  if (!header || document.getElementById('pt-txplan-strip')) return;

  var strip = document.createElement('div');
  strip.id = 'pt-txplan-strip';
  strip.style.cssText = 'margin-top:8px;padding-top:8px;border-top:1px solid #e2e8f0;cursor:pointer';
  strip.title = 'Click to open Treatment Plan';
  strip.addEventListener('click', function(){ switchGroup('clinical','tx-plan'); });

  var label = document.createElement('div');
  label.style.cssText = 'font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:5px';
  label.textContent = '📋 Pending Treatment Plan (' + pending.length + ')';
  strip.appendChild(label);

  var items = document.createElement('div');
  items.style.cssText = 'display:flex;flex-wrap:wrap;gap:5px';
  pending.slice(0,4).forEach(function(t) {
    var chip = document.createElement('span');
    chip.style.cssText = 'font-size:11px;font-weight:600;color:#1e3a5f;background:#eff6ff;border:1px solid #bfdbfe;border-radius:6px;padding:3px 8px;white-space:nowrap';
    chip.textContent = t.procedure||t.tooth||'Treatment';
    items.appendChild(chip);
  });
  if (pending.length > 4) {
    var more = document.createElement('span');
    more.style.cssText = 'font-size:11px;color:#94a3b8;padding:3px 6px';
    more.textContent = '+' + (pending.length-4) + ' more';
    items.appendChild(more);
  }
  strip.appendChild(items);

  var card = header.querySelector('.card-body') || header.querySelector('.card') || header;
  card.appendChild(strip);
}




