/* ─── RECORD EDITING ─────────────────────────────────── */
function rec_editLoad(recId) {
  var rec = (activePt.records||[]).find(function(r){ return r.id===recId; });
  if (!rec) return;

  /* Scroll to form */
  var form = document.getElementById('rec-form') || document.querySelector('[id^="tab-content-records"]');

  /* Fill form fields */
  var set = function(id, val) {
    var el = document.getElementById(id);
    if (el) el.value = val||'';
  };
  set('rec-date',  rec.date||todayISO());
  set('rec-diag',  rec.diagnosis||'');
  set('rec-treat', rec.treatment||'');
  set('rec-notes', rec.notes||'');
  set('rec-dur-mins', rec.durationMins||rec.duration>0 ? (rec.durationMins || Math.round(rec.duration/60)) : '');

  /* Mark as edit mode */
  var editIdEl = document.getElementById('rec-edit-id');
  if (editIdEl) { editIdEl.textContent = recId; editIdEl.style.display='none'; }

  /* Update save button label */
  var saveBtn = document.querySelector('[onclick="saveRecord()"]');
  if (saveBtn) { saveBtn.textContent = '💾 Update Record'; saveBtn.style.background='#d97706'; }

  /* Scroll form into view */
  if (form) form.scrollIntoView({ behavior:'smooth', block:'start' });
  setTimeout(function(){ var d=document.getElementById('rec-diag'); if(d) d.focus(); }, 300);

  showToast && showToast('Editing record — make changes and tap Update');
}

function rec_editCancel() {
  var editIdEl = document.getElementById('rec-edit-id');
  if (editIdEl) editIdEl.textContent = '';
  var saveBtn = document.querySelector('[onclick="saveRecord()"]');
  if (saveBtn) { saveBtn.textContent = 'Save'; saveBtn.style.background=''; }
}

function bil_markFullyPaid(billId) {
  var ptIdx = DATA.patients.findIndex(function(p){ return p.id===activePt.id; });
  var bIdx  = DATA.patients[ptIdx].billing.findIndex(function(b){ return b.id===billId; });
  if (bIdx<0) return;
  var b = DATA.patients[ptIdx].billing[bIdx];
  var due = Math.max(0, Number(b.totalAmount||b.amount||0) - Number(b.paidAmount||0));
  if (due <= 0) { showToast && showToast('Already fully paid'); return; }
  if (!confirm('Mark ₹'+due.toLocaleString('en-IN')+' as collected?')) return;
  if (!b.payments) b.payments = [];
  b.payments.push({id:'pmt'+Date.now(), amount:due, date:todayISO(), mode:'Cash', note:'Marked fully paid'});
  b.paidAmount  = Number(b.totalAmount||b.amount||0);
  b.paid        = true;
  DATA.patients[ptIdx].billing[bIdx] = b;
  activePt = DATA.patients[ptIdx];
  saveData(); renderBillingTab(); renderPatientHeader();
  showToast && showToast('✅ Marked fully paid');
}

/* ─── RECORD FORM STATE PERSISTENCE ─────────────────── */
var _recFormState = {};

function recForm_save() {
  var fields = ['rec-date','rec-diag','rec-treat','rec-notes','rec-dur-mins'];
  fields.forEach(function(id) {
    var el = document.getElementById(id);
    if (el) _recFormState[id] = el.value;
  });
  var formVisible = document.getElementById('rec-form');
  _recFormState._visible = formVisible ? formVisible.style.display !== 'none' : false;
  var editEl = document.getElementById('rec-edit-id');
  _recFormState._editId = editEl ? editEl.textContent.trim() : '';
}

function recForm_restore() {
  if (!_recFormState._visible) return;
  var formEl = document.getElementById('rec-form');
  if (formEl) formEl.style.display = 'block';
  var fields = ['rec-date','rec-diag','rec-treat','rec-notes','rec-dur-mins'];
  fields.forEach(function(id) {
    if (_recFormState[id] !== undefined) {
      var el = document.getElementById(id);
      if (el) el.value = _recFormState[id];
    }
  });
  /* Restore main timer UI if it was running */
  procTrack_restoreUI();
  if (_recFormState._editId) {
    var editEl = document.getElementById('rec-edit-id');
    if (editEl) editEl.textContent = _recFormState._editId;
    var saveBtn = document.querySelector('[onclick="saveRecord()"]');
    if (saveBtn) { saveBtn.textContent = '💾 Update Record'; saveBtn.style.background = '#d97706'; }
  }
}

function recForm_clear() {
  _recFormState = {};
}

/* ─── CLINICAL SUB-TIMERS ────────────────────────────── */
var CLINICAL_TIMERS = [
  { id:'etch',  label:'Etching',     seconds:30,  color:'#dc2626' },
  { id:'edta',  label:'EDTA',        seconds:60,  color:'#7c3aed' },
  { id:'hypo',  label:'Hypo/NaOCl',  seconds:30,  color:'#0284c7' },
  { id:'bond',  label:'Bonding',     seconds:20,  color:'#059669' },
  { id:'light', label:'Light Cure',  seconds:20,  color:'#d97706' },
  { id:'set',   label:'Setting Time',seconds:90,  color:'#475569' },
];
var _clinTimers = {}; /* id → intervalId */

function clinTimer_render(containerId) {
  var el = document.getElementById(containerId);
  if (!el) return;
  var html = '<div style="font-size:10px;font-weight:800;color:#94a3b8;text-transform:uppercase;margin-bottom:8px">⏱ Clinical Timers</div>';
  html += '<div style="display:flex;flex-wrap:wrap;gap:6px">';
  CLINICAL_TIMERS.forEach(function(t) {
    html += '<div style="background:#f8fafc;border:1.5px solid #e2e8f0;border-radius:10px;padding:8px 10px;min-width:90px;text-align:center">'
      + '<div style="font-size:10px;font-weight:700;color:#475569;margin-bottom:4px">'+t.label+'</div>'
      + '<div id="ct-display-'+t.id+'" style="font-size:16px;font-weight:800;color:'+t.color+';margin-bottom:6px;font-variant-numeric:tabular-nums">'+clinTimer_fmt(t.seconds)+'</div>'
      + '<div style="display:flex;gap:4px;justify-content:center">'
      + '<button data-tid="'+t.id+'" data-secs="'+t.seconds+'" onclick="clinTimer_start(this.dataset.tid,parseInt(this.dataset.secs))" id="ct-start-'+t.id+'" style="background:'+t.color+';color:#fff;border:none;border-radius:6px;padding:3px 8px;font-size:10px;font-weight:700;cursor:pointer">▶</button>'
      + '<button data-tid="'+t.id+'" onclick="clinTimer_reset(this.dataset.tid)" style="background:#f1f5f9;border:none;border-radius:6px;padding:3px 8px;font-size:10px;cursor:pointer">↺</button>'
      + '</div></div>';
  });
  /* Custom timer */
  html += '<div style="background:#f8fafc;border:1.5px dashed #e2e8f0;border-radius:10px;padding:8px 10px;min-width:90px;text-align:center">'
    + '<div style="font-size:10px;font-weight:700;color:#475569;margin-bottom:4px">Custom</div>'
    + '<input id="ct-custom-secs" type="number" min="5" max="600" placeholder="sec" style="width:55px;border:1px solid #e2e8f0;border-radius:6px;padding:3px 5px;font-size:11px;text-align:center;margin-bottom:4px"/>'
    + '<div style="display:flex;gap:4px;justify-content:center">'
    + '<button onclick="clinTimer_startCustom()" style="background:#1e3a5f;color:#fff;border:none;border-radius:6px;padding:3px 8px;font-size:10px;font-weight:700;cursor:pointer">▶</button>'
    + '<button onclick="clinTimer_reset(\'custom\')" style="background:#f1f5f9;border:none;border-radius:6px;padding:3px 8px;font-size:10px;cursor:pointer">↺</button>'
    + '</div><div id="ct-display-custom" style="font-size:14px;font-weight:800;color:#1e3a5f;margin-top:4px"></div>'
    + '</div>';
  html += '</div>';
  el.innerHTML = html;
}

function clinTimer_fmt(s) {
  s = Math.max(0, Math.round(s));
  return (Math.floor(s/60)<10?'0':'')+Math.floor(s/60)+':'+(s%60<10?'0':'')+(s%60);
}

function clinTimer_start(tid, totalSecs) {
  /* Stop if already running */
  if (_clinTimers[tid]) { clearInterval(_clinTimers[tid]); delete _clinTimers[tid]; }
  var remaining = totalSecs;
  var dispEl = document.getElementById('ct-display-'+tid);
  var t = CLINICAL_TIMERS.find(function(x){ return x.id===tid; });
  var color = t ? t.color : '#1e3a5f';

  _clinTimers[tid] = setInterval(function() {
    remaining--;
    var el = document.getElementById('ct-display-'+tid);
    if (el) {
      el.textContent = clinTimer_fmt(remaining);
      el.style.color = remaining <= 5 ? '#dc2626' : color;
    }
    if (remaining <= 0) {
      clearInterval(_clinTimers[tid]);
      delete _clinTimers[tid];
      /* Flash + beep */
      var label = t ? t.label : 'Timer';
      showToast && showToast('⏰ '+label+' done!');
      if (el) { el.textContent = 'DONE'; el.style.color = '#059669'; }
    }
  }, 1000);
}

function clinTimer_startCustom() {
  var secs = parseInt((document.getElementById('ct-custom-secs')||{}).value||0);
  if (!secs || secs<5) { alert('Enter seconds (min 5)'); return; }
  if (_clinTimers['custom']) { clearInterval(_clinTimers['custom']); delete _clinTimers['custom']; }
  var remaining = secs;
  _clinTimers['custom'] = setInterval(function() {
    remaining--;
    var el = document.getElementById('ct-display-custom');
    if (el) {
      el.textContent = clinTimer_fmt(remaining);
      el.style.color = remaining <= 5 ? '#dc2626' : '#1e3a5f';
    }
    if (remaining <= 0) {
      clearInterval(_clinTimers['custom']);
      delete _clinTimers['custom'];
      showToast && showToast('⏰ Custom timer done!');
      var el2 = document.getElementById('ct-display-custom');
      if (el2) { el2.textContent = 'DONE'; el2.style.color = '#059669'; }
    }
  }, 1000);
}

function clinTimer_reset(tid) {
  if (_clinTimers[tid]) { clearInterval(_clinTimers[tid]); delete _clinTimers[tid]; }
  var t = CLINICAL_TIMERS.find(function(x){ return x.id===tid; });
  var el = document.getElementById('ct-display-'+tid);
  if (el && t) { el.textContent = clinTimer_fmt(t.seconds); el.style.color = t.color; }
  if (tid==='custom') {
    var el2 = document.getElementById('ct-display-custom');
    if (el2) { el2.textContent = ''; }
  }
}

/* Restore main proc timer UI if timer was running when user left the tab */
function procTrack_restoreUI() {
  if (!procTrack_startTs) return;
  var startBtn = document.getElementById('proc-track-start-btn');
  var stopBtn  = document.getElementById('proc-track-stop-btn');
  var status   = document.getElementById('proc-track-status');
  if (startBtn) startBtn.style.display = 'none';
  if (stopBtn)  stopBtn.style.display  = 'inline-block';
  if (status)   status.textContent     = 'Timer running...';
  /* Restart the display update loop */
  if (!procTrack_intervalId) {
    procTrack_intervalId = setInterval(function() {
      var el = document.getElementById('proc-track-status');
      if (!el || !procTrack_startTs) { clearInterval(procTrack_intervalId); procTrack_intervalId=null; return; }
      var secs = Math.floor((Date.now() - procTrack_startTs) / 1000);
      var m = Math.floor(secs/60), s = secs%60;
      el.textContent = (m<10?'0':'')+m+':'+(s<10?'0':'')+s;
    }, 1000);
  }
}


/* ═══════════════════════════════════════════════════════════════
   FMR — FULL MOUTH REHABILITATION MODULE
   Tooth-wise RCT + Crown tracking, per-tooth costs, visit log,
   instalment payments, old patient import, progress report
═══════════════════════════════════════════════════════════════ */

/* ─── CONSTANTS ──────────────────────────────────────────────── */
var FMR_STATUS = {
  planned:    { label:'Planned',        icon:'○', color:'#94a3b8', bg:'#f1f5f9' },
  inprogress: { label:'RCT In Progress',icon:'◑', color:'#0284c7', bg:'#e0f2fe' },
  rctdone:    { label:'RCT Done',       icon:'●', color:'#7c3aed', bg:'#f5f3ff' },
  impression: { label:'Impression',     icon:'◈', color:'#d97706', bg:'#fffbeb' },
  inlab:      { label:'Crown in Lab',   icon:'◆', color:'#dc2626', bg:'#fef2f2' },
  complete:   { label:'Complete',       icon:'✓', color:'#059669', bg:'#ecfdf5' },
  skip:       { label:'Skip / Not Req', icon:'✕', color:'#cbd5e1', bg:'#f8fafc' },
};

var FMR_STATUS_ORDER = ['planned','inprogress','rctdone','impression','inlab','complete','skip'];

/* FDI tooth layout: [quadrant, position, type] */
var FMR_TOOTH_META = {
  '18':['U','M3'],'17':['U','M2'],'16':['U','M1'],'15':['U','P2'],'14':['U','P1'],
  '13':['U','C'], '12':['U','L2'],'11':['U','I2'],
  '21':['U','I1'],'22':['U','L1'],'23':['U','C2'],'24':['U','P3'],
  '25':['U','P4'],'26':['U','M4'],'27':['U','M5'],'28':['U','M6'],
  '48':['L','M3'],'47':['L','M2'],'46':['L','M1'],'45':['L','P2'],'44':['L','P1'],
  '43':['L','C'], '42':['L','L2'],'41':['L','I2'],
  '31':['L','I1'],'32':['L','L1'],'33':['L','C2'],'34':['L','P3'],
  '35':['L','P4'],'36':['L','M4'],'37':['L','M5'],'38':['L','M6'],
};

/* Tooth type → default costs */
function fmr_defaultRCTCost(tooth, defaults) {
  var meta = FMR_TOOTH_META[String(tooth)];
  if (!meta) return defaults.rct_molar||6000;
  var t = meta[1];
  if (t.startsWith('I')||t.startsWith('C')) return defaults.rct_anterior||3000;
  if (t.startsWith('P')) return defaults.rct_premolar||4500;
  return defaults.rct_molar||6000;
}

/* ─── DATA LAYER ─────────────────────────────────────────────── */
function fmr_getCases() { return DATA.fmrCases||[]; }
function fmr_getCase(id) { return (DATA.fmrCases||[]).find(function(x){ return x.id===id; })||null; }
function fmr_saveCase(c) {
  if (!DATA.fmrCases) DATA.fmrCases = [];
  var idx = DATA.fmrCases.findIndex(function(x){ return x.id===c.id; });
  if (idx>=0) DATA.fmrCases[idx]=c; else DATA.fmrCases.push(c);
  saveData();
}
function fmr_deleteCase(id) {
  DATA.fmrCases=(DATA.fmrCases||[]).filter(function(x){ return x.id!==id; }); saveData();
}

/* ─── CALCULATIONS ───────────────────────────────────────────── */
function fmr_calcTotal(c) {
  var total = 0;
  Object.keys(c.teeth||{}).forEach(function(tn){
    var t = c.teeth[tn];
    if (t.status==='skip') return;
    total += Number(t.rctCost||0) + Number(t.crownCost||0);
  });
  return total;
}
function fmr_progress(c) {
  var teeth = Object.keys(c.teeth||{}).filter(function(k){ return (c.teeth[k].status||'planned')!=='skip'; });
  var done  = teeth.filter(function(k){ return c.teeth[k].status==='complete'; }).length;
  return { total:teeth.length, done:done, pct: teeth.length ? Math.round(done/teeth.length*100) : 0 };
}
function fmr_statusCounts(c) {
  var counts = {};
  FMR_STATUS_ORDER.forEach(function(s){ counts[s]=0; });
  Object.values(c.teeth||{}).forEach(function(t){ var s=t.status||'planned'; if(counts[s]!==undefined) counts[s]++; });
  return counts;
}

/* ─── PAGE RENDER ─────────────────────────────────────────────── */
var _fmrDetailId = null;

function renderFMRPage() {
  var el = document.getElementById('page-fmr');
  if (!el) return;
  _fmrDetailId = null;
  el.innerHTML = '';

  var cases = fmr_getCases();
  var active = cases.filter(function(c){ return c.status==='active'; }).length;
  var done   = cases.filter(function(c){ return c.status==='completed'; }).length;
  var totalRev = cases.reduce(function(s,c){ return s+fmr_calcTotal(c); }, 0);
  var totalPaid= cases.reduce(function(s,c){ return s+Number(c.paidAmount||0); }, 0);

  /* ── Header ── */
  var hdr = document.createElement('div');
  hdr.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px">'
    +'<h1 class="page-title" style="margin:0">🦷 FMR Cases</h1>'
    +'<button onclick="fmr_showForm(null)" style="background:#1e3a5f;color:#fff;border:none;border-radius:10px;padding:8px 16px;font-size:13px;font-weight:700;cursor:pointer">➕ New FMR Case</button>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(90px,1fr));gap:8px;margin-bottom:14px">'
    +[
      ['Total', cases.length, '#1e3a5f'],
      ['Active', active, '#059669'],
      ['Completed', done, '#1d4ed8'],
      ['Revenue', '₹'+Math.round(totalRev/1000)+'k', '#1e3a5f'],
      ['Collected', '₹'+Math.round(totalPaid/1000)+'k', '#059669'],
      ['Pending', '₹'+Math.round(Math.max(0,totalRev-totalPaid)/1000)+'k', '#dc2626'],
    ].map(function(s){
      return '<div style="background:#fff;border-radius:10px;padding:10px;text-align:center;box-shadow:0 1px 3px rgba(0,0,0,.07)">'
        +'<div style="font-size:16px;font-weight:800;color:'+s[2]+'">'+s[1]+'</div>'
        +'<div style="font-size:10px;color:#64748b;font-weight:600">'+s[0]+'</div></div>';
    }).join('')+'</div>';
  el.appendChild(hdr);

  if (!cases.length) {
    el.innerHTML += '<div style="text-align:center;padding:40px;color:#94a3b8"><div style="font-size:40px;margin-bottom:10px">🦷</div><div style="font-size:14px;font-weight:700">No FMR cases yet</div><div style="font-size:12px;margin-top:6px">Tap ➕ New FMR Case to start</div></div>';
    return;
  }

  var sorted = cases.slice().sort(function(a,b){ return (b.startDate||'').localeCompare(a.startDate||''); });
  var listWrap = document.createElement('div');
  listWrap.style.cssText = 'display:flex;flex-direction:column;gap:10px';
  sorted.forEach(function(c){ listWrap.appendChild(fmr_buildCard(c)); });
  el.appendChild(listWrap);
}

/* ─── CASE CARD ──────────────────────────────────────────────── */
function fmr_buildCard(c) {
  var prog = fmr_progress(c);
  var sc   = fmr_statusCounts(c);
  var total= fmr_calcTotal(c);
  var pending = Math.max(0, total - Number(c.paidAmount||0));
  var stColor = c.status==='completed'?'#1d4ed8':c.status==='on-hold'?'#d97706':'#059669';

  var card = document.createElement('div');
  card.style.cssText = 'background:#fff;border-radius:14px;padding:14px 16px;box-shadow:0 1px 4px rgba(0,0,0,.08);border-left:4px solid '+stColor+';cursor:pointer';
  card.addEventListener('click', function(){ fmr_openDetail(c.id); });

  var inner = '';
  /* Header */
  inner += '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px">'
    +'<div><div style="font-size:14px;font-weight:800;color:#1e293b">'+esc(c.patientName||'')+'</div>'
    +'<div style="font-size:11px;color:#64748b;margin-top:2px">'+(c.phone||'')+(c.startDate?' · Started '+fmtDate(c.startDate):'')+'</div></div>'
    +'<span style="font-size:10px;font-weight:800;padding:3px 8px;border-radius:6px;background:'+stColor+'18;color:'+stColor+'">'
    +(c.status==='completed'?'Completed':c.status==='on-hold'?'On Hold':'Active')+'</span>'
    +'</div>';

  /* Progress bar */
  inner += '<div style="margin-bottom:10px">'
    +'<div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:4px">'
    +'<span style="font-weight:700">'+prog.done+'/'+prog.total+' teeth complete</span>'
    +'<span style="color:#64748b">'+prog.pct+'%</span></div>'
    +'<div style="background:#e2e8f0;border-radius:20px;height:8px;overflow:hidden">'
    +'<div style="background:'+stColor+';width:'+prog.pct+'%;height:8px;border-radius:20px"></div></div></div>';

  /* Status chips */
  inner += '<div style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:10px">';
  FMR_STATUS_ORDER.filter(function(s){ return s!=='skip'&&sc[s]>0; }).forEach(function(s){
    var st = FMR_STATUS[s];
    inner += '<span style="font-size:10px;font-weight:700;color:'+st.color+';background:'+st.bg+';border-radius:4px;padding:2px 6px">'+st.icon+' '+sc[s]+' '+st.label+'</span>';
  });
  inner += '</div>';

  /* Financials */
  inner += '<div style="display:flex;gap:12px;flex-wrap:wrap;font-size:11px">'
    +'<span style="color:#1e293b;font-weight:700">Total: ₹'+total.toLocaleString('en-IN')+'</span>'
    +'<span style="color:#059669">Paid: ₹'+Number(c.paidAmount||0).toLocaleString('en-IN')+'</span>'
    +(pending>0?'<span style="color:#dc2626;font-weight:700">Pending: ₹'+pending.toLocaleString('en-IN')+'</span>':'')
    +'</div>';

  card.innerHTML = inner;
  return card;
}

/* ─── CASE DETAIL ─────────────────────────────────────────────── */
function fmr_openDetail(id) {
  _fmrDetailId = id;
  var c = fmr_getCase(id);
  if (!c) return;
  var el = document.getElementById('page-fmr');
  el.innerHTML = '';

  var back = document.createElement('button');
  back.style.cssText = 'background:none;border:none;color:#1e3a5f;font-size:13px;font-weight:700;cursor:pointer;margin-bottom:14px;padding:0';
  back.innerHTML = '← Back to FMR Cases';
  back.addEventListener('click', function(){ _fmrDetailId=null; renderFMRPage(); });
  el.appendChild(back);

  var prog = fmr_progress(c);
  var total= fmr_calcTotal(c);
  var pending = Math.max(0, total - Number(c.paidAmount||0));
  var stColor = c.status==='completed'?'#1d4ed8':'#059669';

  /* ── Info card ── */
  var infoCard = document.createElement('div');
  infoCard.style.cssText = 'background:#fff;border-radius:14px;padding:16px;margin-bottom:12px;box-shadow:0 1px 4px rgba(0,0,0,.08)';
  infoCard.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px;flex-wrap:wrap;gap:8px">'
    +'<div><div style="font-size:18px;font-weight:800;color:#1e293b">'+esc(c.patientName||'')+'</div>'
    +'<div style="font-size:12px;color:#64748b">'+esc(c.phone||'')+'</div></div>'
    +'<div style="display:flex;gap:6px;flex-wrap:wrap">'
    +'<button data-id="'+id+'" onclick="fmr_showForm(this.dataset.id)" style="background:#f1f5f9;border:1px solid #e2e8f0;color:#475569;border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer">✏️ Edit</button>'
    +'<button data-id="'+id+'" onclick="fmr_printProgress(this.dataset.id)" style="background:#1e3a5f;color:#fff;border:none;border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer">🖨️ Print</button>'
    +'<button data-id="'+id+'" onclick="fmr_confirmDelete(this.dataset.id)" style="background:none;border:1px solid #dc2626;color:#dc2626;border-radius:8px;padding:5px 10px;font-size:11px;cursor:pointer">🗑</button>'
    +'</div></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:12px">'
    +[['Progress',prog.done+'/'+prog.total+' teeth'],['Total Cost','₹'+total.toLocaleString('en-IN')],
      ['Paid','₹'+Number(c.paidAmount||0).toLocaleString('en-IN')],
      ['Pending','₹'+pending.toLocaleString('en-IN')],
      ['Started',fmtDate(c.startDate||'')],['Visits',(c.visits||[]).length+' logged']]
     .map(function(r){ return '<div style="background:#f8fafc;border-radius:8px;padding:8px 10px"><div style="font-size:10px;color:#94a3b8;font-weight:700">'+r[0].toUpperCase()+'</div><div style="font-size:13px;font-weight:700;color:#1e293b">'+r[1]+'</div></div>'; }).join('')
    +'</div>'
    +(c.status==='active'
      ?'<div style="display:flex;gap:8px;flex-wrap:wrap">'
        +'<button data-id="'+id+'" onclick="fmr_logVisitModal(this.dataset.id)" style="background:#1e3a5f;color:#fff;border:none;border-radius:10px;padding:10px 16px;font-size:12px;font-weight:700;cursor:pointer">📋 Log Visit</button>'
        +'<button data-id="'+id+'" onclick="fmr_addPaymentModal(this.dataset.id)" style="background:#059669;color:#fff;border:none;border-radius:10px;padding:10px 16px;font-size:12px;font-weight:700;cursor:pointer">💰 Add Payment</button>'
        +'<button data-id="'+id+'" onclick="fmr_markComplete(this.dataset.id)" style="background:#f1f5f9;color:#1d4ed8;border:1px solid #1d4ed8;border-radius:10px;padding:10px 16px;font-size:12px;font-weight:700;cursor:pointer">✅ Mark Complete</button>'
        +'</div>'
      :'<button data-id="'+id+'" onclick="fmr_addPaymentModal(this.dataset.id)" style="background:#059669;color:#fff;border:none;border-radius:10px;padding:10px 16px;font-size:12px;font-weight:700;cursor:pointer">💰 Add Payment</button>');
  el.appendChild(infoCard);

  /* ── Tooth Chart ── */
  var chartSection = document.createElement('div');
  chartSection.style.cssText = 'background:#fff;border-radius:14px;padding:16px;margin-bottom:12px;box-shadow:0 1px 4px rgba(0,0,0,.08)';
  chartSection.appendChild(fmr_buildToothChart(c));
  el.appendChild(chartSection);

  /* ── Cost breakdown table ── */
  var breakdown = fmr_buildBreakdown(c);
  el.appendChild(breakdown);

  /* ── Visit log ── */
  var visits = (c.visits||[]).slice().sort(function(a,b){ return (b.date||'').localeCompare(a.date||''); });
  var visitSection = document.createElement('div');
  visitSection.style.cssText = 'background:#fff;border-radius:14px;padding:16px;margin-bottom:12px;box-shadow:0 1px 4px rgba(0,0,0,.08)';
  visitSection.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">'
    +'<div style="font-size:14px;font-weight:800;color:#1e293b">📋 Visit Log ('+visits.length+')</div>'
    +(c.status==='active'?'<button data-id="'+id+'" onclick="fmr_logVisitModal(this.dataset.id)" style="background:#1e3a5f;color:#fff;border:none;border-radius:8px;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer">+ Log Visit</button>':'')
    +'</div>';
  if (!visits.length) {
    visitSection.innerHTML += '<div style="color:#94a3b8;font-size:12px;text-align:center;padding:16px">No visits logged yet</div>';
  } else {
    visits.forEach(function(v){
      var vd = document.createElement('div');
      vd.style.cssText = 'border-left:3px solid #bfdbfe;padding:10px 14px;margin-bottom:8px';
      vd.innerHTML = '<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px">'
        +'<span style="font-size:13px;font-weight:700;color:#1e293b">'+esc(v.procedure||'Visit')+'</span>'
        +'<span style="font-size:11px;color:#64748b">'+fmtDate(v.date)+'</span></div>'
        +(v.teethTreated&&v.teethTreated.length?'<div style="font-size:11px;color:#1e3a5f;margin-top:3px;font-weight:600">Teeth: '+v.teethTreated.join(', ')+'</div>':'')
        +(v.notes?'<div style="font-size:12px;color:#374151;margin-top:4px">'+esc(v.notes)+'</div>':'');
      visitSection.appendChild(vd);
    });
  }
  el.appendChild(visitSection);

  /* ── Payment history ── */
  var instalments = c.instalments||c.paymentHistory||[];
  if (instalments.length) {
    var paySection = document.createElement('div');
    paySection.style.cssText = 'background:#fff;border-radius:14px;padding:16px;margin-bottom:12px;box-shadow:0 1px 4px rgba(0,0,0,.08)';
    paySection.innerHTML = '<div style="font-size:14px;font-weight:800;color:#1e293b;margin-bottom:10px">💰 Payment History</div>';
    instalments.slice().sort(function(a,b){return(b.date||'').localeCompare(a.date||'');}).forEach(function(p){
      var row = document.createElement('div');
      row.style.cssText = 'display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #f1f5f9;font-size:12px';
      row.innerHTML = '<span>'+fmtDate(p.date)+(p.mode?' · '+p.mode:'')+(p.note?' · '+esc(p.note):'')+'</span>'
        +'<span style="font-weight:700;color:#059669">₹'+Number(p.amount||0).toLocaleString('en-IN')+'</span>';
      paySection.appendChild(row);
    });
    el.appendChild(paySection);
  }
}

/* ─── TOOTH CHART ─────────────────────────────────────────────── */
function fmr_buildToothChart(c) {
  var wrap = document.createElement('div');

  var title = document.createElement('div');
  title.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:12px';
  title.innerHTML = '<div style="font-size:14px;font-weight:800;color:#1e293b">🦷 Tooth Chart</div>'
    +'<div style="font-size:10px;color:#64748b">Tap any tooth to update status</div>';
  wrap.appendChild(title);

  /* Legend */
  var legend = document.createElement('div');
  legend.style.cssText = 'display:flex;flex-wrap:wrap;gap:5px;margin-bottom:12px';
  FMR_STATUS_ORDER.forEach(function(s){
    var st = FMR_STATUS[s];
    var chip = document.createElement('span');
    chip.style.cssText = 'font-size:9px;font-weight:700;color:'+st.color+';background:'+st.bg+';border-radius:4px;padding:2px 6px';
    chip.textContent = st.icon+' '+st.label;
    legend.appendChild(chip);
  });
  wrap.appendChild(legend);

  /* Upper arch */
  var upperLabel = document.createElement('div');
  upperLabel.style.cssText = 'font-size:10px;font-weight:700;color:#94a3b8;text-align:center;margin-bottom:6px';
  upperLabel.textContent = 'UPPER ARCH';
  wrap.appendChild(upperLabel);

  var upperRow = document.createElement('div');
  upperRow.style.cssText = 'display:flex;justify-content:center;gap:4px;margin-bottom:4px';
  var upperTeeth = ['18','17','16','15','14','13','12','11','21','22','23','24','25','26','27','28'];
  upperTeeth.forEach(function(tn){ upperRow.appendChild(fmr_buildToothCell(c, tn)); });
  wrap.appendChild(upperRow);

  /* Midline */
  var mid = document.createElement('div');
  mid.style.cssText = 'border-top:2px dashed #e2e8f0;margin:6px 0';
  wrap.appendChild(mid);

  /* Lower arch */
  var lowerRow = document.createElement('div');
  lowerRow.style.cssText = 'display:flex;justify-content:center;gap:4px;margin-bottom:6px';
  var lowerTeeth = ['48','47','46','45','44','43','42','41','31','32','33','34','35','36','37','38'];
  lowerTeeth.forEach(function(tn){ lowerRow.appendChild(fmr_buildToothCell(c, tn)); });
  wrap.appendChild(lowerRow);

  var lowerLabel = document.createElement('div');
  lowerLabel.style.cssText = 'font-size:10px;font-weight:700;color:#94a3b8;text-align:center';
  lowerLabel.textContent = 'LOWER ARCH';
  wrap.appendChild(lowerLabel);

  return wrap;
}

function fmr_buildToothCell(c, tn) {
  var tooth = (c.teeth||{})[tn] || { status:'planned' };
  var st    = FMR_STATUS[tooth.status||'planned'] || FMR_STATUS.planned;
  var cell  = document.createElement('div');
  var hasCost = Number(tooth.rctCost||0) + Number(tooth.crownCost||0) > 0;
  var hasNote = !!(tooth.notes||tooth.labName);

  cell.style.cssText = 'width:34px;height:44px;border-radius:6px;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;border:2px solid '+st.color+';background:'+st.bg+';position:relative;flex-shrink:0;transition:transform .1s';
  cell.innerHTML = '<div style="font-size:14px;line-height:1;color:'+st.color+'">'+st.icon+'</div>'
    +'<div style="font-size:9px;font-weight:800;color:'+st.color+';margin-top:2px">'+tn+'</div>'
    +(hasNote?'<div style="position:absolute;top:2px;right:2px;width:5px;height:5px;background:#f59e0b;border-radius:50%"></div>':'');

  cell.dataset.cid = c.id;
  cell.dataset.tn  = tn;
  cell.addEventListener('click', function(e){
    e.stopPropagation();
    fmr_toothModal(this.dataset.cid, this.dataset.tn);
  });
  cell.addEventListener('mouseover', function(){ this.style.transform='scale(1.1)'; });
  cell.addEventListener('mouseout',  function(){ this.style.transform='scale(1)'; });
  return cell;
}

/* ─── TOOTH MODAL ─────────────────────────────────────────────── */
function fmr_toothModal(caseId, toothNum) {
  var c = fmr_getCase(caseId);
  if (!c) return;
  if (!c.teeth) c.teeth = {};
  if (!c.teeth[toothNum]) c.teeth[toothNum] = { status:'planned', rctCost:0, crownCost:0 };
  var t = c.teeth[toothNum];

  var old = document.getElementById('fmr-tooth-modal');
  if (old) old.remove();

  var modal = document.createElement('div');
  modal.id = 'fmr-tooth-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9900;display:flex;align-items:flex-end;justify-content:center;padding:16px';

  var sheet = document.createElement('div');
  sheet.style.cssText = 'background:#fff;border-radius:20px 20px 0 0;width:100%;max-width:520px;padding:20px;max-height:85vh;overflow-y:auto';

  var crownTypes = ['PFM','Zirconia','E-max','Metal','Temp'];
  var rctDefaults = fmr_defaultRCTCost(toothNum, c.defaultCosts||{});

  sheet.innerHTML =
    '<div style="font-size:16px;font-weight:800;color:#1e293b;margin-bottom:4px">Tooth #'+toothNum+'</div>'
    +'<div style="font-size:11px;color:#64748b;margin-bottom:16px">'+(FMR_TOOTH_META[toothNum]?(['Anterior','Premolar','Molar'][['C','I','L'].some(function(x){return FMR_TOOTH_META[toothNum][1].startsWith(x);})?0:FMR_TOOTH_META[toothNum][1].startsWith('P')?1:2]):'')+'</div>'

    /* Status picker */
    +'<div style="margin-bottom:14px"><label class="form-label">Status</label>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:6px" id="fmr-status-grid">'
    +FMR_STATUS_ORDER.map(function(s){
      var st = FMR_STATUS[s];
      var active = (t.status||'planned')===s;
      return '<button data-s="'+s+'" onclick="fmr_selectStatus(this)" style="border-radius:8px;padding:8px;border:2px solid '+(active?st.color:'#e2e8f0')+';background:'+(active?st.bg:'#fff')+';cursor:pointer;text-align:left;font-size:11px;font-weight:700;color:'+(active?st.color:'#64748b')+'">'
        +st.icon+' '+st.label+'</button>';
    }).join('')+'</div></div>'

    /* Dates */
    +'<div class="form-grid-2" style="gap:10px;margin-bottom:12px">'
    +'<div class="form-group"><label class="form-label">RCT Date</label>'
    +'<input id="fmr-t-rctdate" type="date" class="form-input" value="'+(t.rctDate||'')+'"/></div>'
    +'<div class="form-group"><label class="form-label">Crown Type</label>'
    +'<select id="fmr-t-crowntype" class="form-input">'
    +'<option value="">—</option>'
    +crownTypes.map(function(ct){ return '<option '+(t.crownType===ct?'selected':'')+'>'+ct+'</option>'; }).join('')
    +'</select></div>'
    +'<div class="form-group"><label class="form-label">Lab Name</label>'
    +'<input id="fmr-t-lab" class="form-input" value="'+esc(t.labName||'')+'" placeholder="Lab name"/></div>'
    +'<div class="form-group"><label class="form-label">Crown Sent</label>'
    +'<input id="fmr-t-sent" type="date" class="form-input" value="'+(t.crownSentDate||'')+'"/></div>'
    +'<div class="form-group"><label class="form-label">Crown Return</label>'
    +'<input id="fmr-t-return" type="date" class="form-input" value="'+(t.crownReturnDate||'')+'"/></div>'
    +'</div>'

    /* Costs */
    +'<div class="form-grid-2" style="gap:10px;margin-bottom:12px">'
    +'<div class="form-group"><label class="form-label">RCT Cost (₹)</label>'
    +'<input id="fmr-t-rctcost" type="number" class="form-input" value="'+(t.rctCost||rctDefaults)+'" min="0"/></div>'
    +'<div class="form-group"><label class="form-label">Crown Cost (₹)</label>'
    +'<input id="fmr-t-crownco" type="number" class="form-input" value="'+(t.crownCost||c.defaultCosts&&c.defaultCosts.crown_zirconia||8000)+'" min="0"/></div>'
    +'</div>'

    /* Notes */
    +'<div class="form-group" style="margin-bottom:14px"><label class="form-label">Notes</label>'
    +'<textarea id="fmr-t-notes" class="form-input" rows="2" style="resize:none">'+esc(t.notes||'')+'</textarea></div>'

    +'<div style="display:flex;gap:8px">'
    +'<button id="fmr-t-cancel" style="flex:1;background:#f1f5f9;border:none;border-radius:12px;padding:12px;font-size:13px;font-weight:700;cursor:pointer">Cancel</button>'
    +'<button id="fmr-t-save" data-cid="'+caseId+'" data-tn="'+toothNum+'" style="flex:2;background:#1e3a5f;color:#fff;border:none;border-radius:12px;padding:12px;font-size:13px;font-weight:700;cursor:pointer">💾 Save Tooth</button>'
    +'</div>';

  modal.appendChild(sheet);
  document.body.appendChild(modal);
  document.getElementById('fmr-t-cancel').addEventListener('click', function(){ modal.remove(); });
  modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });
  document.getElementById('fmr-t-save').addEventListener('click', function(){
    var selectedStatus = sheet.querySelector('[data-s].active-status, [data-s][style*="border: 2px solid #"]');
    /* Read selected status */
    var statusBtns = sheet.querySelectorAll('[data-s]');
    var selectedS = t.status||'planned';
    statusBtns.forEach(function(b){
      if (b.style.background && b.style.background!=='rgb(255, 255, 255)' && b.style.background!=='white' && b.style.background!='') {
        selectedS = b.dataset.s;
      }
    });
    var cc = fmr_getCase(caseId);
    if (!cc) return;
    if (!cc.teeth) cc.teeth = {};
    cc.teeth[toothNum] = {
      status:        selectedS,
      rctDate:       (document.getElementById('fmr-t-rctdate')||{}).value||'',
      crownType:     (document.getElementById('fmr-t-crowntype')||{}).value||'',
      labName:       (document.getElementById('fmr-t-lab')||{}).value||'',
      crownSentDate: (document.getElementById('fmr-t-sent')||{}).value||'',
      crownReturnDate:(document.getElementById('fmr-t-return')||{}).value||'',
      rctCost:       Number((document.getElementById('fmr-t-rctcost')||{}).value||0),
      crownCost:     Number((document.getElementById('fmr-t-crownco')||{}).value||0),
      notes:         (document.getElementById('fmr-t-notes')||{}).value||'',
    };
    /* Update total */
    cc.totalCost = fmr_calcTotal(cc);
    fmr_saveCase(cc);
    modal.remove();
    fmr_openDetail(caseId);
    showToast && showToast('Tooth #'+toothNum+' updated → '+FMR_STATUS[selectedS].label);
  });
}

function fmr_selectStatus(btn) {
  var grid = document.getElementById('fmr-status-grid');
  if (!grid) return;
  var s = btn.dataset.s;
  var st = FMR_STATUS[s];
  grid.querySelectorAll('[data-s]').forEach(function(b){
    b.style.border = '2px solid #e2e8f0';
    b.style.background = '#fff';
    b.style.color = '#64748b';
  });
  btn.style.border = '2px solid '+st.color;
  btn.style.background = st.bg;
  btn.style.color = st.color;
}

/* ─── COST BREAKDOWN TABLE ────────────────────────────────────── */
function fmr_buildBreakdown(c) {
  var section = document.createElement('div');
  section.style.cssText = 'background:#fff;border-radius:14px;padding:16px;margin-bottom:12px;box-shadow:0 1px 4px rgba(0,0,0,.08)';

  var header = document.createElement('div');
  header.style.cssText = 'font-size:14px;font-weight:800;color:#1e293b;margin-bottom:12px';
  header.textContent = '₹ Tooth-wise Cost Breakdown';
  section.appendChild(header);

  var allTeeth = ['11','12','13','14','15','16','17','18',
                  '21','22','23','24','25','26','27','28',
                  '31','32','33','34','35','36','37','38',
                  '41','42','43','44','45','46','47','48'];
  var totalRCT=0, totalCrown=0;

  /* Only show teeth that are active (not skip and not planned-without-costs) */
  var activTeeth = allTeeth.filter(function(tn){
    var t = (c.teeth||{})[tn];
    if (!t) return false;
    if (t.status==='skip') return false;
    return t.status!=='planned' || Number(t.rctCost||0)>0 || Number(t.crownCost||0)>0;
  });

  if (!activTeeth.length) {
    section.innerHTML += '<div style="color:#94a3b8;font-size:12px;text-align:center;padding:16px">Tap teeth in the chart above to set costs</div>';
    return section;
  }

  /* Table header */
  var table = document.createElement('div');
  table.style.cssText = 'font-size:11px';

  var tHeader = document.createElement('div');
  tHeader.style.cssText = 'display:grid;grid-template-columns:50px 1fr 80px 80px 80px 60px;gap:4px;padding:6px 8px;background:#f1f5f9;border-radius:8px;font-weight:700;color:#64748b;margin-bottom:4px';
  tHeader.innerHTML = '<span>Tooth</span><span>Status</span><span style="text-align:right">RCT</span><span style="text-align:right">Crown</span><span style="text-align:right">Total</span><span></span>';
  table.appendChild(tHeader);

  activTeeth.forEach(function(tn){
    var t  = (c.teeth||{})[tn] || {};
    var st = FMR_STATUS[t.status||'planned'] || FMR_STATUS.planned;
    var rct   = Number(t.rctCost||0);
    var crown = Number(t.crownCost||0);
    var rowTotal = rct+crown;
    totalRCT   += rct;
    totalCrown += crown;

    var row = document.createElement('div');
    row.style.cssText = 'display:grid;grid-template-columns:50px 1fr 80px 80px 80px 60px;gap:4px;padding:7px 8px;border-bottom:1px solid #f8fafc;align-items:center';
    row.innerHTML = '<span style="font-weight:800;color:#1e293b">'+tn+'</span>'
      +'<span style="font-size:10px;font-weight:700;color:'+st.color+'">'+st.icon+' '+st.label+'</span>'
      +'<span style="text-align:right;color:#374151">'+(rct?'₹'+rct.toLocaleString('en-IN'):'—')+'</span>'
      +'<span style="text-align:right;color:#374151">'+(crown?'₹'+crown.toLocaleString('en-IN'):'—')+'</span>'
      +'<span style="text-align:right;font-weight:700;color:#1e293b">₹'+rowTotal.toLocaleString('en-IN')+'</span>'
      +'<button data-cid="'+c.id+'" data-tn="'+tn+'" onclick="event.stopPropagation();fmr_toothModal(this.dataset.cid,this.dataset.tn)" style="font-size:10px;background:#eff6ff;border:none;border-radius:4px;padding:2px 6px;cursor:pointer;color:#1e3a5f">Edit</button>';
    table.appendChild(row);
  });

  /* Total row */
  var totalRow = document.createElement('div');
  totalRow.style.cssText = 'display:grid;grid-template-columns:50px 1fr 80px 80px 80px 60px;gap:4px;padding:8px;background:#f0fdf4;border-radius:8px;margin-top:4px;font-weight:800';
  totalRow.innerHTML = '<span style="color:#059669">TOTAL</span><span></span>'
    +'<span style="text-align:right;color:#059669">₹'+totalRCT.toLocaleString('en-IN')+'</span>'
    +'<span style="text-align:right;color:#059669">₹'+totalCrown.toLocaleString('en-IN')+'</span>'
    +'<span style="text-align:right;color:#059669">₹'+(totalRCT+totalCrown).toLocaleString('en-IN')+'</span>'
    +'<span></span>';
  table.appendChild(totalRow);
  section.appendChild(table);
  return section;
}

/* ─── LOG VISIT MODAL ─────────────────────────────────────────── */
function fmr_logVisitModal(id) {
  var c = fmr_getCase(id);
  if (!c) return;
  var old = document.getElementById('fmr-visit-modal');
  if (old) old.remove();

  var modal = document.createElement('div');
  modal.id = 'fmr-visit-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9900;display:flex;align-items:flex-end;justify-content:center;padding:16px';
  var sheet = document.createElement('div');
  sheet.style.cssText = 'background:#fff;border-radius:20px 20px 0 0;width:100%;max-width:520px;padding:20px;max-height:85vh;overflow-y:auto';

  /* Multi-select teeth */
  var allTeeth = ['11','12','13','14','15','16','17','18','21','22','23','24','25','26','27','28',
                  '31','32','33','34','35','36','37','38','41','42','43','44','45','46','47','48'];
  var activeTeeth = allTeeth.filter(function(tn){
    var t = (c.teeth||{})[tn];
    return t && t.status!=='skip' && t.status!=='complete';
  });

  sheet.innerHTML =
    '<div style="font-size:15px;font-weight:800;margin-bottom:16px">📋 Log Visit — '+esc(c.patientName)+'</div>'
    +'<div class="form-grid-2" style="gap:10px;margin-bottom:12px">'
    +'<div class="form-group"><label class="form-label">Date</label>'
    +'<input id="fmr-v-date" type="date" class="form-input" value="'+todayISO()+'"/></div>'
    +'<div class="form-group"><label class="form-label">Procedure Done</label>'
    +'<input id="fmr-v-proc" class="form-input" placeholder="e.g. RCT — Q2, Crown — #26"/></div>'
    +'</div>'
    +'<div class="form-group" style="margin-bottom:12px"><label class="form-label">Teeth Treated (tap to select)</label>'
    +'<div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:6px" id="fmr-v-teeth">'
    +activeTeeth.map(function(tn){
      var t   = (c.teeth||{})[tn]||{};
      var st  = FMR_STATUS[t.status||'planned']||FMR_STATUS.planned;
      return '<button type="button" data-tn="'+tn+'" onclick="this.classList.toggle(\'fmr-sel\');this.style.background=this.classList.contains(\'fmr-sel\')?\'#1e3a5f\':\''+st.bg+'\';this.style.color=this.classList.contains(\'fmr-sel\')?\'#fff\':\''+st.color+'\'" style="border:2px solid '+st.color+';background:'+st.bg+';color:'+st.color+';border-radius:8px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">'+tn+'</button>';
    }).join('')
    +'</div></div>'
    +'<div class="form-group" style="margin-bottom:14px"><label class="form-label">Visit Notes</label>'
    +'<textarea id="fmr-v-notes" class="form-input" rows="3" style="resize:none" placeholder="Observations, next plan, patient feedback..."></textarea></div>'
    +'<div style="display:flex;gap:8px">'
    +'<button id="fmr-v-cancel" style="flex:1;background:#f1f5f9;border:none;border-radius:12px;padding:12px;font-size:13px;font-weight:700;cursor:pointer">Cancel</button>'
    +'<button id="fmr-v-save" style="flex:2;background:#1e3a5f;color:#fff;border:none;border-radius:12px;padding:12px;font-size:13px;font-weight:700;cursor:pointer">✅ Save Visit</button>'
    +'</div>';

  modal.appendChild(sheet);
  document.body.appendChild(modal);
  document.getElementById('fmr-v-cancel').addEventListener('click', function(){ modal.remove(); });
  modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });
  document.getElementById('fmr-v-save').addEventListener('click', function(){
    var date   = document.getElementById('fmr-v-date').value||todayISO();
    var proc   = document.getElementById('fmr-v-proc').value.trim();
    var notes  = document.getElementById('fmr-v-notes').value.trim();
    var teeth  = [];
    sheet.querySelectorAll('[data-tn].fmr-sel').forEach(function(b){ teeth.push(b.dataset.tn); });
    if (!proc && !teeth.length) { alert('Enter procedure or select teeth.'); return; }
    var visit = { id:'fv'+Date.now(), date:date, procedure:proc||'Visit', teethTreated:teeth, notes:notes };
    if (!c.visits) c.visits = [];
    c.visits.push(visit);
    fmr_saveCase(c);
    modal.remove();
    fmr_openDetail(id);
    showToast && showToast('Visit logged for '+teeth.length+' teeth');
  });
}

/* ─── ADD PAYMENT MODAL ──────────────────────────────────────── */
function fmr_addPaymentModal(id) {
  var c = fmr_getCase(id);
  if (!c) return;
  var total   = fmr_calcTotal(c);
  var pending = Math.max(0, total - Number(c.paidAmount||0));
  var old = document.getElementById('fmr-pay-modal');
  if (old) old.remove();

  var modal = document.createElement('div');
  modal.id = 'fmr-pay-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9900;display:flex;align-items:flex-end;justify-content:center;padding:16px';
  var sheet = document.createElement('div');
  sheet.style.cssText = 'background:#fff;border-radius:20px 20px 0 0;width:100%;max-width:520px;padding:20px';
  sheet.innerHTML =
    '<div style="font-size:15px;font-weight:800;margin-bottom:4px">💰 Add Instalment</div>'
    +'<div style="font-size:12px;color:#94a3b8;margin-bottom:16px">Pending: ₹'+pending.toLocaleString('en-IN')+' of ₹'+total.toLocaleString('en-IN')+'</div>'
    +'<div class="form-grid-2" style="gap:10px;margin-bottom:14px">'
    +'<div class="form-group"><label class="form-label">Amount ✱</label>'
    +'<input id="fmrp-amt" type="number" class="form-input" value="'+pending+'"/></div>'
    +'<div class="form-group"><label class="form-label">Mode</label>'
    +'<select id="fmrp-mode" class="form-input"><option>Cash</option><option>UPI</option><option>Card</option></select></div>'
    +'<div class="form-group"><label class="form-label">Date</label>'
    +'<input id="fmrp-date" type="date" class="form-input" value="'+todayISO()+'"/></div>'
    +'<div class="form-group"><label class="form-label">Note</label>'
    +'<input id="fmrp-note" class="form-input" placeholder="e.g. Advance, 2nd instalment"/></div>'
    +'</div>'
    +'<div style="display:flex;gap:8px">'
    +'<button id="fmrp-cancel" style="flex:1;background:#f1f5f9;border:none;border-radius:12px;padding:12px;font-size:13px;font-weight:700;cursor:pointer">Cancel</button>'
    +'<button id="fmrp-save" style="flex:2;background:#059669;color:#fff;border:none;border-radius:12px;padding:12px;font-size:13px;font-weight:700;cursor:pointer">✅ Record</button>'
    +'</div>';

  modal.appendChild(sheet);
  document.body.appendChild(modal);
  document.getElementById('fmrp-cancel').addEventListener('click', function(){ modal.remove(); });
  modal.addEventListener('click', function(e){ if(e.target===modal) modal.remove(); });
  document.getElementById('fmrp-save').addEventListener('click', function(){
    var amt  = Number(document.getElementById('fmrp-amt').value||0);
    var mode = document.getElementById('fmrp-mode').value;
    var date = document.getElementById('fmrp-date').value||todayISO();
    var note = document.getElementById('fmrp-note').value||mode;
    if (!amt) { alert('Enter amount.'); return; }
    if (!c.instalments) c.instalments = [];
    c.instalments.push({id:'i'+Date.now(), amount:amt, mode:mode, date:date, note:note});
    c.paidAmount = Math.round((Number(c.paidAmount||0)+amt)*100)/100;
    /* Sync to patient billing */
    fmr_syncPaymentToBilling(c, amt, mode, date);
    fmr_saveCase(c);
    modal.remove();
    fmr_openDetail(id);
    showToast && showToast('₹'+amt.toLocaleString('en-IN')+' recorded');
  });
}

function fmr_syncPaymentToBilling(c, amt, mode, date) {
  if (!c.patientId) return;
  var ptIdx = (DATA.patients||[]).findIndex(function(p){ return p.id===c.patientId; });
  if (ptIdx<0) return;
  if (!DATA.patients[ptIdx].billing) DATA.patients[ptIdx].billing=[];
  var bill = DATA.patients[ptIdx].billing.find(function(b){ return b.fmrCaseId===c.id; });
  if (bill) {
    bill.paidAmount = Math.round((Number(bill.paidAmount||0)+amt)*100)/100;
    bill.paid = bill.paidAmount >= Number(bill.totalAmount||bill.amount||0);
  }
}

/* ─── NEW / EDIT FORM ─────────────────────────────────────────── */
