function fmr_toggleToothSel(btn) {
  var on = btn.classList.toggle('fmr-tsel-on');
  btn.style.border   = '2px solid '+(on?'#1e3a5f':'#cbd5e1');
  btn.style.background = on?'#1e3a5f':'#f8fafc';
  btn.style.color    = on?'#fff':'#94a3b8';
}
function fmr_selectAll() {
  document.querySelectorAll('.fmr-tsel').forEach(function(b){
    b.classList.add('fmr-tsel-on');
    b.style.border='2px solid #1e3a5f'; b.style.background='#1e3a5f'; b.style.color='#fff';
  });
}
function fmr_clearAll() {
  document.querySelectorAll('.fmr-tsel').forEach(function(b){
    b.classList.remove('fmr-tsel-on');
    b.style.border='2px solid #cbd5e1'; b.style.background='#f8fafc'; b.style.color='#94a3b8';
  });
}
function fmr_onPtChange(val) {
  var wrap    = document.getElementById('fmr-newname-wrap');
  var impWrap = document.getElementById('fmr-import-wrap');
  var prevEl  = document.getElementById('fmr-import-preview');
  var phoneEl = document.getElementById('fmr-ptphone');
  if (val==='_new') {
    if (wrap) wrap.style.display='block';
    if (impWrap) impWrap.style.display='none';
    return;
  }
  if (wrap) wrap.style.display='none';
  var pt = (DATA.patients||[]).find(function(p){ return p.id===val; });
  if (pt && phoneEl) phoneEl.value = pt.phone||'';
  if (pt && impWrap) {
    /* Scan for RCT records */
    var rctCount = (pt.rctLog||[]).length;
    var rctInRecords = (pt.records||[]).filter(function(r){
      return (r.diagnosis+r.treatment||'').toLowerCase().includes('rct')||
             (r.diagnosis+r.treatment||'').toLowerCase().includes('root canal');
    }).length;
    var billingAmt = (pt.billing||[]).filter(function(b){
      return (b.item||'').toLowerCase().includes('rct')||(b.item||'').toLowerCase().includes('root canal')||
             (b.item||'').toLowerCase().includes('crown')||(b.item||'').toLowerCase().includes('fmr');
    }).reduce(function(s,b){ return s+Number(b.totalAmount||b.amount||0); },0);
    if (prevEl) prevEl.innerHTML = '<b>'+rctCount+'</b> RCT log entries · <b>'+rctInRecords+'</b> RCT records · <b>₹'+billingAmt.toLocaleString('en-IN')+'</b> in related billing';
    impWrap.style.display = 'block';
  }
}

/* ─── SAVE FORM ────────────────────────────────────────────────── */
function fmr_saveForm(editId, existing) {
  var ptIdEl = document.getElementById('fmr-ptid');
  var ptId = ptIdEl ? ptIdEl.value : (existing?existing.patientId:'');
  var ptName='', phone='';
  if (ptId==='_new'||!ptId) {
    var nn = document.getElementById('fmr-newname');
    ptName = nn ? nn.value.trim() : '';
    ptId = '';
    if (!ptName) { alert('Enter patient name.'); return; }
  } else {
    var pt = (DATA.patients||[]).find(function(p){ return p.id===ptId; });
    ptName = pt ? pt.name : (existing?existing.patientName:'');
    phone  = pt ? pt.phone||'' : (existing?existing.phone||'':'');
  }

  var defCosts = {
    rct_anterior:  Number((document.getElementById('fmr-dc-rct_anterior')||{}).value||3000),
    rct_premolar:  Number((document.getElementById('fmr-dc-rct_premolar')||{}).value||4500),
    rct_molar:     Number((document.getElementById('fmr-dc-rct_molar')||{}).value||6000),
    crown_pfm:     Number((document.getElementById('fmr-dc-crown_pfm')||{}).value||5000),
    crown_zirconia:Number((document.getElementById('fmr-dc-crown_zirconia')||{}).value||8000),
  };

  /* Build teeth from selector */
  var selectedTeeth = {};
  document.querySelectorAll('.fmr-tsel-on').forEach(function(b){
    var tn = b.dataset.tn;
    /* Preserve existing tooth data if editing */
    if (existing && existing.teeth && existing.teeth[tn]) {
      selectedTeeth[tn] = existing.teeth[tn];
    } else {
      selectedTeeth[tn] = {
        status:'planned',
        rctCost:  fmr_defaultRCTCost(tn, defCosts),
        crownCost:defCosts.crown_zirconia,
      };
    }
  });

  var newCase = {
    id:              editId || ('FMR'+Date.now()),
    patientId:       ptId,
    patientName:     ptName,
    phone:           phone,
    startDate:       (document.getElementById('fmr-start')||{}).value||todayISO(),
    expectedEndDate: (document.getElementById('fmr-end')||{}).value||'',
    status:          (document.getElementById('fmr-status')||{}).value||'active',
    defaultCosts:    defCosts,
    teeth:           selectedTeeth,
    visits:          existing ? (existing.visits||[]) : [],
    instalments:     existing ? (existing.instalments||[]) : [],
    paidAmount:      existing ? Number(existing.paidAmount||0) : 0,
    notes:           (document.getElementById('fmr-notes')||{}).value||'',
    completionNotes: existing ? existing.completionNotes||'' : '',
  };
  newCase.totalCost = fmr_calcTotal(newCase);

  /* ── Import existing RCT records if checkbox ticked ── */
  var importCheck = document.getElementById('fmr-import-check');
  if (importCheck && importCheck.checked && ptId) {
    fmr_importFromPatient(newCase, ptId);
  }

  /* Auto-create billing entry for patient */
  if (ptId && newCase.totalCost>0 && !editId) {
    var ptIdx2 = (DATA.patients||[]).findIndex(function(p){ return p.id===ptId; });
    if (ptIdx2>=0) {
      var alreadyBilled = ((DATA.patients[ptIdx2].billing||[])).some(function(b){ return b.fmrCaseId===newCase.id; });
      if (!alreadyBilled) {
        if (!DATA.patients[ptIdx2].billing) DATA.patients[ptIdx2].billing=[];
        DATA.patients[ptIdx2].billing.push({
          id:'b'+Date.now(), fmrCaseId:newCase.id,
          item:'FMR Treatment ('+Object.keys(selectedTeeth).length+' teeth)',
          totalAmount:newCase.totalCost, amount:newCase.totalCost,
          paidAmount:0, paid:false, date:newCase.startDate, paymentMode:'Instalment', payments:[]
        });
        saveData();
      }
    }
  }

  fmr_saveCase(newCase);
  fmr_openDetail(newCase.id);
  showToast && showToast(editId?'FMR case updated':'FMR case created — '+Object.keys(selectedTeeth).length+' teeth');
}

/* ─── IMPORT FROM EXISTING PATIENT ───────────────────────────── */
function fmr_importFromPatient(caseObj, ptId) {
  var pt = (DATA.patients||[]).find(function(p){ return p.id===ptId; });
  if (!pt) return;

  /* Scan RCT log */
  (pt.rctLog||[]).forEach(function(r){
    var tn = String(r.toothNo||'');
    if (!tn || !caseObj.teeth[tn]) return;
    caseObj.teeth[tn].status   = r.obturationDate ? 'rctdone' : 'inprogress';
    caseObj.teeth[tn].rctDate  = r.obturationDate || r.date || '';
    if (r.notes) caseObj.teeth[tn].notes = r.notes;
  });

  /* Scan records for tooth/RCT mentions */
  var toothRegex = /\b([1-4][1-8])\b/g;
  (pt.records||[]).forEach(function(rec){
    var text = (rec.diagnosis||'')+(rec.treatment||'');
    var isRCT = /rct|root canal/i.test(text);
    var m;
    while ((m=toothRegex.exec(text))!==null) {
      var tn = m[1];
      if (!caseObj.teeth[tn]) continue;
      if (isRCT && caseObj.teeth[tn].status==='planned') {
        caseObj.teeth[tn].status  = 'rctdone';
        caseObj.teeth[tn].rctDate = rec.date||'';
      }
    }
  });

  /* Scan billing for paid amounts */
  var rctPaid=0, crownPaid=0;
  (pt.billing||[]).forEach(function(b){
    var item = (b.item||'').toLowerCase();
    if (item.includes('rct')||item.includes('root canal')) rctPaid += Number(b.paidAmount||0);
    if (item.includes('crown')||item.includes('cap')) crownPaid += Number(b.paidAmount||0);
  });
  if (rctPaid+crownPaid > 0 && !caseObj.paidAmount) {
    caseObj.paidAmount = rctPaid + crownPaid;
    if (!caseObj.instalments) caseObj.instalments = [];
    caseObj.instalments.push({id:'imp'+Date.now(), amount:rctPaid+crownPaid, date:pt.createdAt||todayISO(), mode:'Imported', note:'Imported from existing billing'});
  }
  caseObj.totalCost = fmr_calcTotal(caseObj);
}

/* ─── MARK COMPLETE ──────────────────────────────────────────── */
function fmr_markComplete(id) {
  var c = fmr_getCase(id);
  if (!c) return;
  if (!confirm('Mark this FMR case as completed?')) return;
  c.status = 'completed';
  fmr_saveCase(c);
  fmr_openDetail(id);
  showToast && showToast('FMR case marked complete');
}
function fmr_confirmDelete(id) {
  var c = fmr_getCase(id);
  if (!c || !confirm('Delete FMR case for '+c.patientName+'? Cannot undo.')) return;
  fmr_deleteCase(id);
  renderFMRPage();
}

/* ─── PRINT PROGRESS REPORT ──────────────────────────────────── */
function fmr_printProgress(id) {
  var c = fmr_getCase(id);
  if (!c) return;
  var prog  = fmr_progress(c);
  var total = fmr_calcTotal(c);
  var pending = Math.max(0, total - Number(c.paidAmount||0));
  var sc    = fmr_statusCounts(c);

  var rows = '';
  var allTeeth = ['11','12','13','14','15','16','17','18','21','22','23','24','25','26','27','28',
                  '31','32','33','34','35','36','37','38','41','42','43','44','45','46','47','48'];
  allTeeth.forEach(function(tn){
    var t = (c.teeth||{})[tn];
    if (!t || t.status==='skip') return;
    var st = FMR_STATUS[t.status||'planned'];
    rows += '<tr><td style="padding:6px 8px;border-bottom:1px solid #eee;font-weight:700">'+tn+'</td>'
      +'<td style="padding:6px 8px;border-bottom:1px solid #eee;color:'+st.color+'">'+st.icon+' '+st.label+'</td>'
      +'<td style="padding:6px 8px;border-bottom:1px solid #eee">'+(t.rctDate?fmtDate(t.rctDate):'—')+'</td>'
      +'<td style="padding:6px 8px;border-bottom:1px solid #eee">'+(t.crownType||'—')+'</td>'
      +'<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">₹'+Number(t.rctCost||0).toLocaleString('en-IN')+'</td>'
      +'<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right">₹'+Number(t.crownCost||0).toLocaleString('en-IN')+'</td>'
      +'<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:right;font-weight:700">₹'+(Number(t.rctCost||0)+Number(t.crownCost||0)).toLocaleString('en-IN')+'</td></tr>';
  });

  var win = window.open('','_blank','width=800,height=900');
  win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"/>'
    +'<title>FMR Progress Report</title><style>'
    +'body{font-family:Arial,sans-serif;padding:24px;color:#1e293b}h2{color:#1e3a5f}'
    +'table{width:100%;border-collapse:collapse}th{background:#1e3a5f;color:#fff;padding:8px;text-align:left}'
    +'@media print{button{display:none}}'
    +'</style></head><body>'
    +'<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px">'
    +'<div><h2 style="margin:0">Full Mouth Rehabilitation</h2>'
    +'<div style="font-size:14px;color:#64748b">Treatment Progress Report</div></div>'
    +'<div style="text-align:right;font-size:12px;color:#64748b">The Home Of Smiles<br/>Dr. Tanmay Jain<br/>'+fmtDate(todayISO())+'</div></div>'
    +'<hr style="margin-bottom:16px"/>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px">'
    +'<div><div style="font-size:12px;color:#64748b">PATIENT</div><div style="font-size:16px;font-weight:700">'+esc(c.patientName)+'</div>'
    +(c.phone?'<div style="font-size:12px">'+c.phone+'</div>':'')+'</div>'
    +'<div><div style="font-size:12px;color:#64748b">PROGRESS</div>'
    +'<div style="font-size:16px;font-weight:700">'+prog.done+' / '+prog.total+' teeth complete ('+prog.pct+'%)</div>'
    +'<div style="background:#e2e8f0;border-radius:10px;height:10px;overflow:hidden;margin-top:4px">'
    +'<div style="background:#059669;width:'+prog.pct+'%;height:10px;border-radius:10px"></div></div></div>'
    +'<div><div style="font-size:12px;color:#64748b">TOTAL COST</div><div style="font-size:16px;font-weight:700">₹'+total.toLocaleString('en-IN')+'</div></div>'
    +'<div><div style="font-size:12px;color:#64748b">BALANCE</div><div style="font-size:16px;font-weight:700;color:'+(pending>0?'#dc2626':'#059669')+'">₹'+pending.toLocaleString('en-IN')+'</div></div>'
    +'</div>'
    +'<table><thead><tr><th>Tooth</th><th>Status</th><th>RCT Date</th><th>Crown</th><th>RCT Cost</th><th>Crown Cost</th><th>Total</th></tr></thead>'
    +'<tbody>'+rows+'</tbody></table>'
    +'<div style="margin-top:40px;display:flex;gap:40px">'
    +'<div style="flex:1;border-top:2px solid #1e293b;padding-top:8px;text-align:center;font-size:12px">Patient Signature</div>'
    +'<div style="flex:1;border-top:2px solid #1e293b;padding-top:8px;text-align:center;font-size:12px">Dr. Tanmay Jain</div>'
    +'</div>'
    +'<div style="margin-top:20px;text-align:center"><button onclick="window.print()" style="background:#1e3a5f;color:#fff;border:none;padding:10px 24px;border-radius:8px;font-size:14px;cursor:pointer">🖨️ Print</button></div>'
    +'</body></html>');
  win.document.close();
  win.focus();
  setTimeout(function(){ win.print(); }, 400);
}

/* ── Public Patient Registration Link Copy ── */
function copyPublicRegisterLink() {
  var url = window.location.origin + '/register';
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(function() {
      alert('✅ Patient Self-Registration Link Copied!\n\n' + url + '\n\nYou can share this link with patients on WhatsApp/SMS for direct self-registration.');
    }).catch(function() {
      prompt('Copy this Patient Registration link:', url);
    });
  } else {
    prompt('Copy this Patient Registration link:', url);
  }
}
window.copyPublicRegisterLink = copyPublicRegisterLink;
